window.OTTER2_STORYSUB = window.OTTER2_STORYSUB || {};
window.OTTER2_STORYSUB["3"] = {"hsk3-01": {"dur": 259.92, "cues": [[7.128, 10.31, "你们每天晚上几点睡觉？", "Nǐ Men Měi Tiān Wǎn Shàng Jǐ Diǎn Shuì Jiào?", "Mọi người thường ngủ lúc mấy giờ tối?"], [10.31, 13.89, "去年，我有一个不好的习惯。", "Qù Nián, Wǒ Yǒu Yí Gè Bù Hǎo De Xí Guàn.", "Năm ngoái, tôi có một thói quen không tốt."], [13.89, 18.454, "去年我常常很晚才睡觉，早上起不来。", "Qù Nián Wǒ Cháng Cháng Hěn Wǎn Cái Shuì Jiào, Zǎo Shàng Qǐ Bù Lái.", "Năm ngoái tôi thường ngủ rất muộn và sáng không dậy nổi."], [18.454, 22.058, "晚上十一点，我还在看手机。", "Wǎn Shàng Shí Yī Diǎn, Wǒ Hái Zài Kàn Shǒu Jī.", "Mười một giờ tối, tôi vẫn còn xem điện thoại."], [22.058, 27.246, "手机里的视频很好看，我看了一个又一个。", "Shǒu Jī Lǐ De Shì Pín Hěn Hǎo Kàn, Wǒ Kàn Le Yí Gè Yòu Yí Gè.", "Video trong điện thoại rất hay, tôi xem cái này rồi lại cái khác."], [27.246, 30.994, "我看着手机，常常忘记时间。", "Wǒ Kàn Zhe Shǒu Jī, Cháng Cháng Wàng Jì Shí Jiān.", "Cứ nhìn điện thoại, tôi thường quên mất thời gian."], [30.994, 35.51, "有时候，十二点多了，我还没睡。", "Yǒu Shí Hòu, Shí Èr Diǎn Duō Le, Wǒ Hái Méi Shuì.", "Có lúc đã hơn mười hai giờ mà tôi vẫn chưa ngủ."], [35.51, 40.937, "第二天早上，我起不来，妈妈叫了我好几次。", "Dì Èr Tiān Zǎo Shàng, Wǒ Qǐ Bù Lái, Mā Ma Jiào Le Wǒ Hǎo Jǐ Cì.", "Sáng hôm sau tôi không dậy nổi, mẹ gọi tôi mấy lần."], [40.937, 44.661, "我起来以后，早饭也来不及吃。", "Wǒ Qǐ Lái Yǐ Hòu, Zǎo Fàn Yě Lái Bù Jí Chī.", "Dậy rồi, tôi cũng không kịp ăn sáng."], [44.661, 48.623, "我跑到学校的时候，心里很着急。", "Wǒ Pǎo Dào Xué Xiào De Shí Hòu, Xīn Lǐ Hěn Zháo Jí.", "Khi chạy đến trường, trong lòng tôi rất sốt ruột."], [48.623, 53.043, "上课的时候想睡觉，作业也做得很慢。", "Shàng Kè De Shí Hòu Xiǎng Shuì Jiào, Zuò Yè Yě Zuò Dé Hěn Màn.", "Trong lớp tôi buồn ngủ, bài tập cũng làm rất chậm."], [53.043, 56.587, "有一次上课，我睡了几分钟。", "Yǒu Yí Cì Shàng Kè, Wǒ Shuì Le Jǐ Fēn Zhōng.", "Có một lần trong giờ học, tôi ngủ mất mấy phút."], [56.587, 60.431, "老师走到我旁边，叫我的名字。", "Lǎo Shī Zǒu Dào Wǒ Páng Biān, Jiào Wǒ De Míng Zi.", "Thầy đi đến bên cạnh tôi và gọi tên tôi."], [60.431, 63.948, "我红着脸，不知道说什么好。", "Wǒ Hóng Zhe Liǎn, Bù Zhī Dào Shuō Shén Me Hǎo.", "Tôi đỏ mặt, không biết nói gì."], [63.948, 67.552, "那天下午，老师跟我谈话。", "Nà Tiān Xià Wǔ, Lǎo Shī Gēn Wǒ Tán Huà.", "Chiều hôm đó, thầy nói chuyện với tôi."], [67.552, 71.756, "老师问我：“你昨天晚上几点睡的？”", "Lǎo Shī Wèn Wǒ: \"Nǐ Zuó Tiān Wǎn Shàng Jǐ Diǎn Shuì De?\"", "Thầy hỏi tôi: \"Tối qua em ngủ lúc mấy giờ?\""], [71.756, 74.592, "我说：“十二点多。”", "Wǒ Shuō: \"Shí Èr Diǎn Duō.\"", "Tôi nói: \"Hơn mười hai giờ ạ.\""], [74.592, 79.273, "老师提醒我，身体和学习都需要休息。", "Lǎo Shī Tí Xǐng Wǒ, Shēn Tǐ Hé Xué Xí Dōu Xū Yào Xiū Xi.", "Thầy nhắc tôi rằng cả sức khỏe và việc học đều cần nghỉ ngơi."], [79.273, 84.389, "老师说：“你先试两个星期，早一点儿睡。”", "Lǎo Shī Shuō: \"Nǐ Xiān Shì Liǎng Gè Xīng Qī, Zǎo Yì Diǎn Ér Shuì.\"", "Thầy nói: \"Em cứ thử hai tuần, ngủ sớm hơn một chút.\""], [84.389, 87.729, "我问：“两个星期以后呢？”", "Wǒ Wèn: \"Liǎng Gè Xīng Qī Yǐ Hòu Ne?\"", "Tôi hỏi: \"Sau hai tuần thì sao ạ?\""], [87.729, 92.508, "老师笑着说：“以后你就不想晚睡了。”", "Lǎo Shī Xiào Zhe Shuō: \"Yǐ Hòu Nǐ Jiù Bù Xiǎng Wǎn Shuì Le.\"", "Thầy cười nói: \"Sau này em sẽ không muốn ngủ muộn nữa.\""], [92.508, 96.952, "从那天起，我决定十一点以前睡觉。", "Cóng Nà Tiān Qǐ, Wǒ Jué Dìng Shí Yī Diǎn Yǐ Qián Shuì Jiào.", "Từ hôm đó tôi quyết định ngủ trước mười một giờ."], [96.952, 101.75, "我把这个决定写在纸上，放在桌子上。", "Wǒ Bǎ Zhè Ge Jué Dìng Xiě Zài Zhǐ Shàng, Fàng Zài Zhuō Zi Shàng.", "Tôi viết quyết định này lên giấy và đặt trên bàn."], [101.75, 105.86, "从那以后，我把手机放在客厅。", "Cóng Nà Yǐ Hòu, Wǒ Bǎ Shǒu Jī Fàng Zài Kè Tīng.", "Từ đó tôi để điện thoại ở phòng khách."], [105.86, 109.584, "妈妈问我：“手机怎么在客厅？”", "Mā Ma Wèn Wǒ: \"Shǒu Jī Zěn Me Zài Kè Tīng?\"", "Mẹ hỏi tôi: \"Sao điện thoại lại ở phòng khách?\""], [109.584, 112.9, "我说：“我要早一点儿睡觉。”", "Wǒ Shuō: \"Wǒ Yào Zǎo Yì Diǎn Ér Shuì Jiào.\"", "Tôi nói: \"Con muốn ngủ sớm hơn một chút.\""], [112.9, 119.165, "妈妈听了很高兴，说：“这样对身体好，妈妈放心了。”", "Mā Ma Tīng Le Hěn Gāo Xìng, Shuō: \"Zhè Yàng Duì Shēn Tǐ Hǎo, Mā Ma Fàng Xīn Le.\"", "Mẹ nghe xong rất vui, nói: \"Như vậy tốt cho sức khỏe, mẹ yên tâm rồi.\""], [119.165, 122.601, "睡觉以前我不再看视频。", "Shuì Jiào Yǐ Qián Wǒ Bú Zài Kàn Shì Pín.", "Trước khi ngủ tôi không xem video nữa."], [122.601, 126.085, "睡觉以前，我看一会儿书。", "Shuì Jiào Yǐ Qián, Wǒ Kàn Yí Huì Ér Shū.", "Trước khi ngủ, tôi đọc sách một lúc."], [126.085, 129.591, "可是第一个晚上，我睡不着。", "Kě Shì Dì Yī Gè Wǎn Shàng, Wǒ Shuì Bù Zháo.", "Nhưng đêm đầu tiên, tôi không ngủ được."], [129.591, 132.451, "我想去客厅拿手机。", "Wǒ Xiǎng Qù Kè Tīng Ná Shǒu Jī.", "Tôi muốn ra phòng khách lấy điện thoại."], [132.451, 136.007, "我走到客厅门口，又回来了。", "Wǒ Zǒu Dào Kè Tīng Mén Kǒu, Yòu Huí Lái Le.", "Tôi đi đến cửa phòng khách rồi lại quay về."], [136.007, 139.552, "我对自己说：“再等一会儿吧。”", "Wǒ Duì Zì Jǐ Shuō: \"Zài Děng Yí Huì Ér Ba.\"", "Tôi tự nhủ: \"Đợi thêm một lúc nữa đi.\""], [139.552, 143.876, "一个星期六的晚上，爸爸妈妈不在家。", "Yí Gè Xīng Qī Liù De Wǎn Shàng, Bà Ba Mā Ma Bú Zài Jiā.", "Một tối thứ Bảy, bố mẹ không ở nhà."], [143.876, 147.768, "我想，今天晚一点儿睡也没关系。", "Wǒ Xiǎng, Jīn Tiān Wǎn Yì Diǎn Ér Shuì Yě Méi Guān Xì.", "Tôi nghĩ, hôm nay ngủ muộn một chút cũng không sao."], [147.768, 153.043, "我把手机拿回房间，看了一个多小时的视频。", "Wǒ Bǎ Shǒu Jī Ná Huí Fáng Jiān, Kàn Le Yí Gè Duō Xiǎo Shí De Shì Pín.", "Tôi mang điện thoại về phòng, xem video hơn một tiếng."], [153.043, 158.231, "第二天早上，我的头很疼，眼睛也很累。", "Dì Èr Tiān Zǎo Shàng, Wǒ De Tóu Hěn Téng, Yǎn Jīng Yě Hěn Lèi.", "Sáng hôm sau, đầu tôi rất đau, mắt cũng rất mỏi."], [158.231, 163.19, "我对自己说：“这样的晚上，不能再有了。”", "Wǒ Duì Zì Jǐ Shuō: \"Zhè Yàng De Wǎn Shàng, Bù Néng Zài Yǒu Le.\"", "Tôi tự nhủ: \"Không thể có thêm một buổi tối như thế này nữa.\""], [163.19, 168.618, "那天晚上，我十点半就把手机放回客厅了。", "Nà Tiān Wǎn Shàng, Wǒ Shí Diǎn Bàn Jiù Bǎ Shǒu Jī Fàng Huí Kè Tīng Le.", "Tối hôm đó, mười giờ rưỡi tôi đã để điện thoại lại phòng khách."], [168.618, 171.781, "这一次，我没有再去拿。", "Zhè Yí Cì, Wǒ Méi Yǒu Zài Qù Ná.", "Lần này, tôi không ra lấy nữa."], [171.781, 177.401, "开始的两个星期很不习惯，可是我坚持下来了。", "Kāi Shǐ De Liǎng Gè Xīng Qī Hěn Bù Xí Guàn, Kě Shì Wǒ Jiān Chí Xià Lái Le.", "Hai tuần đầu rất không quen, nhưng tôi đã kiên trì."], [177.401, 180.693, "早上七点，我自己会醒。", "Zǎo Shàng Qī Diǎn, Wǒ Zì Jǐ Huì Xǐng.", "Bảy giờ sáng tôi tự tỉnh."], [180.693, 185.521, "我听见妈妈做早饭的声音，心里很开心。", "Wǒ Tīng Jiàn Mā Ma Zuò Zǎo Fàn De Shēng Yīn, Xīn Lǐ Hěn Kāi Xīn.", "Tôi nghe thấy tiếng mẹ làm bữa sáng, trong lòng rất vui."], [185.521, 189.057, "我醒来以后，先喝一杯水。", "Wǒ Xǐng Lái Yǐ Hòu, Xiān Hē Yì Bēi Shuǐ.", "Tỉnh dậy, tôi uống một cốc nước trước."], [189.057, 194.003, "然后我吃早饭，吃得很慢，也很好吃。", "Rán Hòu Wǒ Chī Zǎo Fàn, Chī Dé Hěn Màn, Yě Hěn Hǎo Chī.", "Sau đó tôi ăn sáng, ăn chậm rãi mà thấy rất ngon."], [194.003, 198.111, "上课的时候也能听清楚老师的话。", "Shàng Kè De Shí Hòu Yě Néng Tīng Qīng Chǔ Lǎo Shī De Huà.", "Trong lớp tôi cũng nghe rõ lời thầy."], [198.111, 201.688, "老师的问题，我也能回答了。", "Lǎo Shī De Wèn Tí, Wǒ Yě Néng Huí Dá Le.", "Câu hỏi của thầy, tôi cũng trả lời được."], [201.688, 208.84, "我的作业比以前快多了，放学以后，我还能跟同学一起玩一会儿。", "Wǒ De Zuò Yè Bǐ Yǐ Qián Kuài Duō Le, Fàng Xué Yǐ Hòu, Wǒ Hái Néng Gēn Tóng Xué Yì Qǐ Wán Yí Huì Ér.", "Bài tập của tôi làm nhanh hơn trước nhiều, tan học rồi tôi còn được chơi cùng các bạn một lúc."], [208.84, 212.204, "同学说我看起来有精神了。", "Tóng Xué Shuō Wǒ Kàn Qǐ Lái Yǒu Jīng Shén Le.", "Bạn nói tôi trông có tinh thần hơn."], [212.204, 215.736, "同学问我：“你用了什么办法？”", "Tóng Xué Wèn Wǒ: \"Nǐ Yòng Le Shén Me Bàn Fǎ?\"", "Bạn hỏi tôi: \"Cậu dùng cách gì vậy?\""], [215.736, 222.285, "我笑着说：“早一点儿睡觉，就是我的办法，你也试一试吧！”", "Wǒ Xiào Zhe Shuō: \"Zǎo Yì Diǎn Ér Shuì Jiào, Jiù Shì Wǒ De Bàn Fǎ, Nǐ Yě Shì Yí Shì Ba!\"", "Tôi cười nói: \"Ngủ sớm hơn một chút, đó chính là cách của mình, cậu cũng thử xem nhé!\""], [222.285, 227.017, "一个月以后，我的成绩也比以前好了。", "Yí Gè Yuè Yǐ Hòu, Wǒ De Chéng Jì Yě Bǐ Yǐ Qián Hǎo Le.", "Một tháng sau, thành tích của tôi cũng tốt hơn trước."], [227.017, 232.2, "现在我早上精神很好，学习也比以前顺利。", "Xiàn Zài Wǒ Zǎo Shàng Jīng Shén Hěn Hǎo, Xué Xí Yě Bǐ Yǐ Qián Shùn Lì.", "Bây giờ buổi sáng tôi tỉnh táo, học cũng thuận hơn trước."], [232.2, 241.612, "晚上十一点以前，房间里的灯就关了，家里很安静，我很快就睡着了，心里很舒服。", "Wǎn Shàng Shí Yī Diǎn Yǐ Qián, Fáng Jiān Lǐ De Dēng Jiù Guān Le, Jiā Lǐ Hěn Ān Jìng, Wǒ Hěn Kuài Jiù Shuì Zháo Le, Xīn Lǐ Hěn Shū Fú.", "Trước mười một giờ tối, đèn trong phòng đã tắt, trong nhà rất yên tĩnh, tôi nhanh chóng ngủ thiếp đi, trong lòng rất dễ chịu."], [241.612, 244.88, "我想把这个习惯一直留着。", "Wǒ Xiǎng Bǎ Zhè Ge Xí Guàn Yì Zhí Liú Zhe.", "Tôi muốn giữ thói quen này mãi."], [244.88, 251.0, "妈妈说：“你现在每天都很有精神，妈妈看了真高兴。”", "Mā Ma Shuō: \"Nǐ Xiàn Zài Měi Tiān Dōu Hěn Yǒu Jīng Shén, Mā Ma Kàn Le Zhēn Gāo Xìng.\"", "Mẹ nói: \"Bây giờ ngày nào con cũng tỉnh táo, mẹ nhìn thấy thật sự rất vui.\""]]}, "hsk3-02": {"dur": 262.75, "cues": [[8.057, 11.157, "你们有没有拿错过东西？", "Nǐ Men Yǒu Méi Yǒu Ná Cuò Guò Dōng Xī?", "Bạn đã bao giờ cầm nhầm đồ chưa?"], [11.157, 14.161, "我们的笔记本是一样的。", "Wǒ Men De Bǐ Jì Běn Shì Yí Yàng De.", "Vở ghi của chúng tôi giống hệt nhau."], [14.161, 17.694, "两本笔记本上都没有名字。", "Liǎng Běn Bǐ Jì Běn Shàng Dōu Méi Yǒu Míng Zi.", "Cả hai cuốn vở đều không ghi tên."], [17.694, 23.026, "星期二下午，我把同学的笔记本带回了家。", "Xīng Qī Èr Xià Wǔ, Wǒ Bǎ Tóng Xué De Bǐ Jì Běn Dài Huí Le Jiā.", "Chiều thứ Ba tôi mang nhầm vở của bạn về nhà."], [23.026, 28.55, "那天下课以后，我收拾书包的时候太着急了。", "Nà Tiān Xià Kè Yǐ Hòu, Wǒ Shōu Shi Shū Bāo De Shí Hòu Tài Zháo Jí Le.", "Hôm đó tan học, lúc dọn cặp tôi vội quá."], [28.55, 34.064, "我没有看清楚，就把她的本子放进了我的包里。", "Wǒ Méi Yǒu Kàn Qīng Chǔ, Jiù Bǎ Tā De Běn Zi Fàng Jìn Le Wǒ De Bāo Lǐ.", "Tôi không nhìn kỹ, cứ thế bỏ vở của bạn vào cặp mình."], [34.064, 37.956, "她找了很久，以为自己弄丢了。", "Tā Zhǎo Le Hěn Jiǔ, Yǐ Wéi Zì Jǐ Nòng Diū Le.", "Bạn tìm rất lâu và tưởng mình làm mất."], [37.956, 41.08, "她在教室里找了三遍。", "Tā Zài Jiào Shì Lǐ Zhǎo Le Sān Biàn.", "Bạn tìm trong lớp đến ba lượt."], [41.08, 45.476, "她问同学：“你们看见我的笔记本了吗？”", "Tā Wèn Tóng Xué: \"Nǐ Men Kàn Jiàn Wǒ De Bǐ Jì Běn Le Ma?\"", "Bạn hỏi các bạn: \"Các cậu có thấy vở của tớ không?\""], [45.476, 48.483, "同学都说没有看见。", "Tóng Xué Dōu Shuō Méi Yǒu Kàn Jiàn.", "Các bạn đều nói không thấy."], [48.483, 53.023, "她心里很着急，因为第二天有考试。", "Tā Xīn Lǐ Hěn Zháo Jí, Yīn Wèi Dì Èr Tiān Yǒu Kǎo Shì.", "Bạn rất sốt ruột vì ngày mai có bài kiểm tra."], [53.023, 56.866, "笔记本里都是她写的重要内容。", "Bǐ Jì Běn Lǐ Dōu Shì Tā Xiě De Zhòng Yào Nèi Róng.", "Trong vở toàn là nội dung quan trọng bạn đã ghi."], [56.866, 61.742, "晚上我打开包，才发现那不是我的本子。", "Wǎn Shàng Wǒ Dǎ Kāi Bāo, Cái Fā Xiàn Nà Bú Shì Wǒ De Běn Zi.", "Tối tôi mở cặp mới phát hiện đó không phải vở của tôi."], [61.742, 67.17, "我看见本子上的名字，心里一下子紧张起来。", "Wǒ Kàn Jiàn Běn Zi Shàng De Míng Zi, Xīn Lǐ Yí Xià Zi Jǐn Zhāng Qǐ Lái.", "Nhìn thấy tên trên vở, lòng tôi bỗng căng thẳng hẳn lên."], [67.17, 70.751, "我想，她现在一定很着急。", "Wǒ Xiǎng, Tā Xiàn Zài Yí Dìng Hěn Zháo Jí.", "Tôi nghĩ, lúc này bạn ấy chắc chắn đang rất sốt ruột."], [70.751, 74.643, "我马上给她打电话，向她道歉。", "Wǒ Mǎ Shàng Gěi Tā Dǎ Diàn Huà, Xiàng Tā Dào Qiàn.", "Tôi gọi cho bạn ngay và xin lỗi."], [74.643, 80.455, "电话里，我说：“对不起，我拿错了你的笔记本。”", "Diàn Huà Lǐ, Wǒ Shuō: \"Duì Bù Qǐ, Wǒ Ná Cuò Le Nǐ De Bǐ Jì Běn.\"", "Trong điện thoại, tôi nói: \"Xin lỗi, tớ cầm nhầm vở của cậu.\""], [80.455, 85.139, "她问：“真的是在你那儿吗？我找了很久。”", "Tā Wèn: \"Zhēn De Shì Zài Nǐ Nà Ér Ma? Wǒ Zhǎo Le Hěn Jiǔ.\"", "Bạn hỏi: \"Thật là ở chỗ cậu à? Tớ tìm mãi.\""], [85.139, 91.479, "我说：“是的，你放心，明天早上我一定带给你。”", "Wǒ Shuō: \"Shì De, Nǐ Fàng Xīn, Míng Tiān Zǎo Shàng Wǒ Yí Dìng Dài Gěi Nǐ.\"", "Tôi nói: \"Ừ, cậu yên tâm, sáng mai tớ nhất định mang cho cậu.\""], [91.479, 96.316, "她说：“太好了，我还以为找不到了。”", "Tā Shuō: \"Tài Hǎo Le, Wǒ Hái Yǐ Wéi Zhǎo Bú Dào Le.\"", "Bạn nói: \"Tốt quá, tớ còn tưởng không tìm lại được.\""], [96.316, 102.008, "我说：“今天太晚了，我明天七点就去学校。”", "Wǒ Shuō: \"Jīn Tiān Tài Wǎn Le, Wǒ Míng Tiān Qī Diǎn Jiù Qù Xué Xiào.\"", "Tôi nói: \"Hôm nay muộn quá rồi, mai bảy giờ tớ đến trường.\""], [102.008, 108.994, "她笑着说：“没关系，你打电话来，我就放心了，明天见！”", "Tā Xiào Zhe Shuō: \"Méi Guān Xì, Nǐ Dǎ Diàn Huà Lái, Wǒ Jiù Fàng Xīn Le, Míng Tiān Jiàn!\"", "Bạn cười nói: \"Không sao, cậu gọi đến là tớ yên tâm rồi, mai gặp nhé!\""], [108.994, 112.934, "打完电话，我心里还是不舒服。", "Dǎ Wán Diàn Huà, Wǒ Xīn Lǐ Hái Shì Bù Shū Fú.", "Gọi xong, trong lòng tôi vẫn thấy khó chịu."], [112.934, 117.522, "我在她的笔记本里放了一张小纸条。", "Wǒ Zài Tā De Bǐ Jì Běn Lǐ Fàng Le Yì Zhāng Xiǎo Zhǐ Tiáo.", "Tôi đặt một mẩu giấy nhỏ vào vở của bạn."], [117.522, 122.88, "纸条上写着：对不起，明天请你喝茶。", "Zhǐ Tiáo Shàng Xiě Zhe: Duì Bù Qǐ, Míng Tiān Qǐng Nǐ Hē Chá.", "Trên giấy viết: Xin lỗi, mai tớ mời cậu uống trà."], [122.88, 127.228, "妈妈知道了这件事，说我做得对。", "Mā Ma Zhī Dào Le Zhè Jiàn Shì, Shuō Wǒ Zuò Dé Duì.", "Mẹ biết chuyện này, nói tôi làm đúng."], [127.228, 134.536, "她说：“做错了事，要马上说清楚，你做到了，妈妈很高兴。”", "Tā Shuō: \"Zuò Cuò Le Shì, Yào Mǎ Shàng Shuō Qīng Chǔ, Nǐ Zuò Dào Le, Mā Ma Hěn Gāo Xìng.\"", "Mẹ nói: \"Làm sai thì phải nói rõ ngay, con làm được rồi, mẹ rất vui.\""], [134.536, 137.684, "第二天，我起得很早。", "Dì Èr Tiān, Wǒ Qǐ Dé Hěn Zǎo.", "Hôm sau, tôi dậy rất sớm."], [137.684, 143.174, "妈妈给我做了早饭，我只吃了几口就出门了。", "Mā Ma Gěi Wǒ Zuò Le Zǎo Fàn, Wǒ Zhǐ Chī Le Jǐ Kǒu Jiù Chū Mén Le.", "Mẹ làm bữa sáng cho tôi, tôi chỉ ăn vài miếng rồi ra khỏi nhà."], [143.174, 148.218, "我在学校门口等她，心里有点儿紧张。", "Wǒ Zài Xué Xiào Mén Kǒu Děng Tā, Xīn Lǐ Yǒu Diǎn Ér Jǐn Zhāng.", "Tôi đợi bạn ở cổng trường, lòng hơi hồi hộp."], [148.218, 152.857, "她来了以后，我先说了一声对不起。", "Tā Lái Le Yǐ Hòu, Wǒ Xiān Shuō Le Yì Shēng Duì Bù Qǐ.", "Bạn đến, tôi nói một tiếng xin lỗi trước."], [152.857, 158.525, "第二天我把笔记本还给她，还请她喝了一杯茶。", "Dì Èr Tiān Wǒ Bǎ Bǐ Jì Běn Hái Gěi Tā, Hái Qǐng Tā Hē Le Yì Bēi Chá.", "Hôm sau tôi trả vở và mời bạn một cốc trà."], [158.525, 163.617, "喝茶的时候，她看见了笔记本里的纸条。", "Hē Chá De Shí Hòu, Tā Kàn Jiàn Le Bǐ Jì Běn Lǐ De Zhǐ Tiáo.", "Lúc uống trà, bạn nhìn thấy mẩu giấy trong vở."], [163.617, 167.369, "她笑着说：“我已经不生气了。”", "Tā Xiào Zhe Shuō: \"Wǒ Yǐ Jīng Bù Shēng Qì Le.\"", "Bạn cười nói: \"Tớ hết giận rồi.\""], [167.369, 171.285, "她说没关系，我们还是好朋友。", "Tā Shuō Méi Guān Xì, Wǒ Men Hái Shì Hǎo Péng Yǒu.", "Bạn nói không sao, chúng tôi vẫn là bạn tốt."], [171.285, 176.593, "她还告诉我，她昨天晚上也很担心考试。", "Tā Hái Gào Sù Wǒ, Tā Zuó Tiān Wǎn Shàng Yě Hěn Dān Xīn Kǎo Shì.", "Bạn còn bảo tôi, tối qua bạn cũng rất lo cho bài kiểm tra."], [176.593, 183.136, "我说：“谢谢你不生气，以后我的东西，我都写上名字。”", "Wǒ Shuō: \"Xiè Xie Nǐ Bù Shēng Qì, Yǐ Hòu Wǒ De Dōng Xī, Wǒ Dōu Xiě Shàng Míng Zi.\"", "Tôi nói: \"Cảm ơn cậu không giận, từ nay đồ của tớ, tớ đều ghi tên lên.\""], [183.136, 187.94, "她收到笔记本以后，还帮我检查了作业。", "Tā Shōu Dào Bǐ Jì Běn Yǐ Hòu, Hái Bāng Wǒ Jiǎn Chá Le Zuò Yè.", "Bạn nhận vở còn giúp tôi xem bài."], [187.94, 191.208, "她发现我写错了一个词。", "Tā Fā Xiàn Wǒ Xiě Cuò Le Yí Gè Cí.", "Bạn phát hiện tôi viết sai một từ."], [191.208, 198.554, "她慢慢讲给我听，我很快就明白了，我说：“谢谢你，你真好。”", "Tā Màn Màn Jiǎng Gěi Wǒ Tīng, Wǒ Hěn Kuài Jiù Míng Bai Le, Wǒ Shuō: \"Xiè Xie Nǐ, Nǐ Zhēn Hǎo.\"", "Bạn giảng chậm rãi cho tôi nghe, tôi nhanh chóng hiểu ra, tôi nói: \"Cảm ơn cậu, cậu tốt thật.\""], [198.554, 203.454, "我们说好，以后借东西要写个纸条。", "Wǒ Men Shuō Hǎo, Yǐ Hòu Jiè Dōng Xī Yào Xiě Gè Zhǐ Tiáo.", "Chúng tôi hẹn sau này mượn đồ phải viết giấy."], [203.454, 206.286, "这样就不会再拿错。", "Zhè Yàng Jiù Bú Huì Zài Ná Cuò.", "Như vậy sẽ không lấy nhầm nữa."], [206.286, 210.202, "一个星期以后，她借给我一本书。", "Yí Gè Xīng Qī Yǐ Hòu, Tā Jiè Gěi Wǒ Yì Běn Shū.", "Một tuần sau, bạn cho tôi mượn một cuốn sách."], [210.202, 215.798, "她在书里放了一张纸条，上面写着她的名字。", "Tā Zài Shū Lǐ Fàng Le Yì Zhāng Zhǐ Tiáo, Shàng Miàn Xiě Zhe Tā De Míng Zi.", "Bạn đặt một mẩu giấy trong sách, trên đó viết tên bạn."], [215.798, 220.626, "我看完书，把书和纸条一起还给她。", "Wǒ Kàn Wán Shū, Bǎ Shū Hé Zhǐ Tiáo Yì Qǐ Huán Gěi Tā.", "Đọc xong sách, tôi trả lại cả sách lẫn mẩu giấy cho bạn."], [220.626, 227.881, "她高兴地说：“这个办法真有用，我一看纸条就知道是我的书了！”", "Tā Gāo Xìng Dì Shuō: \"Zhè Ge Bàn Fǎ Zhēn Yǒu Yòng, Wǒ Yí Kàn Zhǐ Tiáo Jiù Zhī Dào Shì Wǒ De Shū Le!\"", "Bạn vui vẻ nói: \"Cách này thật hữu ích, tớ nhìn mẩu giấy là biết ngay sách của mình rồi!\""], [227.881, 231.221, "那天晚上我睡得很安心。", "Nà Tiān Wǎn Shàng Wǒ Shuì Dé Hěn Ān Xīn.", "Tối hôm đó tôi ngủ rất yên."], [231.221, 236.728, "误会虽然让人不舒服，可是说开了就好了。", "Wù Huì Suī Rán Ràng Rén Bù Shū Fú, Kě Shì Shuō Kāi Le Jiù Hǎo Le.", "Hiểu nhầm tuy khó chịu, nhưng nói ra thì ổn."], [236.728, 241.843, "现在我拿东西以前，都会先看一看名字。", "Xiàn Zài Wǒ Ná Dōng Xī Yǐ Qián, Dōu Huì Xiān Kàn Yí Kàn Míng Zi.", "Giờ trước khi cầm đồ, tôi đều xem tên trước."], [241.843, 245.255, "我现在更知道先问清楚。", "Wǒ Xiàn Zài Gèng Zhī Dào Xiān Wèn Qīng Chǔ.", "Bây giờ tôi biết hỏi cho rõ trước."], [245.255, 252.963, "这件小事以后，我们比以前更开心了，常常一起说话，一起做作业。", "Zhè Jiàn Xiǎo Shì Yǐ Hòu, Wǒ Men Bǐ Yǐ Qián Gèng Kāi Xīn Le, Cháng Cháng Yì Qǐ Shuō Huà, Yì Qǐ Zuò Zuò Yè.", "Sau chuyện nhỏ này, chúng tôi vui hơn trước, thường nói chuyện cùng nhau, làm bài cùng nhau."]]}, "hsk3-03": {"dur": 256.09, "cues": [[8.22, 11.368, "你们家附近有旧书店吗？", "Nǐ Men Jiā Fù Jìn Yǒu Jiù Shū Diàn Ma?", "Gần nhà bạn có hiệu sách cũ không?"], [11.368, 15.14, "我家附近有一家很小的旧书店。", "Wǒ Jiā Fù Jìn Yǒu Yì Jiā Hěn Xiǎo De Jiù Shū Diàn.", "Gần nhà tôi có một hiệu sách cũ rất nhỏ."], [15.14, 18.72, "这家店在一家小饭店的旁边。", "Zhè Jiā Diàn Zài Yì Jiā Xiǎo Fàn Diàn De Páng Biān.", "Hiệu sách này nằm cạnh một quán ăn nhỏ."], [18.72, 23.545, "我第一次去的时候，还以为走错了地方。", "Wǒ Dì Yī Cì Qù De Shí Hòu, Hái Yǐ Wéi Zǒu Cuò Le Dì Fāng.", "Lần đầu đến đó, tôi còn tưởng mình đi nhầm chỗ."], [23.545, 27.965, "店里很安静，只有书和一张旧桌子。", "Diàn Lǐ Hěn Ān Jìng, Zhǐ Yǒu Shū Hé Yì Zhāng Jiù Zhuō Zi.", "Trong tiệm rất yên tĩnh, chỉ có sách và một chiếc bàn cũ."], [27.965, 32.769, "老板是一位头发花白的先生，说话很慢。", "Lǎo Bǎn Shì Yí Wèi Tóu Fa Huā Bái De Xiān Shēng, Shuō Huà Hěn Màn.", "Chủ tiệm là một ông tóc hoa râm, nói rất chậm."], [32.769, 38.568, "他看见我，笑着说：“慢慢看，不买也没关系。”", "Tā Kàn Jiàn Wǒ, Xiào Zhe Shuō: \"Màn Màn Kàn, Bù Mǎi Yě Méi Guān Xì.\"", "Thấy tôi, ông cười nói: \"Cứ xem từ từ, không mua cũng không sao.\""], [38.568, 42.34, "店里的书不新，可是种类很多。", "Diàn Lǐ De Shū Bù Xīn, Kě Shì Zhǒng Lèi Hěn Duō.", "Sách trong tiệm không mới, nhưng có rất nhiều loại."], [42.34, 46.04, "有故事书，也有学汉语的书。", "Yǒu Gù Shì Shū, Yě Yǒu Xué Hàn Yǔ De Shū.", "Có sách truyện, cũng có sách học tiếng Trung."], [46.04, 49.853, "有的书很便宜，只要几块钱。", "Yǒu De Shū Hěn Pián Yi, Zhǐ Yào Jǐ Kuài Qián.", "Có cuốn rất rẻ, chỉ vài đồng."], [49.853, 53.985, "我每个星期六都去那里坐一个小时。", "Wǒ Měi Gè Xīng Qī Liù Dōu Qù Nà Lǐ Zuò Yí Gè Xiǎo Shí.", "Mỗi thứ Bảy tôi đều đến đó ngồi một tiếng."], [53.985, 57.493, "我常常坐在窗户旁边看书。", "Wǒ Cháng Cháng Zuò Zài Chuāng Hu Páng Biān Kàn Shū.", "Tôi thường ngồi cạnh cửa sổ đọc sách."], [57.493, 62.513, "外面的人走来走去，店里还是很安静。", "Wài Miàn De Rén Zǒu Lái Zǒu Qù, Diàn Lǐ Hái Shì Hěn Ān Jìng.", "Người ngoài đường đi qua đi lại, trong tiệm vẫn rất yên tĩnh."], [62.513, 66.669, "有时候我买一本，有时候只是看看。", "Yǒu Shí Hòu Wǒ Mǎi Yì Běn, Yǒu Shí Hòu Zhǐ Shì Kàn Kàn.", "Có lúc tôi mua một cuốn, có lúc chỉ xem."], [66.669, 71.053, "我觉得，安静地看书是一件幸福的事。", "Wǒ Jué De, Ān Jìng Dì Kàn Shū Shì Yí Jiàn Xìng Fú De Shì.", "Tôi thấy yên lặng đọc sách là một việc hạnh phúc."], [71.053, 74.273, "老板有时候给我一杯茶。", "Lǎo Bǎn Yǒu Shí Hòu Gěi Wǒ Yì Bēi Chá.", "Đôi khi ông chủ cho tôi một cốc trà."], [74.273, 79.691, "他说：“看书的时候，喝一点儿热茶很舒服。”", "Tā Shuō: \"Kàn Shū De Shí Hòu, Hē Yì Diǎn Ér Rè Chá Hěn Shū Fú.\"", "Ông nói: \"Lúc đọc sách, uống chút trà nóng thì rất dễ chịu.\""], [79.691, 82.935, "老板还记得我喜欢的作家。", "Lǎo Bǎn Hái Jì De Wǒ Xǐ Huan De Zuò Jiā.", "Chủ tiệm còn nhớ nhà văn tôi thích."], [82.935, 86.635, "我喜欢的作家写了很多短故事。", "Wǒ Xǐ Huan De Zuò Jiā Xiě Le Hěn Duō Duǎn Gù Shì.", "Nhà văn tôi thích đã viết nhiều truyện ngắn."], [86.635, 91.788, "老板说，他年轻的时候也喜欢这个作家。", "Lǎo Bǎn Shuō, Tā Nián Qīng De Shí Hòu Yě Xǐ Huan Zhè Ge Zuò Jiā.", "Ông chủ nói, hồi trẻ ông cũng thích nhà văn này."], [91.788, 95.344, "有一次他推荐了一本短故事。", "Yǒu Yí Cì Tā Tuī Jiàn Le Yì Běn Duǎn Gù Shì.", "Có lần ông giới thiệu một tập truyện ngắn."], [95.344, 100.412, "他把书给我，说：“这本你一定会喜欢。”", "Tā Bǎ Shū Gěi Wǒ, Shuō: \"Zhè Běn Nǐ Yí Dìng Huì Xǐ Huan.\"", "Ông đưa sách cho tôi, nói: \"Cuốn này cháu nhất định sẽ thích.\""], [100.412, 103.104, "我问：“多少钱？”", "Wǒ Wèn: \"Duō Shǎo Qián?\"", "Tôi hỏi: \"Bao nhiêu tiền ạ?\""], [103.104, 107.601, "他说：“三块钱，你先拿去看吧。”", "Tā Shuō: \"Sān Kuài Qián, Nǐ Xiān Ná Qù Kàn Ba.\"", "Ông nói: \"Ba đồng, cháu cứ mang về xem trước đi.\""], [107.601, 110.701, "我用一个下午就看完了。", "Wǒ Yòng Yí Gè Xià Wǔ Jiù Kàn Wán Le.", "Tôi đọc hết trong một buổi chiều."], [110.701, 119.441, "书里有一个故事，写的是一个小花园，那里花很多，树也很多，还有一条小路。", "Shū Lǐ Yǒu Yí Gè Gù Shì, Xiě De Shì Yí Gè Xiǎo Huā Yuán, Nà Lǐ Huā Hěn Duō, Shù Yě Hěn Duō, Hái Yǒu Yì Tiáo Xiǎo Lù.", "Trong sách có một câu chuyện viết về một khu vườn nhỏ, ở đó hoa rất nhiều, cây cũng rất nhiều, còn có một con đường nhỏ."], [119.441, 123.252, "我看得很认真，忘记了吃晚饭。", "Wǒ Kàn Dé Hěn Rèn Zhēn, Wàng Jì Le Chī Wǎn Fàn.", "Tôi đọc rất chăm chú, quên cả ăn tối."], [123.252, 127.143, "看完以后，我又回去跟他聊天。", "Kàn Wán Yǐ Hòu, Wǒ Yòu Huí Qù Gēn Tā Liáo Tiān.", "Đọc xong tôi quay lại nói chuyện với ông."], [127.143, 131.371, "我告诉他，我最喜欢最后一个故事。", "Wǒ Gào Sù Tā, Wǒ Zuì Xǐ Huan Zuì Hòu Yí Gè Gù Shì.", "Tôi bảo ông, tôi thích nhất câu chuyện cuối cùng."], [131.371, 135.192, "他问我为什么，我说了我的想法。", "Tā Wèn Wǒ Wèi Shén Me, Wǒ Shuō Le Wǒ De Xiǎng Fǎ.", "Ông hỏi vì sao, tôi nói suy nghĩ của mình."], [135.192, 139.714, "他说年轻人肯慢慢看书，他很高兴。", "Tā Shuō Nián Qīng Rén Kěn Màn Màn Kàn Shū, Tā Hěn Gāo Xìng.", "Ông nói người trẻ chịu đọc chậm thì ông rất vui."], [139.714, 143.822, "有一个星期六，我因为考试没有去。", "Yǒu Yí Gè Xīng Qī Liù, Wǒ Yīn Wèi Kǎo Shì Méi Yǒu Qù.", "Có một thứ Bảy, vì kỳ thi nên tôi không đến."], [143.822, 149.394, "下一个星期六，我刚走进小店，老板就笑了。", "Xià Yí Gè Xīng Qī Liù, Wǒ Gāng Zǒu Jìn Xiǎo Diàn, Lǎo Bǎn Jiù Xiào Le.", "Thứ Bảy sau, tôi vừa bước vào tiệm, ông chủ đã cười."], [149.394, 154.808, "他说：“你上个星期没来，我还有点儿担心。”", "Tā Shuō: \"Nǐ Shàng Gè Xīng Qī Méi Lái, Wǒ Hái Yǒu Diǎn Ér Dān Xīn.\"", "Ông nói: \"Tuần trước cháu không đến, ông còn hơi lo.\""], [154.808, 158.243, "他从桌子下面拿出一本书。", "Tā Cóng Zhuō Zi Xià Miàn Ná Chū Yì Běn Shū.", "Ông lấy ra một cuốn sách từ dưới bàn."], [158.243, 164.296, "他笑着说：“这本是给你留的，我知道你一定会来。”", "Tā Xiào Zhe Shuō: \"Zhè Běn Shì Gěi Nǐ Liú De, Wǒ Zhī Dào Nǐ Yí Dìng Huì Lái.\"", "Ông cười nói: \"Cuốn này để dành cho cháu đấy, ông biết cháu nhất định sẽ đến.\""], [164.296, 169.076, "我这才知道，他一直记得我想看这本书。", "Wǒ Zhè Cái Zhī Dào, Tā Yì Zhí Jì De Wǒ Xiǎng Kàn Zhè Běn Shū.", "Lúc đó tôi mới biết, ông vẫn luôn nhớ cuốn sách tôi muốn đọc."], [169.076, 173.174, "我心里很感动，说了好几次谢谢。", "Wǒ Xīn Lǐ Hěn Gǎn Dòng, Shuō Le Hǎo Jǐ Cì Xiè Xie.", "Trong lòng tôi rất cảm động, nói cảm ơn mấy lần."], [173.174, 178.53, "那天下午，我帮老板把很多书搬到了店里。", "Nà Tiān Xià Wǔ, Wǒ Bāng Lǎo Bǎn Bǎ Hěn Duō Shū Bān Dào Le Diàn Lǐ.", "Chiều hôm đó, tôi giúp ông chủ chuyển rất nhiều sách vào trong tiệm."], [178.53, 184.274, "书很重，我的手都累了，可是我心里很高兴。", "Shū Hěn Zhòng, Wǒ De Shǒu Dōu Lèi Le, Kě Shì Wǒ Xīn Lǐ Hěn Gāo Xìng.", "Sách rất nặng, tay tôi mỏi cả rồi, nhưng trong lòng tôi rất vui."], [184.274, 191.866, "老板笑着说：“谢谢你，今天你可以多坐一会儿，我再给你一杯热茶。”", "Lǎo Bǎn Xiào Zhe Shuō: \"Xiè Xie Nǐ, Jīn Tiān Nǐ Kě Yǐ Duō Zuò Yí Huì Ér, Wǒ Zài Gěi Nǐ Yì Bēi Rè Chá.\"", "Ông chủ cười nói: \"Cảm ơn cháu, hôm nay cháu cứ ngồi thêm một lúc, ông cho cháu thêm một cốc trà nóng nữa.\""], [191.866, 195.038, "我带朋友去过一次小店。", "Wǒ Dài Péng Yǒu Qù Guò Yí Cì Xiǎo Diàn.", "Tôi từng đưa bạn đến tiệm nhỏ một lần."], [195.038, 201.666, "朋友高兴地说：“这里真安静，我很喜欢，我也想常来。”", "Péng Yǒu Gāo Xìng Dì Shuō: \"Zhè Lǐ Zhēn Ān Jìng, Wǒ Hěn Xǐ Huan, Wǒ Yě Xiǎng Cháng Lái.\"", "Bạn vui vẻ nói: \"Ở đây yên tĩnh thật, tớ rất thích, tớ cũng muốn thường đến.\""], [201.666, 207.563, "老板听了，笑着说：“好，好，欢迎你们常来！”", "Lǎo Bǎn Tīng Le, Xiào Zhe Shuō: \"Hǎo, Hǎo, Huān Yíng Nǐ Men Cháng Lái!\"", "Ông chủ nghe xong, cười nói: \"Tốt, tốt, hoan nghênh các cháu thường đến!\""], [207.563, 213.375, "现在，每个星期六，小店里常常有我们两个人。", "Xiàn Zài, Měi Gè Xīng Qī Liù, Xiǎo Diàn Lǐ Cháng Cháng Yǒu Wǒ Men Liǎng Gè Rén.", "Bây giờ, mỗi thứ Bảy, trong tiệm thường có hai chúng tôi."], [213.375, 216.859, "我们看书，也跟老板聊天。", "Wǒ Men Kàn Shū, Yě Gēn Lǎo Bǎn Liáo Tiān.", "Chúng tôi đọc sách, cũng trò chuyện với ông chủ."], [216.859, 224.537, "老板说，看书的人多了，店里的人说着话，笑着，他听了很高兴。", "Lǎo Bǎn Shuō, Kàn Shū De Rén Duō Le, Diàn Lǐ De Rén Shuō Zhe Huà, Xiào Zhe, Tā Tīng Le Hěn Gāo Xìng.", "Ông chủ nói, người đọc sách nhiều lên, người trong tiệm nói chuyện, mỉm cười, ông nghe thấy rất vui."], [224.537, 229.869, "我觉得，小店不大，可是里面有很多故事。", "Wǒ Jué De, Xiǎo Diàn Bù Dà, Kě Shì Lǐ Miàn Yǒu Hěn Duō Gù Shì.", "Tôi thấy, tiệm không lớn, nhưng bên trong có rất nhiều câu chuyện."], [229.869, 233.689, "这家小店已经成了我的一个习惯。", "Zhè Jiā Xiǎo Diàn Yǐ Jīng Chéng Le Wǒ De Yí Gè Xí Guàn.", "Quán nhỏ này đã thành một thói quen của tôi."], [233.689, 237.389, "我希望，这家小店一直开着。", "Wǒ Xī Wàng, Zhè Jiā Xiǎo Diàn Yì Zhí Kāi Zhe.", "Tôi hy vọng hiệu sách nhỏ này cứ mở mãi."], [237.389, 246.825, "我也希望，以后每个星期六，我都能去坐一个小时，看书，跟老板说话，心里很开心。", "Wǒ Yě Xī Wàng, Yǐ Hòu Měi Gè Xīng Qī Liù, Wǒ Dōu Néng Qù Zuò Yí Gè Xiǎo Shí, Kàn Shū, Gēn Lǎo Bǎn Shuō Huà, Xīn Lǐ Hěn Kāi Xīn.", "Tôi cũng hy vọng sau này mỗi thứ Bảy đều đến ngồi được một tiếng, đọc sách, trò chuyện với ông chủ, trong lòng rất vui."]]}, "hsk3-04": {"dur": 260.23, "cues": [[6.827, 11.271, "你们小时候，是谁教你们骑自行车的？", "Nǐ Men Xiǎo Shí Hòu, Shì Shuí Jiào Nǐ Men Qí Zì Xíng Chē De?", "Hồi nhỏ, ai là người dạy bạn đi xe đạp?"], [11.271, 15.931, "小时候我不敢骑自行车，总怕摔倒。", "Xiǎo Shí Hòu Wǒ Bù Gǎn Qí Zì Xíng Chē, Zǒng Pà Shuāi Dǎo.", "Hồi nhỏ tôi không dám đi xe đạp vì sợ ngã."], [15.931, 20.831, "别的孩子骑车的时候，我只在旁边看。", "Bié De Hái Zi Qí Chē De Shí Hòu, Wǒ Zhǐ Zài Páng Biān Kàn.", "Khi các bạn khác đạp xe, tôi chỉ đứng bên cạnh nhìn."], [20.831, 25.588, "他们骑得很快，我很想跟他们一起玩。", "Tā Men Qí Dé Hěn Kuài, Wǒ Hěn Xiǎng Gēn Tā Men Yì Qǐ Wán.", "Các bạn đạp rất nhanh, tôi rất muốn chơi cùng."], [25.588, 29.984, "有一天，爸爸带回来一辆旧自行车。", "Yǒu Yì Tiān, Bà Ba Dài Huí Lái Yí Liàng Jiù Zì Xíng Chē.", "Một hôm, bố mang về một chiếc xe đạp cũ."], [29.984, 33.324, "车不高，正好合适我。", "Chē Bù Gāo, Zhèng Hǎo Hé Shì Wǒ.", "Xe không cao, vừa hợp với tôi."], [33.324, 39.784, "爸爸笑着说：“这个星期六，我教你，你一定能学会。”", "Bà Ba Xiào Zhe Shuō: \"Zhè Ge Xīng Qī Liù, Wǒ Jiào Nǐ, Nǐ Yí Dìng Néng Xué Huì.\"", "Bố cười nói: \"Thứ Bảy này bố dạy con, con nhất định sẽ học được.\""], [39.784, 43.05, "我又高兴，又有点儿怕。", "Wǒ Yòu Gāo Xìng, Yòu Yǒu Diǎn Ér Pà.", "Tôi vừa vui, lại vừa hơi sợ."], [43.05, 47.566, "星期六早上，我们去了家附近的公园。", "Xīng Qī Liù Zǎo Shàng, Wǒ Men Qù Le Jiā Fù Jìn De Gōng Yuán.", "Sáng thứ Bảy, chúng tôi đến công viên gần nhà."], [47.566, 51.711, "公园里人不多，路又长又安静。", "Gōng Yuán Lǐ Rén Bù Duō, Lù Yòu Cháng Yòu Ān Jìng.", "Trong công viên không đông người, đường vừa dài vừa yên tĩnh."], [51.711, 56.755, "爸爸说，谁都会摔几次，这很正常。", "Bà Ba Shuō, Shuí Dōu Huì Shuāi Jǐ Cì, Zhè Hěn Zhèng Cháng.", "Bố nói ai cũng ngã vài lần, chuyện đó rất bình thường."], [56.755, 62.063, "我高兴地说：“好，我试一试，我想学！”", "Wǒ Gāo Xìng Dì Shuō: \"Hǎo, Wǒ Shì Yí Shì, Wǒ Xiǎng Xué!\"", "Tôi vui vẻ nói: \"Vâng, con thử xem, con muốn học!\""], [62.063, 66.819, "他在后面扶着车，让我慢慢往前走。", "Tā Zài Hòu Miàn Fú Zhe Chē, Ràng Wǒ Màn Màn Wǎng Qián Zǒu.", "Ông đỡ xe phía sau và bảo tôi đi chậm về phía trước."], [66.819, 70.495, "我坐在车上，心里很紧张。", "Wǒ Zuò Zài Chē Shàng, Xīn Lǐ Hěn Jǐn Zhāng.", "Ngồi trên xe, trong lòng tôi rất hồi hộp."], [70.495, 74.42, "爸爸说：“别怕，我在后面。”", "Bà Ba Shuō: \"Bié Pà, Wǒ Zài Hòu Miàn.\"", "Bố nói: \"Đừng sợ, bố ở phía sau đây.\""], [74.42, 78.504, "我慢慢往前骑，爸爸在后面跑。", "Wǒ Màn Màn Wǎng Qián Qí, Bà Ba Zài Hòu Miàn Pǎo.", "Tôi đạp chậm về phía trước, bố chạy theo phía sau."], [78.504, 82.66, "过了一会儿，爸爸说：“我要放手了。”", "Guò Le Yí Huì Ér, Bà Ba Shuō: \"Wǒ Yào Fàng Shǒu Le.\"", "Một lúc sau, bố nói: \"Bố buông tay đây.\""], [82.66, 86.192, "我说：“再等一下，我怕。”", "Wǒ Shuō: \"Zài Děng Yí Xià, Wǒ Pà.\"", "Tôi nói: \"Đợi một chút nữa, con sợ.\""], [86.192, 89.374, "可是爸爸已经放手了。", "Kě Shì Bà Ba Yǐ Jīng Fàng Shǒu Le.", "Nhưng bố đã buông tay rồi."], [89.374, 93.53, "第一次放手的时候，我真的摔倒了。", "Dì Yī Cì Fàng Shǒu De Shí Hòu, Wǒ Zhēn De Shuāi Dǎo Le.", "Lần đầu buông tay, tôi ngã thật."], [93.53, 97.686, "摔倒的时候，我的膝盖有一点儿疼。", "Shuāi Dǎo De Shí Hòu, Wǒ De Xī Gài Yǒu Yì Diǎn Ér Téng.", "Lúc ngã, đầu gối tôi hơi đau."], [97.686, 101.169, "我坐在地上，不想再试了。", "Wǒ Zuò Zài Dì Shàng, Bù Xiǎng Zài Shì Le.", "Tôi ngồi dưới đất, không muốn thử nữa."], [101.169, 105.061, "爸爸没有笑我，只是把我拉起来。", "Bà Ba Méi Yǒu Xiào Wǒ, Zhǐ Shì Bǎ Wǒ Lā Qǐ Lái.", "Bố không cười tôi, chỉ kéo tôi đứng dậy."], [105.061, 111.041, "爸爸看了看我的膝盖，说：“没关系，休息一会儿。”", "Bà Ba Kàn Le Kàn Wǒ De Xī Gài, Shuō: \"Méi Guān Xì, Xiū Xi Yí Huì Ér.\"", "Bố xem đầu gối của tôi, nói: \"Không sao, nghỉ một lúc đi.\""], [111.041, 116.239, "我们坐下来，喝了一点儿水，休息了十分钟。", "Wǒ Men Zuò Xià Lái, Hē Le Yì Diǎn Ér Shuǐ, Xiū Xi Le Shí Fēn Zhōng.", "Chúng tôi ngồi xuống, uống chút nước, nghỉ mười phút."], [116.239, 120.443, "他说眼睛看着前面，不要看脚下。", "Tā Shuō Yǎn Jīng Kàn Zhe Qián Miàn, Bú Yào Kàn Jiǎo Xià.", "Ông nói mắt nhìn phía trước, đừng nhìn xuống chân."], [120.443, 122.967, "我记住了这句话。", "Wǒ Jì Zhù Le Zhè Jù Huà.", "Tôi nhớ câu đó."], [122.967, 126.502, "我站起来，又试了好几次。", "Wǒ Zhàn Qǐ Lái, Yòu Shì Le Hǎo Jǐ Cì.", "Tôi đứng dậy và thử thêm nhiều lần."], [126.502, 133.322, "第二次，我骑了几米就下来了，爸爸说：“比第一次好多了！”", "Dì Èr Cì, Wǒ Qí Le Jǐ Mǐ Jiù Xià Lái Le, Bà Ba Shuō: \"Bǐ Dì Yī Cì Hǎo Duō Le!\"", "Lần thứ hai, tôi đạp được vài mét rồi xuống xe, bố nói: \"Tốt hơn lần đầu nhiều rồi!\""], [133.322, 137.502, "第三次，我骑得比第二次远一点儿。", "Dì Sān Cì, Wǒ Qí Dé Bǐ Dì Èr Cì Yuǎn Yì Diǎn Ér.", "Lần thứ ba, tôi đạp xa hơn lần thứ hai một chút."], [137.502, 143.917, "爸爸在后面高兴地说：“看前面，对了，你做得真好！”", "Bà Ba Zài Hòu Miàn Gāo Xìng Dì Shuō: \"Kàn Qián Miàn, Duì Le, Nǐ Zuò Dé Zhēn Hǎo!\"", "Bố ở phía sau vui vẻ nói: \"Nhìn phía trước, đúng rồi, con làm tốt lắm!\""], [143.917, 148.625, "妈妈也来了，她给我们带了水和面包。", "Mā Ma Yě Lái Le, Tā Gěi Wǒ Men Dài Le Shuǐ Hé Miàn Bāo.", "Mẹ cũng đến, mang nước và bánh mì cho chúng tôi."], [148.625, 153.995, "妈妈说：“慢慢来，今天学不会也没关系。”", "Mā Ma Shuō: \"Màn Màn Lái, Jīn Tiān Xué Bú Huì Yě Méi Guān Xì.\"", "Mẹ nói: \"Cứ từ từ, hôm nay chưa học được cũng không sao.\""], [153.995, 158.127, "下午，太阳很好，我又上了车。", "Xià Wǔ, Tài Yáng Hěn Hǎo, Wǒ Yòu Shàng Le Chē.", "Buổi chiều, trời nắng đẹp, tôi lại lên xe."], [158.127, 163.387, "这一次，爸爸放手以后，我没有马上摔倒。", "Zhè Yí Cì, Bà Ba Fàng Shǒu Yǐ Hòu, Wǒ Méi Yǒu Mǎ Shàng Shuāi Dǎo.", "Lần này, sau khi bố buông tay, tôi không ngã ngay."], [163.387, 167.591, "我骑了一会儿，心里又高兴又紧张。", "Wǒ Qí Le Yí Huì Ér, Xīn Lǐ Yòu Gāo Xìng Yòu Jǐn Zhāng.", "Tôi đạp một lúc, trong lòng vừa vui vừa hồi hộp."], [167.591, 171.411, "爸爸站在很远的地方，对我笑。", "Bà Ba Zhàn Zài Hěn Yuǎn De Dì Fāng, Duì Wǒ Xiào.", "Bố đứng ở một chỗ rất xa, cười với tôi."], [171.411, 176.147, "我这才知道，我已经自己骑了很久了。", "Wǒ Zhè Cái Zhī Dào, Wǒ Yǐ Jīng Zì Jǐ Qí Le Hěn Jiǔ Le.", "Lúc đó tôi mới biết, mình đã tự đạp được một lúc lâu rồi."], [176.147, 181.959, "那天太阳落山以前，我终于可以自己骑回家了。", "Nà Tiān Tài Yáng Luò Shān Yǐ Qián, Wǒ Zhōng Yú Kě Yǐ Zì Jǐ Qí Huí Jiā Le.", "Trước khi mặt trời lặn hôm đó, tôi cuối cùng đã tự đạp xe về nhà."], [181.959, 186.955, "回家的路上，我骑得很慢，可是很高兴。", "Huí Jiā De Lù Shàng, Wǒ Qí Dé Hěn Màn, Kě Shì Hěn Gāo Xìng.", "Trên đường về nhà, tôi đạp rất chậm, nhưng rất vui."], [186.955, 191.007, "妈妈走在旁边，爸爸走在后面。", "Mā Ma Zǒu Zài Páng Biān, Bà Ba Zǒu Zài Hòu Miàn.", "Mẹ đi bên cạnh, bố đi phía sau."], [191.007, 195.859, "到家以后，我把骑车的事告诉了奶奶。", "Dào Jiā Yǐ Hòu, Wǒ Bǎ Qí Chē De Shì Gào Sù Le Nǎi Nǎi.", "Về đến nhà, tôi kể chuyện đạp xe cho bà nghe."], [195.859, 199.088, "奶奶说：“你真了不起。”", "Nǎi Nǎi Shuō: \"Nǐ Zhēn Liǎo Bù Qǐ.\"", "Bà nói: \"Cháu giỏi thật đấy.\""], [199.088, 206.484, "第二个星期六，我又去公园练了半天，爸爸一直在旁边看着我笑。", "Dì Èr Gè Xīng Qī Liù, Wǒ Yòu Qù Gōng Yuán Liàn Le Bàn Tiān, Bà Ba Yì Zhí Zài Páng Biān Kàn Zhe Wǒ Xiào.", "Thứ Bảy tuần sau, tôi lại ra công viên luyện nửa ngày, bố vẫn luôn ở bên cạnh nhìn tôi cười."], [206.484, 209.723, "这次我一次也没有摔倒。", "Zhè Cì Wǒ Yí Cì Yě Méi Yǒu Shuāi Dǎo.", "Lần này tôi không ngã lần nào."], [209.723, 213.303, "后来我可以骑到学校门口。", "Hòu Lái Wǒ Kě Yǐ Qí Dào Xué Xiào Mén Kǒu.", "Sau tôi đạp được đến cổng trường."], [213.303, 218.755, "我每天早上骑车去学校，晚上再骑回家。", "Wǒ Měi Tiān Zǎo Shàng Qí Chē Qù Xué Xiào, Wǎn Shàng Zài Qí Huí Jiā.", "Mỗi sáng tôi đạp xe đến trường, tối lại đạp về nhà."], [218.755, 223.144, "有时候，我和同学一起骑车回家。", "Yǒu Shí Hòu, Wǒ Hé Tóng Xué Yì Qǐ Qí Chē Huí Jiā.", "Đôi khi, tôi đạp xe về nhà cùng bạn học."], [223.144, 226.748, "现在，弟弟也想学骑车。", "Xiàn Zài, Dì Di Yě Xiǎng Xué Qí Chē.", "Bây giờ, em trai tôi cũng muốn học đạp xe."], [226.748, 234.504, "我笑着对他说：“别怕，谁都会摔几次，哥哥在后面，你放心。”", "Wǒ Xiào Zhe Duì Tā Shuō: \"Bié Pà, Shuí Dōu Huì Shuāi Jǐ Cì, Gē Ge Zài Hòu Miàn, Nǐ Fàng Xīn.\"", "Tôi cười nói với em: \"Đừng sợ, ai cũng ngã vài lần, anh ở phía sau đây, em yên tâm.\""], [234.504, 239.328, "我在后面扶着车，像爸爸那时候一样。", "Wǒ Zài Hòu Miàn Fú Zhe Chē, Xiàng Bà Ba Nà Shí Hòu Yí Yàng.", "Tôi đỡ xe phía sau, giống như bố ngày đó."], [239.328, 243.508, "现在骑自行车已经是我每天的事。", "Xiàn Zài Qí Zì Xíng Chē Yǐ Jīng Shì Wǒ Měi Tiān De Shì.", "Bây giờ đi xe đạp đã là việc mỗi ngày."], [243.508, 250.976, "我到现在还记得爸爸说的话，也记得那天回家的路，心里一直很开心。", "Wǒ Dào Xiàn Zài Hái Jì De Bà Ba Shuō De Huà, Yě Jì De Nà Tiān Huí Jiā De Lù, Xīn Lǐ Yì Zhí Hěn Kāi Xīn.", "Đến bây giờ tôi vẫn nhớ câu nói ấy của bố, cũng nhớ con đường về nhà hôm đó, trong lòng vẫn luôn rất vui."]]}, "hsk3-05": {"dur": 265.53, "cues": [[7.221, 10.273, "你们去过历史博物馆吗？", "Nǐ Men Qù Guò Lì Shǐ Bó Wù Guǎn Ma?", "Bạn đã từng đến bảo tàng lịch sử chưa?"], [10.273, 15.173, "上个星期天，学校组织我们去历史博物馆。", "Shàng Gè Xīng Qī Tiān, Xué Xiào Zǔ Zhī Wǒ Men Qù Lì Shǐ Bó Wù Guǎn.", "Chủ nhật tuần trước trường tổ chức chúng tôi đi bảo tàng lịch sử."], [15.173, 21.06, "老师告诉我们，第二天早上八点在学校门口见。", "Lǎo Shī Gào Sù Wǒ Men, Dì Èr Tiān Zǎo Shàng Bā Diǎn Zài Xué Xiào Mén Kǒu Jiàn.", "Thầy bảo chúng tôi, sáng hôm sau tám giờ gặp ở cổng trường."], [21.06, 25.008, "我很早就睡了，因为我怕来不及。", "Wǒ Hěn Zǎo Jiù Shuì Le, Yīn Wèi Wǒ Pà Lái Bù Jí.", "Tôi ngủ rất sớm vì sợ không kịp."], [25.008, 29.62, "第二天，我和同学一起坐公共汽车去。", "Dì Èr Tiān, Wǒ Hé Tóng Xué Yì Qǐ Zuò Gōng Gòng Qì Chē Qù.", "Hôm sau, tôi đi xe buýt cùng các bạn."], [29.62, 35.576, "车上，老师说：“到了博物馆，要安静，不要跑。”", "Chē Shàng, Lǎo Shī Shuō: \"Dào Le Bó Wù Guǎn, Yào Ān Jìng, Bú Yào Pǎo.\"", "Trên xe, thầy nói: \"Đến bảo tàng, phải giữ yên lặng, không được chạy.\""], [35.576, 39.799, "我们都说：“知道了，我们会安静的！”", "Wǒ Men Dōu Shuō: \"Zhī Dào Le, Wǒ Men Huì Ān Jìng De!\"", "Chúng tôi đều nói: \"Chúng em biết rồi, chúng em sẽ giữ yên lặng ạ!\""], [39.799, 44.459, "博物馆很大，里面有很多旧照片和工具。", "Bó Wù Guǎn Hěn Dà, Lǐ Miàn Yǒu Hěn Duō Jiù Zhào Piàn Hé Gōng Jù.", "Bảo tàng rất lớn, bên trong có nhiều ảnh cũ và dụng cụ."], [44.459, 49.047, "我们走进大门，看见了很多学生和游客。", "Wǒ Men Zǒu Jìn Dà Mén, Kàn Jiàn Le Hěn Duō Xué Shēng Hé Yóu Kè.", "Chúng tôi bước vào cổng lớn, thấy nhiều học sinh và du khách."], [49.047, 54.427, "讲解员告诉大家，这些东西都有自己的故事。", "Jiǎng Jiě Yuán Gào Sù Dà Jiā, Zhè Xiē Dōng Xī Dōu Yǒu Zì Jǐ De Gù Shì.", "Người thuyết minh nói với mọi người mỗi món đồ đều có câu chuyện."], [54.427, 60.143, "讲解员是一位年轻人，说话很慢，也很清楚。", "Jiǎng Jiě Yuán Shì Yí Wèi Nián Qīng Rén, Shuō Huà Hěn Màn, Yě Hěn Qīng Chǔ.", "Người thuyết minh là một người trẻ, nói rất chậm và rất rõ ràng."], [60.143, 64.876, "她说：“大家跟我来，先看旧照片。”", "Tā Shuō: \"Dà Jiā Gēn Wǒ Lái, Xiān Kàn Jiù Zhào Piàn.\"", "Cô nói: \"Mọi người theo tôi, xem ảnh cũ trước.\""], [64.876, 70.016, "照片里，人们穿着旧衣服，骑着自行车。", "Zhào Piàn Lǐ, Rén Men Chuān Zhe Jiù Yī Fu, Qí Zhe Zì Xíng Chē.", "Trong ảnh, mọi người mặc quần áo cũ, đạp xe đạp."], [70.016, 73.884, "同学问：“那时候有公共汽车吗？”", "Tóng Xué Wèn: \"Nà Shí Hòu Yǒu Gōng Gòng Qì Chē Ma?\"", "Một bạn hỏi: \"Thời đó có xe buýt không ạ?\""], [73.884, 81.363, "讲解员笑着说：“有，可是很少，那时候大家更喜欢骑自行车。”", "Jiǎng Jiě Yuán Xiào Zhe Shuō: \"Yǒu, Kě Shì Hěn Shǎo, Nà Shí Hòu Dà Jiā Gèng Xǐ Huan Qí Zì Xíng Chē.\"", "Người thuyết minh cười nói: \"Có, nhưng rất ít, thời đó mọi người thích đi xe đạp hơn.\""], [81.363, 84.439, "我们又看了很多旧工具。", "Wǒ Men Yòu Kàn Le Hěn Duō Jiù Gōng Jù.", "Chúng tôi lại xem nhiều dụng cụ cũ."], [84.439, 88.547, "有的我没见过，也不知道怎么用。", "Yǒu De Wǒ Méi Jiàn Guò, Yě Bù Zhī Dào Zěn Me Yòng.", "Có thứ tôi chưa từng thấy, cũng không biết dùng thế nào."], [88.547, 93.205, "讲解员慢慢告诉我们，每个工具怎么用。", "Jiǎng Jiě Yuán Màn Màn Gào Sù Wǒ Men, Měi Gè Gōng Jù Zěn Me Yòng.", "Người thuyết minh từ từ cho chúng tôi biết mỗi dụng cụ dùng thế nào."], [93.205, 98.297, "我最感兴趣的是一张一百年前的城市地图。", "Wǒ Zuì Gǎn Xìng Qù De Shì Yì Zhāng Yì Bǎi Nián Qián De Chéng Shì Dì Tú.", "Tôi thích nhất một tấm bản đồ thành phố cách đây một trăm năm."], [98.297, 101.541, "我在地图前面站了很久。", "Wǒ Zài Dì Tú Qián Miàn Zhàn Le Hěn Jiǔ.", "Tôi đứng trước tấm bản đồ rất lâu."], [101.541, 105.279, "那时的路很窄，房子也不高。", "Nà Shí De Lù Hěn Zhǎi, Fáng Zi Yě Bù Gāo.", "Lúc đó đường rất hẹp, nhà cũng không cao."], [105.279, 108.907, "我在地图上找我们学校的地方。", "Wǒ Zài Dì Tú Shàng Zhǎo Wǒ Men Xué Xiào De Dì Fāng.", "Tôi tìm vị trí trường chúng tôi trên bản đồ."], [108.907, 114.095, "那时候，那里还没有学校，只有一条小路。", "Nà Shí Hòu, Nà Lǐ Hái Méi Yǒu Xué Xiào, Zhǐ Yǒu Yì Tiáo Xiǎo Lù.", "Thời đó, ở đó chưa có trường, chỉ có một con đường nhỏ."], [114.095, 121.022, "同学笑着说：“现在那条路上的人最多了，大家都喜欢去那儿。”", "Tóng Xué Xiào Zhe Shuō: \"Xiàn Zài Nà Tiáo Lù Shàng De Rén Zuì Duō Le, Dà Jiā Dōu Xǐ Huan Qù Nà Ér.\"", "Bạn cười nói: \"Bây giờ trên con đường đó đông người nhất, ai cũng thích đến đó.\""], [121.022, 128.85, "我看了看地图，又想了想现在的城市，心里很高兴，也很想告诉弟弟。", "Wǒ Kàn Le Kàn Dì Tú, Yòu Xiǎng Le Xiǎng Xiàn Zài De Chéng Shì, Xīn Lǐ Hěn Gāo Xìng, Yě Hěn Xiǎng Gào Sù Dì Di.", "Tôi nhìn bản đồ, lại nghĩ đến thành phố bây giờ, trong lòng rất vui, cũng rất muốn kể cho em trai nghe."], [128.85, 133.654, "中午，我们在博物馆外面吃面包，喝水。", "Zhōng Wǔ, Wǒ Men Zài Bó Wù Guǎn Wài Miàn Chī Miàn Bāo, Hē Shuǐ.", "Buổi trưa, chúng tôi ăn bánh mì và uống nước bên ngoài bảo tàng."], [133.654, 141.386, "休息的时候，我把喜欢的东西写在本子上，一边写一边想那张旧地图。", "Xiū Xi De Shí Hòu, Wǒ Bǎ Xǐ Huan De Dōng Xī Xiě Zài Běn Zi Shàng, Yì Biān Xiě Yì Biān Xiǎng Nà Zhāng Jiù Dì Tú.", "Lúc nghỉ, tôi ghi những thứ mình thích vào vở, vừa viết vừa nghĩ đến tấm bản đồ cũ đó."], [141.386, 144.486, "下午，我们去看旧灯。", "Xià Wǔ, Wǒ Men Qù Kàn Jiù Dēng.", "Buổi chiều, chúng tôi đi xem những chiếc đèn cũ."], [144.486, 148.09, "那些灯不大，可是很有意思。", "Nà Xiē Dēng Bù Dà, Kě Shì Hěn Yǒu Yì Si.", "Những chiếc đèn đó không lớn, nhưng rất thú vị."], [148.09, 153.566, "讲解员说，以前的人晚上就用这样的灯看书。", "Jiǎng Jiě Yuán Shuō, Yǐ Qián De Rén Wǎn Shàng Jiù Yòng Zhè Yàng De Dēng Kàn Shū.", "Người thuyết minh nói, người xưa buổi tối dùng loại đèn như thế này để đọc sách."], [153.566, 157.617, "我想，那时候看书一定很不容易。", "Wǒ Xiǎng, Nà Shí Hòu Kàn Shū Yí Dìng Hěn Bù Róng Yì.", "Tôi nghĩ, thời đó đọc sách chắc chắn không dễ dàng."], [157.617, 162.541, "参观完以后，我更加了解自己生活的地方。", "Cān Guān Wán Yǐ Hòu, Wǒ Gèng Jiā Liǎo Jiě Zì Jǐ Shēng Huó De Dì Fāng.", "Tham quan xong, tôi hiểu hơn nơi mình đang sống."], [162.541, 167.23, "回家的车上，同学还在说那张地图。", "Huí Jiā De Chē Shàng, Tóng Xué Hái Zài Shuō Nà Zhāng Dì Tú.", "Trên xe về nhà, các bạn vẫn còn nói về tấm bản đồ đó."], [167.23, 171.722, "回来以后，我把看到的东西告诉了家人。", "Huí Lái Yǐ Hòu, Wǒ Bǎ Kàn Dào De Dōng Xī Gào Sù Le Jiā Rén.", "Về rồi tôi kể cho người nhà những thứ đã xem."], [171.722, 175.158, "妈妈问我：“你最喜欢什么？”", "Mā Ma Wèn Wǒ: \"Nǐ Zuì Xǐ Huan Shén Me?\"", "Mẹ hỏi tôi: \"Con thích nhất thứ gì?\""], [175.158, 182.695, "我高兴地说：“一张一百年前的地图！我站着看了很久，太有意思了。”", "Wǒ Gāo Xìng Dì Shuō: \"Yì Zhāng Yì Bǎi Nián Qián De Dì Tú! Wǒ Zhàn Zhe Kàn Le Hěn Jiǔ, Tài Yǒu Yì Si Le.\"", "Tôi vui vẻ nói: \"Một tấm bản đồ cách đây một trăm năm! Con đứng xem rất lâu, thú vị lắm ạ.\""], [182.695, 186.443, "弟弟问我，以前的人用什么灯。", "Dì Di Wèn Wǒ, Yǐ Qián De Rén Yòng Shén Me Dēng.", "Em trai hỏi ngày xưa người ta dùng đèn gì."], [186.443, 189.615, "我把下午听到的告诉了他。", "Wǒ Bǎ Xià Wǔ Tīng Dào De Gào Sù Le Tā.", "Tôi kể lại cho em những gì nghe được buổi chiều."], [189.615, 192.883, "弟弟说：“我也想去看看。”", "Dì Di Shuō: \"Wǒ Yě Xiǎng Qù Kàn Kan.\"", "Em trai nói: \"Em cũng muốn đi xem.\""], [192.883, 195.953, "我说明天再带他去看。", "Wǒ Shuō Míng Tiān Zài Dài Tā Qù Kàn.", "Tôi nói ngày mai đưa em đi xem."], [195.953, 199.509, "第二天，我真的带弟弟去了。", "Dì Èr Tiān, Wǒ Zhēn De Dài Dì Di Qù Le.", "Hôm sau, tôi thật sự đưa em trai đi."], [199.509, 202.993, "弟弟在旧灯前面站了很久。", "Dì Di Zài Jiù Dēng Qián Miàn Zhàn Le Hěn Jiǔ.", "Em trai đứng trước những chiếc đèn cũ rất lâu."], [202.993, 207.888, "他问了很多问题，我知道的都告诉他了。", "Tā Wèn Le Hěn Duō Wèn Tí, Wǒ Zhī Dào De Dōu Gào Sù Tā Le.", "Em hỏi rất nhiều câu, điều nào biết tôi đều nói cho em."], [207.888, 212.788, "有一个问题我不知道，我就去问讲解员。", "Yǒu Yí Gè Wèn Tí Wǒ Bù Zhī Dào, Wǒ Jiù Qù Wèn Jiǎng Jiě Yuán.", "Có một câu tôi không biết, tôi liền đi hỏi người thuyết minh."], [212.788, 216.056, "讲解员笑着回答了我们。", "Jiǎng Jiě Yuán Xiào Zhe Huí Dá Le Wǒ Men.", "Người thuyết minh mỉm cười trả lời chúng tôi."], [216.056, 222.168, "弟弟高兴地说：“这里太有意思了，我以后也要常来！”", "Dì Di Gāo Xìng Dì Shuō: \"Zhè Lǐ Tài Yǒu Yì Si Le, Wǒ Yǐ Hòu Yě Yào Cháng Lái!\"", "Em trai vui vẻ nói: \"Ở đây thú vị quá, sau này em cũng muốn thường đến!\""], [222.168, 225.436, "老师也让我们写一篇短文。", "Lǎo Shī Yě Ràng Wǒ Men Xiě Yì Piān Duǎn Wén.", "Thầy cũng bảo chúng tôi viết một bài ngắn."], [225.436, 228.656, "我想了很久，才开始写。", "Wǒ Xiǎng Le Hěn Jiǔ, Cái Kāi Shǐ Xiě.", "Tôi suy nghĩ rất lâu mới bắt đầu viết."], [228.656, 231.42, "我写了那张旧地图。", "Wǒ Xiě Le Nà Zhāng Jiù Dì Tú.", "Tôi viết về tấm bản đồ cũ."], [231.42, 235.912, "我还写了和弟弟一起去看旧灯的事。", "Wǒ Hái Xiě Le Hé Dì Di Yì Qǐ Qù Kàn Jiù Dēng De Shì.", "Tôi còn viết chuyện cùng em trai đi xem đèn cũ."], [235.912, 242.95, "老师看了我的短文，笑着说：“你写得很认真，老师很高兴。”", "Lǎo Shī Kàn Le Wǒ De Duǎn Wén, Xiào Zhe Shuō: \"Nǐ Xiě Dé Hěn Rèn Zhēn, Lǎo Shī Hěn Gāo Xìng.\"", "Thầy xem bài ngắn của tôi, cười nói: \"Em viết rất chăm chỉ, thầy rất vui.\""], [242.95, 246.746, "这次参观让历史离我近了一点儿。", "Zhè Cì Cān Guān Ràng Lì Shǐ Lí Wǒ Jìn Le Yì Diǎn Ér.", "Lần tham quan này khiến lịch sử gần tôi hơn một chút."], [246.746, 256.278, "现在我经过那条路，会想起那张旧地图，也会想起和弟弟一起去的那天，心里很开心。", "Xiàn Zài Wǒ Jīng Guò Nà Tiáo Lù, Huì Xiǎng Qǐ Nà Zhāng Jiù Dì Tú, Yě Huì Xiǎng Qǐ Hé Dì Di Yì Qǐ Qù De Nà Tiān, Xīn Lǐ Hěn Kāi Xīn.", "Bây giờ mỗi khi đi qua con đường đó, tôi lại nhớ đến tấm bản đồ cũ, cũng nhớ đến ngày cùng em trai đi xem, trong lòng rất vui."]]}, "hsk3-06": {"dur": 292.64, "cues": [[8.406, 13.378, "那天早上，我刚吃完早饭，手机就响了。", "Nà Tiān Zǎo Shàng, Wǒ Gāng Chī Wán Zǎo Fàn, Shǒu Jī Jiù Xiǎng Le.", "Sáng hôm đó, tôi vừa ăn sáng xong thì điện thoại đổ chuông."], [13.378, 16.862, "电话是那家小公司打来的。", "Diàn Huà Shì Nà Jiā Xiǎo Gōng Sī Dǎ Lái De.", "Cuộc gọi là từ công ty nhỏ đó."], [16.862, 22.964, "他们笑着说：请你下个星期来面试，我们等你来。", "Tā Men Xiào Zhe Shuō: Qǐng Nǐ Xià Gè Xīng Qī Lái Miàn Shì, Wǒ Men Děng Nǐ Lái.", "Họ cười nói: Mời bạn tuần sau đến phỏng vấn, chúng tôi đợi bạn đến nhé."], [22.964, 26.688, "上个月我去一家小公司面试。", "Shàng Gè Yuè Wǒ Qù Yì Jiā Xiǎo Gōng Sī Miàn Shì.", "Tháng trước tôi đi phỏng vấn ở một công ty nhỏ."], [26.688, 29.629, "这是我第一次找工作。", "Zhè Shì Wǒ Dì Yī Cì Zhǎo Gōng Zuò.", "Đây là lần đầu tiên tôi đi tìm việc."], [29.629, 33.689, "我把这个消息告诉了好朋友小刚。", "Wǒ Bǎ Zhè Ge Xiāo Xī Gào Sù Le Hǎo Péng You Xiǎo Gāng.", "Tôi kể tin này cho người bạn thân Tiểu Cương."], [33.689, 40.005, "小刚笑着说：太好了！你别紧张，认真准备就可以。", "Xiǎo Gāng Xiào Zhe Shuō: Tài Hǎo Le! Nǐ Bié Jǐn Zhāng, Rèn Zhēn Zhǔn Bèi Jiù Kě Yǐ.", "Tiểu Cương cười nói: Tuyệt quá! Đừng hồi hộp, cứ chuẩn bị nghiêm túc là được."], [40.005, 45.79, "他还笑着说：别怕，公司最喜欢认真的人了。", "Tā Hái Xiào Zhe Shuō: Bié Pà, Gōng Sī Zuì Xǐ Huan Rèn Zhēn De Rén Le.", "Bạn ấy còn cười nói: Đừng sợ, công ty thích nhất người nghiêm túc đấy."], [45.79, 50.738, "面试前一天，我先看了看公司的介绍。", "Miàn Shì Qián Yì Tiān, Wǒ Xiān Kàn Le Kàn Gōng Sī De Jiè Shào.", "Ngày trước buổi phỏng vấn, tôi xem trước phần giới thiệu của công ty."], [50.738, 54.242, "我把想说的话写在本子上。", "Wǒ Bǎ Xiǎng Shuō De Huà Xiě Zài Běn Zi Shàng.", "Tôi viết những điều muốn nói vào sổ."], [54.242, 57.51, "我看着本子练习了三遍。", "Wǒ Kàn Zhe Běn Zi Liàn Xí Le Sān Biàn.", "Tôi nhìn sổ luyện tập ba lần."], [57.51, 63.778, "妈妈说：早点儿睡，明天才有精神，妈妈相信你。", "Mā Ma Shuō: Zǎo Diǎn Er Shuì, Míng Tiān Cái Yǒu Jīng Shén, Mā Ma Xiāng Xìn Nǐ.", "Mẹ nói: Ngủ sớm một chút, mai mới có tinh thần, mẹ tin con."], [63.778, 68.87, "前一天晚上我准备了很久，几乎没有睡好。", "Qián Yì Tiān Wǎn Shàng Wǒ Zhǔn Bèi Le Hěn Jiǔ, Jī Hū Méi Yǒu Shuì Hǎo.", "Đêm hôm trước tôi chuẩn bị rất lâu, gần như không ngủ ngon."], [68.87, 73.05, "第二天早上，我六点半就起床了。", "Dì Èr Tiān Zǎo Shàng, Wǒ Liù Diǎn Bàn Jiù Qǐ Chuáng Le.", "Sáng hôm sau, tôi dậy từ sáu giờ rưỡi."], [73.05, 76.798, "我选了一件干净的白色的衣服。", "Wǒ Xuǎn Le Yí Jiàn Gān Jìng De Bái Sè De Yī Fu.", "Tôi chọn một chiếc áo trắng sạch sẽ."], [76.798, 84.265, "爸爸看了看，笑着说：真好看！衣服干净，人看起来就有精神。", "Bà Ba Kàn Le Kàn, Xiào Zhe Shuō: Zhēn Hǎo Kàn! Yī Fu Gān Jìng, Rén Kàn Qǐ Lái Jiù Yǒu Jīng Shén.", "Bố nhìn một lúc, cười nói: Đẹp thật! Quần áo sạch sẽ thì trông người có tinh thần."], [84.265, 88.781, "我坐公共汽车去公司，路上人很多。", "Wǒ Zuò Gōng Gòng Qì Chē Qù Gōng Sī, Lù Shàng Rén Hěn Duō.", "Tôi đi xe buýt đến công ty, trên đường rất đông người."], [88.781, 92.649, "我比说好的时间早到了十分钟。", "Wǒ Bǐ Shuō Hǎo De Shí Jiān Zǎo Dào Le Shí Fēn Zhōng.", "Tôi đến sớm hơn giờ hẹn mười phút."], [92.649, 97.292, "我在门口等了一会儿，心里还是很紧张。", "Wǒ Zài Mén Kǒu Děng Le Yí Huì Er, Xīn Lǐ Hái Shì Hěn Jǐn Zhāng.", "Tôi đợi ở cửa một lúc, trong lòng vẫn rất hồi hộp."], [97.292, 102.432, "一位同事请我先坐下，还给了我一杯水。", "Yí Wèi Tóng Shì Qǐng Wǒ Xiān Zuò Xià, Hái Gěi Le Wǒ Yì Bēi Shuǐ.", "Một đồng nghiệp mời tôi ngồi xuống trước, còn đưa cho tôi một cốc nước."], [102.432, 106.278, "喝了一口水，我慢慢不紧张了。", "Hē Le Yì Kǒu Shuǐ, Wǒ Màn Màn Bù Jǐn Zhāng Le.", "Uống một ngụm nước, tôi dần bớt hồi hộp."], [106.278, 109.978, "过了一会儿，面试的老师来了。", "Guò Le Yí Huì Er, Miàn Shì De Lǎo Shī Lái Le.", "Một lúc sau, thầy phỏng vấn đến."], [109.978, 116.006, "他笑着说：请坐，别紧张，我们先聊一聊。", "Tā Xiào Zhe Shuō: Qǐng Zuò, Bié Jǐn Zhāng, Wǒ Men Xiān Liáo Yì Liáo.", "Thầy cười nói: Mời ngồi, đừng hồi hộp, chúng ta nói chuyện một chút trước."], [116.006, 120.234, "面试的老师问我为什么想做这份工作。", "Miàn Shì De Lǎo Shī Wèn Wǒ Wèi Shén Me Xiǎng Zuò Zhè Fèn Gōng Zuò.", "Thầy phỏng vấn hỏi vì sao tôi muốn làm công việc này."], [120.234, 126.433, "我告诉他，我喜欢和人交流，也愿意学习新东西。", "Wǒ Gào Sù Tā, Wǒ Xǐ Huan Hé Rén Jiāo Liú, Yě Yuàn Yì Xué Xí Xīn Dōng Xī.", "Tôi nói tôi thích giao tiếp với người khác và cũng muốn học điều mới."], [126.433, 130.997, "他又问：你以前做过这样的工作吗？", "Tā Yòu Wèn: Nǐ Yǐ Qián Zuò Guò Zhè Yàng De Gōng Zuò Ma?", "Thầy lại hỏi: Trước đây bạn đã làm công việc như thế này chưa?"], [130.997, 136.137, "我说：没有做过，可是我愿意认真学。", "Wǒ Shuō: Méi Yǒu Zuò Guò, Kě Shì Wǒ Yuàn Yì Rèn Zhēn Xué.", "Tôi nói: Chưa ạ, nhưng tôi sẵn lòng học nghiêm túc."], [136.137, 141.015, "老师点点头，在本子上写了几个字。", "Lǎo Shī Diǎn Diǎn Tóu, Zài Běn Zi Shàng Xiě Le Jǐ Gè Zì.", "Thầy gật đầu, viết mấy chữ vào sổ."], [141.015, 145.627, "有一个问题很难，我想了想才回答。", "Yǒu Yí Gè Wèn Tí Hěn Nán, Wǒ Xiǎng Le Xiǎng Cái Huí Dá.", "Có một câu hỏi rất khó, tôi nghĩ một lúc mới trả lời."], [145.627, 149.735, "我说：这个问题我还要再学习。", "Wǒ Shuō: Zhè Ge Wèn Tí Wǒ Hái Yào Zài Xué Xí.", "Tôi nói: Vấn đề này tôi còn phải học thêm."], [149.735, 156.051, "虽然有几个问题我答得不太好，可是我态度很认真。", "Suī Rán Yǒu Jǐ Gè Wèn Tí Wǒ Dá Dé Bú Tài Hǎo, Kě Shì Wǒ Tài Dù Hěn Rèn Zhēn.", "Vài câu tôi trả lời chưa thật tốt, nhưng thái độ của tôi rất nghiêm túc."], [156.051, 163.423, "最后，老师笑着说：你很认真，我们三天以后告诉你消息。", "Zuì Hòu, Lǎo Shī Xiào Zhe Shuō: Nǐ Hěn Rèn Zhēn, Wǒ Men Sān Tiān Yǐ Hòu Gào Sù Nǐ Xiāo Xī.", "Cuối cùng, thầy cười nói: Bạn rất nghiêm túc, ba ngày nữa chúng tôi sẽ báo tin cho bạn."], [163.423, 167.369, "我站起来，高兴地说了一声谢谢。", "Wǒ Zhàn Qǐ Lái, Gāo Xìng De Shuō Le Yì Shēng Xiè Xiè.", "Tôi đứng dậy, vui vẻ nói một tiếng cảm ơn."], [167.369, 171.357, "回家的路上，我给小刚打了电话。", "Huí Jiā De Lù Shàng, Wǒ Gěi Xiǎo Gāng Dǎ Le Diàn Huà.", "Trên đường về nhà, tôi gọi điện cho Tiểu Cương."], [171.357, 174.553, "小刚问：你答得怎么样？", "Xiǎo Gāng Wèn: Nǐ Dá Dé Zěn Me Yàng?", "Tiểu Cương hỏi: Bạn trả lời thế nào?"], [174.553, 180.396, "我说：有两个问题答得不好，可是我没有放弃。", "Wǒ Shuō: Yǒu Liǎng Gè Wèn Tí Dá Dé Bù Hǎo, Kě Shì Wǒ Méi Yǒu Fàng Qì.", "Tôi nói: Có hai câu trả lời chưa tốt, nhưng tôi không bỏ cuộc."], [180.396, 184.456, "这三天，我每天都看几次手机。", "Zhè Sān Tiān, Wǒ Měi Tiān Dōu Kàn Jǐ Cì Shǒu Jī.", "Ba ngày đó, ngày nào tôi cũng xem điện thoại mấy lần."], [184.456, 188.564, "手机一直没有响，我有点儿担心。", "Shǒu Jī Yì Zhí Méi Yǒu Xiǎng, Wǒ Yǒu Diǎn Er Dān Xīn.", "Điện thoại mãi không đổ chuông, tôi hơi lo lắng."], [188.564, 194.76, "晚上，我看着手机，心里一会儿高兴，一会儿担心。", "Wǎn Shàng, Wǒ Kàn Zhe Shǒu Jī, Xīn Lǐ Yí Huì Er Gāo Xìng, Yí Huì Er Dān Xīn.", "Buổi tối, tôi nhìn điện thoại, trong lòng lúc vui lúc lo."], [194.76, 201.526, "妈妈笑着说：别担心，做好你能做的事，我们都相信你。", "Mā Ma Xiào Zhe Shuō: Bié Dān Xīn, Zuò Hǎo Nǐ Néng Zuò De Shì, Wǒ Men Dōu Xiāng Xìn Nǐ.", "Mẹ cười nói: Đừng lo, cứ làm tốt việc con có thể làm, cả nhà đều tin con."], [201.526, 205.658, "三天以后，我收到了录取的消息。", "Sān Tiān Yǐ Hòu, Wǒ Shōu Dào Le Lù Qǔ De Xiāo Xī.", "Ba ngày sau tôi nhận được tin được nhận."], [205.658, 208.374, "我高兴得跳了起来。", "Wǒ Gāo Xìng Dé Tiào Le Qǐ Lái.", "Tôi vui đến mức nhảy lên."], [208.374, 213.25, "收到消息的那天，我给父母打了电话。", "Shōu Dào Xiāo Xī De Nà Tiān, Wǒ Gěi Fù Mǔ Dǎ Le Diàn Huà.", "Ngày nhận tin tôi gọi cho bố mẹ."], [213.25, 219.086, "爸爸在电话里笑着说：太好了，我们为你高兴！", "Bà Ba Zài Diàn Huà Lǐ Xiào Zhe Shuō: Tài Hǎo Le, Wǒ Men Wèi Nǐ Gāo Xìng!", "Bố cười nói trong điện thoại: Tuyệt quá, bố mẹ mừng cho con!"], [219.086, 221.751, "他们比我还高兴。", "Tā Men Bǐ Wǒ Hái Gāo Xìng.", "Họ còn vui hơn tôi."], [221.751, 225.739, "第一天上班，我早到了二十分钟。", "Dì Yī Tiān Shàng Bān, Wǒ Zǎo Dào Le Èr Shí Fēn Zhōng.", "Ngày đầu đi làm tôi đến sớm hai mươi phút."], [225.739, 230.687, "办公室里还很安静，只有那位同事在。", "Bàn Gōng Shì Lǐ Hái Hěn Ān Jìng, Zhǐ Yǒu Nà Wèi Tóng Shì Zài.", "Trong văn phòng còn rất yên tĩnh, chỉ có đồng nghiệp hôm trước ở đó."], [230.687, 233.931, "同事带我认识了办公室。", "Tóng Shì Dài Wǒ Rèn Shi Le Bàn Gōng Shì.", "Đồng nghiệp dẫn tôi làm quen văn phòng."], [233.931, 238.051, "她教我先做什么，后做什么。", "Tā Jiào Wǒ Xiān Zuò Shén Me, Hòu Zuò Shén Me.", "Chị ấy dạy tôi làm gì trước, làm gì sau."], [238.051, 242.447, "中午，我和同事一起在附近吃饭。", "Zhōng Wǔ, Wǒ Hé Tóng Shì Yì Qǐ Zài Fù Jìn Chī Fàn.", "Buổi trưa, tôi ăn cơm cùng đồng nghiệp ở gần đó."], [242.447, 245.883, "他们问我第一天感觉怎么样。", "Tā Men Wèn Wǒ Dì Yī Tiān Gǎn Jué Zěn Me Yàng.", "Họ hỏi tôi cảm thấy ngày đầu tiên thế nào."], [245.883, 252.401, "我说：有一点儿紧张，可是大家都很好，我很喜欢这里。", "Wǒ Shuō: Yǒu Yì Diǎn Er Jǐn Zhāng, Kě Shì Dà Jiā Dōu Hěn Hǎo, Wǒ Hěn Xǐ Huan Zhè Lǐ.", "Tôi nói: Hơi hồi hộp một chút, nhưng mọi người đều rất tốt, tôi rất thích nơi này."], [252.401, 255.645, "我从最小的事情开始做。", "Wǒ Cóng Zuì Xiǎo De Shì Qíng Kāi Shǐ Zuò.", "Tôi bắt đầu từ việc nhỏ nhất."], [255.645, 260.281, "下午下班以前，我做完了第一件小事。", "Xià Wǔ Xià Bān Yǐ Qián, Wǒ Zuò Wán Le Dì Yī Jiàn Xiǎo Shì.", "Buổi chiều trước giờ tan làm, tôi làm xong việc nhỏ đầu tiên."], [260.281, 266.658, "同事笑着说：你做得很认真，真的很好，明天继续！", "Tóng Shì Xiào Zhe Shuō: Nǐ Zuò Dé Hěn Rèn Zhēn, Zhēn De Hěn Hǎo, Míng Tiān Jì Xù!", "Đồng nghiệp cười nói: Bạn làm rất nghiêm túc, thật sự rất tốt, mai cứ tiếp tục nhé!"], [266.658, 271.006, "晚上回家，我把这一天告诉了父母。", "Wǎn Shàng Huí Jiā, Wǒ Bǎ Zhè Yì Tiān Gào Sù Le Fù Mǔ.", "Tối về nhà, tôi kể lại ngày hôm đó cho bố mẹ."], [271.006, 278.45, "妈妈笑着说：你看，认真准备，就有好消息，妈妈真为你高兴。", "Mā Ma Xiào Zhe Shuō: Nǐ Kàn, Rèn Zhēn Zhǔn Bèi, Jiù Yǒu Hǎo Xiāo Xī, Mā Ma Zhēn Wèi Nǐ Gāo Xìng.", "Mẹ cười nói: Con thấy chưa, chuẩn bị nghiêm túc là có tin vui, mẹ thật sự mừng cho con."], [278.45, 283.422, "我知道，认真比一下子做到完美更重要。", "Wǒ Zhī Dào, Rèn Zhēn Bǐ Yí Xià Zǐ Zuò Dào Wán Měi Gèng Zhòng Yào.", "Tôi biết nghiêm túc quan trọng hơn làm hoàn hảo ngay."]]}, "hsk3-07": {"dur": 258.5, "cues": [[7.593, 12.565, "今年夏天，我们城市已经很多天没有下雨了。", "Jīn Nián Xià Tiān, Wǒ Men Chéng Shì Yǐ Jīng Hěn Duō Tiān Méi Yǒu Xià Yǔ Le.", "Mùa hè năm nay, thành phố chúng tôi đã nhiều ngày không mưa."], [12.565, 17.345, "我们城市今年夏天特别热，也很少下雨。", "Wǒ Men Chéng Shì Jīn Nián Xià Tiān Tè Bié Rè, Yě Hěn Shǎo Xià Yǔ.", "Mùa hè năm nay thành phố rất nóng và hiếm khi mưa."], [17.345, 21.873, "天气太热，我每天都要喝很多水。", "Tiān Qì Tài Rè, Wǒ Měi Tiān Dōu Yào Hē Hěn Duō Shuǐ.", "Trời quá nóng, ngày nào tôi cũng phải uống nhiều nước."], [21.873, 27.085, "有一天晚上，我们一家人坐在客厅看电视。", "Yǒu Yì Tiān Wǎn Shàng, Wǒ Men Yì Jiā Rén Zuò Zài Kè Tīng Kàn Diàn Shì.", "Một tối nọ, cả nhà tôi ngồi ở phòng khách xem tivi."], [27.085, 31.556, "新闻里说，大家应该注意节约用水。", "Xīn Wén Lǐ Shuō, Dà Jiā Yīng Gāi Zhù Yì Jié Yuē Yòng Shuǐ.", "Bản tin nói mọi người nên chú ý tiết kiệm nước."], [31.556, 38.904, "爸爸听了，认真地说：对，我们家也要这样做，从今天开始。", "Bà Ba Tīng Le, Rèn Zhēn De Shuō: Duì, Wǒ Men Jiā Yě Yào Zhè Yàng Zuò, Cóng Jīn Tiān Kāi Shǐ.", "Bố nghe xong, nghiêm túc nói: Đúng, nhà mình cũng phải làm như vậy, bắt đầu từ hôm nay."], [38.904, 45.0, "妈妈笑着说：好，我们先从洗菜和洗澡开始吧。", "Mā Ma Xiào Zhe Shuō: Hǎo, Wǒ Men Xiān Cóng Xǐ Cài Hé Xǐ Zǎo Kāi Shǐ Ba.", "Mẹ cười nói: Được, nhà mình bắt đầu từ việc rửa rau và tắm trước nhé."], [45.0, 49.087, "第二天早上，我先从洗脸开始。", "Dì Èr Tiān Zǎo Shàng, Wǒ Xiān Cóng Xǐ Liǎn Kāi Shǐ.", "Sáng hôm sau, tôi bắt đầu từ việc rửa mặt trước."], [49.087, 53.411, "中午做饭的时候，妈妈在水里洗菜。", "Zhōng Wǔ Zuò Fàn De Shí Hòu, Mā Ma Zài Shuǐ Lǐ Xǐ Cài.", "Buổi trưa khi nấu cơm, mẹ rửa rau trong nước."], [53.411, 57.015, "洗完以后，她把水留了下来。", "Xǐ Wán Yǐ Hòu, Tā Bǎ Shuǐ Liú Le Xià Lái.", "Rửa xong, mẹ giữ nước lại."], [57.015, 62.88, "她笑着说：这水还干净，给花喝，花会高兴的。", "Tā Xiào Zhe Shuō: Zhè Shuǐ Hái Gān Jìng, Gěi Huā Hē, Huā Huì Gāo Xìng De.", "Mẹ cười nói: Nước này còn sạch, cho hoa uống, hoa sẽ vui đấy."], [62.88, 67.396, "在家里，我洗完菜的水用来浇花。", "Zài Jiā Lǐ, Wǒ Xǐ Wán Cài De Shuǐ Yòng Lái Jiāo Huā.", "Ở nhà, tôi dùng nước rửa rau để tưới hoa."], [67.396, 70.904, "我们家阳台上有很多小花。", "Wǒ Men Jiā Yáng Tái Shàng Yǒu Hěn Duō Xiǎo Huā.", "Ban công nhà tôi có rất nhiều hoa nhỏ."], [70.904, 74.412, "以前我常常忘了给它们浇水。", "Yǐ Qián Wǒ Cháng Cháng Wàng Le Gěi Tā Men Jiāo Shuǐ.", "Trước đây tôi thường quên tưới nước cho chúng."], [74.412, 78.414, "现在每天洗完菜，我就去浇花。", "Xiàn Zài Měi Tiān Xǐ Wán Cài, Wǒ Jiù Qù Jiāo Huā.", "Bây giờ ngày nào rửa rau xong, tôi cũng đi tưới hoa."], [78.414, 81.618, "花喝了水，长得很快。", "Huā Hē Le Shuǐ, Zhǎng Dé Hěn Kuài.", "Hoa được uống nước, lớn rất nhanh."], [81.618, 85.844, "洗澡的时候，我也不再开很长时间。", "Xǐ Zǎo De Shí Hòu, Wǒ Yě Bú Zài Kāi Hěn Cháng Shí Jiān.", "Lúc tắm tôi cũng không mở nước quá lâu nữa."], [85.844, 90.624, "弟弟洗手的时候，喜欢把水开得很大。", "Dì Di Xǐ Shǒu De Shí Hòu, Xǐ Huan Bǎ Shuǐ Kāi Dé Hěn Dà.", "Khi rửa tay, em trai thích mở nước thật to."], [90.624, 96.964, "我笑着告诉他：洗手不用开这么大，花还在等水喝呢。", "Wǒ Xiào Zhe Gào Sù Tā: Xǐ Shǒu Bú Yòng Kāi Zhè Me Dà, Huā Hái Zài Děng Shuǐ Hē Ne.", "Tôi cười bảo em: Rửa tay không cần mở to thế này đâu, hoa còn đang đợi nước uống đấy."], [96.964, 100.45, "弟弟说：可是这样洗得快。", "Dì Di Shuō: Kě Shì Zhè Yàng Xǐ Dé Kuài.", "Em trai nói: Nhưng mở thế này rửa nhanh hơn."], [100.45, 105.038, "我说：水少了，花就没有水喝了。", "Wǒ Shuō: Shuǐ Shǎo Le, Huā Jiù Méi Yǒu Shuǐ Hē Le.", "Tôi nói: Nước ít đi thì hoa sẽ không có nước uống nữa."], [105.038, 109.146, "弟弟看了看花，慢慢把水关小了。", "Dì Di Kàn Le Kàn Huā, Màn Màn Bǎ Shuǐ Guān Xiǎo Le.", "Em trai nhìn hoa, từ từ vặn nước nhỏ lại."], [109.146, 113.731, "从那天起，弟弟洗手也知道节约了。", "Cóng Nà Tiān Qǐ, Dì Di Xǐ Shǒu Yě Zhī Dào Jié Yuē Le.", "Từ hôm đó, em trai rửa tay cũng biết tiết kiệm rồi."], [113.731, 118.535, "一开始觉得有点儿麻烦，后来就习惯了。", "Yì Kāi Shǐ Jué De Yǒu Diǎn Er Má Fán, Hòu Lái Jiù Xí Guàn Le.", "Lúc đầu thấy hơi phiền, sau thì quen."], [118.535, 122.283, "有一次，我洗完手忘了关水。", "Yǒu Yí Cì, Wǒ Xǐ Wán Shǒu Wàng Le Guān Shuǐ.", "Có một lần, rửa tay xong tôi quên tắt nước."], [122.283, 129.295, "妈妈看见了，没有生气，只小声提醒我：用水以后要关好。", "Mā Ma Kàn Jiàn Le, Méi Yǒu Shēng Qì, Zhǐ Xiǎo Shēng Tí Xǐng Wǒ: Yòng Shuǐ Yǐ Hòu Yào Guān Hǎo.", "Mẹ thấy vậy, không giận, chỉ nhẹ nhàng nhắc tôi: Dùng nước xong phải tắt cẩn thận."], [129.295, 133.561, "我说：对不起，下次我一定记得。", "Wǒ Shuō: Duì Bù Qǐ, Xià Cì Wǒ Yí Dìng Jì De.", "Tôi nói: Con xin lỗi, lần sau con nhất định sẽ nhớ."], [133.561, 139.133, "保护环境不一定要做大事，从小事开始就可以。", "Bǎo Hù Huán Jìng Bù Yí Dìng Yào Zuò Dà Shì, Cóng Xiǎo Shì Kāi Shǐ Jiù Kě Yǐ.", "Bảo vệ môi trường không nhất thiết phải làm việc lớn, bắt đầu từ việc nhỏ là được."], [139.133, 144.465, "过了两个星期，我们家的花开得比以前好看。", "Guò Le Liǎng Gè Xīng Qī, Wǒ Men Jiā De Huā Kāi Dé Bǐ Yǐ Qián Hǎo Kàn.", "Hai tuần trôi qua, hoa nhà tôi nở đẹp hơn trước."], [144.465, 150.953, "早上打开门，就能看见红花和白色的花，心里很高兴。", "Zǎo Shàng Dǎ Kāi Mén, Jiù Néng Kàn Jiàn Hóng Huā Hé Bái Sè De Huā, Xīn Lǐ Hěn Gāo Xìng.", "Buổi sáng mở cửa ra là thấy hoa đỏ và hoa trắng, trong lòng rất vui."], [150.953, 155.781, "邻居看见我浇花，也开始用洗菜的水。", "Lín Jū Kàn Jiàn Wǒ Jiāo Huā, Yě Kāi Shǐ Yòng Xǐ Cài De Shuǐ.", "Hàng xóm thấy tôi tưới hoa cũng bắt đầu dùng nước rửa rau."], [155.781, 161.041, "邻居阿姨笑着问我：这水真的可以浇花吗？", "Lín Jū Ā Yí Xiào Zhe Wèn Wǒ: Zhè Shuǐ Zhēn De Kě Yǐ Jiāo Huā Ma?", "Cô hàng xóm cười hỏi tôi: Nước này thật sự tưới hoa được à?"], [161.041, 167.671, "我高兴地说：可以，阿姨您看，我家的花就是这样长大的。", "Wǒ Gāo Xìng De Shuō: Kě Yǐ, Ā Yí Nín Kàn, Wǒ Jiā De Huā Jiù Shì Zhè Yàng Zhǎng Dà De.", "Tôi vui vẻ nói: Được ạ, cô xem này, hoa nhà cháu lớn lên như vậy đấy."], [167.671, 172.379, "第二天，阿姨也把洗菜的水留了下来。", "Dì Èr Tiān, Ā Yí Yě Bǎ Xǐ Cài De Shuǐ Liú Le Xià Lái.", "Hôm sau, cô cũng giữ lại nước rửa rau."], [172.379, 176.319, "小区门口还贴了节约用水的通知。", "Xiǎo Qū Mén Kǒu Hái Tiē Le Jié Yuē Yòng Shuǐ De Tōng Zhī.", "Cổng khu còn dán thông báo tiết kiệm nước."], [176.319, 179.875, "通知是小区的一位老师写的。", "Tōng Zhī Shì Xiǎo Qū De Yí Wèi Lǎo Shī Xiě De.", "Thông báo là do một thầy giáo trong khu viết."], [179.875, 183.647, "很多邻居都站在门口看通知。", "Hěn Duō Lín Jū Dōu Zhàn Zài Mén Kǒu Kàn Tōng Zhī.", "Nhiều hàng xóm đều đứng ở cổng xem thông báo."], [183.647, 188.907, "在学校里，老师也把这件事告诉了孩子们。", "Zài Xué Xiào Lǐ, Lǎo Shī Yě Bǎ Zhè Jiàn Shì Gào Sù Le Hái Zi Men.", "Ở trường, thầy cô cũng kể chuyện này cho các em nghe."], [188.907, 192.511, "孩子们在黑板上画了一滴水。", "Hái Zi Men Zài Hēi Bǎn Shàng Huà Le Yì Dī Shuǐ.", "Trẻ em vẽ một giọt nước lên bảng."], [192.511, 197.363, "一个孩子问：老师，一滴水能做什么？", "Yí Gè Hái Zi Wèn: Lǎo Shī, Yì Dī Shuǐ Néng Zuò Shén Me?", "Một em hỏi: Thưa thầy, một giọt nước làm được gì ạ?"], [197.363, 200.736, "老师说，一滴水也有用。", "Lǎo Shī Shuō, Yì Dī Shuǐ Yě Yǒu Yòng.", "Thầy nói một giọt nước cũng có ích."], [200.736, 207.892, "孩子们听了，都点点头，一个孩子小声说：我也要节约用水。", "Hái Zi Men Tīng Le, Dōu Diǎn Diǎn Tóu, Yí Gè Hái Zi Xiǎo Shēng Shuō: Wǒ Yě Yào Jié Yuē Yòng Shuǐ.", "Các em nghe xong đều gật đầu, một em khẽ nói: Em cũng sẽ tiết kiệm nước."], [207.892, 212.323, "我觉得这句话很简单，可是很对。", "Wǒ Jué De Zhè Jù Huà Hěn Jiǎn Dān, Kě Shì Hěn Duì.", "Tôi thấy câu đó rất đơn giản nhưng rất đúng."], [212.323, 216.455, "回到家，我把老师的话告诉了弟弟。", "Huí Dào Jiā, Wǒ Bǎ Lǎo Shī De Huà Gào Sù Le Dì Di.", "Về nhà, tôi kể lại lời thầy cho em trai."], [216.455, 223.167, "弟弟笑着说：那我以后洗手也关小一点儿，我喜欢看花开。", "Dì Di Xiào Zhe Shuō: Nà Wǒ Yǐ Hòu Xǐ Shǒu Yě Guān Xiǎo Yì Diǎn Er, Wǒ Xǐ Huan Kàn Huā Kāi.", "Em trai cười nói: Vậy từ nay rửa tay em cũng vặn nhỏ một chút, em thích ngắm hoa nở."], [223.167, 228.379, "夏天快结束的时候，我们小区的花都开了。", "Xià Tiān Kuài Jié Shù De Shí Hòu, Wǒ Men Xiǎo Qū De Huā Dōu Kāi Le.", "Khi mùa hè sắp kết thúc, hoa trong khu chúng tôi đều nở."], [228.379, 234.815, "爸爸看着花，笑着说：这个习惯好，我们要一直留着。", "Bà Ba Kàn Zhe Huā, Xiào Zhe Shuō: Zhè Ge Xí Guàn Hǎo, Wǒ Men Yào Yì Zhí Liú Zhe.", "Bố ngắm hoa, cười nói: Thói quen này tốt, nhà mình phải giữ mãi."], [234.815, 239.355, "现在，节约用水成了我们小区的习惯。", "Xiàn Zài, Jié Yuē Yòng Shuǐ Chéng Le Wǒ Men Xiǎo Qū De Xí Guàn.", "Bây giờ, tiết kiệm nước đã thành thói quen của khu chúng tôi."], [239.355, 243.151, "这个夏天我们真的少用了一些水。", "Zhè Ge Xià Tiān Wǒ Men Zhēn De Shǎo Yòng Le Yì Xiē Shuǐ.", "Mùa hè này chúng tôi thật sự dùng ít nước hơn."], [243.151, 249.607, "妈妈笑着说：今年夏天，花开得真好看，我们做对了。", "Mā Ma Xiào Zhe Shuō: Jīn Nián Xià Tiān, Huā Kāi Dé Zhēn Hǎo Kàn, Wǒ Men Zuò Duì Le.", "Mẹ cười nói: Mùa hè năm nay hoa nở đẹp thật, nhà mình làm đúng rồi."]]}, "hsk3-08": {"dur": 282.08, "cues": [[6.78, 10.888, "每个月，我都想去城外看看爷爷。", "Měi Gè Yuè, Wǒ Dōu Xiǎng Qù Chéng Wài Kàn Kan Yé Ye.", "Tháng nào tôi cũng muốn ra ngoại thành thăm ông."], [10.888, 16.052, "爷爷住在城外，房子前面有一个小花园。", "Yé Ye Zhù Zài Chéng Wài, Fáng Zi Qián Miàn Yǒu Yí Gè Xiǎo Huā Yuán.", "Ông sống ngoài thành, trước nhà có một vườn nhỏ."], [16.052, 21.246, "爷爷的房子不大，可是很干净，也很安静。", "Yé Ye De Fáng Zi Bú Dà, Kě Shì Hěn Gān Jìng, Yě Hěn Ān Jìng.", "Nhà ông không lớn, nhưng rất sạch sẽ và yên tĩnh."], [21.246, 26.338, "春天他种花，夏天他种西红柿和黄瓜。", "Chūn Tiān Tā Zhǒng Huā, Xià Tiān Tā Zhǒng Xī Hóng Shì Hé Huáng Guā.", "Mùa xuân ông trồng hoa, mùa hè ông trồng cà chua và dưa chuột."], [26.338, 30.302, "花园里还有几盆花和很多菜。", "Huā Yuán Lǐ Hái Yǒu Jǐ Pén Huā Hé Hěn Duō Cài.", "Trong vườn còn có mấy chậu hoa và rất nhiều rau."], [30.302, 34.194, "上个星期六，爷爷给我打电话。", "Shàng Gè Xīng Qī Liù, Yé Ye Gěi Wǒ Dǎ Diàn Huà.", "Thứ Bảy tuần trước, ông gọi điện cho tôi."], [34.194, 42.046, "他高兴地说：花园里的西红柿红了，红得很好看，你快来看看吧。", "Tā Gāo Xìng De Shuō: Huā Yuán Lǐ De Xī Hóng Shì Hóng Le, Hóng Dé Hěn Hǎo Kàn, Nǐ Kuài Lái Kàn Kan Ba.", "Ông vui vẻ nói: Cà chua trong vườn chín đỏ rồi, đỏ rất đẹp, cháu mau đến xem đi."], [42.046, 47.276, "我听了很高兴，马上说：我明天就来。", "Wǒ Tīng Le Hěn Gāo Xìng, Mǎ Shàng Shuō: Wǒ Míng Tiān Jiù Lái.", "Nghe vậy tôi rất vui, nói ngay: Mai cháu đến ạ."], [47.276, 51.816, "第二天早上，我坐了一个小时的车。", "Dì Èr Tiān Zǎo Shàng, Wǒ Zuò Le Yí Gè Xiǎo Shí De Chē.", "Sáng hôm sau, tôi đi xe mất một tiếng."], [51.816, 58.372, "到了城外，空气和城里很不一样，到处都是花的味道。", "Dào Le Chéng Wài, Kōng Qì Hé Chéng Lǐ Hěn Bù Yí Yàng, Dào Chù Dōu Shì Huā De Wèi Dào.", "Đến ngoại thành, không khí rất khác trong thành phố, khắp nơi đều thơm mùi hoa."], [58.372, 61.712, "爷爷站在花园门口等我。", "Yé Ye Zhàn Zài Huā Yuán Mén Kǒu Děng Wǒ.", "Ông đứng ở cổng vườn đợi tôi."], [61.712, 68.244, "他笑着说：你来了，爷爷等你很久了，先喝口水。", "Tā Xiào Zhe Shuō: Nǐ Lái Le, Yé Ye Děng Nǐ Hěn Jiǔ Le, Xiān Hē Kǒu Shuǐ.", "Ông cười nói: Cháu đến rồi, ông đợi cháu lâu lắm rồi, uống ngụm nước trước đi."], [68.244, 73.936, "每次我去看他，他都让我先尝尝最新鲜的菜。", "Měi Cì Wǒ Qù Kàn Tā, Tā Dōu Ràng Wǒ Xiān Cháng Cháng Zuì Xīn Xiān De Cài.", "Mỗi lần tôi đến thăm, ông đều bảo tôi nếm rau mới hái trước."], [73.936, 78.044, "我吃了一个西红柿，真的很新鲜。", "Wǒ Chī Le Yí Gè Xī Hóng Shì, Zhēn De Hěn Xīn Xiān.", "Tôi ăn một quả cà chua, thật sự rất tươi."], [78.044, 85.032, "我高兴地说：爷爷，这比商店里的好吃多了，我还想吃一个。", "Wǒ Gāo Xìng De Shuō: Yé Ye, Zhè Bǐ Shāng Diàn Lǐ De Hǎo Chī Duō Le, Wǒ Hái Xiǎng Chī Yí Gè.", "Tôi vui vẻ nói: Ông ơi, cái này ngon hơn ở cửa hàng nhiều, cháu muốn ăn thêm một quả nữa."], [85.032, 90.075, "爷爷说：你上次来的时候，它还很小。", "Yé Ye Shuō: Nǐ Shàng Cì Lái De Shí Hòu, Tā Hái Hěn Xiǎo.", "Ông nói: Lần trước cháu đến, nó còn nhỏ lắm."], [90.075, 96.416, "吃完西红柿，我说：爷爷，今天我帮你浇水吧。", "Chī Wán Xī Hóng Shì, Wǒ Shuō: Yé Ye, Jīn Tiān Wǒ Bāng Nǐ Jiāo Shuǐ Ba.", "Ăn cà chua xong, tôi nói: Ông ơi, hôm nay để cháu giúp ông tưới nước nhé."], [96.416, 102.284, "爷爷说：好，你给花一些水，我给菜一些水。", "Yé Ye Shuō: Hǎo, Nǐ Gěi Huā Yì Xiē Shuǐ, Wǒ Gěi Cài Yì Xiē Shuǐ.", "Ông nói: Được, cháu cho hoa ít nước, ông cho rau ít nước."], [102.284, 106.032, "我看着爷爷怎么做，我也怎么做。", "Wǒ Kàn Zhe Yé Ye Zěn Me Zuò, Wǒ Yě Zěn Me Zuò.", "Tôi nhìn ông làm thế nào thì làm theo thế ấy."], [106.032, 109.492, "有一盆花看起来没有精神。", "Yǒu Yì Pén Huā Kàn Qǐ Lái Méi Yǒu Jīng Shén.", "Có một chậu hoa trông không có sức sống."], [109.492, 113.964, "我担心地问：爷爷，它是不是生病了？", "Wǒ Dān Xīn De Wèn: Yé Ye, Tā Shì Bú Shì Shēng Bìng Le?", "Tôi lo lắng hỏi: Ông ơi, nó bị bệnh phải không ạ?"], [113.964, 121.12, "爷爷看了看，笑着说：别担心，它只是今天喝的水太少了。", "Yé Ye Kàn Le Kàn, Xiào Zhe Shuō: Bié Dān Xīn, Tā Zhǐ Shì Jīn Tiān Hē De Shuǐ Tài Shǎo Le.", "Ông nhìn một lúc, cười nói: Đừng lo, nó chỉ là hôm nay uống nước quá ít thôi."], [121.12, 124.1, "我马上又给它一些水。", "Wǒ Mǎ Shàng Yòu Gěi Tā Yì Xiē Shuǐ.", "Tôi lập tức cho nó thêm một ít nước nữa."], [124.1, 130.078, "爷爷笑着说：不用太多，慢慢来，它会好起来的。", "Yé Ye Xiào Zhe Shuō: Bú Yòng Tài Duō, Màn Màn Lái, Tā Huì Hǎo Qǐ Lái De.", "Ông cười nói: Không cần nhiều quá, cứ từ từ, nó sẽ khỏe lại thôi."], [130.078, 135.314, "爷爷说，植物和人一样，需要时间和关心。", "Yé Ye Shuō, Zhí Wù Hé Rén Yí Yàng, Xū Yào Shí Jiān Hé Guān Xīn.", "Ông nói cây cũng giống người, cần thời gian và sự quan tâm."], [135.314, 138.832, "我听了这句话，点点头。", "Wǒ Tīng Le Zhè Jù Huà, Diǎn Diǎn Tóu.", "Nghe câu đó, tôi gật đầu."], [138.832, 143.18, "中午，爷爷用花园里的菜做了午饭。", "Zhōng Wǔ, Yé Ye Yòng Huā Yuán Lǐ De Cài Zuò Le Wǔ Fàn.", "Buổi trưa, ông dùng rau trong vườn nấu cơm trưa."], [143.18, 147.048, "有西红柿鸡蛋，还有炒黄瓜。", "Yǒu Xī Hóng Shì Jī Dàn, Hái Yǒu Chǎo Huáng Guā.", "Có cà chua trứng, còn có dưa chuột xào."], [147.048, 152.462, "我洗菜，爷爷做菜，我们一边做一边说话。", "Wǒ Xǐ Cài, Yé Ye Zuò Cài, Wǒ Men Yì Biān Zuò Yì Biān Shuō Huà.", "Tôi rửa rau, ông nấu ăn, chúng tôi vừa làm vừa nói chuyện."], [152.462, 157.77, "吃饭的时候，爷爷告诉我他年轻时候的事。", "Chī Fàn De Shí Hòu, Yé Ye Gào Sù Wǒ Tā Nián Qīng Shí Hòu De Shì.", "Lúc ăn cơm, ông kể cho tôi chuyện hồi ông còn trẻ."], [157.77, 164.662, "他笑着说，那时候他每天早上都先去看花，再去工作。", "Tā Xiào Zhe Shuō, Nà Shí Hòu Tā Měi Tiān Zǎo Shàng Dōu Xiān Qù Kàn Huā, Zài Qù Gōng Zuò.", "Ông cười nói, hồi đó sáng nào ông cũng đi xem hoa trước rồi mới đi làm."], [164.662, 172.292, "我看着花园，高兴地说：爷爷的花园真的很好看，我最喜欢这里。", "Wǒ Kàn Zhe Huā Yuán, Gāo Xìng De Shuō: Yé Ye De Huā Yuán Zhēn De Hěn Hǎo Kàn, Wǒ Zuì Xǐ Huan Zhè Lǐ.", "Tôi ngắm khu vườn, vui vẻ nói: Vườn của ông đẹp thật đấy, cháu thích nơi này nhất."], [172.292, 175.8, "下午，太阳没有那么热了。", "Xià Wǔ, Tài Yáng Méi Yǒu Nà Me Rè Le.", "Buổi chiều, nắng không còn gắt như vậy nữa."], [175.8, 181.06, "我在城里住惯了，可是很喜欢那里的空气。", "Wǒ Zài Chéng Lǐ Zhù Guàn Le, Kě Shì Hěn Xǐ Huan Nà Lǐ De Kōng Qì.", "Tôi quen sống trong thành nhưng rất thích không khí ở đó."], [181.06, 185.945, "放假的时候，我还要再去帮爷爷浇水。", "Fàng Jià De Shí Hòu, Wǒ Hái Yào Zài Qù Bāng Yé Ye Jiāo Shuǐ.", "Lúc nghỉ tôi sẽ đến giúp ông tưới nước."], [185.945, 189.501, "爷爷还教我认识不同的叶子。", "Yé Ye Hái Jiào Wǒ Rèn Shi Bù Tóng De Yè Zi.", "Ông còn dạy tôi nhận các loại lá."], [189.501, 193.283, "有的叶子早上开，晚上合上。", "Yǒu De Yè Zi Zǎo Shàng Kāi, Wǎn Shàng Hé Shàng.", "Có lá sáng mở, tối khép."], [193.283, 198.063, "我问：它们晚上合上，是在睡觉吗？", "Wǒ Wèn: Tā Men Wǎn Shàng Hé Shàng, Shì Zài Shuì Jiào Ma?", "Tôi hỏi: Tối chúng khép lại, là đang ngủ phải không ạ?"], [198.063, 205.051, "爷爷笑着说：对，它们也要休息，你看，它们睡得真安静。", "Yé Ye Xiào Zhe Shuō: Duì, Tā Men Yě Yào Xiū Xi, Nǐ Kàn, Tā Men Shuì Dé Zhēn Ān Jìng.", "Ông cười nói: Đúng vậy, chúng cũng cần nghỉ ngơi, cháu xem, chúng ngủ yên tĩnh thật đấy."], [205.051, 208.84, "我觉得植物像有自己的时间表。", "Wǒ Jué De Zhí Wù Xiàng Yǒu Zì Jǐ De Shí Jiān Biǎo.", "Tôi thấy cây như có thời gian biểu riêng."], [208.84, 212.972, "我把爷爷教我的都记在了本子上。", "Wǒ Bǎ Yé Ye Jiào Wǒ De Dōu Jì Zài Le Běn Zi Shàng.", "Tôi ghi lại vào sổ tất cả những gì ông dạy."], [212.972, 217.344, "上午没有精神的花，下午也好多了。", "Shàng Wǔ Méi Yǒu Jīng Shén De Huā, Xià Wǔ Yě Hǎo Duō Le.", "Bông hoa buổi sáng trông thiếu sức sống, đến chiều đã khá hơn nhiều."], [217.344, 224.072, "我高兴地对爷爷说：爷爷您看，它喝了水，就有精神了！", "Wǒ Gāo Xìng De Duì Yé Ye Shuō: Yé Ye Nín Kàn, Tā Hē Le Shuǐ, Jiù Yǒu Jīng Shén Le!", "Tôi vui vẻ nói với ông: Ông xem này, nó uống nước vào là có sức sống ngay!"], [224.072, 227.7, "天慢慢晚了，我要回城里了。", "Tiān Màn Màn Wǎn Le, Wǒ Yào Huí Chéng Lǐ Le.", "Trời dần tối muộn, tôi phải về thành phố."], [227.7, 232.072, "离开的时候，他送给我两个西红柿。", "Lí Kāi De Shí Hòu, Tā Sòng Gěi Wǒ Liǎng Gè Xī Hóng Shì.", "Lúc tôi đi, ông đưa hai quả cà chua."], [232.072, 239.537, "爷爷站在门口说：路上小心，到了给我打电话，爷爷等你的电话。", "Yé Ye Zhàn Zài Mén Kǒu Shuō: Lù Shàng Xiǎo Xīn, Dào Le Gěi Wǒ Dǎ Diàn Huà, Yé Ye Děng Nǐ De Diàn Huà.", "Ông đứng ở cổng nói: Đi đường cẩn thận, đến nơi thì gọi cho ông, ông đợi điện thoại của cháu."], [239.537, 245.157, "在车上，我看着那两个西红柿，心里很温暖。", "Zài Chē Shàng, Wǒ Kàn Zhe Nà Liǎng Gè Xī Hóng Shì, Xīn Lǐ Hěn Wēn Nuǎn.", "Trên xe, tôi nhìn hai quả cà chua, trong lòng rất ấm áp."], [245.157, 248.964, "回到城里，我把它们做成了菜。", "Huí Dào Chéng Lǐ, Wǒ Bǎ Tā Men Zuò Chéng Le Cài.", "Về thành phố tôi nấu chúng thành món ăn."], [248.964, 252.736, "吃的时候，我给爷爷打了电话。", "Chī De Shí Hòu, Wǒ Gěi Yé Ye Dǎ Le Diàn Huà.", "Lúc ăn, tôi gọi điện cho ông."], [252.736, 260.348, "我笑着说：爷爷，谢谢您，您的西红柿真好吃，我都吃完了。", "Wǒ Xiào Zhe Shuō: Yé Ye, Xiè Xiè Nín, Nín De Xī Hóng Shì Zhēn Hǎo Chī, Wǒ Dōu Chī Wán Le.", "Tôi cười nói: Ông ơi, cảm ơn ông, cà chua của ông ngon thật đấy, cháu ăn hết rồi."], [260.348, 263.424, "爷爷在电话那边笑了。", "Yé Ye Zài Diàn Huà Nà Biān Xiào Le.", "Ông cười ở đầu dây bên kia."], [263.424, 266.932, "味道让我想起那个小花园。", "Wèi Dào Ràng Wǒ Xiǎng Qǐ Nà Ge Xiǎo Huā Yuán.", "Vị đó khiến tôi nhớ khu vườn nhỏ."], [266.932, 272.816, "我想，下个月，我还要去看爷爷和他的小花园。", "Wǒ Xiǎng, Xià Gè Yuè, Wǒ Hái Yào Qù Kàn Yé Ye Hé Tā De Xiǎo Huā Yuán.", "Tôi nghĩ, tháng sau tôi sẽ lại đến thăm ông và khu vườn nhỏ của ông."]]}, "hsk3-09": {"dur": 272.79, "cues": [[8.522, 13.062, "星期五下午，下课以后我坐车回家。", "Xīng Qī Wǔ Xià Wǔ, Xià Kè Yǐ Hòu Wǒ Zuò Chē Huí Jiā.", "Chiều thứ Sáu, tan học xong tôi đi xe về nhà."], [13.062, 17.299, "那天车上的人特别多，我站了很久。", "Nà Tiān Chē Shàng De Rén Tè Bié Duō, Wǒ Zhàn Le Hěn Jiǔ.", "Hôm đó người trên xe đặc biệt đông, tôi đứng rất lâu."], [17.299, 21.719, "快到家的时候，我想看看钱包在不在。", "Kuài Dào Jiā De Shí Hòu, Wǒ Xiǎng Kàn Kan Qián Bāo Zài Bú Zài.", "Sắp về đến nhà, tôi muốn xem ví còn ở đó không."], [21.719, 26.427, "星期五我在公共汽车上发现钱包不见了。", "Xīng Qī Wǔ Wǒ Zài Gōng Gòng Qì Chē Shàng Fā Xiàn Qián Bāo Bú Jiàn Le.", "Thứ Sáu trên xe buýt tôi phát hiện mất ví."], [26.427, 31.3, "里面有学生证、一张银行卡和一点儿现金。", "Lǐ Miàn Yǒu Xué Shēng Zhèng, Yì Zhāng Yín Háng Kǎ Hé Yì Diǎn Ér Xiàn Jīn.", "Bên trong có thẻ học sinh, một thẻ ngân hàng và một ít tiền mặt."], [31.3, 35.384, "我把包里的东西都拿出来看了看。", "Wǒ Bǎ Bāo Lǐ De Dōng Xī Dōu Ná Chū Lái Kàn Le Kàn.", "Tôi lấy hết đồ trong túi ra xem."], [35.384, 38.266, "我一下子紧张起来了。", "Wǒ Yí Xià Zǐ Jǐn Zhāng Qǐ Lái Le.", "Tôi bỗng căng thẳng hẳn lên."], [38.266, 42.758, "我非常着急，马上给司机说明了情况。", "Wǒ Fēi Cháng Zháo Jí, Mǎ Shàng Gěi Sī Jī Shuō Míng Le Qíng Kuàng.", "Tôi rất sốt ruột và nói ngay với tài xế."], [42.758, 47.778, "我说：司机，我的钱包不见了，怎么办？", "Wǒ Shuō: Sī Jī, Wǒ De Qián Bāo Bú Jiàn Le, Zěn Me Bàn?", "Tôi nói: Bác tài ơi, ví của cháu mất rồi, phải làm sao ạ?"], [47.778, 54.335, "司机小声说：你先别着急，慢慢想一想，我们一起找。", "Sī Jī Xiǎo Shēng Shuō: Nǐ Xiān Bié Zháo Jí, Màn Màn Xiǎng Yì Xiǎng, Wǒ Men Yì Qǐ Zhǎo.", "Tài xế nhẹ nhàng nói: Đừng sốt ruột, cứ từ từ nghĩ lại xem, chúng ta cùng tìm."], [54.335, 58.467, "他问我：你是在哪一站上车的？", "Tā Wèn Wǒ: Nǐ Shì Zài Nǎ Yì Zhàn Shàng Chē De?", "Bác ấy hỏi tôi: Cháu lên xe ở trạm nào?"], [58.467, 63.199, "我说：我在学校门口那一站上的车。", "Wǒ Shuō: Wǒ Zài Xué Xiào Mén Kǒu Nà Yì Zhàn Shàng De Chē.", "Tôi nói: Cháu lên ở trạm cổng trường ạ."], [63.199, 69.706, "司机点点头，说：你先下车，我在车上帮你找一找。", "Sī Jī Diǎn Diǎn Tóu, Shuō: Nǐ Xiān Xià Chē, Wǒ Zài Chē Shàng Bāng Nǐ Zhǎo Yì Zhǎo.", "Tài xế gật đầu, nói: Cháu xuống xe trước, bác tìm giúp trên xe."], [69.706, 75.062, "他还说，如果找到了，就送到车站办公室。", "Tā Hái Shuō, Rú Guǒ Zhǎo Dào Le, Jiù Sòng Dào Chē Zhàn Bàn Gōng Shì.", "Bác ấy còn nói, nếu tìm thấy sẽ mang đến văn phòng nhà ga."], [75.062, 79.434, "司机让我留下电话，说会帮我问问。", "Sī Jī Ràng Wǒ Liú Xià Diàn Huà, Shuō Huì Bāng Wǒ Wèn Wèn.", "Tài xế bảo tôi để lại số điện thoại và sẽ hỏi giúp."], [79.434, 83.11, "我把电话写在一张纸上给了他。", "Wǒ Bǎ Diàn Huà Xiě Zài Yì Zhāng Zhǐ Shàng Gěi Le Tā.", "Tôi viết số điện thoại lên một tờ giấy đưa cho bác ấy."], [83.11, 90.117, "司机笑着说：你放心，有消息我马上打给你，不用担心。", "Sī Jī Xiào Zhe Shuō: Nǐ Fàng Xīn, Yǒu Xiāo Xī Wǒ Mǎ Shàng Dǎ Gěi Nǐ, Bú Yòng Dān Xīn.", "Tài xế cười nói: Yên tâm, có tin bác gọi cho cháu ngay, đừng lo."], [90.117, 93.577, "办公室不大，里面很安静。", "Bàn Gōng Shì Bú Dà, Lǐ Miàn Hěn Ān Jìng.", "Văn phòng không lớn, bên trong rất yên tĩnh."], [93.577, 97.229, "办公室里有一位阿姨在工作。", "Bàn Gōng Shì Lǐ Yǒu Yí Wèi Ā Yí Zài Gōng Zuò.", "Trong văn phòng có một cô đang làm việc."], [97.229, 100.473, "我把丢钱包的事告诉了她。", "Wǒ Bǎ Diū Qián Bāo De Shì Gào Sù Le Tā.", "Tôi kể cho cô chuyện mất ví."], [100.473, 108.301, "阿姨给了我一杯热水，笑着说：你先坐下等一等，我帮你问问别的车。", "Ā Yí Gěi Le Wǒ Yì Bēi Rè Shuǐ, Xiào Zhe Shuō: Nǐ Xiān Zuò Xià Děng Yí Děng, Wǒ Bāng Nǐ Wèn Wèn Bié De Chē.", "Cô đưa cho tôi một cốc nước nóng, cười nói: Cháu ngồi đợi một lát trước, cô hỏi giúp ở các xe khác."], [108.301, 115.008, "我坐在办公室门口，听着外边的车声，心里一直想着钱包。", "Wǒ Zuò Zài Bàn Gōng Shì Mén Kǒu, Tīng Zhe Wài Biān De Chē Shēng, Xīn Lǐ Yì Zhí Xiǎng Zhe Qián Bāo.", "Tôi ngồi ở cửa văn phòng, nghe tiếng xe bên ngoài, trong lòng cứ nghĩ mãi về chiếc ví."], [115.008, 119.068, "如果学生证丢了，明天上课怎么办？", "Rú Guǒ Xué Shēng Zhèng Diū Le, Míng Tiān Shàng Kè Zěn Me Bàn?", "Nếu thẻ học sinh mà mất, mai đi học thì sao?"], [119.068, 122.888, "这时候，妈妈给我打来了电话。", "Zhè Shí Hòu, Mā Ma Gěi Wǒ Dǎ Lái Le Diàn Huà.", "Lúc này, mẹ gọi điện đến cho tôi."], [122.888, 126.228, "妈妈问：你怎么还没回家？", "Mā Ma Wèn: Nǐ Zěn Me Hái Méi Huí Jiā?", "Mẹ hỏi: Sao con chưa về nhà?"], [126.228, 129.112, "我把事情告诉了妈妈。", "Wǒ Bǎ Shì Qíng Gào Sù Le Mā Ma.", "Tôi kể lại sự việc cho mẹ."], [129.112, 136.208, "妈妈小声说：别着急，钱不多，人没事就好，妈妈等你回家。", "Mā Ma Xiǎo Shēng Shuō: Bié Zháo Jí, Qián Bù Duō, Rén Méi Shì Jiù Hǎo, Mā Ma Děng Nǐ Huí Jiā.", "Mẹ nhẹ nhàng nói: Đừng sốt ruột, tiền không nhiều, người không sao là tốt rồi, mẹ đợi con về nhà."], [136.208, 140.076, "听了妈妈的话，我没有那么着急了。", "Tīng Le Mā Ma De Huà, Wǒ Méi Yǒu Nà Me Zháo Jí Le.", "Nghe lời mẹ, tôi không còn sốt ruột như vậy nữa."], [140.076, 143.464, "我等了很久，天慢慢晚了。", "Wǒ Děng Le Hěn Jiǔ, Tiān Màn Màn Wǎn Le.", "Tôi đợi rất lâu, trời dần tối muộn."], [143.464, 146.913, "这时候，阿姨的电话响了。", "Zhè Shí Hòu, Ā Yí De Diàn Huà Xiǎng Le.", "Đúng lúc này, điện thoại của cô đổ chuông."], [146.913, 154.453, "她听完电话，高兴地对我说：找到了，找到了，你的钱包找到了！", "Tā Tīng Wán Diàn Huà, Gāo Xìng De Duì Wǒ Shuō: Zhǎo Dào Le, Zhǎo Dào Le, Nǐ De Qián Bāo Zhǎo Dào Le!", "Nghe điện thoại xong, cô vui vẻ nói với tôi: Tìm thấy rồi, tìm thấy rồi, ví của cháu tìm thấy rồi!"], [154.453, 159.425, "晚上，一位乘客把钱包送到了车站办公室。", "Wǎn Shàng, Yí Wèi Chéng Kè Bǎ Qián Bāo Sòng Dào Le Chē Zhàn Bàn Gōng Shì.", "Buổi tối một hành khách đưa ví đến văn phòng nhà ga."], [159.425, 163.678, "我在车站等了十分钟，拿到了钱包。", "Wǒ Zài Chē Zhàn Děng Le Shí Fēn Zhōng, Ná Dào Le Qián Bāo.", "Tôi đợi mười phút ở ga và nhận lại ví."], [163.678, 166.778, "我马上打开钱包看了看。", "Wǒ Mǎ Shàng Dǎ Kāi Qián Bāo Kàn Le Kàn.", "Tôi lập tức mở ví ra xem."], [166.778, 170.022, "学生证、银行卡都在。", "Xué Shēng Zhèng, Yín Háng Kǎ Dōu Zài.", "Thẻ học sinh và thẻ ngân hàng vẫn còn."], [170.022, 173.842, "一点儿现金也在，什么都没有少。", "Yì Diǎn Er Xiàn Jīn Yě Zài, Shén Me Dōu Méi Yǒu Shǎo.", "Một ít tiền mặt cũng còn, không thiếu thứ gì."], [173.842, 178.933, "我高兴得不知道说什么好，只一直说谢谢。", "Wǒ Gāo Xìng Dé Bù Zhī Dào Shuō Shén Me Hǎo, Zhǐ Yì Zhí Shuō Xiè Xiè.", "Tôi vui đến mức không biết nói gì, chỉ liên tục nói cảm ơn."], [178.933, 185.081, "阿姨笑着说：你要谢谢那位学生，他真是个好孩子。", "Ā Yí Xiào Zhe Shuō: Nǐ Yào Xiè Xiè Nà Wèi Xué Shēng, Tā Zhēn Shì Gè Hǎo Hái Zi.", "Cô cười nói: Cháu nên cảm ơn bạn học sinh đó, bạn ấy thật là một người tốt."], [185.081, 189.381, "办公室的人说，是一位学生捡到的。", "Bàn Gōng Shì De Rén Shuō, Shì Yí Wèi Xué Shēng Jiǎn Dào De.", "Người ở văn phòng nói một học sinh nhặt được."], [189.381, 191.797, "他没有留下名字。", "Tā Méi Yǒu Liú Xià Míng Zì.", "Bạn ấy không để lại tên."], [191.797, 195.401, "我问阿姨：我能在哪儿找到他？", "Wǒ Wèn Ā Yí: Wǒ Néng Zài Nǎ Er Zhǎo Dào Tā?", "Tôi hỏi cô: Cháu có thể tìm bạn ấy ở đâu ạ?"], [195.401, 201.712, "阿姨说：他也是坐这辆车的学生，他做好事不留名字。", "Ā Yí Shuō: Tā Yě Shì Zuò Zhè Liàng Chē De Xué Shēng, Tā Zuò Hǎo Shì Bù Liú Míng Zì.", "Cô nói: Bạn ấy cũng là học sinh đi chuyến xe này, bạn ấy làm việc tốt mà không để lại tên."], [201.712, 206.324, "我给司机和那位学生各写了一句谢谢。", "Wǒ Gěi Sī Jī Hé Nà Wèi Xué Shēng Gè Xiě Le Yí Jù Xiè Xiè.", "Tôi viết một lời cảm ơn cho tài xế và bạn học sinh đó."], [206.324, 210.84, "我把给学生的那句谢谢留在了办公室。", "Wǒ Bǎ Gěi Xué Shēng De Nà Jù Xiè Xiè Liú Zài Le Bàn Gōng Shì.", "Tôi để lại lời cảm ơn cho bạn học sinh ở văn phòng."], [210.84, 216.317, "阿姨说，她见到那个学生，一定把话告诉他。", "Ā Yí Shuō, Tā Jiàn Dào Nà Ge Xué Shēng, Yí Dìng Bǎ Huà Gào Sù Tā.", "Cô nói, gặp bạn học sinh đó, cô nhất định sẽ chuyển lời cho bạn ấy."], [216.317, 220.113, "第二天早上，我又坐了那辆车。", "Dì Èr Tiān Zǎo Shàng, Wǒ Yòu Zuò Le Nà Liàng Chē.", "Sáng hôm sau, tôi lại đi chuyến xe đó."], [220.113, 225.061, "司机看见我，笑着问：钱包拿到了吗？", "Sī Jī Kàn Jiàn Wǒ, Xiào Zhe Wèn: Qián Bāo Ná Dào Le Ma?", "Tài xế thấy tôi, cười hỏi: Nhận được ví rồi chứ?"], [225.061, 230.783, "我高兴地说：拿到了，谢谢您帮我，您真好！", "Wǒ Gāo Xìng De Shuō: Ná Dào Le, Xiè Xiè Nín Bāng Wǒ, Nín Zhēn Hǎo!", "Tôi vui vẻ nói: Nhận được rồi ạ, cảm ơn bác đã giúp cháu, bác tốt thật đấy!"], [230.783, 236.451, "从那天起，我下车以前都会先检查一下包。", "Cóng Nà Tiān Qǐ, Wǒ Xià Chē Yǐ Qián Dōu Huì Xiān Jiǎn Chá Yí Xià Bāo.", "Từ hôm đó, trước khi xuống xe tôi đều kiểm tra túi trước."], [236.451, 240.751, "有一次，我在车上看见一张学生证。", "Yǒu Yí Cì, Wǒ Zài Chē Shàng Kàn Jiàn Yì Zhāng Xué Shēng Zhèng.", "Có một lần, tôi thấy một chiếc thẻ học sinh trên xe."], [240.751, 243.611, "我马上把它给了司机。", "Wǒ Mǎ Shàng Bǎ Tā Gěi Le Sī Jī.", "Tôi lập tức đưa nó cho tài xế."], [243.611, 247.92, "我想，那个学生现在一定也很着急。", "Wǒ Xiǎng, Nà Ge Xué Shēng Xiàn Zài Yí Dìng Yě Hěn Zháo Jí.", "Tôi nghĩ, bạn học sinh đó lúc này chắc cũng đang rất sốt ruột."], [247.92, 250.852, "好意是可以传下去的。", "Hǎo Yì Shì Kě Yǐ Chuán Xià Qù De.", "Lòng tốt có thể truyền tiếp đi."], [250.852, 255.343, "这件事让我对这座城市更有信心。", "Zhè Jiàn Shì Ràng Wǒ Duì Zhè Zuò Chéng Shì Gèng Yǒu Xìn Xīn.", "Chuyện này khiến tôi tin thành phố này hơn."], [255.343, 263.58, "现在，每次坐车，我都会想起那个没有留下名字的学生，心里还是很温暖。", "Xiàn Zài, Měi Cì Zuò Chē, Wǒ Dōu Huì Xiǎng Qǐ Nà Ge Méi Yǒu Liú Xià Míng Zì De Xué Shēng, Xīn Lǐ Hái Shì Hěn Wēn Nuǎn.", "Bây giờ mỗi lần đi xe, tôi đều nhớ đến bạn học sinh không để lại tên ấy, trong lòng vẫn rất ấm áp."]]}, "hsk3-10": {"dur": 293.15, "cues": [[7.593, 12.829, "新学期开始的时候，我对自己很有信心。", "Xīn Xué Qī Kāi Shǐ De Shí Hòu, Wǒ Duì Zì Jǐ Hěn Yǒu Xìn Xīn.", "Đầu học kỳ mới, tôi rất tự tin vào bản thân."], [12.829, 16.817, "上课的时候，我很少打开本子。", "Shàng Kè De Shí Hòu, Wǒ Hěn Shǎo Dǎ Kāi Běn Zi.", "Lúc học, tôi hiếm khi mở sổ."], [16.817, 20.805, "以前我上课只听，不爱写下来。", "Yǐ Qián Wǒ Shàng Kè Zhī Tīng, Bú Ài Xiě Xià Lái.", "Trước đây tôi chỉ nghe giảng, không thích ghi lại."], [20.805, 24.938, "我想，听懂了就可以了，不用写。", "Wǒ Xiǎng, Tīng Dǒng Le Jiù Kě Yǐ Le, Bú Yòng Xiě.", "Tôi nghĩ, nghe hiểu là được rồi, không cần viết."], [24.938, 29.094, "老师说得很快，我也听得很认真。", "Lǎo Shī Shuō Dé Hěn Kuài, Wǒ Yě Tīng Dé Hěn Rèn Zhēn.", "Thầy nói rất nhanh, tôi cũng nghe rất chăm chú."], [29.094, 33.274, "可是一个星期以后，我就忘了很多。", "Kě Shì Yí Gè Xīng Qī Yǐ Hòu, Wǒ Jiù Wàng Le Hěn Duō.", "Nhưng một tuần sau, tôi đã quên rất nhiều."], [33.274, 38.342, "有一次上课，老师问了上个星期的内容。", "Yǒu Yí Cì Shàng Kè, Lǎo Shī Wèn Le Shàng Gè Xīng Qī De Nèi Róng.", "Có một lần trong giờ học, thầy hỏi nội dung tuần trước."], [38.342, 42.354, "同学们都能回答，我却说不出来。", "Tóng Xué Men Dōu Néng Huí Dá, Wǒ Què Shuō Bù Chū Lái.", "Các bạn đều trả lời được, còn tôi thì không nói ra được."], [42.354, 45.598, "我坐在那里，脸都红了。", "Wǒ Zuò Zài Nà Lǐ, Liǎn Dōu Hóng Le.", "Tôi ngồi ở đó, mặt đỏ cả lên."], [45.598, 49.691, "下课以后，我的心里很不舒服。", "Xià Kè Yǐ Hòu, Wǒ De Xīn Lǐ Hěn Bù Shū Fu.", "Tan học xong, trong lòng tôi rất khó chịu."], [49.691, 53.439, "考试还有两个星期就要到了。", "Kǎo Shì Hái Yǒu Liǎng Gè Xīng Qī Jiù Yào Dào Le.", "Kỳ thi còn hai tuần nữa là đến."], [53.439, 58.675, "我开始复习，可是书上的内容都很陌生。", "Wǒ Kāi Shǐ Fù Xí, Kě Shì Shū Shàng De Nèi Róng Dōu Hěn Mò Shēng.", "Tôi bắt đầu ôn, nhưng nội dung trong sách đều rất xa lạ."], [58.675, 63.367, "考试以前才发现，很多内容已经忘了。", "Kǎo Shì Yǐ Qián Cái Fā Xiàn, Hěn Duō Nèi Róng Yǐ Jīng Wàng Le.", "Trước kỳ thi mới phát hiện nhiều nội dung đã quên."], [63.367, 67.523, "那天晚上，我给同学小刚打电话。", "Nà Tiān Wǎn Shàng, Wǒ Gěi Tóng Xué Xiǎo Gāng Dǎ Diàn Huà.", "Tối hôm đó, tôi gọi điện cho bạn học Tiểu Cương."], [67.523, 74.559, "我着急地说：小刚，我复习得不好，心里很不舒服，怎么办？", "Wǒ Zháo Jí De Shuō: Xiǎo Gāng, Wǒ Fù Xí Dé Bù Hǎo, Xīn Lǐ Hěn Bù Shū Fu, Zěn Me Bàn?", "Tôi sốt ruột nói: Tiểu Cương, tớ ôn không tốt, trong lòng khó chịu lắm, phải làm sao đây?"], [74.559, 81.363, "小刚笑着说：别着急，你先来我家，我给你看我的笔记。", "Xiǎo Gāng Xiào Zhe Shuō: Bié Zháo Jí, Nǐ Xiān Lái Wǒ Jiā, Wǒ Gěi Nǐ Kàn Wǒ De Bǐ Jì.", "Tiểu Cương cười nói: Đừng sốt ruột, cậu đến nhà tớ trước đi, tớ cho cậu xem vở ghi của tớ."], [81.363, 85.615, "到了小刚家，他把本子打开给我看。", "Dào Le Xiǎo Gāng Jiā, Tā Bǎ Běn Zi Dǎ Kāi Gěi Wǒ Kàn.", "Đến nhà Tiểu Cương, bạn ấy mở sổ ra cho tôi xem."], [85.615, 91.019, "他的本子上没有很多字，只有词和短句子。", "Tā De Běn Zi Shàng Méi Yǒu Hěn Duō Zì, Zhǐ Yǒu Cí Hé Duǎn Jù Zi.", "Sổ của bạn ấy không có nhiều chữ, chỉ có từ và câu ngắn."], [91.019, 94.598, "我问：这么少，能记住吗？", "Wǒ Wèn: Zhè Me Shǎo, Néng Jì Zhù Ma?", "Tôi hỏi: Ít thế này, nhớ được không?"], [94.598, 101.154, "小刚笑着说：你看着这个词，想一想老师说了什么。", "Xiǎo Gāng Xiào Zhe Shuō: Nǐ Kàn Zhe Zhè Ge Cí, Xiǎng Yì Xiǎng Lǎo Shī Shuō Le Shén Me.", "Tiểu Cương cười nói: Cậu nhìn từ này, nghĩ xem thầy đã nói gì."], [101.154, 105.598, "我看着一个词，真的想起了老师的话。", "Wǒ Kàn Zhe Yí Gè Cí, Zhēn De Xiǎng Qǐ Le Lǎo Shī De Huà.", "Tôi nhìn một từ, thật sự nhớ ra lời thầy."], [105.598, 111.572, "我高兴地说：这个方法真有意思，谢谢你告诉我。", "Wǒ Gāo Xìng De Shuō: Zhè Ge Fāng Fǎ Zhēn Yǒu Yì Si, Xiè Xiè Nǐ Gào Sù Wǒ.", "Tôi vui vẻ nói: Cách này hay thật, cảm ơn cậu đã chỉ cho tớ."], [111.572, 118.2, "同学把他的方法告诉我：一边听，一边记下关键词。", "Tóng Xué Bǎ Tā De Fāng Fǎ Gào Sù Wǒ: Yì Biān Tīng, Yì Biān Jì Xià Guān Jiàn Cí.", "Bạn kể cho tôi cách của bạn: vừa nghe vừa ghi từ khóa."], [118.2, 122.068, "不用把老师的每一句话都写上。", "Bú Yòng Bǎ Lǎo Shī De Měi Yí Jù Huà Dōu Xiě Shàng.", "Không cần chép từng câu của thầy."], [122.068, 130.566, "小刚还笑着说：例子也要写一个，复习的时候最有用，你试试就知道了。", "Xiǎo Gāng Hái Xiào Zhe Shuō: Lì Zǐ Yě Yào Xiě Yí Gè, Fù Xí De Shí Hòu Zuì Yǒu Yòng, Nǐ Shì Shì Jiù Zhī Dào Le.", "Tiểu Cương còn cười nói: Ví dụ cũng phải viết một cái, lúc ôn là hữu ích nhất, cậu thử là biết ngay."], [130.566, 134.146, "回家以后，我马上试了试。", "Huí Jiā Yǐ Hòu, Wǒ Mǎ Shàng Shì Le Shì.", "Về nhà xong, tôi lập tức thử ngay."], [134.146, 139.622, "第二天上课，我一边听，一边写关键词。", "Dì Èr Tiān Shàng Kè, Wǒ Yì Biān Tīng, Yì Biān Xiě Guān Jiàn Cí.", "Hôm sau trong giờ học, tôi vừa nghe vừa viết từ khóa."], [139.622, 144.66, "一开始很难，老师说得快，我写得慢。", "Yì Kāi Shǐ Hěn Nán, Lǎo Shī Shuō Dé Kuài, Wǒ Xiě Dé Màn.", "Lúc đầu rất khó, thầy nói nhanh, tôi viết chậm."], [144.66, 149.536, "有一句话我没有听清楚，也没有写下来。", "Yǒu Yí Jù Huà Wǒ Méi Yǒu Tīng Qīng Chǔ, Yě Méi Yǒu Xiě Xià Lái.", "Có một câu tôi không nghe rõ, cũng không viết lại được."], [149.536, 153.284, "下课以后，我有一点儿想放弃。", "Xià Kè Yǐ Hòu, Wǒ Yǒu Yì Diǎn Er Xiǎng Fàng Qì.", "Tan học xong, tôi hơi muốn bỏ cuộc."], [153.284, 161.866, "小刚看见了，笑着说：别放弃，先写词，不用写完一句话，慢慢来。", "Xiǎo Gāng Kàn Jiàn Le, Xiào Zhe Shuō: Bié Fàng Qì, Xiān Xiě Cí, Bú Yòng Xiě Wán Yí Jù Huà, Màn Màn Lái.", "Tiểu Cương thấy vậy, cười nói: Đừng bỏ cuộc, cứ viết từ trước, không cần viết hết cả câu, cứ từ từ."], [161.866, 165.278, "他还把他记下的词给我看。", "Tā Hái Bǎ Tā Jì Xià De Cí Gěi Wǒ Kàn.", "Bạn ấy còn cho tôi xem những từ bạn ấy ghi lại."], [165.278, 171.99, "我点点头，笑着说：好，谢谢你，我再试一个星期。", "Wǒ Diǎn Diǎn Tóu, Xiào Zhe Shuō: Hǎo, Xiè Xiè Nǐ, Wǒ Zài Shì Yí Gè Xīng Qī.", "Tôi gật đầu, cười nói: Được, cảm ơn cậu, tớ thử thêm một tuần nữa."], [171.99, 175.618, "慢慢地，我写得比以前快了。", "Màn Màn De, Wǒ Xiě Dé Bǐ Yǐ Qián Kuài Le.", "Dần dần, tôi viết nhanh hơn trước."], [175.618, 179.126, "我也不再把每一句话都写上。", "Wǒ Yě Bú Zài Bǎ Měi Yí Jù Huà Dōu Xiě Shàng.", "Tôi cũng không còn chép lại từng câu nữa."], [179.126, 183.546, "现在我的笔记只写关键词和例子。", "Xiàn Zài Wǒ De Bǐ Jì Zhī Xiě Guān Jiàn Cí Hé Lì Zǐ.", "Bây giờ ghi chú của tôi chỉ có từ khóa và ví dụ."], [183.546, 188.902, "晚上复习的时候，我先看词，再想例子。", "Wǎn Shàng Fù Xí De Shí Hòu, Wǒ Xiān Kàn Cí, Zài Xiǎng Lì Zǐ.", "Buổi tối khi ôn, tôi xem từ trước, rồi nghĩ đến ví dụ."], [188.902, 194.018, "我试了几个星期，复习的时候清楚多了。", "Wǒ Shì Le Jǐ Gè Xīng Qī, Fù Xí De Shí Hòu Qīng Chǔ Duō Le.", "Tôi thử vài tuần, lúc ôn thì rõ ràng hơn nhiều."], [194.018, 199.459, "复习的时候，我看着词就能想起老师的话。", "Fù Xí De Shí Hòu, Wǒ Kàn Zhe Cí Jiù Néng Xiǎng Qǐ Lǎo Shī De Huà.", "Lúc ôn, nhìn từ là tôi nhớ lời thầy."], [199.459, 204.191, "有不懂的地方，我第二天就去问老师。", "Yǒu Bù Dǒng De Dì Fāng, Wǒ Dì Èr Tiān Jiù Qù Wèn Lǎo Shī.", "Chỗ nào không hiểu, hôm sau tôi đi hỏi thầy ngay."], [204.191, 210.466, "老师笑着说：问得好，你的问题比以前清楚多了。", "Lǎo Shī Xiào Zhe Shuō: Wèn Dé Hǎo, Nǐ De Wèn Tí Bǐ Yǐ Qián Qīng Chǔ Duō Le.", "Thầy cười nói: Hỏi hay lắm, câu hỏi của em rõ ràng hơn trước nhiều."], [210.466, 215.102, "考试前一个星期，我和小刚一起复习。", "Kǎo Shì Qián Yí Gè Xīng Qī, Wǒ Hé Xiǎo Gāng Yì Qǐ Fù Xí.", "Một tuần trước kỳ thi, tôi ôn cùng Tiểu Cương."], [215.102, 219.475, "我们看着笔记，一边问，一边回答。", "Wǒ Men Kàn Zhe Bǐ Jì, Yì Biān Wèn, Yì Biān Huí Dá.", "Chúng tôi nhìn vở ghi, vừa hỏi vừa trả lời."], [219.475, 223.199, "考试前一天，我没有再通宵。", "Kǎo Shì Qián Yì Tiān, Wǒ Méi Yǒu Zài Tōng Xiāo.", "Hôm trước kỳ thi tôi không thức trắng đêm."], [223.199, 226.683, "因为前面已经看过三遍。", "Yīn Wèi Qián Miàn Yǐ Jīng Kàn Guò Sān Biàn.", "Vì trước đó tôi đã xem ba lần."], [226.683, 235.102, "考试那天早上，天气很好，我吃完早饭，慢慢走去学校，心里很安静。", "Kǎo Shì Nà Tiān Zǎo Shàng, Tiān Qì Hěn Hǎo, Wǒ Chī Wán Zǎo Fàn, Màn Màn Zǒu Qù Xué Xiào, Xīn Lǐ Hěn Ān Jìng.", "Sáng ngày thi, trời rất đẹp, tôi ăn sáng xong, từ từ đi bộ đến trường, trong lòng rất yên tĩnh."], [235.102, 239.426, "我坐在教室里，心里一点儿也不紧张。", "Wǒ Zuò Zài Jiào Shì Lǐ, Xīn Lǐ Yì Diǎn Er Yě Bù Jǐn Zhāng.", "Tôi ngồi trong lớp, trong lòng chẳng hồi hộp chút nào."], [239.426, 243.654, "考试的时候，很多问题我都见过。", "Kǎo Shì De Shí Hòu, Hěn Duō Wèn Tí Wǒ Dōu Jiàn Guò.", "Lúc thi, nhiều câu hỏi tôi đều đã gặp."], [243.654, 248.964, "成绩出来以后，我的成绩比上次稳定了。", "Chéng Jì Chū Lái Yǐ Hòu, Wǒ De Chéng Jì Bǐ Shàng Cì Wěn Dìng Le.", "Khi có điểm, điểm số của tôi ổn định hơn lần trước."], [248.964, 252.592, "我把这个好消息告诉了小刚。", "Wǒ Bǎ Zhè Ge Hǎo Xiāo Xī Gào Sù Le Xiǎo Gāng.", "Tôi báo tin vui này cho Tiểu Cương."], [252.592, 260.458, "小刚笑着说：看，方法对了，就不用很多时间了，我真为你高兴。", "Xiǎo Gāng Xiào Zhe Shuō: Kàn, Fāng Fǎ Duì Le, Jiù Bú Yòng Hěn Duō Shí Jiān Le, Wǒ Zhēn Wèi Nǐ Gāo Xìng.", "Tiểu Cương cười nói: Thấy chưa, phương pháp đúng rồi thì không tốn nhiều thời gian nữa, tớ thật sự mừng cho cậu."], [260.458, 264.782, "现在，班里有同学问我怎么做笔记。", "Xiàn Zài, Bān Lǐ Yǒu Tóng Xué Wèn Wǒ Zěn Me Zuò Bǐ Jì.", "Bây giờ, có bạn trong lớp hỏi tôi cách ghi chép."], [264.782, 268.938, "我也像小刚一样，把方法告诉他们。", "Wǒ Yě Xiàng Xiǎo Gāng Yí Yàng, Bǎ Fāng Fǎ Gào Sù Tā Men.", "Tôi cũng giống Tiểu Cương, chỉ lại cách cho các bạn."], [268.938, 273.766, "现在我觉得，好的笔记真的能节省时间。", "Xiàn Zài Wǒ Jué De, Hǎo De Bǐ Jì Zhēn De Néng Jié Shěng Shí Jiān.", "Bây giờ tôi thấy ghi chép tốt thật sự tiết kiệm thời gian."], [273.766, 277.61, "我终于觉得方法比时间更重要。", "Wǒ Zhōng Yú Jué De Fāng Fǎ Bǐ Shí Jiān Gèng Zhòng Yào.", "Cuối cùng tôi thấy cách học quan trọng hơn thời gian."], [277.61, 283.926, "一个同学笑着说：谢谢你，我现在复习也清楚多了。", "Yí Gè Tóng Xué Xiào Zhe Shuō: Xiè Xiè Nǐ, Wǒ Xiàn Zài Fù Xí Yě Qīng Chǔ Duō Le.", "Một bạn học cười nói: Cảm ơn cậu, bây giờ tớ ôn cũng rõ ràng hơn nhiều."]]}, "hsk3-11": {"dur": 346.57, "cues": [[6.989, 13.785, "九月的一天，老师在班里问我们：“谁想参加今年的运动会？”", "Jiǔ Yuè De Yì Tiān, Lǎo Shī Zài Bān Lǐ Wèn Wǒ Men, Shuí Xiǎng Cān Jiā Jīn Nián De Yùn Dòng Huì?", "Một ngày tháng Chín, thầy hỏi cả lớp: “Ai muốn tham gia hội thao năm nay?”"], [13.785, 17.197, "学校运动会在十月举行。", "Xué Xiào Yùn Dòng Huì Zài Shí Yuè Jǔ Xíng.", "Hội thao của trường tổ chức vào tháng Mười."], [17.197, 25.078, "同学们听了都很高兴，有的想跑步，有的想跳远，还有的想参加接力。", "Tóng Xué Men Tīng Le Dōu Hěn Gāo Xìng, Yǒu De Xiǎng Pǎo Bù, Yǒu De Xiǎng Tiào Yuǎn, Hái Yǒu De Xiǎng Cān Jiā Jiē Lì.", "Các bạn nghe xong đều rất vui, có bạn muốn chạy, có bạn muốn nhảy xa, có bạn lại muốn chạy tiếp sức."], [25.078, 29.234, "我们班参加了跑步、跳远和接力。", "Wǒ Men Bān Cān Jiā Le Pǎo Bù, Tiào Yuǎn Hé Jiē Lì.", "Lớp tôi tham gia chạy, nhảy xa và chạy tiếp sức."], [29.234, 34.278, "我的朋友小刚跑得很快，他参加的是接力。", "Wǒ De Péng Yǒu Xiǎo Gāng Pǎo Dé Hěn Kuài, Tā Cān Jiā De Shì Jiē Lì.", "Bạn tôi là Tiểu Cương chạy rất nhanh, bạn ấy tham gia chạy tiếp sức."], [34.278, 39.102, "我想了很久，不知道自己可以参加什么。", "Wǒ Xiǎng Le Hěn Jiǔ, Bù Zhī Dào Zì Jǐ Kě Yǐ Cān Jiā Shén Me.", "Tôi nghĩ rất lâu, không biết mình có thể tham gia môn gì."], [39.102, 44.986, "小刚笑着说：“你跑步不错，可以试试四百米。”", "Xiǎo Gāng Xiào Zhe Shuō, Nǐ Pǎo Bù Bú Cuò, Kě Yǐ Shì Shì Sì Bǎi Mǐ.", "Tiểu Cương cười nói: “Cậu chạy khá tốt, thử chạy bốn trăm mét đi.”"], [44.986, 49.946, "我报名的是四百米，心里其实很紧张。", "Wǒ Bào Míng De Shì Sì Bǎi Mǐ, Xīn Lǐ Qí Shí Hěn Jǐn Zhāng.", "Tôi đăng ký bốn trăm mét, trong lòng thật ra rất hồi hộp."], [49.946, 58.654, "我跟妈妈说了这件事，妈妈笑着说：“太好了！妈妈为你高兴，慢慢练习就可以。”", "Wǒ Gēn Mā Mā Shuō Le Zhè Jiàn Shì, Mā Mā Xiào Zhe Shuō, Tài Hǎo Le! Mā Mā Wèi Nǐ Gāo Xìng, Màn Màn Liàn Xí Jiù Kě Yǐ.", "Tôi kể chuyện này với mẹ, mẹ cười nói: “Tuyệt quá! Mẹ mừng cho con, cứ tập từ từ là được.”"], [58.654, 64.034, "报名以后，我每天早上都去学校练习跑步。", "Bào Míng Yǐ Hòu, Wǒ Měi Tiān Zǎo Shàng Dōu Qù Xué Xiào Liàn Xí Pǎo Bù.", "Sau khi đăng ký, sáng nào tôi cũng đến trường tập chạy."], [64.034, 69.366, "第一天，我跑得很慢，跑完以后，腿很疼。", "Dì Yī Tiān, Wǒ Pǎo Dé Hěn Màn, Pǎo Wán Yǐ Hòu, Tuǐ Hěn Téng.", "Ngày đầu tiên tôi chạy rất chậm, chạy xong thì chân rất đau."], [69.366, 74.838, "我坐在地上休息，心里想，明天我还要来吗？", "Wǒ Zuò Zài Dì Shàng Xiū Xī, Xīn Lǐ Xiǎng, Míng Tiān Wǒ Hái Yào Lái Ma?", "Tôi ngồi xuống đất nghỉ, trong lòng tự hỏi, mai mình còn đến nữa không?"], [74.838, 79.546, "教练看见了，走过来告诉我跑步的方法。", "Jiào Liàn Kàn Jiàn Le, Zǒu Guò Lái Gào Sù Wǒ Pǎo Bù De Fāng Fǎ.", "Huấn luyện viên nhìn thấy, đi lại và chỉ cho tôi cách chạy."], [79.546, 87.182, "他笑着说：“开始不要跑太快，慢慢来，最后再快一点儿，你做得到的。”", "Tā Xiào Zhe Shuō, Kāi Shǐ Bú Yào Pǎo Tài Kuài, Màn Màn Lái, Zuì Hòu Zài Kuài Yì Diǎn Ér, Nǐ Zuò Dé Dào De.", "Thầy cười nói: “Lúc đầu đừng chạy nhanh quá, cứ từ từ, cuối cùng mới nhanh hơn một chút, em làm được mà.”"], [87.182, 92.274, "我记住了教练的话，每天用他的方法练习。", "Wǒ Jì Zhù Le Jiào Liàn De Huà, Měi Tiān Yòng Tā De Fāng Fǎ Liàn Xí.", "Tôi ghi nhớ lời thầy, ngày nào cũng tập theo cách của thầy."], [92.274, 98.23, "一个星期以后，我跑得比以前快了，也没有那么累了。", "Yí Gè Xīng Qī Yǐ Hòu, Wǒ Pǎo Dé Bǐ Yǐ Qián Kuài Le, Yě Méi Yǒu Nà Me Lèi Le.", "Sau một tuần, tôi chạy nhanh hơn trước, cũng không mệt như trước nữa."], [98.23, 104.536, "两个星期以后，我可以跑完四百米了，腿也不太疼了。", "Liǎng Gè Xīng Qī Yǐ Hòu, Wǒ Kě Yǐ Pǎo Wán Sì Bǎi Mǐ Le, Tuǐ Yě Bú Tài Téng Le.", "Sau hai tuần, tôi đã chạy hết được bốn trăm mét, chân cũng không đau lắm nữa."], [104.536, 108.836, "运动会前一天晚上，我很晚才睡觉。", "Yùn Dòng Huì Qián Yì Tiān Wǎn Shàng, Wǒ Hěn Wǎn Cái Shuì Jiào.", "Tối hôm trước hội thao, tôi ngủ rất muộn."], [108.836, 113.496, "妈妈说：“早点儿休息吧，明天好好跑。”", "Mā Mā Shuō, Zǎo Diǎn Ér Xiū Xī Ba, Míng Tiān Hǎo Hǎo Pǎo.", "Mẹ nói: “Nghỉ sớm đi, mai chạy cho tốt nhé.”"], [113.496, 119.164, "我说：“我有点儿害怕，大家都比我快，怎么办？”", "Wǒ Shuō, Wǒ Yǒu Diǎn Ér Hài Pà, Dà Jiā Dōu Bǐ Wǒ Kuài, Zěn Me Bàn?", "Tôi nói: “Con hơi sợ, mọi người đều nhanh hơn con thì sao?”"], [119.164, 125.481, "妈妈笑着说：“妈妈相信你，跑完就好，名次不重要。”", "Mā Mā Xiào Zhe Shuō, Mā Mā Xiāng Xìn Nǐ, Pǎo Wán Jiù Hǎo, Míng Cì Bú Zhòng Yào.", "Mẹ cười nói: “Mẹ tin con, chạy hết là tốt rồi, thứ hạng không quan trọng.”"], [125.481, 133.933, "第二天早上，学校里来了很多人，到处都是说话声和笑声，大家都很高兴。", "Dì Èr Tiān Zǎo Shàng, Xué Xiào Lǐ Lái Le Hěn Duō Rén, Dào Chù Dōu Shì Shuō Huà Shēng Hé Xiào Shēng, Dà Jiā Dōu Hěn Gāo Xìng.", "Sáng hôm sau, trường có rất nhiều người đến, khắp nơi đều là tiếng nói chuyện và tiếng cười, ai cũng vui vẻ."], [133.933, 138.391, "天气很好，没有下雨，太阳也不太热。", "Tiān Qì Hěn Hǎo, Méi Yǒu Xià Yǔ, Tài Yáng Yě Bú Tài Rè.", "Thời tiết rất đẹp, không mưa, nắng cũng không gắt."], [138.391, 144.347, "我穿上号码布，站在小刚旁边，心里更紧张了。", "Wǒ Chuān Shàng Hào Mǎ Bù, Zhàn Zài Xiǎo Gāng Páng Biān, Xīn Lǐ Gèng Jǐn Zhāng Le.", "Tôi đeo số áo, đứng cạnh Tiểu Cương, trong lòng càng hồi hộp hơn."], [144.347, 152.295, "小刚笑着说：“别紧张，我相信你，你练习了两个星期了，一定可以的！”", "Xiǎo Gāng Xiào Zhe Shuō, Bié Jǐn Zhāng, Wǒ Xiāng Xìn Nǐ, Nǐ Liàn Xí Le Liǎng Gè Xīng Qī Le, Yí Dìng Kě Yǐ De.", "Tiểu Cương cười nói: “Đừng hồi hộp, tớ tin cậu, cậu đã tập hai tuần rồi, nhất định làm được!”"], [152.295, 158.731, "先是跳远比赛，一个同学跳得很远，同学们都很高兴。", "Xiān Shì Tiào Yuǎn Bǐ Sài, Yí Gè Tóng Xué Tiào Dé Hěn Yuǎn, Tóng Xué Men Dōu Hěn Gāo Xìng.", "Trước tiên là thi nhảy xa, một bạn nhảy rất xa, các bạn đều rất vui."], [158.731, 164.519, "然后是接力比赛，我们班跑得很快，拿了第一名。", "Rán Hòu Shì Jiē Lì Bǐ Sài, Wǒ Men Bān Pǎo Dé Hěn Kuài, Ná Le Dì Yī Míng.", "Sau đó là chạy tiếp sức, lớp tôi chạy rất nhanh và giành hạng nhất."], [164.519, 170.736, "听到我们班拿了第一名，我很高兴，也更想好好跑了。", "Tīng Dào Wǒ Men Bān Ná Le Dì Yī Míng, Wǒ Hěn Gāo Xìng, Yě Gèng Xiǎng Hǎo Hǎo Pǎo Le.", "Nghe tin lớp mình về nhất, tôi rất vui và càng muốn chạy thật tốt."], [170.736, 175.612, "很快就到四百米了，我慢慢走到前面。", "Hěn Kuài Jiù Dào Sì Bǎi Mǐ Le, Wǒ Màn Màn Zǒu Dào Qián Miàn.", "Chẳng mấy chốc đã đến lượt chạy bốn trăm mét, tôi từ từ đi lên phía trước."], [175.612, 179.936, "我看着前面，心里一直想着教练的话。", "Wǒ Kàn Zhe Qián Miàn, Xīn Lǐ Yì Zhí Xiǎng Zhe Jiào Liàn De Huà.", "Tôi nhìn về phía trước, trong lòng cứ nghĩ mãi đến lời của huấn luyện viên."], [179.936, 185.04, "教练对我说：“不要紧张，把步子跑稳。”", "Jiào Liàn Duì Wǒ Shuō, Bú Yào Jǐn Zhāng, Bǎ Bù Zi Pǎo Wěn.", "Huấn luyện viên nói với tôi: “Đừng hồi hộp, giữ nhịp bước cho vững.”"], [185.04, 189.58, "枪响以后，我只想着把步子跑稳。", "Qiāng Xiǎng Yǐ Hòu, Wǒ Zhī Xiǎng Zhe Bǎ Bù Zǐ Pǎo Wěn.", "Sau tiếng súng, tôi chỉ nghĩ đến việc giữ nhịp bước."], [189.58, 195.944, "开始的时候，我跑得不快，旁边的人都跑到我前面去了。", "Kāi Shǐ De Shí Hòu, Wǒ Pǎo Dé Bú Kuài, Páng Biān De Rén Dōu Pǎo Dào Wǒ Qián Miàn Qù Le.", "Lúc bắt đầu tôi chạy không nhanh, mọi người bên cạnh đều chạy lên trước tôi."], [195.944, 201.66, "跑到一半的时候，我的腿很累，我很想休息一下。", "Pǎo Dào Yí Bàn De Shí Hòu, Wǒ De Tuǐ Hěn Lèi, Wǒ Hěn Xiǎng Xiū Xī Yí Xià.", "Chạy được nửa đường, chân tôi rất mỏi, tôi rất muốn nghỉ một chút."], [201.66, 207.842, "我心里想，我要一直跑下去，休息了就到不了终点了。", "Wǒ Xīn Lǐ Xiǎng, Wǒ Yào Yì Zhí Pǎo Xià Qù, Xiū Xī Le Jiù Dào Bù Liǎo Zhōng Diǎn Le.", "Tôi thầm nghĩ, mình phải chạy mãi về phía trước, nghỉ là sẽ không tới được đích."], [207.842, 213.438, "我听见同学们的掌声，也听见他们叫我的名字。", "Wǒ Tīng Jiàn Tóng Xué Men De Zhǎng Shēng, Yě Tīng Jiàn Tā Men Jiào Wǒ De Míng Zì.", "Tôi nghe thấy tiếng vỗ tay của các bạn, và nghe thấy họ gọi tên tôi."], [213.438, 219.418, "小刚在旁边大声说：“你可以的，我等你，慢慢来！”", "Xiǎo Gāng Zài Páng Biān Dà Shēng Shuō, Nǐ Kě Yǐ De, Wǒ Děng Nǐ, Màn Màn Lái!", "Tiểu Cương ở bên cạnh nói to: “Cậu làm được mà, tớ đợi cậu, cứ từ từ!”"], [219.418, 225.187, "我听了他的话，一点儿一点儿往前跑，一直跑到最后。", "Wǒ Tīng Le Tā De Huà, Yì Diǎn Ér Yì Diǎn Ér Wǎng Qián Pǎo, Yì Zhí Pǎo Dào Zuì Hòu.", "Nghe lời bạn, tôi chạy từng chút từng chút về phía trước, chạy mãi cho đến cuối cùng."], [225.187, 228.743, "最后一点儿路，我跑得更快了。", "Zuì Hòu Yì Diǎn Ér Lù, Wǒ Pǎo Dé Gèng Kuài Le.", "Đoạn đường cuối cùng, tôi chạy nhanh hơn."], [228.743, 233.619, "我跑到终点的时候，同学们都在那儿等我。", "Wǒ Pǎo Dào Zhōng Diǎn De Shí Hòu, Tóng Xué Men Dōu Zài Nà Ér Děng Wǒ.", "Khi tôi chạy tới đích, các bạn đều đang đợi tôi ở đó."], [233.619, 238.807, "虽然我不是第一名，可是完成了自己的目标。", "Suī Rán Wǒ Bú Shì Dì Yī Míng, Kě Shì Wán Chéng Le Zì Jǐ De Mù Biāo.", "Dù tôi không về nhất, tôi đã hoàn thành mục tiêu của mình."], [238.807, 243.879, "同学们在终点等我，那一刻我特别感动。", "Tóng Xué Men Zài Zhōng Diǎn Děng Wǒ, Nà Yí Kè Wǒ Tè Bié Gǎn Dòng.", "Các bạn đợi tôi ở đích, khoảnh khắc đó tôi rất xúc động."], [243.879, 249.139, "小刚马上给我一杯水，说：“你跑得真好！”", "Xiǎo Gāng Mǎ Shàng Gěi Wǒ Yì Bēi Shuǐ, Shuō, Nǐ Pǎo Dé Zhēn Hǎo!", "Tiểu Cương lập tức đưa tôi một cốc nước và nói: “Cậu chạy giỏi lắm!”"], [249.139, 256.559, "我喝完水，坐下来休息了很久，听着大家的笑声，心里特别高兴。", "Wǒ Hē Wán Shuǐ, Zuò Xià Lái Xiū Xī Le Hěn Jiǔ, Tīng Zhe Dà Jiā De Xiào Shēng, Xīn Lǐ Tè Bié Gāo Xìng.", "Uống nước xong, tôi ngồi xuống nghỉ rất lâu, nghe tiếng cười của mọi người, trong lòng vô cùng vui."], [256.559, 260.83, "我的腿还是很疼，可是我一直在笑。", "Wǒ De Tuǐ Hái Shì Hěn Téng, Kě Shì Wǒ Yì Zhí Zài Xiào.", "Chân tôi vẫn rất đau, nhưng tôi cứ cười mãi."], [260.83, 264.77, "回到班里，大家拍了很多照片。", "Huí Dào Bān Lǐ, Dà Jiā Pāi Le Hěn Duō Zhào Piàn.", "Về lớp mọi người chụp rất nhiều ảnh."], [264.77, 270.246, "我和小刚也拍了一张照片，我们两个人都笑着。", "Wǒ Hé Xiǎo Gāng Yě Pāi Le Yì Zhāng Zhào Piàn, Wǒ Men Liǎng Gè Rén Dōu Xiào Zhe.", "Tôi và Tiểu Cương cũng chụp một tấm ảnh, cả hai đứa đều đang cười."], [270.246, 275.435, "大家看着照片，说今天是很高兴的一天。", "Dà Jiā Kàn Zhe Zhào Piàn, Shuō Jīn Tiān Shì Hěn Gāo Xìng De Yì Tiān.", "Mọi người xem ảnh và nói hôm nay là một ngày rất vui."], [275.435, 278.727, "教练说明年还可以再试。", "Jiào Liàn Shuō Míng Nián Hái Kě Yǐ Zài Shì.", "Huấn luyện viên nói năm sau có thể thử lại."], [278.727, 285.691, "教练还笑着说：“老师为你高兴！你今年是第一次，明年会更好。”", "Jiào Liàn Hái Xiào Zhe Shuō, Lǎo Shī Wèi Nǐ Gāo Xìng, Nǐ Jīn Nián Shì Dì Yī Cì, Míng Nián Huì Gèng Hǎo.", "Thầy còn cười nói: “Thầy mừng cho em! Năm nay là lần đầu của em, năm sau sẽ tốt hơn.”"], [285.691, 291.828, "我笑着说：“谢谢老师！明年我还参加，还跑四百米。”", "Wǒ Xiào Zhe Shuō, Xiè Xiè Lǎo Shī! Míng Nián Wǒ Hái Cān Jiā, Hái Pǎo Sì Bǎi Mǐ.", "Tôi cười nói: “Em cảm ơn thầy! Năm sau em vẫn tham gia, vẫn chạy bốn trăm mét.”"], [291.828, 296.896, "回家以后，我把今天的事告诉了爸爸妈妈。", "Huí Jiā Yǐ Hòu, Wǒ Bǎ Jīn Tiān De Shì Gào Sù Le Bà Bà Mā Mā.", "Về đến nhà, tôi kể chuyện hôm nay cho bố mẹ nghe."], [296.896, 303.404, "爸爸笑着说：“你能跑完四百米，爸爸妈妈真为你高兴！”", "Bà Bà Xiào Zhe Shuō, Nǐ Néng Pǎo Wán Sì Bǎi Mǐ, Bà Bà Mā Mā Zhēn Wèi Nǐ Gāo Xìng!", "Bố cười nói: “Con chạy hết được bốn trăm mét, bố mẹ thật sự mừng cho con!”"], [303.404, 307.368, "妈妈把一张照片放在我的桌子上。", "Mā Mā Bǎ Yì Zhāng Zhào Piàn Fàng Zài Wǒ De Zhuō Zi Shàng.", "Mẹ đặt một tấm ảnh lên bàn của tôi."], [307.368, 310.52, "我把号码布夹在本子里。", "Wǒ Bǎ Hào Mǎ Bù Jiá Zài Běn Zi Lǐ.", "Tôi kẹp số áo vào vở."], [310.52, 314.869, "每次看见它，我就想起终点的那一下。", "Měi Cì Kàn Jiàn Tā, Wǒ Jiù Xiǎng Qǐ Zhōng Diǎn De Nà Yí Xià.", "Mỗi lần nhìn nó tôi nhớ khoảnh khắc ở đích."], [314.869, 318.232, "那一下比名次更让我高兴。", "Nà Yí Xià Bǐ Míng Cì Gèng Ràng Wǒ Gāo Xìng.", "Khoảnh khắc đó khiến tôi vui hơn thứ hạng."], [318.232, 324.309, "现在我不怕运动会了，我知道，慢慢练习，就能做好。", "Xiàn Zài Wǒ Bú Pà Yùn Dòng Huì Le, Wǒ Zhī Dào, Màn Màn Liàn Xí, Jiù Néng Zuò Hǎo.", "Bây giờ tôi không sợ hội thao nữa, tôi hiểu rằng cứ tập từ từ là sẽ làm được."], [324.309, 328.872, "明年十月，我还要再跑一次四百米。", "Míng Nián Shí Yuè, Wǒ Hái Yào Zài Pǎo Yí Cì Sì Bǎi Mǐ.", "Tháng Mười năm sau, tôi sẽ lại chạy bốn trăm mét một lần nữa."], [328.872, 337.92, "妈妈笑着说：“这张照片妈妈也要留着，看见它，妈妈就想起你跑到终点的那一天。”", "Mā Mā Xiào Zhe Shuō, Zhè Zhāng Zhào Piàn Mā Mā Yě Yào Liú Zhe, Kàn Jiàn Tā, Mā Mā Jiù Xiǎng Qǐ Nǐ Pǎo Dào Zhōng Diǎn De Nà Yì Tiān.", "Mẹ cười nói: “Tấm ảnh này mẹ cũng sẽ giữ, nhìn nó là mẹ lại nhớ đến ngày con chạy về đích.”"]]}, "hsk3-12": {"dur": 295.99, "cues": [[7.43, 12.474, "那天晚上，我的朋友给我看她的新衣服。", "Nà Tiān Wǎn Shàng, Wǒ De Péng Yǒu Gěi Wǒ Kàn Tā De Xīn Yī Fú.", "Tối hôm đó, bạn tôi cho tôi xem bộ quần áo mới của cô ấy."], [12.474, 21.094, "她笑着说：“这是在网上买的，不贵，也很好看，穿上很舒服，我很喜欢。”", "Tā Xiào Zhe Shuō, Zhè Shì Zài Wǎng Shàng Mǎi De, Bú Guì, Yě Hěn Hǎo Kàn, Chuān Shàng Hěn Shū Fú, Wǒ Hěn Xǐ Huān.", "Cô ấy cười nói: “Cái này mua trên mạng đấy, không đắt mà cũng đẹp, mặc lên rất thoải mái, tớ thích lắm.”"], [21.094, 25.346, "我问她：“在网上买东西，方便吗？”", "Wǒ Wèn Tā, Zài Wǎng Shàng Mǎi Dōng Xī, Fāng Biàn Ma?", "Tôi hỏi cô ấy: “Mua đồ trên mạng có tiện không?”"], [25.346, 33.437, "她笑着说：“很方便，在手机上看看，几天就寄到家了，你也试试吧！”", "Tā Xiào Zhe Shuō, Hěn Fāng Biàn, Zài Shǒu Jī Shàng Kàn Kàn, Jǐ Tiān Jiù Jì Dào Jiā Le, Nǐ Yě Shì Shì Ba!", "Cô ấy cười nói: “Tiện lắm, xem trên điện thoại, mấy ngày là gửi đến nhà rồi, cậu cũng thử đi!”"], [33.437, 36.618, "我听了，也想试一试。", "Wǒ Tīng Le, Yě Xiǎng Shì Yí Shì.", "Nghe xong, tôi cũng muốn thử một lần."], [36.618, 42.118, "我在网上看了很久，看见一件红色的衣服。", "Wǒ Zài Wǎng Shàng Kàn Le Hěn Jiǔ, Kàn Jiàn Yí Jiàn Hóng Sè De Yī Fú.", "Tôi xem trên mạng rất lâu và thấy một bộ quần áo màu đỏ."], [42.118, 47.138, "那件衣服很好看，也不贵，我很喜欢。", "Nà Jiàn Yī Fú Hěn Hǎo Kàn, Yě Bú Guì, Wǒ Hěn Xǐ Huān.", "Bộ quần áo đó rất đẹp, cũng không đắt, tôi rất thích."], [47.138, 50.736, "我只看了几分钟，就下单了。", "Wǒ Zhǐ Kàn Le Jǐ Fēn Zhōng, Jiù Xià Dān Le.", "Tôi mới xem vài phút đã đặt hàng ngay."], [50.736, 55.996, "我第一次在网上买衣服，没有看清楚尺寸。", "Wǒ Dì Yī Cì Zài Wǎng Shàng Mǎi Yī Fu, Méi Yǒu Kàn Qīng Chǔ Chǐ Cùn.", "Lần đầu tôi mua quần áo trên mạng và không xem kỹ kích cỡ."], [55.996, 62.508, "我没有问朋友，也没有再看第二遍，只想着快点儿穿上它。", "Wǒ Méi Yǒu Wèn Péng Yǒu, Yě Méi Yǒu Zài Kàn Dì Èr Biàn, Zhǐ Xiǎng Zhe Kuài Diǎn Ér Chuān Shàng Tā.", "Tôi không hỏi bạn, cũng không xem lại lần hai, chỉ nghĩ đến việc mặc nó thật nhanh."], [62.508, 66.256, "等了三天，衣服终于寄到了。", "Děng Le Sān Tiān, Yī Fú Zhōng Yú Jì Dào Le.", "Đợi ba ngày, quần áo cuối cùng cũng được gửi đến."], [66.256, 74.66, "我打开包，拿出衣服一看，衣服比我想的小很多，颜色也没有照片上好看。", "Wǒ Dǎ Kāi Bāo, Ná Chū Yī Fú Yí Kàn, Yī Fú Bǐ Wǒ Xiǎng De Xiǎo Hěn Duō, Yán Sè Yě Méi Yǒu Zhào Piàn Shàng Hǎo Kàn.", "Tôi mở túi, lấy quần áo ra xem, quần áo nhỏ hơn tôi tưởng rất nhiều, màu cũng không đẹp như trong ảnh."], [74.66, 78.672, "衣服寄到以后太小了，不能穿。", "Yī Fu Jì Dào Yǐ Hòu Tài Xiǎo Le, Bù Néng Chuān.", "Quần áo gửi đến thì quá nhỏ, không mặc được."], [78.672, 83.545, "我穿上试了试，坐下来都很不舒服。", "Wǒ Chuān Shàng Shì Le Shì, Zuò Xià Lái Dōu Hěn Bù Shū Fú.", "Tôi mặc thử, ngồi xuống cũng thấy rất khó chịu."], [83.545, 87.917, "我看着这件小衣服，不知道怎么办。", "Wǒ Kàn Zhe Zhè Jiàn Xiǎo Yī Fú, Bù Zhī Dào Zěn Me Bàn.", "Tôi nhìn bộ quần áo nhỏ, không biết phải làm sao."], [87.917, 91.649, "我给朋友打电话，问她怎么办。", "Wǒ Gěi Péng Yǒu Dǎ Diàn Huà, Wèn Tā Zěn Me Bàn.", "Tôi gọi điện cho bạn, hỏi cô ấy phải làm sao."], [91.649, 99.213, "她笑着说：“别担心，可以退货的，我帮你，你先看清楚说明。”", "Tā Xiào Zhe Shuō, Bié Dān Xīn, Kě Yǐ Tuì Huò De, Wǒ Bāng Nǐ, Nǐ Xiān Kàn Qīng Chǔ Shuō Míng.", "Cô ấy cười nói: “Đừng lo, trả hàng được mà, tớ giúp cậu, cậu xem kỹ hướng dẫn trước đi.”"], [99.213, 107.041, "她还笑着说：“别难过，我第一次买衣服的时候，也买错过，我们都一样。”", "Tā Hái Xiào Zhe Shuō, Bié Nán Guò, Wǒ Dì Yī Cì Mǎi Yī Fú De Shí Hòu, Yě Mǎi Cuò Guò, Wǒ Men Dōu Yí Yàng.", "Cô ấy còn cười nói: “Đừng buồn, lần đầu tớ mua quần áo cũng từng mua nhầm, ai cũng thế cả.”"], [107.041, 111.015, "我听了她的话，心里放心了一点儿。", "Wǒ Tīng Le Tā De Huà, Xīn Lǐ Fàng Xīn Le Yì Diǎn Ér.", "Nghe lời cô ấy, tôi yên tâm hơn một chút."], [111.015, 115.603, "我根据说明申请退货，店家同意了。", "Wǒ Gēn Jù Shuō Míng Shēn Qǐng Tuì Huò, Diàn Jiā Tóng Yì Le.", "Tôi làm theo hướng dẫn để trả hàng và cửa hàng đồng ý."], [115.603, 120.906, "我把衣服放回包里，第二天寄回了店里。", "Wǒ Bǎ Yī Fú Fàng Huí Bāo Lǐ, Dì Èr Tiān Jì Huí Le Diàn Lǐ.", "Tôi cho quần áo lại vào túi, hôm sau gửi trả về cho cửa hàng."], [120.906, 125.182, "店家收到以后，给我发了一条短信。", "Diàn Jiā Shōu Dào Yǐ Hòu, Gěi Wǒ Fā Le Yì Tiáo Duǎn Xìn.", "Cửa hàng nhận được hàng thì nhắn tin cho tôi."], [125.182, 130.562, "短信上说，钱要等几天才能回到卡里。", "Duǎn Xìn Shàng Shuō, Qián Yào Děng Jǐ Tiān Cái Néng Huí Dào Kǎ Lǐ.", "Tin nhắn nói tiền phải đợi mấy ngày mới về lại thẻ."], [130.562, 135.581, "我每天都看一看卡里的钱，有点儿担心。", "Wǒ Měi Tiān Dōu Kàn Yí Kàn Kǎ Lǐ De Qián, Yǒu Diǎn Ér Dān Xīn.", "Ngày nào tôi cũng kiểm tra tiền trong thẻ, hơi lo lắng."], [135.581, 140.721, "第一天没有，第二天也没有，我更担心了。", "Dì Yī Tiān Méi Yǒu, Dì Èr Tiān Yě Méi Yǒu, Wǒ Gèng Dān Xīn Le.", "Ngày đầu không có, ngày thứ hai cũng không, tôi càng lo hơn."], [140.721, 143.965, "我又给店家打了一个电话。", "Wǒ Yòu Gěi Diàn Jiā Dǎ Le Yí Gè Diàn Huà.", "Tôi lại gọi điện cho cửa hàng."], [143.965, 151.766, "店家笑着说：“对不起，请等一等，钱已经在路上了，一定会到的。”", "Diàn Jiā Xiào Zhe Shuō, Duì Bù Qǐ, Qǐng Děng Yì Děng, Qián Yǐ Jīng Zài Lù Shàng Le, Yí Dìng Huì Dào De.", "Chủ shop cười nói: “Xin lỗi bạn nhé, đợi một chút, tiền đang trên đường về rồi, nhất định sẽ tới.”"], [151.766, 155.898, "退货用了五天，钱才回到卡里。", "Tuì Huò Yòng Le Wǔ Tiān, Qián Cái Huí Dào Kǎ Lǐ.", "Trả hàng mất năm ngày tiền mới về thẻ."], [155.898, 164.676, "第五天早上，手机响了一下，我看见钱回来了，一下子高兴起来，笑了很久。", "Dì Wǔ Tiān Zǎo Shàng, Shǒu Jī Xiǎng Le Yí Xià, Wǒ Kàn Jiàn Qián Huí Lái Le, Yí Xià Zi Gāo Xìng Qǐ Lái, Xiào Le Hěn Jiǔ.", "Sáng ngày thứ năm, điện thoại reo một tiếng, tôi thấy tiền đã về, vui hẳn lên và cười rất lâu."], [164.676, 170.704, "这次我明白了，买东西以前要比较，也要看评价。", "Zhè Cì Wǒ Míng Bái Le, Mǎi Dōng Xī Yǐ Qián Yào Bǐ Jiào, Yě Yào Kàn Píng Jià.", "Lần này tôi hiểu trước khi mua phải so sánh và xem nhận xét."], [170.704, 174.986, "便宜不一定合适，合适才最重要。", "Pián Yi Bù Yí Dìng Hé Shì, Hé Shì Cái Zuì Zhòng Yào.", "Rẻ chưa chắc hợp, hợp mới là quan trọng nhất."], [174.986, 180.534, "从那天起，我买东西以前会先想三件事。", "Cóng Nà Tiān Qǐ, Wǒ Mǎi Dōng Xī Yǐ Qián Huì Xiān Xiǎng Sān Jiàn Shì.", "Từ hôm đó, trước khi mua đồ tôi đều nghĩ đến ba điều."], [180.534, 187.522, "我先想，尺寸对不对，评价好不好，我是不是真的需要它。", "Wǒ Xiān Xiǎng, Chǐ Cùn Duì Bu Duì, Píng Jià Hǎo Bu Hǎo, Wǒ Shì Bu Shì Zhēn De Xū Yào Tā.", "Tôi nghĩ trước: kích cỡ có đúng không, đánh giá có tốt không, mình có thật sự cần nó không."], [187.522, 192.614, "我把这些话写在本子上，放在电脑旁边。", "Wǒ Bǎ Zhè Xiē Huà Xiě Zài Běn Zi Shàng, Fàng Zài Diàn Nǎo Páng Biān.", "Tôi ghi những điều này vào sổ, để cạnh máy tính."], [192.614, 196.185, "我还把容易买错的东西写下来。", "Wǒ Hái Bǎ Róng Yì Mǎi Cuò De Dōng Xī Xiě Xià Lái.", "Tôi còn ghi những thứ dễ mua nhầm."], [196.185, 200.317, "后来我想买鞋，也先等了一天。", "Hòu Lái Wǒ Xiǎng Mǎi Xié, Yě Xiān Děng Le Yì Tiān.", "Sau này tôi muốn mua giày, cũng đợi trước một ngày."], [200.317, 204.209, "现在下单以前，我会等一天。", "Xiàn Zài Xià Dān Yǐ Qián, Wǒ Huì Děng Yì Tiān.", "Bây giờ trước khi đặt tôi đợi một ngày."], [204.209, 208.422, "很多东西等一天以后就不想买了。", "Hěn Duō Dōng Xī Děng Yì Tiān Yǐ Hòu Jiù Bù Xiǎng Mǎi Le.", "Nhiều thứ đợi một ngày là không muốn mua nữa."], [208.422, 215.338, "有一次，我看见一件很贵的衣服，等了一天，还是很想买。", "Yǒu Yí Cì, Wǒ Kàn Jiàn Yí Jiàn Hěn Guì De Yī Fú, Děng Le Yì Tiān, Hái Shì Hěn Xiǎng Mǎi.", "Có lần tôi thấy một bộ quần áo rất đắt, đợi một ngày rồi vẫn rất muốn mua."], [215.338, 220.838, "这次我先看清楚了尺寸，也看了很多评价。", "Zhè Cì Wǒ Xiān Kàn Qīng Chǔ Le Chǐ Cùn, Yě Kàn Le Hěn Duō Píng Jià.", "Lần này tôi xem kỹ kích cỡ trước, cũng đọc nhiều đánh giá."], [220.838, 228.666, "我给朋友看了这件衣服，她笑着说：“太好看了，你穿上一定很好看！”", "Wǒ Gěi Péng Yǒu Kàn Le Zhè Jiàn Yī Fú, Tā Xiào Zhe Shuō, Tài Hǎo Kàn Le, Nǐ Chuān Shàng Yí Dìng Hěn Hǎo Kàn!", "Tôi cho bạn xem bộ quần áo này, cô ấy cười nói: “Đẹp quá, cậu mặc lên nhất định sẽ rất đẹp!”"], [228.666, 231.921, "想清楚了，我才下单。", "Xiǎng Qīng Chǔ Le, Wǒ Cái Xià Dān.", "Nghĩ kỹ rồi tôi mới đặt hàng."], [231.921, 235.429, "三天以后，衣服寄到了。", "Sān Tiān Yǐ Hòu, Yī Fú Jì Dào Le.", "Ba ngày sau, quần áo được gửi đến."], [235.429, 239.441, "这次大小也对，穿上很舒服。", "Zhè Cì Dà Xiǎo Yě Duì, Chuān Shàng Hěn Shū Fú.", "Lần này kích cỡ vừa đúng, mặc lên rất thoải mái."], [239.441, 248.925, "我穿着新衣服去见朋友，她笑着说：“真好看！你穿着真合适，我真为你高兴！”", "Wǒ Chuān Zhe Xīn Yī Fú Qù Jiàn Péng Yǒu, Tā Xiào Zhe Shuō, Zhēn Hǎo Kàn! Nǐ Chuān Zhe Zhēn Hé Shì, Wǒ Zhēn Wèi Nǐ Gāo Xìng!", "Tôi mặc quần áo mới đi gặp bạn, cô ấy cười nói: “Đẹp thật! Cậu mặc vừa hợp lắm, tớ thật sự mừng cho cậu!”"], [248.925, 254.003, "我听了很高兴，心里想，这次买对了。", "Wǒ Tīng Le Hěn Gāo Xìng, Xīn Lǐ Xiǎng, Zhè Cì Mǎi Duì Le.", "Nghe vậy tôi rất vui, thầm nghĩ lần này mình mua đúng rồi."], [254.003, 259.143, "现在我网购少了一些，可是买得更放心。", "Xiàn Zài Wǒ Wǎng Gòu Shǎo Le Yì Xiē, Kě Shì Mǎi Dé Gèng Fàng Xīn.", "Bây giờ tôi mua online ít hơn, nhưng mua yên tâm hơn."], [259.143, 262.804, "这样既省钱，也不占地方。", "Zhè Yàng Jì Shěng Qián, Yě Bú Zhàn Dì Fāng.", "Vừa đỡ tốn tiền vừa không chiếm chỗ."], [262.804, 268.688, "现在朋友问我网购的事，我都会把我的办法告诉她。", "Xiàn Zài Péng Yǒu Wèn Wǒ Wǎng Gòu De Shì, Wǒ Dū Huì Bǎ Wǒ De Bàn Fǎ Gào Sù Tā.", "Bây giờ bạn hỏi tôi chuyện mua hàng online, tôi đều chia sẻ cách của mình cho cô ấy."], [268.688, 274.811, "我觉得，买东西慢一点儿，心里更安静，也更开心。", "Wǒ Jué De, Mǎi Dōng Xī Màn Yì Diǎn Ér, Xīn Lǐ Gèng Ān Jìng, Yě Gèng Kāi Xīn.", "Tôi thấy mua đồ chậm lại một chút thì trong lòng yên tĩnh hơn, cũng vui hơn."], [274.811, 280.239, "便宜的东西很多，可是合适的东西要慢慢找。", "Pián Yi De Dōng Xī Hěn Duō, Kě Shì Hé Shì De Dōng Xī Yào Màn Màn Zhǎo.", "Đồ rẻ thì nhiều, nhưng đồ hợp với mình thì phải tìm từ từ."], [280.239, 287.37, "朋友笑着说：“你的办法真好，以后我买东西，也先等一天！”", "Péng Yǒu Xiào Zhe Shuō, Nǐ De Bàn Fǎ Zhēn Hǎo, Yǐ Hòu Wǒ Mǎi Dōng Xī, Yě Xiān Děng Yì Tiān!", "Bạn tôi cười nói: “Cách của cậu hay thật, từ nay tớ mua đồ cũng sẽ đợi một ngày trước!”"]]}, "hsk3-13": {"dur": 292.04, "cues": [[7.941, 12.025, "那天是星期五，第二天我有考试。", "Nà Tiān Shì Xīng Qī Wǔ, Dì Èr Tiān Wǒ Yǒu Kǎo Shì.", "Hôm đó là thứ Sáu, hôm sau tôi có bài kiểm tra."], [12.025, 17.237, "下午的天气很好，我出门的时候没有带伞。", "Xià Wǔ De Tiān Qì Hěn Hǎo, Wǒ Chū Mén De Shí Hòu Méi Yǒu Dài Sǎn.", "Buổi chiều trời rất đẹp, lúc ra khỏi nhà tôi không mang ô."], [17.237, 22.059, "我想，晚上回家的时候，不会下雨吧。", "Wǒ Xiǎng, Wǎn Shàng Huí Jiā De Shí Hòu, Bú Huì Xià Yǔ Ba.", "Tôi nghĩ, tối về chắc sẽ không mưa đâu."], [22.059, 26.095, "我在图书馆看书，做了很多练习。", "Wǒ Zài Tú Shū Guǎn Kàn Shū, Zuò Le Hěn Duō Liàn Xí.", "Tôi đọc sách ở thư viện và làm rất nhiều bài tập."], [26.095, 31.739, "图书馆里很安静，人也不多，我学得很认真。", "Tú Shū Guǎn Lǐ Hěn Ān Jìng, Rén Yě Bù Duō, Wǒ Xué Dé Hěn Rèn Zhēn.", "Trong thư viện rất yên tĩnh, người cũng không đông, tôi học rất chăm."], [31.739, 35.031, "我一直看书，忘了时间。", "Wǒ Yì Zhí Kàn Shū, Wàng Le Shí Jiān.", "Tôi cứ đọc sách mãi, quên cả thời gian."], [35.031, 38.986, "那天晚上我在图书馆学到九点。", "Nà Tiān Wǎn Shàng Wǒ Zài Tú Shū Guǎn Xué Dào Jiǔ Diǎn.", "Tối hôm đó tôi học ở thư viện đến chín giờ."], [38.986, 44.294, "我走出图书馆，站在门口，看着门外的雨。", "Wǒ Zǒu Chū Tú Shū Guǎn, Zhàn Zài Mén Kǒu, Kàn Zhe Mén Wài De Yǔ.", "Tôi bước ra khỏi thư viện, đứng ở cửa, nhìn cơn mưa bên ngoài."], [44.294, 48.714, "一出门就下起了大雨，我没带伞。", "Yì Chū Mén Jiù Xià Qǐ Le Dà Yǔ, Wǒ Méi Dài Sǎn.", "Vừa ra cửa thì mưa to, tôi không mang ô."], [48.714, 54.869, "雨下得很大，打在伞上，也打在地上，路上都是水。", "Yǔ Xià Dé Hěn Dà, Dǎ Zài Sǎn Shàng, Yě Dǎ Zài Dì Shàng, Lù Shàng Dōu Shì Shuǐ.", "Mưa rất to, rơi trên ô, cũng rơi trên mặt đất, trên đường toàn là nước."], [54.869, 59.289, "我的书包里有书，我怕书也湿了。", "Wǒ De Shū Bāo Lǐ Yǒu Shū, Wǒ Pà Shū Yě Shī Le.", "Trong cặp tôi có sách, tôi sợ sách cũng bị ướt."], [59.289, 64.141, "我想等雨小一点儿再走，可是越等越大。", "Wǒ Xiǎng Děng Yǔ Xiǎo Yì Diǎn Ér Zài Zǒu, Kě Shì Yuè Děng Yuè Dà.", "Tôi định đợi mưa nhỏ rồi đi, nhưng càng đợi mưa càng lớn."], [64.141, 67.841, "我等了二十分钟，雨还是很大。", "Wǒ Děng Le Èr Shí Fēn Zhōng, Yǔ Hái Shì Hěn Dà.", "Tôi đợi hai mươi phút, mưa vẫn rất to."], [67.841, 72.678, "风也很大，我站在门口，有点儿冷。", "Fēng Yě Hěn Dà, Wǒ Zhàn Zài Mén Kǒu, Yǒu Diǎn Ér Lěng.", "Gió cũng rất lớn, tôi đứng ở cửa, hơi lạnh."], [72.678, 77.386, "路上的人很少，有伞的人都跑回家了。", "Lù Shàng De Rén Hěn Shǎo, Yǒu Sǎn De Rén Dōu Pǎo Huí Jiā Le.", "Trên đường ít người, ai có ô đều chạy về nhà cả rồi."], [77.386, 81.95, "我想走回家，可是我家离图书馆很远。", "Wǒ Xiǎng Zǒu Huí Jiā, Kě Shì Wǒ Jiā Lí Tú Shū Guǎn Hěn Yuǎn.", "Tôi muốn đi bộ về, nhưng nhà tôi cách thư viện rất xa."], [81.95, 87.666, "我也想坐公共汽车，可是车站离这儿还有一点儿远。", "Wǒ Yě Xiǎng Zuò Gōng Gòng Qì Chē, Kě Shì Chē Zhàn Lí Zhè Ér Hái Yǒu Yì Diǎn Ér Yuǎn.", "Tôi cũng muốn đi xe buýt, nhưng bến xe còn cách chỗ này một đoạn."], [87.666, 92.183, "我看了看路上，一辆出租车也没有。", "Wǒ Kàn Le Kàn Lù Shàng, Yí Liàng Chū Zū Chē Yě Méi Yǒu.", "Tôi nhìn ra đường, không có chiếc taxi nào cả."], [92.183, 97.299, "我心里很着急，因为爸爸妈妈还在家等我。", "Wǒ Xīn Lǐ Hěn Zháo Jí, Yīn Wèi Bà Bà Mā Mā Hái Zài Jiā Děng Wǒ.", "Tôi rất sốt ruột, vì bố mẹ vẫn đang đợi tôi ở nhà."], [97.299, 102.823, "又等了一会儿，我看见一辆出租车慢慢开过来。", "Yòu Děng Le Yí Huì Ér, Wǒ Kàn Jiàn Yí Liàng Chū Zū Chē Màn Màn Kāi Guò Lái.", "Đợi thêm một lúc, tôi thấy một chiếc taxi từ từ chạy đến."], [102.823, 105.883, "最后我打了一辆出租车。", "Zuì Hòu Wǒ Dǎ Le Yí Liàng Chū Zū Chē.", "Cuối cùng tôi gọi một chiếc taxi."], [105.883, 109.679, "我上了车，告诉司机我住在哪儿。", "Wǒ Shàng Le Chē, Gào Sù Sī Jī Wǒ Zhù Zài Nǎ Ér.", "Tôi lên xe và nói cho tài xế biết tôi ở đâu."], [109.679, 114.103, "车里不冷，我坐下来，心里放心了。", "Chē Lǐ Bù Lěng, Wǒ Zuò Xià Lái, Xīn Lǐ Fàng Xīn Le.", "Trong xe không lạnh, tôi ngồi xuống, trong lòng yên tâm hẳn."], [114.103, 119.603, "司机看我全身都湿了，把一块干毛巾递给我。", "Sī Jī Kàn Wǒ Quán Shēn Dōu Shī Le, Bǎ Yí Kuài Gān Máo Jīn Dì Gěi Wǒ.", "Tài xế thấy tôi ướt hết người liền đưa một chiếc khăn khô."], [119.603, 128.031, "司机笑着说：“先坐好，别着急，下雨天，我们慢慢开，一定送你到家。”", "Sī Jī Xiào Zhe Shuō, Xiān Zuò Hǎo, Bié Zháo Jí, Xià Yǔ Tiān, Wǒ Men Màn Màn Kāi, Yí Dìng Sòng Nǐ Dào Jiā.", "Tài xế cười nói: “Ngồi cho vững trước đã, đừng sốt ruột, ngày mưa chúng ta đi từ từ thôi, nhất định sẽ đưa cháu về đến nhà.”"], [128.031, 134.971, "我拿着毛巾说：“谢谢您，毛巾很干，我心里一下子就不冷了。”", "Wǒ Ná Zhe Máo Jīn Shuō, Xiè Xiè Nín, Máo Jīn Hěn Gān, Wǒ Xīn Lǐ Yí Xià Zi Jiù Bù Lěng Le.", "Tôi cầm chiếc khăn nói: “Cảm ơn bác, khăn khô lắm, trong lòng cháu bỗng thấy không còn lạnh nữa.”"], [134.971, 142.478, "司机笑着说：“没事，没事，下雨天，大家都这样，能帮就帮。”", "Sī Jī Xiào Zhe Shuō, Méi Shì, Méi Shì, Xià Yǔ Tiān, Dà Jiā Dōu Zhè Yàng, Néng Bāng Jiù Bāng.", "Tài xế cười nói: “Không sao, không sao, ngày mưa ai cũng thế cả, giúp được thì giúp thôi.”"], [142.478, 148.074, "虽然只是一件小事，我到现在还记得他的好意。", "Suī Rán Zhǐ Shì Yí Jiàn Xiǎo Shì, Wǒ Dào Xiàn Zài Hái Jì De Tā De Hǎo Yì.", "Chỉ là chuyện nhỏ, nhưng đến giờ tôi vẫn nhớ lòng tốt của ông."], [148.074, 154.273, "路上，司机开得很慢，因为雨大得看不清前面的路。", "Lù Shàng, Sī Jī Kāi Dé Hěn Màn, Yīn Wèi Yǔ Dà Dé Kàn Bù Qīng Qián Miàn De Lù.", "Trên đường, tài xế lái rất chậm, vì mưa to đến mức không nhìn rõ đường phía trước."], [154.273, 157.829, "到了我家门口，雨小了一点儿。", "Dào Le Wǒ Jiā Mén Kǒu, Yǔ Xiǎo Le Yì Diǎn Ér.", "Đến cửa nhà tôi, mưa đã nhỏ hơn một chút."], [157.829, 161.673, "我给了司机钱，又说了一次谢谢。", "Wǒ Gěi Le Sī Jī Qián, Yòu Shuō Le Yí Cì Xiè Xiè.", "Tôi trả tiền cho tài xế và nói cảm ơn một lần nữa."], [161.673, 170.179, "司机笑着说：“快回家吧，爸爸妈妈等你很久了，换件干衣服，喝点儿热水。”", "Sī Jī Xiào Zhe Shuō, Kuài Huí Jiā Ba, Bà Bà Mā Mā Děng Nǐ Hěn Jiǔ Le, Huàn Jiàn Gān Yī Fú, Hē Diǎn Ér Rè Shuǐ.", "Tài xế cười nói: “Về nhà nhanh đi, bố mẹ đợi cháu lâu rồi, thay bộ quần áo khô, uống chút nước nóng nhé.”"], [170.179, 174.839, "我跑回家，爸爸妈妈都在门口等我。", "Wǒ Pǎo Huí Jiā, Bà Bà Mā Mā Dōu Zài Mén Kǒu Děng Wǒ.", "Tôi chạy về nhà, bố mẹ đều đang đợi tôi ở cửa."], [174.839, 181.162, "妈妈拉着我的手说：“你回来了！看见你，妈妈就放心了。”", "Mā Mā Lā Zhe Wǒ De Shǒu Shuō, Nǐ Huí Lái Le! Kàn Jiàn Nǐ, Mā Mā Jiù Fàng Xīn Le.", "Mẹ nắm tay tôi nói: “Con về rồi! Nhìn thấy con là mẹ yên tâm rồi.”"], [181.162, 185.246, "回到家，我给司机发了一条短信。", "Huí Dào Jiā, Wǒ Gěi Sī Jī Fā Le Yì Tiáo Duǎn Xìn.", "Về nhà tôi nhắn tin cho tài xế."], [185.246, 188.034, "我说谢谢他的毛巾。", "Wǒ Shuō Xiè Xiè Tā De Máo Jīn.", "Tôi nói cảm ơn chiếc khăn của ông."], [188.034, 192.19, "他回我说，下雨天大家都不容易。", "Tā Huí Wǒ Shuō, Xià Yǔ Tiān Dà Jiā Dōu Bù Róng Yì.", "Ông trả lời ngày mưa ai cũng vất vả."], [192.19, 194.932, "这句话我记到现在。", "Zhè Jù Huà Wǒ Jì Dào Xiàn Zài.", "Câu đó tôi nhớ đến giờ."], [194.932, 199.015, "妈妈让我先去洗澡，换上干衣服。", "Mā Mā Ràng Wǒ Xiān Qù Xǐ Zǎo, Huàn Shàng Gān Yī Fú.", "Mẹ bảo tôi đi tắm trước, thay bộ quần áo khô."], [199.015, 207.707, "我洗完澡，喝了妈妈给我的热水，身上不冷了，听着外面的雨声，心里也很舒服。", "Wǒ Xǐ Wán Zǎo, Hē Le Mā Mā Gěi Wǒ De Rè Shuǐ, Shēn Shàng Bù Lěng Le, Tīng Zhe Wài Miàn De Yǔ Shēng, Xīn Lǐ Yě Hěn Shū Fú.", "Tắm xong, tôi uống nước nóng mẹ đưa, người không còn lạnh, nghe tiếng mưa bên ngoài, trong lòng cũng rất dễ chịu."], [207.707, 211.023, "那天晚上，我睡得很好。", "Nà Tiān Wǎn Shàng, Wǒ Shuì Dé Hěn Hǎo.", "Tối hôm đó tôi ngủ rất ngon."], [211.023, 215.131, "可是司机的那句话，我一直没有忘。", "Kě Shì Sī Jī De Nà Jù Huà, Wǒ Yì Zhí Méi Yǒu Wàng.", "Nhưng câu nói của bác tài xế, tôi mãi không quên."], [215.131, 219.767, "第二天早上，太阳出来了，天气很好。", "Dì Èr Tiān Zǎo Shàng, Tài Yáng Chū Lái Le, Tiān Qì Hěn Hǎo.", "Sáng hôm sau, mặt trời lên, thời tiết rất đẹp."], [219.767, 224.595, "我走在路上，看见路上的水还没有干。", "Wǒ Zǒu Zài Lù Shàng, Kàn Jiàn Lù Shàng De Shuǐ Hái Méi Yǒu Gān.", "Tôi đi trên đường, thấy nước trên đường vẫn chưa khô."], [224.595, 227.863, "我心里又想起了那位司机。", "Wǒ Xīn Lǐ Yòu Xiǎng Qǐ Le Nà Wèi Sī Jī.", "Trong lòng tôi lại nhớ đến bác tài xế ấy."], [227.863, 233.755, "我想，每个人都像他一样，这个城市就更温暖了。", "Wǒ Xiǎng, Měi Gè Rén Dōu Xiàng Tā Yí Yàng, Zhè Gè Chéng Shì Jiù Gèng Wēn Nuǎn Le.", "Tôi nghĩ, nếu ai cũng như bác ấy, thành phố này sẽ ấm áp hơn nhiều."], [233.755, 239.015, "后来我自己也在车上帮助过一个没带伞的人。", "Hòu Lái Wǒ Zì Jǐ Yě Zài Chē Shàng Bāng Zhù Guò Yí Gè Méi Dài Sǎn De Rén.", "Sau này trên xe tôi cũng giúp một người không mang ô."], [239.015, 243.972, "那是一个下雨的晚上，我在公共汽车上。", "Nà Shì Yí Gè Xià Yǔ De Wǎn Shàng, Wǒ Zài Gōng Gòng Qì Chē Shàng.", "Đó là một buổi tối mưa, tôi đang ở trên xe buýt."], [243.972, 249.568, "一个学生没有带伞，站在车门口，不知道怎么办。", "Yí Gè Xué Shēng Méi Yǒu Dài Sǎn, Zhàn Zài Chē Mén Kǒu, Bù Zhī Dào Zěn Me Bàn.", "Một bạn học sinh không mang ô, đứng ở cửa xe, không biết phải làm sao."], [249.568, 254.108, "我把我的伞借给他，他笑着说谢谢。", "Wǒ Bǎ Wǒ De Sǎn Jiè Gěi Tā, Tā Xiào Zhe Shuō Xiè Xiè.", "Tôi cho bạn ấy mượn ô của mình, bạn ấy cười và nói cảm ơn."], [254.108, 260.969, "他笑着说：“太好了！下次我也帮助别人，也把好意传下去。”", "Tā Xiào Zhe Shuō, Tài Hǎo Le! Xià Cì Wǒ Yě Bāng Zhù Bié Rén, Yě Bǎ Hǎo Yì Chuán Xià Qù.", "Bạn ấy cười nói: “Hay quá! Lần sau tớ cũng sẽ giúp người khác, cũng truyền lòng tốt này đi tiếp.”"], [260.969, 263.901, "好意是可以传下去的。", "Hǎo Yì Shì Kě Yǐ Chuán Xià Qù De.", "Lòng tốt có thể được truyền tiếp."], [263.901, 270.865, "从那天起，下雨天我出门都会带伞，包里还放一条干毛巾。", "Cóng Nà Tiān Qǐ, Xià Yǔ Tiān Wǒ Chū Mén Dū Huì Dài Sǎn, Bāo Lǐ Hái Fàng Yì Tiáo Gān Máo Jīn.", "Từ hôm đó, ngày mưa ra ngoài tôi đều mang ô, trong cặp còn để sẵn một chiếc khăn khô."], [270.865, 275.453, "如果有人需要，我也可以把毛巾给他。", "Rú Guǒ Yǒu Rén Xū Yào, Wǒ Yě Kě Yǐ Bǎ Máo Jīn Gěi Tā.", "Nếu có ai cần, tôi cũng có thể đưa khăn cho người đó."], [275.453, 282.702, "每次下雨，看见包里的毛巾，我就想起那个晚上，心里很温暖。", "Měi Cì Xià Yǔ, Kàn Jiàn Bāo Lǐ De Máo Jīn, Wǒ Jiù Xiǎng Qǐ Nà Gè Wǎn Shàng, Xīn Lǐ Hěn Wēn Nuǎn.", "Mỗi lần trời mưa, nhìn chiếc khăn trong cặp, tôi lại nhớ đến buổi tối hôm đó, trong lòng thấy rất ấm áp."]]}, "hsk3-14": {"dur": 352.65, "cues": [[7.384, 12.5, "我上高中的时候，学习很忙，作业很多。", "Wǒ Shàng Gāo Zhōng De Shí Hòu, Xué Xí Hěn Máng, Zuò Yè Hěn Duō.", "Hồi tôi học cấp ba, việc học rất bận, bài tập rất nhiều."], [12.5, 17.592, "我早上很早去学校，晚上很晚才回家。", "Wǒ Zǎo Shàng Hěn Zǎo Qù Xué Xiào, Wǎn Shàng Hěn Wǎn Cái Huí Jiā.", "Sáng tôi đi học rất sớm, tối rất muộn mới về nhà."], [17.592, 22.825, "在家里，我吃完饭就回自己的房间看书。", "Zài Jiā Lǐ, Wǒ Chī Wán Fàn Jiù Huí Zì Jǐ De Fáng Jiān Kàn Shū.", "Ở nhà, ăn cơm xong là tôi về phòng mình đọc sách."], [22.825, 28.493, "妈妈有时候来问我学校的事，我只说一两句话。", "Mā Mā Yǒu Shí Hòu Lái Wèn Wǒ Xué Xiào De Shì, Wǒ Zhǐ Shuō Yì Liǎng Jù Huà.", "Mẹ thỉnh thoảng đến hỏi chuyện trường lớp, tôi chỉ nói một hai câu."], [28.493, 31.425, "妈妈问：“今天累吗？”", "Mā Mā Wèn, Jīn Tiān Lèi Ma?", "Mẹ hỏi: “Hôm nay có mệt không?”"], [31.425, 40.101, "我说：“不累，妈妈别担心。”说完，我就回了房间，心里其实有点儿难过。", "Wǒ Shuō, Bú Lèi, Mā Mā Bié Dān Xīn. Shuō Wán, Wǒ Jiù Huí Le Fáng Jiān, Xīn Lǐ Qí Shí Yǒu Diǎn Ér Nán Guò.", "Tôi nói: “Không mệt ạ, mẹ đừng lo.” Nói xong, tôi lại về phòng, trong lòng thật ra hơi buồn."], [40.101, 45.025, "爸爸想跟我聊天，我常常说没有时间。", "Bà Bà Xiǎng Gēn Wǒ Liáo Tiān, Wǒ Cháng Cháng Shuō Méi Yǒu Shí Jiān.", "Bố muốn trò chuyện với tôi, tôi thường nói không có thời gian."], [45.025, 49.685, "上高中的时候，我不太愿意跟父母说话。", "Shàng Gāo Zhōng De Shí Hòu, Wǒ Bú Tài Yuàn Yì Gēn Fù Mǔ Shuō Huà.", "Hồi cấp ba tôi không muốn nói chuyện với bố mẹ."], [49.685, 54.657, "我觉得他们不理解我，他们觉得我不听话。", "Wǒ Jué De Tā Men Bù Lǐ Jiě Wǒ, Tā Men Jué De Wǒ Bù Tīng Huà.", "Tôi thấy họ không hiểu tôi, họ thấy tôi không nghe lời."], [54.657, 57.973, "他们越问，我越不想说。", "Tā Men Yuè Wèn, Wǒ Yuè Bù Xiǎng Shuō.", "Họ càng hỏi, tôi càng không muốn nói."], [57.973, 63.344, "我觉得，我的事我自己知道，不用告诉他们。", "Wǒ Jué De, Wǒ De Shì Wǒ Zì Jǐ Zhī Dào, Bú Yòng Gào Sù Tā Men.", "Tôi nghĩ chuyện của mình thì mình tự biết, không cần nói với họ."], [63.344, 67.308, "有一天考试，我的成绩不太好。", "Yǒu Yì Tiān Kǎo Shì, Wǒ De Chéng Jì Bú Tài Hǎo.", "Có một hôm thi, điểm của tôi không tốt lắm."], [67.308, 72.664, "我心里很难过，回家以后更不想说话了。", "Wǒ Xīn Lǐ Hěn Nán Guò, Huí Jiā Yǐ Hòu Gèng Bù Xiǎng Shuō Huà Le.", "Tôi rất buồn, về nhà lại càng không muốn nói chuyện."], [72.664, 76.858, "妈妈看出来了，可是她没有多问我。", "Mā Mā Kàn Chū Lái Le, Kě Shì Tā Méi Yǒu Duō Wèn Wǒ.", "Mẹ nhận ra, nhưng bà không hỏi tôi nhiều."], [76.858, 82.31, "那天晚上，我在同学家做作业，忘了时间。", "Nà Tiān Wǎn Shàng, Wǒ Zài Tóng Xué Jiā Zuò Zuò Yè, Wàng Le Shí Jiān.", "Tối hôm đó, tôi làm bài tập ở nhà bạn và quên mất thời gian."], [82.31, 88.674, "同学的妈妈做了好吃的菜，我们吃完饭，又说了一会儿话。", "Tóng Xué De Mā Mā Zuò Le Hǎo Chī De Cài, Wǒ Men Chī Wán Fàn, Yòu Shuō Le Yí Huì Ér Huà.", "Mẹ của bạn nấu món ngon, chúng tôi ăn xong lại nói chuyện một lúc."], [88.674, 92.16, "我一看时间，已经十点了。", "Wǒ Yí Kàn Shí Jiān, Yǐ Jīng Shí Diǎn Le.", "Tôi nhìn đồng hồ, đã mười giờ rồi."], [92.16, 95.956, "我马上跑回家，心里很着急。", "Wǒ Mǎ Shàng Pǎo Huí Jiā, Xīn Lǐ Hěn Zháo Jí.", "Tôi lập tức chạy về nhà, trong lòng rất sốt ruột."], [95.956, 100.52, "到家的时候，爸爸妈妈都在门口等我。", "Dào Jiā De Shí Hòu, Bà Bà Mā Mā Dōu Zài Mén Kǒu Děng Wǒ.", "Khi tôi về đến nhà, bố mẹ đều đang đợi ở cửa."], [100.52, 108.669, "妈妈的眼睛红了，一直看着门口，爸爸的脸色也不太好，手里拿着手机。", "Mā Mā De Yǎn Jīng Hóng Le, Yì Zhí Kàn Zhe Mén Kǒu, Bà Bà De Liǎn Sè Yě Bú Tài Hǎo, Shǒu Lǐ Ná Zhe Shǒu Jī.", "Mắt mẹ đỏ hoe, cứ nhìn ra cửa mãi, sắc mặt bố cũng không tốt, tay cầm điện thoại."], [108.669, 112.657, "他们问我去哪儿了，为什么不打电话。", "Tā Men Wèn Wǒ Qù Nǎ Ér Le, Wèi Shén Me Bù Dǎ Diàn Huà.", "Họ hỏi tôi đã đi đâu, sao không gọi điện."], [112.657, 117.077, "我觉得他们问得太多，心里很不舒服。", "Wǒ Jué De Tā Men Wèn Dé Tài Duō, Xīn Lǐ Hěn Bù Shū Fú.", "Tôi thấy họ hỏi quá nhiều, trong lòng rất khó chịu."], [117.077, 121.835, "有一次因为回家太晚，我们吵了起来。", "Yǒu Yí Cì Yīn Wèi Huí Jiā Tài Wǎn, Wǒ Men Chǎo Le Qǐ Lái.", "Một lần vì về nhà quá muộn, chúng tôi cãi nhau."], [121.835, 129.951, "我大声说：“我已经长大了，你们不要管我！我心里很难过，你们知道吗？”", "Wǒ Dà Shēng Shuō, Wǒ Yǐ Jīng Zhǎng Dà Le, Nǐ Men Bú Yào Guǎn Wǒ! Wǒ Xīn Lǐ Hěn Nán Guò, Nǐ Men Zhī Dào Ma?", "Tôi nói to: “Con lớn rồi, bố mẹ đừng quản con nữa! Con buồn lắm, bố mẹ có biết không?”"], [129.951, 133.507, "说完，我跑回自己的房间。", "Shuō Wán, Wǒ Pǎo Huí Zì Jǐ De Fáng Jiān.", "Nói xong, tôi chạy về phòng mình."], [133.507, 139.32, "妈妈在门外说了一句话，我没有听，也没有说话。", "Mā Mā Zài Mén Wài Shuō Le Yí Jù Huà, Wǒ Méi Yǒu Tīng, Yě Méi Yǒu Shuō Huà.", "Mẹ nói một câu ngoài cửa, tôi không nghe, cũng không nói gì."], [139.32, 143.74, "那天晚上，我在床上，一直睡不着。", "Nà Tiān Wǎn Shàng, Wǒ Zài Chuáng Shàng, Yì Zhí Shuì Bù Zhe.", "Tối hôm đó, tôi ở trên giường, mãi không ngủ được."], [143.74, 150.535, "我想了很久，想着妈妈红红的眼睛，心里慢慢安静下来了。", "Wǒ Xiǎng Le Hěn Jiǔ, Xiǎng Zhe Mā Mā Hóng Hóng De Yǎn Jīng, Xīn Lǐ Màn Màn Ān Jìng Xià Lái Le.", "Tôi nghĩ rất lâu, nghĩ đến đôi mắt đỏ hoe của mẹ, trong lòng dần yên tĩnh lại."], [150.535, 156.947, "冷静以后，爸爸先跟我道歉，也让我说说自己的想法。", "Lěng Jìng Yǐ Hòu, Bà Ba Xiān Gēn Wǒ Dào Qiàn, Yě Ràng Wǒ Shuō Shuō Zì Jǐ De Xiǎng Fǎ.", "Sau khi bình tĩnh, bố xin lỗi trước và bảo tôi nói ý của mình."], [156.947, 164.679, "爸爸小声说：“对不起，是爸爸不好，我们刚才太着急了，你别难过。”", "Bà Bà Xiǎo Shēng Shuō, Duì Bù Qǐ, Shì Bà Bà Bù Hǎo, Wǒ Men Gāng Cái Tài Zháo Jí Le, Nǐ Bié Nán Guò.", "Bố nói khẽ: “Xin lỗi con, là bố không tốt, lúc nãy bố mẹ sốt ruột quá, con đừng buồn.”"], [164.679, 173.5, "他拉着我的手说：“你不回家，我们不知道你在哪儿，妈妈哭了，我们真的很担心你。”", "Tā Lā Zhe Wǒ De Shǒu Shuō, Nǐ Bù Huí Jiā, Wǒ Men Bù Zhī Dào Nǐ Zài Nǎ Ér, Mā Mā Kū Le, Wǒ Men Zhēn De Hěn Dān Xīn Nǐ.", "Bố nắm tay tôi nói: “Con không về, bố mẹ không biết con ở đâu, mẹ đã khóc, bố mẹ thật sự lo cho con lắm.”"], [173.5, 177.632, "我听了爸爸的话，心里有点儿难过。", "Wǒ Tīng Le Bà Bà De Huà, Xīn Lǐ Yǒu Diǎn Ér Nán Guò.", "Nghe lời bố, tôi hơi buồn."], [177.632, 186.876, "我也哭了，说：“对不起，爸爸妈妈，我在同学家做作业，忘了时间，让你们担心了。”", "Wǒ Yě Kū Le, Shuō, Duì Bù Qǐ, Bà Bà Mā Mā, Wǒ Zài Tóng Xué Jiā Zuò Zuò Yè, Wàng Le Shí Jiān, Ràng Nǐ Men Dān Xīn Le.", "Tôi cũng khóc và nói: “Con xin lỗi bố mẹ, con làm bài tập ở nhà bạn nên quên mất thời gian, làm bố mẹ lo rồi.”"], [186.876, 196.216, "我还小声说：“你们问得太多的时候，我心里害怕，就不想说话了，请你们慢慢问，好吗？”", "Wǒ Hái Xiǎo Shēng Shuō, Nǐ Men Wèn Dé Tài Duō De Shí Hòu, Wǒ Xīn Lǐ Hài Pà, Jiù Bù Xiǎng Shuō Huà Le, Qǐng Nǐ Men Màn Màn Wèn, Hǎo Ma?", "Tôi còn nói khẽ: “Lúc bố mẹ hỏi nhiều quá, trong lòng con sợ nên lại không muốn nói nữa, bố mẹ hỏi từ từ thôi, được không ạ?”"], [196.216, 205.961, "爸爸听完，想了想，笑着说：“好，爸爸记住了，以后我们先听你说完，你慢慢说。”", "Bà Bà Tīng Wán, Xiǎng Le Xiǎng, Xiào Zhe Shuō, Hǎo, Bà Bà Jì Zhù Le, Yǐ Hòu Wǒ Men Xiān Tīng Nǐ Shuō Wán, Nǐ Màn Màn Shuō.", "Bố nghe xong, nghĩ một lúc rồi cười nói: “Được, bố nhớ rồi, từ nay bố mẹ sẽ nghe con nói hết trước, con cứ nói từ từ.”"], [205.961, 210.597, "妈妈也坐下来，给我们每人一杯热水。", "Mā Mā Yě Zuò Xià Lái, Gěi Wǒ Men Měi Rén Yì Bēi Rè Shuǐ.", "Mẹ cũng ngồi xuống, đưa cho mỗi người một cốc nước nóng."], [210.597, 214.417, "那天晚上，我们说了很久的话。", "Nà Tiān Wǎn Shàng, Wǒ Men Shuō Le Hěn Jiǔ De Huà.", "Tối hôm đó, chúng tôi nói chuyện rất lâu."], [214.417, 220.404, "我告诉他们，这次考试我没考好，心里很难过。", "Wǒ Gào Sù Tā Men, Zhè Cì Kǎo Shì Wǒ Méi Kǎo Hǎo, Xīn Lǐ Hěn Nán Guò.", "Tôi kể với họ rằng lần thi này tôi làm không tốt, trong lòng rất buồn."], [220.404, 229.528, "妈妈拉着我的手说：“一次没考好没关系，妈妈不生气，你要多休息，身体最重要。”", "Mā Mā Lā Zhe Wǒ De Shǒu Shuō, Yí Cì Méi Kǎo Hǎo Méi Guān Xì, Mā Mā Bù Shēng Qì, Nǐ Yào Duō Xiū Xī, Shēn Tǐ Zuì Zhòng Yào.", "Mẹ nắm tay tôi nói: “Một lần thi không tốt không sao, mẹ không giận đâu, con phải nghỉ ngơi nhiều vào, sức khỏe là quan trọng nhất.”"], [229.528, 234.8, "我才发现，他们不是想管我，而是担心我。", "Wǒ Cái Fā Xiàn, Tā Men Bú Shì Xiǎng Guǎn Wǒ, Ér Shì Dān Xīn Wǒ.", "Tôi mới nhận ra họ không phải muốn kiểm soát tôi, mà là lo cho tôi."], [234.8, 240.972, "从那天起，我们说好，每个星期天晚上一起说话。", "Cóng Nà Tiān Qǐ, Wǒ Men Shuō Hǎo, Měi Gè Xīng Qī Tiān Wǎn Shàng Yì Qǐ Shuō Huà.", "Từ hôm đó, chúng tôi hẹn với nhau, tối Chủ nhật nào cũng cùng nói chuyện."], [240.972, 246.112, "现在每个星期天晚上，我们都会坐下来说话。", "Xiàn Zài Měi Gè Xīng Qī Tiān Wǎn Shàng, Wǒ Men Dōu Huì Zuò Xià Lái Shuō Huà.", "Bây giờ mỗi tối chủ nhật chúng tôi ngồi nói chuyện."], [246.112, 252.548, "星期天晚上，我们吃完晚饭，不看电视，也不玩手机。", "Xīng Qī Tiān Wǎn Shàng, Wǒ Men Chī Wán Wǎn Fàn, Bú Kàn Diàn Shì, Yě Bù Wán Shǒu Jī.", "Tối Chủ nhật, ăn tối xong, chúng tôi không xem TV, cũng không chơi điện thoại."], [252.548, 256.44, "我们坐在桌子旁边，慢慢说话。", "Wǒ Men Zuò Zài Zhuō Zi Páng Biān, Màn Màn Shuō Huà.", "Chúng tôi ngồi bên bàn, từ từ nói chuyện."], [256.44, 260.435, "我说学校的事，他们说工作的事。", "Wǒ Shuō Xué Xiào De Shì, Tā Men Shuō Gōng Zuò De Shì.", "Tôi kể chuyện trường, họ kể chuyện công việc."], [260.435, 266.391, "有时候我说的话他们不同意，他们会先听我说完。", "Yǒu Shí Hòu Wǒ Shuō De Huà Tā Men Bù Tóng Yì, Tā Men Huì Xiān Tīng Wǒ Shuō Wán.", "Đôi khi điều tôi nói họ không đồng ý, nhưng họ sẽ nghe tôi nói hết trước."], [266.391, 270.859, "有不同意见的时候，我们约好先听完。", "Yǒu Bù Tóng Yì Jiàn De Shí Hòu, Wǒ Men Yuē Hǎo Xiān Tīng Wán.", "Khi khác ý, chúng tôi hẹn nghe hết đã."], [270.859, 277.607, "有一次，我想周末去朋友家住一个晚上，妈妈一开始不同意。", "Yǒu Yí Cì, Wǒ Xiǎng Zhōu Mò Qù Péng Yǒu Jiā Zhù Yí Gè Wǎn Shàng, Mā Mā Yì Kāi Shǐ Bù Tóng Yì.", "Có lần tôi muốn cuối tuần sang nhà bạn ở một đêm, lúc đầu mẹ không đồng ý."], [277.607, 288.206, "她听完我的话，想了想，笑着说：“好，妈妈相信你，你去吧，可是要早点儿回来，妈妈等你。”", "Tā Tīng Wán Wǒ De Huà, Xiǎng Le Xiǎng, Xiào Zhe Shuō, Hǎo, Mā Mā Xiāng Xìn Nǐ, Nǐ Qù Ba, Kě Shì Yào Zǎo Diǎn Ér Huí Lái, Mā Mā Děng Nǐ.", "Bà nghe tôi nói hết, nghĩ một lúc rồi cười nói: “Được, mẹ tin con, con đi đi, nhưng phải về sớm đấy, mẹ đợi con.”"], [288.206, 293.058, "我很高兴，因为妈妈真的听了我的想法。", "Wǒ Hěn Gāo Xìng, Yīn Wèi Mā Mā Zhēn De Tīng Le Wǒ De Xiǎng Fǎ.", "Tôi rất vui, vì mẹ thật sự đã lắng nghe suy nghĩ của tôi."], [293.058, 295.942, "这样吵架少了很多。", "Zhè Yàng Chǎo Jià Shǎo Le Hěn Duō.", "Như vậy cãi nhau ít hơn nhiều."], [295.942, 301.754, "现在我在学校有事，回家会先告诉爸爸妈妈。", "Xiàn Zài Wǒ Zài Xué Xiào Yǒu Shì, Huí Jiā Huì Xiān Gào Sù Bà Bà Mā Mā.", "Bây giờ ở trường có chuyện gì, về nhà tôi đều nói với bố mẹ trước."], [301.754, 305.969, "他们工作很累的时候，也会告诉我。", "Tā Men Gōng Zuò Hěn Lèi De Shí Hòu, Yě Huì Gào Sù Wǒ.", "Khi công việc của họ mệt, họ cũng kể với tôi."], [305.969, 311.325, "妈妈累了，我会给她一杯水，让她休息一会儿。", "Mā Mā Lèi Le, Wǒ Huì Gěi Tā Yì Bēi Shuǐ, Ràng Tā Xiū Xī Yí Huì Ér.", "Khi mẹ mệt, tôi đưa cho mẹ một cốc nước và bảo mẹ nghỉ một lúc."], [311.325, 316.418, "爸爸下班晚了，我会等他回来一起吃饭。", "Bà Bà Xià Bān Wǎn Le, Wǒ Huì Děng Tā Huí Lái Yì Qǐ Chī Fàn.", "Khi bố tan làm muộn, tôi đợi bố về ăn cơm cùng."], [316.418, 320.166, "我发现父母其实愿意理解我。", "Wǒ Fā Xiàn Fù Mǔ Qí Shí Yuàn Yì Lǐ Jiě Wǒ.", "Tôi thấy bố mẹ thật sự muốn hiểu tôi."], [320.166, 323.506, "我也开始理解他们的担心。", "Wǒ Yě Kāi Shǐ Lǐ Jiě Tā Men De Dān Xīn.", "Tôi cũng bắt đầu hiểu nỗi lo của họ."], [323.506, 328.742, "我觉得，一家人多说话，心里就更近了。", "Wǒ Jué De, Yì Jiā Rén Duō Shuō Huà, Xīn Lǐ Jiù Gèng Jìn Le.", "Tôi thấy, cả nhà nói chuyện với nhau nhiều thì trong lòng sẽ gần nhau hơn."], [328.742, 335.73, "现在我最喜欢星期天晚上，因为那是我们一家人说话的时间。", "Xiàn Zài Wǒ Zuì Xǐ Huān Xīng Qī Tiān Wǎn Shàng, Yīn Wèi Nà Shì Wǒ Men Yì Jiā Rén Shuō Huà De Shí Jiān.", "Bây giờ tôi thích nhất tối Chủ nhật, vì đó là thời gian cả nhà tôi nói chuyện với nhau."], [335.73, 344.038, "爸爸笑着说：“这个星期天，我们多说一会儿，爸爸想听你多说说学校的事。”", "Bà Bà Xiào Zhe Shuō, Zhè Gè Xīng Qī Tiān, Wǒ Men Duō Shuō Yí Huì Ér, Bà Bà Xiǎng Tīng Nǐ Duō Shuō Shuō Xué Xiào De Shì.", "Bố cười nói: “Chủ nhật này chúng ta nói chuyện lâu hơn một chút nhé, bố muốn nghe con kể thêm chuyện ở trường.”"]]}, "hsk3-15": {"dur": 330.4, "cues": [[7.639, 11.891, "老师告诉我们，博物馆要找志愿者。", "Lǎo Shī Gào Sù Wǒ Men, Bó Wù Guǎn Yào Zhǎo Zhì Yuàn Zhě.", "Thầy nói với chúng tôi rằng bảo tàng đang cần tình nguyện viên."], [11.891, 18.303, "我听了很想试一试，因为我喜欢博物馆，也喜欢帮助人。", "Wǒ Tīng Le Hěn Xiǎng Shì Yí Shì, Yīn Wèi Wǒ Xǐ Huān Bó Wù Guǎn, Yě Xǐ Huān Bāng Zhù Rén.", "Nghe xong tôi rất muốn thử, vì tôi thích bảo tàng và cũng thích giúp đỡ mọi người."], [18.303, 27.028, "我回家告诉妈妈，妈妈笑着说：“这是好事，妈妈为你高兴，你去吧，慢慢学。”", "Wǒ Huí Jiā Gào Sù Mā Mā, Mā Mā Xiào Zhe Shuō, Zhè Shì Hǎo Shì, Mā Mā Wèi Nǐ Gāo Xìng, Nǐ Qù Ba, Màn Màn Xué.", "Tôi về nhà nói với mẹ, mẹ cười bảo: “Đây là việc tốt, mẹ mừng cho con, con đi đi, cứ học từ từ.”"], [27.028, 30.944, "上个月我报名当博物馆的志愿者。", "Shàng Gè Yuè Wǒ Bào Míng Dāng Bó Wù Guǎn De Zhì Yuàn Zhě.", "Tháng trước tôi đăng ký làm tình nguyện viên ở bảo tàng."], [30.944, 35.736, "第一天去的时候，我很早就到了博物馆。", "Dì Yī Tiān Qù De Shí Hòu, Wǒ Hěn Zǎo Jiù Dào Le Bó Wù Guǎn.", "Ngày đầu tiên đi, tôi đến bảo tàng từ rất sớm."], [35.736, 41.26, "负责人是一位先生，他先带我看了每个展厅。", "Fù Zé Rén Shì Yí Wèi Xiān Shēng, Tā Xiān Dài Wǒ Kàn Le Měi Gè Zhǎn Tīng.", "Người phụ trách là một chú, chú dẫn tôi đi xem từng phòng trưng bày trước."], [41.26, 46.088, "他告诉我，游客有问题，就会来问我。", "Tā Gào Sù Wǒ, Yóu Kè Yǒu Wèn Tí, Jiù Huì Lái Wèn Wǒ.", "Chú nói với tôi, khách có thắc mắc sẽ đến hỏi tôi."], [46.088, 50.898, "我听了有点儿紧张，怕自己说不清楚。", "Wǒ Tīng Le Yǒu Diǎn Ér Jǐn Zhāng, Pà Zì Jǐ Shuō Bù Qīng Chǔ.", "Nghe vậy tôi hơi hồi hộp, sợ mình nói không rõ ràng."], [50.898, 58.942, "他笑着说：“没关系，第一次都这样，慢慢说就可以，大家会喜欢你的。”", "Tā Xiào Zhe Shuō, Méi Guān Xì, Dì Yī Cì Dōu Zhè Yàng, Màn Màn Shuō Jiù Kě Yǐ, Dà Jiā Huì Xǐ Huān Nǐ De.", "Chú cười nói: “Không sao, lần đầu ai cũng thế, cứ nói từ từ là được, mọi người sẽ quý cháu.”"], [58.942, 63.722, "工作不复杂，主要是帮助游客找到展厅。", "Gōng Zuò Bú Fù Zá, Zhǔ Yào Shi Bāng Zhù Yóu Kè Zhǎo Dào Zhǎn Tīng.", "Công việc không phức tạp, chủ yếu giúp khách tìm phòng trưng bày."], [63.722, 69.312, "早上人不多，我站在门口，看着游客走进来。", "Zǎo Shàng Rén Bù Duō, Wǒ Zhàn Zài Mén Kǒu, Kàn Zhe Yóu Kè Zǒu Jìn Lái.", "Buổi sáng không đông người, tôi đứng ở cửa, nhìn khách đi vào."], [69.312, 74.956, "一位老先生走过来，问我旧照片在哪个展厅。", "Yí Wèi Lǎo Xiān Shēng Zǒu Guò Lái, Wèn Wǒ Jiù Zhào Piàn Zài Nǎ Gè Zhǎn Tīng.", "Một ông cụ đi lại, hỏi tôi ảnh cũ ở phòng trưng bày nào."], [74.956, 80.24, "我带他走到那个展厅门口，他说了一声谢谢。", "Wǒ Dài Tā Zǒu Dào Nà Gè Zhǎn Tīng Mén Kǒu, Tā Shuō Le Yì Shēng Xiè Xiè.", "Tôi dẫn ông đến cửa phòng trưng bày đó, ông nói một tiếng cảm ơn."], [80.24, 85.566, "我心里很高兴，我说的第一句话就帮助了人。", "Wǒ Xīn Lǐ Hěn Gāo Xìng, Wǒ Shuō De Dì Yī Jù Huà Jiù Bāng Zhù Le Rén.", "Tôi rất vui, câu nói đầu tiên của tôi đã giúp được người khác."], [85.566, 90.97, "有一位老奶奶看不清说明，我慢慢读给她听。", "Yǒu Yí Wèi Lǎo Nǎi Nai Kàn Bù Qīng Shuō Míng, Wǒ Màn Màn Dú Gěi Tā Tīng.", "Một bà nhìn không rõ phần thuyết minh, tôi đọc chậm cho bà nghe."], [90.97, 96.502, "老奶奶的眼睛不好，她很想知道照片里的故事。", "Lǎo Nǎi Nǎi De Yǎn Jīng Bù Hǎo, Tā Hěn Xiǎng Zhī Dào Zhào Piàn Lǐ De Gù Shì.", "Mắt bà không tốt, bà rất muốn biết câu chuyện trong những bức ảnh."], [96.502, 103.754, "我慢慢读，一个字一个字地读，她慢慢听，眼睛看着我，笑着。", "Wǒ Màn Màn Dú, Yí Gè Zì Yí Gè Zì Dì Dú, Tā Màn Màn Tīng, Yǎn Jīng Kàn Zhe Wǒ, Xiào Zhe.", "Tôi đọc từ từ, đọc từng chữ từng chữ, bà nghe từ từ, mắt nhìn tôi và mỉm cười."], [103.754, 108.27, "她听得很认真，还问了我两个问题。", "Tā Tīng Dé Hěn Rèn Zhēn, Hái Wèn Le Wǒ Liǎng Gè Wèn Tí.", "Bà nghe rất chăm chú, còn hỏi tôi hai câu."], [108.27, 111.247, "我知道的，就告诉她。", "Wǒ Zhī Dào De, Jiù Gào Sù Tā.", "Điều gì tôi biết, tôi đều nói với bà."], [111.247, 116.411, "我不知道的，就去问负责人，再回来告诉她。", "Wǒ Bù Zhī Dào De, Jiù Qù Wèn Fù Zé Rén, Zài Huí Lái Gào Sù Tā.", "Điều gì tôi không biết, tôi đi hỏi người phụ trách rồi quay lại nói với bà."], [116.411, 119.727, "她听完以后连声说谢谢。", "Tā Tīng Wán Yǐ Hòu Lián Shēng Shuō Xiè Xiè.", "Nghe xong bà nói cảm ơn liên tục."], [119.727, 127.686, "老奶奶走的时候，拉着我的手说：“你真好，声音也好听，奶奶谢谢你。”", "Lǎo Nǎi Nǎi Zǒu De Shí Hòu, Lā Zhe Wǒ De Shǒu Shuō, Nǐ Zhēn Hǎo, Shēng Yīn Yě Hǎo Tīng, Nǎi Nǎi Xiè Xiè Nǐ.", "Khi ra về, bà nắm tay tôi và nói: “Cháu tốt quá, giọng cũng hay nữa, bà cảm ơn cháu.”"], [127.686, 134.651, "我笑着说：“您慢慢走，下次再来，我还读给您听，奶奶。”", "Wǒ Xiào Zhe Shuō, Nín Màn Màn Zǒu, Xià Cì Zài Lái, Wǒ Hái Dú Gěi Nín Tīng, Nǎi Nǎi.", "Tôi cười nói: “Bà đi thong thả nhé, lần sau lại đến ạ, cháu lại đọc cho bà nghe, bà nhé.”"], [134.651, 140.175, "中午休息的时候，我坐下来吃饭，腿有点儿疼。", "Zhōng Wǔ Xiū Xī De Shí Hòu, Wǒ Zuò Xià Lái Chī Fàn, Tuǐ Yǒu Diǎn Ér Téng.", "Giờ nghỉ trưa, tôi ngồi xuống ăn cơm, chân hơi đau."], [140.175, 145.473, "一位姐姐也是志愿者，她已经来了很多次了。", "Yí Wèi Jiě Jiě Yě Shì Zhì Yuàn Zhě, Tā Yǐ Jīng Lái Le Hěn Duō Cì Le.", "Một chị cũng là tình nguyện viên, chị đã đến đây nhiều lần rồi."], [145.473, 150.421, "她告诉我，她第一次来的时候也很紧张。", "Tā Gào Sù Wǒ, Tā Dì Yī Cì Lái De Shí Hòu Yě Hěn Jǐn Zhāng.", "Chị nói với tôi, lần đầu chị đến cũng rất hồi hộp."], [150.421, 159.929, "她笑着说：“没关系，我第一次来的时候，也紧张得说不出话，第二次就好了，你也可以的。”", "Tā Xiào Zhe Shuō, Méi Guān Xì, Wǒ Dì Yī Cì Lái De Shí Hòu, Yě Jǐn Zhāng Dé Shuō Bù Chū Huà, Dì Èr Cì Jiù Hǎo Le, Nǐ Yě Kě Yǐ De.", "Chị cười nói: “Không sao, lần đầu chị đến cũng hồi hộp đến mức không nói nên lời, lần thứ hai là quen ngay, em cũng làm được mà.”"], [159.929, 164.815, "下午人多了，一个小孩子跑过来找我。", "Xià Wǔ Rén Duō Le, Yí Gè Xiǎo Hái Zi Pǎo Guò Lái Zhǎo Wǒ.", "Buổi chiều đông người hơn, một em nhỏ chạy lại tìm tôi."], [164.815, 169.139, "小孩子哭着说：“我找不到妈妈了。”", "Xiǎo Hái Zi Kū Zhe Shuō, Wǒ Zhǎo Bú Dào Mā Mā Le.", "Em nhỏ vừa khóc vừa nói: “Cháu không tìm thấy mẹ.”"], [169.139, 175.143, "我心里很着急，可是我先让他坐下来，给他一杯水。", "Wǒ Xīn Lǐ Hěn Zháo Jí, Kě Shì Wǒ Xiān Ràng Tā Zuò Xià Lái, Gěi Tā Yì Bēi Shuǐ.", "Tôi rất sốt ruột, nhưng trước hết tôi cho em ngồi xuống và đưa em một cốc nước."], [175.143, 179.328, "我问他：“你妈妈穿什么颜色的衣服？”", "Wǒ Wèn Tā, Nǐ Mā Mā Chuān Shén Me Yán Sè De Yī Fú?", "Tôi hỏi em: “Mẹ cháu mặc quần áo màu gì?”"], [179.328, 184.156, "他说：“红色的，她的包也是红色的。”", "Tā Shuō, Hóng Sè De, Tā De Bāo Yě Shì Hóng Sè De.", "Em nói: “Màu đỏ ạ, túi của mẹ cũng màu đỏ.”"], [184.156, 189.056, "我带他去找负责人，我们一起找他的妈妈。", "Wǒ Dài Tā Qù Zhǎo Fù Zé Rén, Wǒ Men Yì Qǐ Zhǎo Tā De Mā Mā.", "Tôi dẫn em đi tìm người phụ trách, chúng tôi cùng nhau tìm mẹ của em."], [189.056, 192.996, "十分钟以后，他的妈妈跑过来了。", "Shí Fēn Zhōng Yǐ Hòu, Tā De Mā Mā Pǎo Guò Lái Le.", "Mười phút sau, mẹ của em chạy đến."], [192.996, 200.156, "妈妈拉着孩子的手，笑着说：“找到了！谢谢你，太谢谢你了！”", "Mā Mā Lā Zhe Hái Zi De Shǒu, Xiào Zhe Shuō, Zhǎo Dào Le! Xiè Xiè Nǐ, Tài Xiè Xiè Nǐ Le!", "Người mẹ nắm tay con, cười nói: “Tìm thấy rồi! Cảm ơn cháu, cảm ơn cháu nhiều lắm!”"], [200.156, 203.832, "我看着他们，心里特别高兴。", "Wǒ Kàn Zhe Tā Men, Xīn Lǐ Tè Bié Gāo Xìng.", "Nhìn hai mẹ con, tôi vô cùng vui."], [203.832, 208.252, "那天下午我很累，可是心里很充实。", "Nà Tiān Xià Wǔ Wǒ Hěn Lèi, Kě Shì Xīn Lǐ Hěn Chōng Shí.", "Chiều hôm đó tôi rất mệt, nhưng trong lòng rất đầy."], [208.252, 211.766, "我打算下个学期继续参加。", "Wǒ Dǎ Suàn Xià Gè Xué Qī Jì Xù Cān Jiā.", "Học kỳ sau tôi định tiếp tục tham gia."], [211.766, 216.978, "回家以后，我把这一天的事告诉了爸爸妈妈。", "Huí Jiā Yǐ Hòu, Wǒ Bǎ Zhè Yì Tiān De Shì Gào Sù Le Bà Bà Mā Mā.", "Về nhà, tôi kể chuyện ngày hôm đó cho bố mẹ nghe."], [216.978, 224.518, "爸爸笑着说：“你今天做了很好的事，爸爸为你高兴，快去休息吧。”", "Bà Bà Xiào Zhe Shuō, Nǐ Jīn Tiān Zuò Le Hěn Hǎo De Shì, Bà Bà Wèi Nǐ Gāo Xìng, Kuài Qù Xiū Xī Ba.", "Bố cười nói: “Hôm nay con đã làm một việc rất tốt, bố mừng cho con, đi nghỉ sớm đi.”"], [224.518, 228.77, "那天晚上，我很累，很早就睡了。", "Nà Tiān Wǎn Shàng, Wǒ Hěn Lèi, Hěn Zǎo Jiù Shuì Le.", "Tối hôm đó tôi rất mệt, ngủ từ rất sớm."], [228.77, 234.173, "第二次去的时候，我已经知道每个展厅在哪儿。", "Dì Èr Cì Qù De Shí Hòu, Wǒ Yǐ Jīng Zhī Dào Měi Gè Zhǎn Tīng Zài Nǎ Ér.", "Lần thứ hai đến tôi đã biết mỗi phòng ở đâu."], [234.173, 238.785, "第二次去的路上，我一点儿也不紧张了。", "Dì Èr Cì Qù De Lù Shàng, Wǒ Yì Diǎn Ér Yě Bù Jǐn Zhāng Le.", "Trên đường đi lần thứ hai, tôi không còn hồi hộp chút nào nữa."], [238.785, 243.013, "我走进博物馆，看见老奶奶也在。", "Wǒ Zǒu Jìn Bó Wù Guǎn, Kàn Jiàn Lǎo Nǎi Nǎi Yě Zài.", "Tôi bước vào bảo tàng và thấy bà cụ cũng ở đó."], [243.013, 249.977, "她看见我，笑着说：“你来了！奶奶等你很久了，你还记得我吗？”", "Tā Kàn Jiàn Wǒ, Xiào Zhe Shuō, Nǐ Lái Le! Nǎi Nǎi Děng Nǐ Hěn Jiǔ Le, Nǐ Hái Jì De Wǒ Ma?", "Bà nhìn thấy tôi, cười và nói: “Cháu đến rồi! Bà đợi cháu lâu lắm rồi, cháu còn nhớ bà không?”"], [249.977, 258.136, "我拉着她的手说：“记得，奶奶，我天天都想着您，今天我还读给您听。”", "Wǒ Lā Zhe Tā De Shǒu Shuō, Jì De, Nǎi Nǎi, Wǒ Tiān Tiān Dōu Xiǎng Zhe Nín, Jīn Tiān Wǒ Hái Dú Gěi Nín Tīng.", "Tôi nắm tay bà nói: “Cháu nhớ ạ, bà ơi, ngày nào cháu cũng nghĩ đến bà, hôm nay cháu lại đọc cho bà nghe.”"], [258.136, 261.596, "一位游客问我洗手间怎么走。", "Yí Wèi Yóu Kè Wèn Wǒ Xǐ Shǒu Jiān Zěn Me Zǒu.", "Một khách hỏi nhà vệ sinh đi thế nào."], [261.596, 264.216, "我可以马上告诉他。", "Wǒ Kě Yǐ Mǎ Shàng Gào Sù Tā.", "Tôi nói được ngay."], [264.216, 269.86, "还有一位游客问我出口在哪儿，我也马上告诉他了。", "Hái Yǒu Yí Wèi Yóu Kè Wèn Wǒ Chū Kǒu Zài Nǎ Ér, Wǒ Yě Mǎ Shàng Gào Sù Tā Le.", "Lại một vị khách hỏi tôi lối ra ở đâu, tôi cũng trả lời ngay."], [269.86, 279.032, "这一天我说了很多话，声音有点儿累，喝了很多水，可是看着大家的笑，心里很高兴。", "Zhè Yì Tiān Wǒ Shuō Le Hěn Duō Huà, Shēng Yīn Yǒu Diǎn Ér Lèi, Hē Le Hěn Duō Shuǐ, Kě Shì Kàn Zhe Dà Jiā De Xiào, Xīn Lǐ Hěn Gāo Xìng.", "Ngày hôm đó tôi nói rất nhiều, giọng hơi mệt, uống rất nhiều nước, nhưng nhìn nụ cười của mọi người, trong lòng rất vui."], [279.032, 283.632, "下班以后，负责人说我介绍得很清楚。", "Xià Bān Yǐ Hòu, Fù Zé Rén Shuō Wǒ Jiè Shào Dé Hěn Qīng Chǔ.", "Tan việc, người phụ trách nói tôi giới thiệu rất rõ."], [283.632, 292.18, "负责人笑着说：“你介绍得很清楚，下次有活动，我还叫你来，你一定要来。”", "Fù Zé Rén Xiào Zhe Shuō, Nǐ Jiè Shào Dé Hěn Qīng Chǔ, Xià Cì Yǒu Huó Dòng, Wǒ Hái Jiào Nǐ Lái, Nǐ Yí Dìng Yào Lái.", "Người phụ trách cười nói: “Cháu giới thiệu rất rõ ràng, lần sau có hoạt động chú lại gọi cháu đến, cháu nhất định phải đến nhé.”"], [292.18, 296.912, "我回家的路上还在想那位老奶奶的笑。", "Wǒ Huí Jiā De Lù Shang Hái Zài Xiǎng Nà Wèi Lǎo Nǎi Nai De Xiào.", "Trên đường về tôi vẫn nghĩ nụ cười của bà."], [296.912, 300.444, "能帮到人，这一天就值得。", "Néng Bāng Dào Rén, Zhè Yì Tiān Jiù Zhí Dé.", "Giúp được người thì ngày đó đáng."], [300.444, 304.228, "现在每个月我都去博物馆一次。", "Xiàn Zài Měi Gè Yuè Wǒ Dōu Qù Bó Wù Guǎn Yí Cì.", "Bây giờ tháng nào tôi cũng đến bảo tàng một lần."], [304.228, 308.384, "我觉得，帮助别人，也是帮助自己。", "Wǒ Jué De, Bāng Zhù Bié Rén, Yě Shì Bāng Zhù Zì Jǐ.", "Tôi thấy, giúp người khác cũng là giúp chính mình."], [308.384, 313.98, "下个学期，我还要带我的朋友一起去当志愿者。", "Xià Gè Xué Qī, Wǒ Hái Yào Dài Wǒ De Péng Yǒu Yì Qǐ Qù Dāng Zhì Yuàn Zhě.", "Học kỳ sau, tôi sẽ rủ bạn mình cùng đi làm tình nguyện viên."], [313.98, 321.784, "朋友笑着说：“我也去！到时候我们一起帮助别人，一起听他们说谢谢。”", "Péng Yǒu Xiào Zhe Shuō, Wǒ Yě Qù! Dào Shí Hòu Wǒ Men Yì Qǐ Bāng Zhù Bié Rén, Yì Qǐ Tīng Tā Men Shuō Xiè Xiè.", "Bạn tôi cười nói: “Tớ cũng đi! Đến lúc đó chúng ta cùng giúp mọi người, cùng nghe họ nói cảm ơn.”"]]}, "hsk3-16": {"dur": 306.01, "cues": [[7.523, 11.564, "九月我一个人来到上海上大学。", "Jiǔ Yuè Wǒ Yí Gè Rén Lái Dào Shàng Hǎi Shàng Dà Xué.", "Tháng Chín, tôi một mình đến Thượng Hải học đại học."], [11.564, 19.319, "从车站出来，人很多，声音也很多，我有点儿紧张，也有点儿高兴。", "Cóng Chē Zhàn Chū Lái, Rén Hěn Duō, Shēng Yīn Yě Hěn Duō, Wǒ Yǒu Diǎn Ér Jǐn Zhāng, Yě Yǒu Diǎn Ér Gāo Xìng.", "Bước ra khỏi nhà ga, người rất đông, âm thanh cũng ồn ào, tôi hơi hồi hộp, mà cũng hơi vui."], [19.319, 24.435, "上海比我住的地方大得多，人也多得多。", "Shàng Hǎi Bǐ Wǒ Zhù De Dì Fang Dà De Duō, Rén Yě Duō De Duō.", "Thượng Hải lớn hơn nơi tôi ở rất nhiều, người cũng đông hơn rất nhiều."], [24.435, 30.163, "我拉着箱子，站在车站门口，不知道先去哪儿。", "Wǒ Lā Zhe Xiāng Zi, Zhàn Zài Chē Zhàn Mén Kǒu, Bù Zhī Dào Xiān Qù Nǎ Er.", "Tôi kéo vali, đứng ở cửa nhà ga, không biết nên đi đâu trước."], [30.163, 37.079, "妈妈在电话里说：“到了学校，先给我打电话，妈妈会担心的。”", "Mā Mā Zài Diàn Huà Lǐ Shuō: Dào Le Xué Xiào, Xiān Gěi Wǒ Dǎ Diàn Huà, Mā Mā Huì Dān Xīn De.", "Mẹ nói qua điện thoại: “Đến trường rồi thì gọi cho mẹ trước nhé, không là mẹ lo đấy.”"], [37.079, 43.611, "我笑着说：“放心，我可以自己照顾自己，您别担心。”", "Wǒ Xiào Zhe Shuō: Fàng Xīn, Wǒ Kě Yǐ Zì Jǐ Zhào Gù Zì Jǐ, Nín Bié Dān Xīn.", "Tôi cười nói: “Mẹ yên tâm, con tự chăm sóc mình được, mẹ đừng lo nhé.”"], [43.611, 49.135, "到了学校，室友小王先带我去了我们的房间。", "Dào Le Xué Xiào, Shì Yǒu Xiǎo Wáng Xiān Dài Wǒ Qù Le Wǒ Men De Fáng Jiān.", "Đến trường, bạn cùng phòng Tiểu Vương dẫn tôi về phòng của chúng tôi trước."], [49.135, 52.942, "小王是上海人，说话很快。", "Xiǎo Wáng Shì Shàng Hǎi Rén, Shuō Huà Hěn Kuài.", "Tiểu Vương là người Thượng Hải, nói rất nhanh."], [52.942, 57.29, "刚开始，我连去超市都要看地图。", "Gāng Kāi Shǐ, Wǒ Lián Qù Chāo Shì Dōu Yào Kàn Dì Tú.", "Lúc đầu, ngay cả đi siêu thị tôi cũng phải xem bản đồ."], [57.29, 61.463, "口音不一样，有时候我听不太懂。", "Kǒu Yīn Bù Yí Yàng, Yǒu Shí Hòu Wǒ Tīng Bú Tài Dǒng.", "Giọng nói khác nhau, có lúc tôi nghe không rõ lắm."], [61.463, 68.475, "有一次我问小王：“食堂在哪儿？”他说了三遍，我才听清楚。", "Yǒu Yí Cì Wǒ Wèn Xiǎo Wáng: Shí Táng Zài Nǎ Er? Tā Shuō Le Sān Biàn, Wǒ Cái Tīng Qīng Chǔ.", "Có lần tôi hỏi Tiểu Vương: “Nhà ăn ở đâu?” Cậu ấy nói ba lần tôi mới nghe rõ."], [68.475, 72.487, "他没有笑我，还慢慢又说了一次。", "Tā Méi Yǒu Xiào Wǒ, Hái Màn Màn Yòu Shuō Le Yí Cì.", "Cậu ấy không cười tôi, còn từ từ nói lại một lần nữa."], [72.487, 77.648, "我把不懂的词写在本子上，晚上再问他。", "Wǒ Bǎ Bù Dǒng De Cí Xiě Zài Běn Zi Shàng, Wǎn Shàng Zài Wèn Tā.", "Tôi viết những từ chưa hiểu vào vở, tối lại hỏi cậu ấy."], [77.648, 83.754, "我主动和室友一起吃饭，也加入了学校的汉语角。", "Wǒ Zhǔ Dòng Hé Shì Yǒu Yì Qǐ Chī Fàn, Yě Jiā Rù Le Xué Xiào De Hàn Yǔ Jiǎo.", "Tôi chủ động ăn cơm cùng bạn cùng phòng, và tham gia góc tiếng Trung của trường."], [83.754, 87.766, "汉语角的老师让我先介绍自己。", "Hàn Yǔ Jiǎo De Lǎo Shī Ràng Wǒ Xiān Jiè Shào Zì Jǐ.", "Thầy ở góc tiếng Trung bảo tôi tự giới thiệu trước."], [87.766, 91.905, "我说得很慢，可是大家都认真听。", "Wǒ Shuō De Hěn Màn, Kě Shì Dà Jiā Dōu Rèn Zhēn Tīng.", "Tôi nói rất chậm, nhưng mọi người đều chăm chú nghe."], [91.905, 97.381, "一个星期以后，我第一次自己坐地铁去书店。", "Yí Gè Xīng Qī Yǐ Hòu, Wǒ Dì Yī Cì Zì Jǐ Zuò Dì Tiě Qù Shū Diàn.", "Một tuần sau, lần đầu tiên tôi tự đi tàu điện đến hiệu sách."], [97.381, 104.321, "我坐错了车，车开了二十分钟，我看着外边，才发现不对。", "Wǒ Zuò Cuò Le Chē, Chē Kāi Le Èr Shí Fēn Zhōng, Wǒ Kàn Zhe Wài Biān, Cái Fā Xiàn Bú Duì.", "Tôi lên nhầm xe, xe chạy được hai mươi phút, tôi nhìn ra bên ngoài mới phát hiện không đúng."], [104.321, 108.182, "我一看手机，已经晚上六点了。", "Wǒ Yí Kàn Shǒu Jī, Yǐ Jīng Wǎn Shàng Liù Diǎn Le.", "Tôi nhìn điện thoại, đã sáu giờ tối rồi."], [108.182, 111.642, "我很着急，给小王打电话。", "Wǒ Hěn Zháo Jí, Gěi Xiǎo Wáng Dǎ Diàn Huà.", "Tôi rất sốt ruột, gọi điện cho Tiểu Vương."], [111.642, 119.281, "他说：“别着急，先慢慢下来，再坐回去，我在学校门口等你。”", "Tā Shuō: Bié Zháo Jí, Xiān Màn Màn Xià Lái, Zài Zuò Huí Qù, Wǒ Zài Xué Xiào Mén Kǒu Děng Nǐ.", "Cậu ấy nói: “Đừng sốt ruột, cứ từ từ xuống xe rồi đi ngược lại, tớ đợi cậu ở cổng trường.”"], [119.281, 123.581, "回到学校的时候，已经晚上八点了。", "Huí Dào Xué Xiào De Shí Hou, Yǐ Jīng Wǎn Shàng Bā Diǎn Le.", "Khi về đến trường thì đã tám giờ tối."], [123.581, 128.889, "小王在学校门口等我，还给我带了一份饭。", "Xiǎo Wáng Zài Xué Xiào Mén Kǒu Děng Wǒ, Huán Gěi Wǒ Dài Le Yí Fèn Fàn.", "Tiểu Vương đợi tôi ở cổng trường, còn mang cho tôi một phần cơm."], [128.889, 136.162, "他笑着说：“坐错没关系，我第一次也走错过路，你没事就好。”", "Tā Xiào Zhe Shuō: Zuò Cuò Méi Guān Xì, Wǒ Dì Yī Cì Yě Zǒu Cuò Guò Lù, Nǐ Méi Shì Jiù Hǎo.", "Cậu ấy cười nói: “Đi nhầm không sao đâu, lần đầu tớ cũng đi nhầm đường, cậu không sao là tốt rồi.”"], [136.162, 141.974, "从那天起，我坐地铁以前会先看清楚地图。", "Cóng Nà Tiān Qǐ, Wǒ Zuò Dì Tiě Yǐ Qián Huì Xiān Kàn Qīng Chǔ Dì Tú.", "Từ hôm đó, trước khi đi tàu điện tôi đều xem rõ bản đồ trước."], [141.974, 146.274, "一个月以后，我认识了不少新朋友。", "Yí Gè Yuè Yǐ Hòu, Wǒ Rèn Shi Le Bù Shǎo Xīn Péng Yǒu.", "Một tháng sau, tôi quen được khá nhiều bạn mới."], [146.274, 151.51, "现在我去一个新地方，会先记两个路标。", "Xiàn Zài Wǒ Qù Yí Gè Xīn Dì Fāng, Huì Xiān Jì Liǎng Gè Lù Biāo.", "Bây giờ đến một nơi mới, tôi nhớ hai biển chỉ đường trước."], [151.51, 155.783, "超市、地铁和教室我都认识了。", "Chāo Shì, Dì Tiě Hé Jiào Shì Wǒ Dōu Rèn Shi Le.", "Siêu thị, tàu điện và lớp học tôi đều biết cả rồi."], [155.783, 159.051, "口音也慢慢听得懂一些。", "Kǒu Yīn Yě Màn Màn Tīng Dé Dǒng Yì Xiē.", "Giọng địa phương tôi cũng dần nghe hiểu được một phần."], [159.051, 165.367, "在汉语角，我认识了一位新同学，她也是从外地来的。", "Zài Hàn Yǔ Jiǎo, Wǒ Rèn Shi Le Yí Wèi Xīn Tóng Xué, Tā Yě Shì Cóng Wài Dì Lái De.", "Ở góc tiếng Trung, tôi quen một bạn học mới, cô ấy cũng từ nơi khác đến."], [165.367, 170.099, "我们常常一起去图书馆看书，一起吃饭。", "Wǒ Men Cháng Cháng Yì Qǐ Qù Tú Shū Guǎn Kàn Shū, Yì Qǐ Chī Fàn.", "Chúng tôi thường cùng đến thư viện đọc sách, cùng ăn cơm."], [170.099, 173.964, "她说我的汉语比以前好了一点儿。", "Tā Shuō Wǒ De Hàn Yǔ Bǐ Yǐ Qián Hǎo Le Yì Diǎn Ér.", "Cô ấy nói tiếng Trung của tôi khá hơn trước một chút."], [173.964, 178.792, "我听了很高兴，其实我只会说几句。", "Wǒ Tīng Le Hěn Gāo Xìng, Qí Shí Wǒ Zhǐ Huì Shuō Jǐ Jù.", "Nghe vậy tôi rất vui, thật ra tôi chỉ biết nói vài câu."], [178.792, 182.54, "周末我带室友去吃了家乡菜。", "Zhōu Mò Wǒ Dài Shì Yǒu Qù Chī Le Jiā Xiāng Cài.", "Cuối tuần, tôi dẫn bạn cùng phòng đi ăn món quê nhà."], [182.54, 187.824, "那家小馆子离学校不远，我们走了十分钟。", "Nà Jiā Xiǎo Guǎn Zi Lí Xué Xiào Bù Yuǎn, Wǒ Men Zǒu Le Shí Fēn Zhōng.", "Quán ăn nhỏ đó cách trường không xa, chúng tôi đi bộ mười phút."], [187.824, 191.983, "他们说好吃，我也觉得没那么孤单。", "Tā Men Shuō Hǎo Chī, Wǒ Yě Jué De Méi Nà Me Gū Dān.", "Họ nói ngon, tôi cũng thấy đỡ cô đơn hơn."], [191.983, 197.003, "吃饭的时候，小王教了我几句这里的话。", "Chī Fàn De Shí Hou, Xiǎo Wáng Jiāo Le Wǒ Jǐ Jù Zhè Lǐ De Huà.", "Lúc ăn cơm, Tiểu Vương dạy tôi vài câu tiếng địa phương ở đây."], [197.003, 200.511, "我说了一句，大家都笑了。", "Wǒ Shuō Le Yí Jù, Dà Jiā Dōu Xiào Le.", "Tôi nói một câu, mọi người đều bật cười."], [200.511, 204.715, "回去的路上，我们一边走一边聊天。", "Huí Qù De Lù Shang, Wǒ Men Yì Biān Zǒu Yì Biān Liáo Tiān.", "Trên đường về, chúng tôi vừa đi vừa trò chuyện."], [204.715, 210.768, "晚上我给妈妈打电话，告诉她我认识了很多新朋友。", "Wǎn Shàng Wǒ Gěi Mā Mā Dǎ Diàn Huà, Gào Su Tā Wǒ Rèn Shi Le Hěn Duō Xīn Péng Yǒu.", "Buổi tối tôi gọi cho mẹ, kể rằng tôi đã quen nhiều bạn mới."], [210.768, 217.804, "妈妈高兴地说：“听见你这么说，妈妈就放心了，也为你高兴。”", "Mā Mā Gāo Xìng De Shuō: Tīng Jiàn Nǐ Zhè Me Shuō, Mā Mā Jiù Fàng Xīn Le, Yě Wèi Nǐ Gāo Xìng.", "Mẹ vui vẻ nói: “Nghe con nói vậy, mẹ yên tâm rồi, mẹ cũng mừng cho con.”"], [217.804, 223.4, "以前我每天都很想我的家人，现在想得少了。", "Yǐ Qián Wǒ Měi Tiān Dōu Hěn Xiǎng Wǒ De Jiā Rén, Xiàn Zài Xiǎng De Shǎo Le.", "Trước đây ngày nào tôi cũng nhớ người nhà của mình, giờ thì ít hơn rồi."], [223.4, 230.226, "想家的时候，我就看看手机里家人的照片，心里就安静了。", "Xiǎng Jiā De Shí Hou, Wǒ Jiù Kàn Kan Shǒu Jī Lǐ Jiā Rén De Zhào Piàn, Xīn Lǐ Jiù Ān Jìng Le.", "Những lúc nhớ nhà, tôi lại xem ảnh người nhà trong điện thoại, lòng lại yên tĩnh lại."], [230.226, 234.598, "上个星期，班里来了一位新同学。", "Shàng Gè Xīng Qī, Bān Lǐ Lái Le Yí Wèi Xīn Tóng Xué.", "Tuần trước, lớp tôi có một bạn học mới."], [234.598, 239.57, "他也是第一次来上海，什么都不太清楚。", "Tā Yě Shì Dì Yī Cì Lái Shàng Hǎi, Shén Me Dōu Bú Tài Qīng Chu.", "Cậu ấy cũng lần đầu đến Thượng Hải, việc gì cũng chưa rõ."], [239.57, 244.326, "我带他去食堂，又带他坐了一次地铁。", "Wǒ Dài Tā Qù Shí Táng, Yòu Dài Tā Zuò Le Yí Cì Dì Tiě.", "Tôi dẫn cậu ấy đến nhà ăn, lại dẫn cậu ấy đi tàu điện một lần."], [244.326, 251.098, "我笑着告诉他：“别紧张，先记两个路标，就不会走错了。”", "Wǒ Xiào Zhe Gào Su Tā: Bié Jǐn Zhāng, Xiān Jì Liǎng Gè Lù Biāo, Jiù Bú Huì Zǒu Cuò Le.", "Tôi cười bảo cậu ấy: “Đừng hồi hộp, nhớ hai biển chỉ đường trước là sẽ không đi nhầm đâu.”"], [251.098, 257.347, "他高兴地说：“谢谢你，有你帮忙，我一点儿也不紧张了！”", "Tā Gāo Xìng De Shuō: Xiè Xie Nǐ, Yǒu Nǐ Bāng Máng, Wǒ Yì Diǎn Ér Yě Bù Jǐn Zhāng Le!", "Cậu ấy vui vẻ nói: “Cảm ơn cậu, có cậu giúp, tớ chẳng hồi hộp chút nào nữa!”"], [257.347, 262.175, "听见这句话，我想起了刚来的自己。", "Tīng Jiàn Zhè Jù Huà, Wǒ Xiǎng Qǐ Le Gāng Lái De Zì Jǐ.", "Nghe câu đó, tôi nhớ lại chính mình lúc mới đến."], [262.175, 267.363, "我这才发现，我已经慢慢习惯了这座城市。", "Wǒ Zhè Cái Fā Xiàn, Wǒ Yǐ Jīng Màn Màn Xí Guàn Le Zhè Zuò Chéng Shì.", "Đến lúc đó tôi mới nhận ra, mình đã dần quen với thành phố này rồi."], [267.363, 273.823, "现在这座城市虽然还很陌生，可是已经有了家的感觉。", "Xiàn Zài Zhè Zuò Chéng Shì Suī Rán Hái Hěn Mò Shēng, Kě Shì Yǐ Jīng Yǒu Le Jiā De Gǎn Jué.", "Bây giờ thành phố này tuy vẫn còn lạ, nhưng đã có cảm giác như nhà."], [273.823, 278.732, "城市还大，可是我已经有了自己的路线。", "Chéng Shì Hái Dà, Kě Shì Wǒ Yǐ Jīng Yǒu Le Zì Jǐ De Lù Xiàn.", "Thành phố vẫn lớn, nhưng tôi đã có tuyến đường của riêng mình."], [278.732, 284.856, "下个周末，我想带新朋友去看看这座城市的公园。", "Xià Ge Zhōu Mò, Wǒ Xiǎng Dài Xīn Péng Yǒu Qù Kàn Kan Zhè Zuò Chéng Shì De Gōng Yuán.", "Cuối tuần tới, tôi muốn dẫn bạn mới đi xem công viên của thành phố này."], [284.856, 290.476, "我知道，以后我还会认识更多的地方和朋友。", "Wǒ Zhī Dào, Yǐ Hòu Wǒ Hái Huì Rèn Shi Gèng Duō De Dì Fang Hé Péng Yǒu.", "Tôi biết, sau này tôi sẽ còn biết thêm nhiều nơi và nhiều người bạn nữa."], [290.476, 297.365, "晚上，我给妈妈打电话，笑着说：“妈妈，我在这儿也有家了。”", "Wǎn Shàng, Wǒ Gěi Mā Mā Dǎ Diàn Huà, Xiào Zhe Shuō: Mā Mā, Wǒ Zài Zhè Er Yě Yǒu Jiā Le.", "Buổi tối, tôi gọi điện cho mẹ, cười nói: “Mẹ ơi, ở đây con cũng có nhà rồi.”"]]}, "hsk3-17": {"dur": 293.81, "cues": [[7.338, 11.614, "昨天晚上，我和同学一起看电视。", "Zuó Tiān Wǎn Shàng, Wǒ Hé Tóng Xué Yì Qǐ Kàn Diàn Shì.", "Tối qua, tôi xem ti vi cùng bạn học."], [11.614, 19.13, "同学高兴地说：“今天有一部纪录片，是关于蜜蜂的，你一定会喜欢！”", "Tóng Xué Gāo Xìng De Shuō: Jīn Tiān Yǒu Yí Bù Jì Lù Piàn, Shì Guān Yú Mì Fēng De, Nǐ Yí Dìng Huì Xǐ Huan!", "Bạn tôi vui vẻ nói: “Hôm nay có một bộ phim tài liệu về loài ong, cậu nhất định sẽ thích!”"], [19.13, 22.59, "我说：“蜜蜂有什么好看的？”", "Wǒ Shuō: Mì Fēng Yǒu Shén Me Hǎo Kàn De?", "Tôi nói: “Ong thì có gì hay mà xem?”"], [22.59, 27.538, "以前我有点儿怕蜜蜂，看见了就马上走。", "Yǐ Qián Wǒ Yǒu Diǎn Ér Pà Mì Fēng, Kàn Jiàn Le Jiù Mǎ Shàng Zǒu.", "Trước đây tôi hơi sợ ong, thấy là đi ngay."], [27.538, 32.531, "可是同学说，这部电影跟我想的不一样。", "Kě Shì Tóng Xué Shuō, Zhè Bù Diàn Yǐng Gēn Wǒ Xiǎng De Bù Yí Yàng.", "Nhưng bạn tôi nói, bộ phim này khác với điều tôi nghĩ."], [32.531, 36.639, "昨天我看了一部关于蜜蜂的纪录片。", "Zuó Tiān Wǒ Kàn Le Yí Bù Guān Yú Mì Fēng De Jì Lù Piàn.", "Hôm qua tôi xem một bộ phim tài liệu về loài ong."], [36.639, 41.899, "以前我只知道蜜蜂会采蜜，别的不太清楚。", "Yǐ Qián Wǒ Zhī Zhī Dào Mì Fēng Huì Cǎi Mì, Bié De Bú Tài Qīng Chǔ.", "Trước đây tôi chỉ biết ong lấy mật, còn lại không rõ lắm."], [41.899, 48.994, "电影一开始，我看见很多花，也听见了蜜蜂飞来飞去的声音。", "Diàn Yǐng Yì Kāi Shǐ, Wǒ Kàn Jiàn Hěn Duō Huā, Yě Tīng Jiàn Le Mì Fēng Fēi Lái Fēi Qù De Shēng Yīn.", "Phim vừa bắt đầu, tôi thấy rất nhiều hoa, và nghe thấy tiếng ong bay qua bay lại."], [48.994, 52.622, "一只蜜蜂一天要去很多花上。", "Yì Zhī Mì Fēng Yì Tiān Yào Qù Hěn Duō Huā Shàng.", "Một con ong trong một ngày phải đến rất nhiều bông hoa."], [52.622, 57.906, "它们在花上飞来飞去，身上带着很多花粉。", "Tā Men Zài Huā Shàng Fēi Lái Fēi Qù, Shēn Shang Dài Zhe Hěn Duō Huā Fěn.", "Chúng bay qua bay lại trên những bông hoa, trên mình mang theo rất nhiều phấn hoa."], [57.906, 63.692, "电影里说，很多植物都需要蜜蜂帮助传播花粉。", "Diàn Yǐng Lǐ Shuō, Hěn Duō Zhí Wù Dōu Xū Yào Mì Fēng Bāng Zhù Chuán Bō Huā Fěn.", "Trong phim nói, nhiều loài cây đều cần ong giúp phát tán phấn hoa."], [63.692, 67.92, "没有蜜蜂，很多水果和菜都会变少。", "Méi Yǒu Mì Fēng, Hěn Duō Shuǐ Guǒ Hé Cài Dōu Huì Biàn Shǎo.", "Không có ong, nhiều trái cây và rau sẽ ít đi."], [67.92, 73.422, "如果蜜蜂越来越少，我们的食物也会受到影响。", "Rú Guǒ Mì Fēng Yuè Lái Yuè Shǎo, Wǒ Men De Shí Wù Yě Huì Shòu Dào Yǐng Xiǎng.", "Nếu ong ngày càng ít, thức ăn của chúng ta cũng sẽ bị ảnh hưởng."], [73.422, 77.554, "听了这些，我想起了爷爷的花园。", "Tīng Le Zhè Xiē, Wǒ Xiǎng Qǐ Le Yé Ye De Huā Yuán.", "Nghe những điều này, tôi nhớ đến khu vườn của ông."], [77.554, 82.358, "爷爷种的黄瓜和西红柿，也需要蜜蜂帮忙。", "Yé Ye Zhǒng De Huáng Guā Hé Xī Hóng Shì, Yě Xū Yào Mì Fēng Bāng Máng.", "Dưa chuột và cà chua ông trồng cũng cần ong giúp."], [82.358, 88.306, "同学小声说：“真没想到，这些我以前都不知道。”", "Tóng Xué Xiǎo Shēng Shuō: Zhēn Méi Xiǎng Dào, Zhè Xiē Wǒ Yǐ Qián Dōu Bù Zhī Dào.", "Bạn tôi khẽ nói: “Thật không ngờ, mấy điều này trước đây tớ đều không biết.”"], [88.306, 93.733, "电影里还说，现在有的地方蜜蜂比以前少了。", "Diàn Yǐng Lǐ Hái Shuō, Xiàn Zài Yǒu De Dì Fang Mì Fēng Bǐ Yǐ Qián Shǎo Le.", "Trong phim còn nói, bây giờ có nơi ong đã ít hơn trước."], [93.733, 97.746, "因为天气变了，也因为花变少了。", "Yīn Wèi Tiān Qì Biàn Le, Yě Yīn Wèi Huā Biàn Shǎo Le.", "Vì thời tiết thay đổi, cũng vì hoa ít đi."], [97.746, 103.173, "看完以后，我不再觉得蜜蜂只是一种小虫子。", "Kàn Wán Yǐ Hòu, Wǒ Bú Zài Jué De Mì Fēng Zhǐ Shì Yì Zhǒng Xiǎo Chóng Zǐ.", "Xem xong, tôi không còn thấy ong chỉ là một loài côn trùng nhỏ nữa."], [103.173, 107.416, "保护它们，其实也是在保护我们自己。", "Bǎo Hù Tā Men, Qí Shí Yě Shì Zài Bǎo Hù Wǒ Men Zì Jǐ.", "Bảo vệ chúng, thật ra cũng là bảo vệ chính chúng ta."], [107.416, 112.94, "第二天上课的时候，一只蜜蜂从窗户进来了。", "Dì Èr Tiān Shàng Kè De Shí Hou, Yì Zhī Mì Fēng Cóng Chuāng Hu Jìn Lái Le.", "Hôm sau trong giờ học, một con ong bay vào qua cửa sổ."], [112.94, 118.398, "同学们都站起来，有同学说：“快打开窗户！”", "Tóng Xué Men Dōu Zhàn Qǐ Lai, Yǒu Tóng Xué Shuō: Kuài Dǎ Kāi Chuāng Hu!", "Các bạn đều đứng dậy, có bạn nói: “Mau mở cửa sổ ra!”"], [118.398, 123.586, "以前我一定会跑到外面去，现在我没有跑。", "Yǐ Qián Wǒ Yí Dìng Huì Pǎo Dào Wài Miàn Qù, Xiàn Zài Wǒ Méi Yǒu Pǎo.", "Trước đây chắc chắn tôi đã chạy ra ngoài, còn bây giờ tôi không chạy."], [123.586, 129.519, "教室里很安静，我慢慢站起来，把窗户都打开了。", "Jiào Shì Lǐ Hěn Ān Jìng, Wǒ Màn Màn Zhàn Qǐ Lai, Bǎ Chuāng Hu Dōu Dǎ Kāi Le.", "Lớp học rất yên tĩnh, tôi từ từ đứng dậy, mở hết cửa sổ ra."], [129.519, 133.218, "过了一会儿，蜜蜂自己出去了。", "Guò Le Yí Huì Er, Mì Fēng Zì Jǐ Chū Qù Le.", "Một lúc sau, con ong tự bay ra ngoài."], [133.218, 139.462, "老师笑着说：“你们今天做得很对，老师为你们高兴。”", "Lǎo Shī Xiào Zhe Shuō: Nǐ Men Jīn Tiān Zuò De Hěn Duì, Lǎo Shī Wèi Nǐ Men Gāo Xìng.", "Thầy cười nói: “Hôm nay các em làm rất đúng, thầy mừng cho các em.”"], [139.462, 144.01, "我心里很高兴，因为我不再怕它了。", "Wǒ Xīn Lǐ Hěn Gāo Xìng, Yīn Wèi Wǒ Bú Zài Pà Tā Le.", "Trong lòng tôi rất vui, vì tôi không còn sợ nó nữa."], [144.01, 148.742, "看完电影，我把几句话抄在本子上。", "Kàn Wán Diàn Yǐng, Wǒ Bǎ Jǐ Jù Huà Chāo Zài Běn Zi Shàng.", "Xem phim xong, tôi chép vài câu vào vở."], [148.742, 154.18, "其中一句是，小动物也在维持我们的生活。", "Qí Zhōng Yí Jù Shì, Xiǎo Dòng Wù Yě Zài Wéi Chí Wǒ Men De Shēng Huó.", "Một câu trong đó là: động vật nhỏ cũng đang duy trì cuộc sống của chúng ta."], [154.18, 157.712, "我还把电影里的话告诉了爷爷。", "Wǒ Hái Bǎ Diàn Yǐng Lǐ De Huà Gào Su Le Yé Ye.", "Tôi còn kể cho ông nghe những điều trong phim."], [157.712, 165.256, "爷爷高兴地说：“好，好，下次你来，我们一起看看花园里的蜜蜂。”", "Yé Ye Gāo Xìng De Shuō: Hǎo, Hǎo, Xià Cì Nǐ Lái, Wǒ Men Yì Qǐ Kàn Kan Huā Yuán Lǐ De Mì Fēng.", "Ông vui vẻ nói: “Được, được, lần sau cháu đến, ông cháu mình cùng xem ong trong vườn nhé.”"], [165.256, 169.964, "第二天我在食堂少点了一份浪费的菜。", "Dì Èr Tiān Wǒ Zài Shí Táng Shǎo Diǎn Le Yí Fèn Làng Fèi De Cài.", "Hôm sau ở nhà ăn, tôi gọi bớt một phần món dễ bị lãng phí."], [169.964, 174.048, "同学问我：“你今天怎么吃得这么少？”", "Tóng Xué Wèn Wǒ: Nǐ Jīn Tiān Zěn Me Chī De Zhè Me Shǎo?", "Bạn tôi hỏi: “Hôm nay sao cậu ăn ít thế?”"], [174.048, 181.603, "我说：“点多了吃不完，就是浪费。想起蜜蜂，我真的不想浪费了。”", "Wǒ Shuō: Diǎn Duō Le Chī Bù Wán, Jiù Shì Làng Fèi. Xiǎng Qǐ Mì Fēng, Wǒ Zhēn De Bù Xiǎng Làng Fèi Le.", "Tôi nói: “Gọi nhiều ăn không hết là lãng phí. Nghĩ đến ong, tớ thật sự không muốn lãng phí nữa.”"], [181.603, 184.511, "这只是一件很小的事。", "Zhè Zhǐ Shì Yí Jiàn Hěn Xiǎo De Shì.", "Đó chỉ là một việc rất nhỏ."], [184.511, 189.867, "可是我想，改变常常就是从这种小事开始。", "Kě Shì Wǒ Xiǎng, Gǎi Biàn Cháng Cháng Jiù Shì Cóng Zhè Zhǒng Xiǎo Shì Kāi Shǐ.", "Nhưng tôi nghĩ, thay đổi thường bắt đầu từ những việc nhỏ như vậy."], [189.867, 196.087, "从那天起，我吃饭以前先想一想，自己能吃多少。", "Cóng Nà Tiān Qǐ, Wǒ Chī Fàn Yǐ Qián Xiān Xiǎng Yì Xiǎng, Zì Jǐ Néng Chī Duō Shǎo.", "Từ hôm đó, trước khi ăn tôi đều nghĩ trước xem mình ăn được bao nhiêu."], [196.087, 200.202, "一个星期下来，我没有再浪费过菜。", "Yí Gè Xīng Qī Xià Lái, Wǒ Méi Yǒu Zài Làng Fèi Guò Cài.", "Một tuần trôi qua, tôi không lãng phí món ăn nữa."], [200.202, 205.534, "我还在窗户旁边种了小花，每天都看看它。", "Wǒ Hái Zài Chuāng Hu Páng Biān Zhǒng Le Xiǎo Huā, Měi Tiān Dōu Kàn Kan Tā.", "Tôi còn trồng hoa nhỏ bên cửa sổ, ngày nào cũng ngắm nó."], [205.534, 209.374, "我想，花开了，蜜蜂就会来。", "Wǒ Xiǎng, Huā Kāi Le, Mì Fēng Jiù Huì Lái.", "Tôi nghĩ, hoa nở rồi thì ong sẽ đến."], [209.374, 213.506, "妈妈问我：“你怎么开始关心蜜蜂了？”", "Mā Mā Wèn Wǒ: Nǐ Zěn Me Kāi Shǐ Guān Xīn Mì Fēng Le?", "Mẹ hỏi tôi: “Sao con bắt đầu quan tâm đến ong vậy?”"], [213.506, 216.63, "我把纪录片的事告诉了她。", "Wǒ Bǎ Jì Lù Piàn De Shì Gào Su Le Tā.", "Tôi kể cho mẹ nghe chuyện bộ phim tài liệu."], [216.63, 224.072, "她笑着说：“妈妈也这么想！小动物帮了我们，我们也要好好帮它们。”", "Tā Xiào Zhe Shuō: Mā Mā Yě Zhè Me Xiǎng! Xiǎo Dòng Wù Bāng Le Wǒ Men, Wǒ Men Yě Yào Hǎo Hǎo Bāng Tā Men.", "Mẹ cười nói: “Mẹ cũng nghĩ thế! Động vật nhỏ đã giúp chúng ta, chúng ta cũng phải giúp lại chúng thật tốt.”"], [224.072, 228.036, "周末，我和妈妈一起去公园看花。", "Zhōu Mò, Wǒ Hé Mā Mā Yì Qǐ Qù Gōng Yuán Kàn Huā.", "Cuối tuần, tôi cùng mẹ đến công viên ngắm hoa."], [228.036, 232.984, "公园里有很多花，也有很多蜜蜂在忙。", "Gōng Yuán Lǐ Yǒu Hěn Duō Huā, Yě Yǒu Hěn Duō Mì Fēng Zài Máng.", "Trong công viên có rất nhiều hoa, cũng có nhiều ong đang bận rộn."], [232.984, 239.348, "我站在花旁边，听着蜜蜂的声音，看了很久，也没有怕。", "Wǒ Zhàn Zài Huā Páng Biān, Tīng Zhe Mì Fēng De Shēng Yīn, Kàn Le Hěn Jiǔ, Yě Méi Yǒu Pà.", "Tôi đứng bên cạnh hoa, lắng nghe tiếng ong, xem rất lâu mà cũng không sợ."], [239.348, 243.926, "一只蜜蜂来到我的花上，我也没有怕。", "Yì Zhī Mì Fēng Lái Dào Wǒ De Huā Shàng, Wǒ Yě Méi Yǒu Pà.", "Một con ong đến đậu trên bông hoa của tôi, tôi cũng không sợ."], [243.926, 248.778, "回家以后，我在本子上又写了一句话。", "Huí Jiā Yǐ Hòu, Wǒ Zài Běn Zi Shàng Yòu Xiě Le Yí Jù Huà.", "Về đến nhà, tôi lại viết thêm một câu vào vở."], [248.778, 252.494, "那句话是：“谢谢你们，蜜蜂。”", "Nà Jù Huà Shì: Xiè Xie Nǐ Men, Mì Fēng.", "Câu đó là: “Cảm ơn các bạn nhé, ong ơi.”"], [252.494, 256.578, "我还想再看一部同样认真的纪录片。", "Wǒ Hái Xiǎng Zài Kàn Yí Bù Tóng Yàng Rèn Zhēn De Jì Lù Piàn.", "Tôi còn muốn xem thêm một bộ phim tài liệu nghiêm túc như thế."], [256.578, 261.934, "我想看看关于动物的，也想看看关于植物的。", "Wǒ Xiǎng Kàn Kan Guān Yú Dòng Wù De, Yě Xiǎng Kàn Kan Guān Yú Zhí Wù De.", "Tôi muốn xem phim về động vật, cũng muốn xem phim về thực vật."], [261.934, 268.051, "同学笑着说：“下周还有一部，我们还一起看，好吗？”", "Tóng Xué Xiào Zhe Shuō: Xià Zhōu Hái Yǒu Yí Bù, Wǒ Men Hái Yì Qǐ Kàn, Hǎo Ma?", "Bạn tôi cười nói: “Tuần sau còn một bộ nữa, chúng mình lại cùng xem nhé, được không?”"], [268.051, 273.575, "我觉得，一部好电影可以让人改变一点儿小习惯。", "Wǒ Jué De, Yí Bù Hǎo Diàn Yǐng Kě Yǐ Ràng Rén Gǎi Biàn Yì Diǎn Ér Xiǎo Xí Guàn.", "Tôi thấy, một bộ phim hay có thể khiến người ta thay đổi một thói quen nhỏ."], [273.575, 278.283, "我的改变，就是从这部纪录片开始的。", "Wǒ De Gǎi Biàn, Jiù Shì Cóng Zhè Bù Jì Lù Piàn Kāi Shǐ De.", "Sự thay đổi của tôi chính là bắt đầu từ bộ phim tài liệu này."], [278.283, 284.527, "现在再看见蜜蜂，我会先笑一笑，小声说一句谢谢。", "Xiàn Zài Zài Kàn Jiàn Mì Fēng, Wǒ Huì Xiān Xiào Yi Xiào, Xiǎo Shēng Shuō Yí Jù Xiè Xie.", "Bây giờ gặp lại ong, tôi sẽ mỉm cười trước, rồi khẽ nói một câu cảm ơn."]]}, "hsk3-18": {"dur": 310.37, "cues": [[7.105, 12.533, "新学期开始的时候，我给自己写了一个计划。", "Xīn Xué Qī Kāi Shǐ De Shí Hòu, Wǒ Gěi Zì Jǐ Xiě Le Yí Gè Jì Huà.", "Đầu học kỳ mới, tôi viết cho mình một kế hoạch."], [12.533, 17.601, "写计划以前，我先想了想上学期的事。", "Xiě Jì Huà Yǐ Qián, Wǒ Xiān Xiǎng Le Xiǎng Shàng Xué Qī De Shì.", "Trước khi viết kế hoạch, tôi nghĩ lại chuyện học kỳ trước."], [17.601, 23.893, "上学期我常常很晚才写作业，考试以前才复习。", "Shàng Xué Qī Wǒ Cháng Cháng Hěn Wǎn Cái Xiě Zuò Yè, Kǎo Shì Yǐ Qián Cái Fù Xí.", "Học kỳ trước tôi thường làm bài tập rất muộn, đến trước kỳ thi mới ôn."], [23.893, 27.446, "有一次考试，我错了很多。", "Yǒu Yí Cì Kǎo Shì, Wǒ Cuò Le Hěn Duō.", "Có một lần thi, tôi làm sai rất nhiều."], [27.446, 33.546, "老师说：“学习不能没有计划，要从第一天就开始。”", "Lǎo Shī Shuō: Xué Xí Bù Néng Méi Yǒu Jì Huà, Yào Cóng Dì Yī Tiān Jiù Kāi Shǐ.", "Thầy nói: “Học không thể không có kế hoạch, phải bắt đầu từ ngày đầu tiên.”"], [33.546, 37.407, "我听了，觉得老师说得很对。", "Wǒ Tīng Le, Jué De Lǎo Shī Shuō De Hěn Duì.", "Nghe vậy, tôi thấy thầy nói rất đúng."], [37.407, 43.027, "晚上回家，我打开本子，认真写了我的计划。", "Wǎn Shàng Huí Jiā, Wǒ Dǎ Kāi Běn Zi, Rèn Zhēn Xiě Le Wǒ De Jì Huà.", "Tối về nhà, tôi mở vở ra, nghiêm túc viết kế hoạch của mình."], [43.027, 49.439, "每天早上读二十分钟课文，晚上复习当天的生词。", "Měi Tiān Zǎo Shàng Dú Èr Shí Fēn Zhōng Kè Wén, Wǎn Shàng Fù Xí Dāng Tiān De Shēng Cí.", "Mỗi sáng đọc bài khóa hai mươi phút, tối ôn từ mới của ngày hôm đó."], [49.439, 55.035, "周末用一个小时做练习，再检查错在哪里。", "Zhōu Mò Yòng Yí Gè Xiǎo Shí Zuò Liàn Xí, Zài Jiǎn Chá Cuò Zài Nǎ Lǐ.", "Cuối tuần dành một giờ làm bài tập, rồi kiểm tra xem sai ở đâu."], [55.035, 61.788, "我还写了：每个星期天晚上，检查一次这个星期的计划。", "Wǒ Hái Xiě Le: Měi Ge Xīng Qī Tiān Wǎn Shàng, Jiǎn Chá Yí Cì Zhè Ge Xīng Qī De Jì Huà.", "Tôi còn viết: tối Chủ nhật hằng tuần, kiểm tra kế hoạch của tuần này một lần."], [61.788, 68.296, "妈妈看了我的计划，说：“写得很好，可是你能做到吗？”", "Mā Mā Kàn Le Wǒ De Jì Huà, Shuō: Xiě De Hěn Hǎo, Kě Shì Nǐ Néng Zuò Dào Ma?", "Mẹ xem kế hoạch của tôi và nói: “Viết hay đấy, nhưng con làm được không?”"], [68.296, 74.397, "我笑着说：“我先试一个月，您看着吧，我能做到。”", "Wǒ Xiào Zhe Shuō: Wǒ Xiān Shì Yí Gè Yuè, Nín Kàn Zhe Ba, Wǒ Néng Zuò Dào.", "Tôi cười nói: “Con thử một tháng trước, mẹ cứ xem nhé, con làm được mà.”"], [74.397, 78.481, "计划写起来容易，做到却不容易。", "Jì Huà Xiě Qǐ Lái Róng Yì, Zuò Dào Què Bù Róng Yì.", "Viết kế hoạch thì dễ, làm được thì không dễ."], [78.481, 81.869, "第一周，我每天都做到了。", "Dì Yī Zhōu, Wǒ Měi Tiān Dōu Zuò Dào Le.", "Tuần đầu tiên, ngày nào tôi cũng làm được."], [81.869, 88.353, "早上，房间里很安静，我小声读课文，读得很认真。", "Zǎo Shàng, Fáng Jiān Lǐ Hěn Ān Jìng, Wǒ Xiǎo Shēng Dú Kè Wén, Dú De Hěn Rèn Zhēn.", "Buổi sáng, trong phòng rất yên tĩnh, tôi khẽ đọc bài khóa, đọc rất nghiêm túc."], [88.353, 93.781, "晚上复习生词，我把不会的词写在纸上。", "Wǎn Shàng Fù Xí Shēng Cí, Wǒ Bǎ Bú Huì De Cí Xiě Zài Zhǐ Shàng.", "Buổi tối ôn từ mới, tôi viết những từ chưa biết ra giấy."], [93.781, 97.361, "第二周，我开始有点儿累了。", "Dì Èr Zhōu, Wǒ Kāi Shǐ Yǒu Diǎn Ér Lèi Le.", "Tuần thứ hai, tôi bắt đầu hơi mệt."], [97.361, 103.725, "有一天雨下得很大，我回到家已经很晚了，饭都凉了。", "Yǒu Yì Tiān Yǔ Xià De Hěn Dà, Wǒ Huí Dào Jiā Yǐ Jīng Hěn Wǎn Le, Fàn Dōu Liáng Le.", "Có một hôm mưa rất to, tôi về đến nhà đã rất muộn, cơm cũng nguội cả rồi."], [103.725, 108.313, "我想：“今天太累了，明天再复习吧。”", "Wǒ Xiǎng: Jīn Tiān Tài Lèi Le, Míng Tiān Zài Fù Xí Ba.", "Tôi nghĩ: “Hôm nay mệt quá, mai ôn cũng được.”"], [108.313, 114.103, "可是我看了看本子上的计划，还是坐下来复习了。", "Kě Shì Wǒ Kàn Le Kàn Běn Zi Shàng De Jì Huà, Hái Shì Zuò Xia Lái Fù Xí Le.", "Nhưng nhìn lại kế hoạch trong vở, tôi vẫn ngồi xuống ôn bài."], [114.103, 119.939, "有两天我因为太累没有完成，第二天就补上了。", "Yǒu Liǎng Tiān Wǒ Yīn Wèi Tài Lèi Méi Yǒu Wán Chéng, Dì Èr Tiān Jiù Bǔ Shàng Le.", "Có hai ngày vì quá mệt tôi không hoàn thành, hôm sau liền học bù."], [119.939, 126.711, "补上的时候，我告诉自己：“慢一点儿没关系，明天也要做。”", "Bǔ Shàng De Shí Hou, Wǒ Gào Su Zì Jǐ: Màn Yì Diǎn Ér Méi Guān Xì, Míng Tiān Yě Yào Zuò.", "Lúc học bù, tôi tự nhủ: “Chậm một chút không sao, ngày mai vẫn phải làm.”"], [126.711, 131.371, "第三周，老师说星期五有一次考试。", "Dì Sān Zhōu, Lǎo Shī Shuō Xīng Qī Wǔ Yǒu Yí Cì Kǎo Shì.", "Tuần thứ ba, thầy nói thứ Sáu có một bài kiểm tra."], [131.371, 137.039, "我心里有点儿紧张，因为有两个生词我总是忘。", "Wǒ Xīn Lǐ Yǒu Diǎn Ér Jǐn Zhāng, Yīn Wèi Yǒu Liǎng Gè Shēng Cí Wǒ Zǒng Shì Wàng.", "Tôi hơi hồi hộp, vì có hai từ mới tôi cứ hay quên."], [137.039, 142.292, "我把这两个词写在纸条上，放在书包里。", "Wǒ Bǎ Zhè Liǎng Gè Cí Xiě Zài Zhǐ Tiáo Shàng, Fàng Zài Shū Bāo Lǐ.", "Tôi viết hai từ đó lên giấy nhớ, để trong cặp sách."], [142.292, 149.664, "上课以前，我打开书包看一次纸条，下课以后，我再看一次。", "Shàng Kè Yǐ Qián, Wǒ Dǎ Kāi Shū Bāo Kàn Yí Cì Zhǐ Tiáo, Xià Kè Yǐ Hòu, Wǒ Zài Kàn Yí Cì.", "Trước giờ học tôi mở cặp xem giấy nhớ một lần, tan học lại xem một lần nữa."], [149.664, 156.844, "考试的时候，我心里跳得很快，那两个词都出来了，我都会写。", "Kǎo Shì De Shí Hou, Wǒ Xīn Lǐ Tiào De Hěn Kuài, Nà Liǎng Gè Cí Dōu Chū Lái Le, Wǒ Dōu Huì Xiě.", "Lúc thi, tim tôi đập rất nhanh, cả hai từ đó đều xuất hiện, và tôi đều viết được."], [156.844, 160.334, "我的成绩比上次好了一些。", "Wǒ De Chéng Jì Bǐ Shàng Cì Hǎo Le Yì Xiē.", "Điểm của tôi tốt hơn lần trước một chút."], [160.334, 165.642, "一个月下来，我的成绩比上学期稳定多了。", "Yí Gè Yuè Xià Lái, Wǒ De Chéng Jì Bǐ Shàng Xué Qī Wěn Dìng Duō Le.", "Sau một tháng, điểm của tôi ổn định hơn học kỳ trước nhiều."], [165.642, 170.35, "第二个月，我没有再把计划写得太满。", "Dì Èr Gè Yuè, Wǒ Méi Yǒu Zài Bǎ Jì Huà Xiě Dé Tài Mǎn.", "Tháng thứ hai, tôi không viết kế hoạch quá đầy nữa."], [170.35, 174.338, "每天只保留两件必须完成的事。", "Měi Tiān Zhī Bǎo Liú Liǎng Jiàn Bì Xū Wán Chéng De Shì.", "Mỗi ngày chỉ giữ hai việc bắt buộc phải hoàn thành."], [174.338, 178.979, "一件是读课文，一件是复习生词。", "Yí Jiàn Shì Dú Kè Wén, Yí Jiàn Shì Fù Xí Shēng Cí.", "Một việc là đọc bài khóa, một việc là ôn từ mới."], [178.979, 182.775, "做完了，我就在后面打一个钩。", "Zuò Wán Le, Wǒ Jiù Zài Hòu Miàn Dǎ Yí Gè Gōu.", "Làm xong, tôi đánh một dấu tích ở phía sau."], [182.775, 188.515, "看着本子上的钩越来越多，我心里也越来越高兴。", "Kàn Zhe Běn Zi Shàng De Gōu Yuè Lái Yuè Duō, Wǒ Xīn Lǐ Yě Yuè Lái Yuè Gāo Xìng.", "Nhìn dấu tích trong vở ngày càng nhiều, trong lòng tôi cũng ngày càng vui."], [188.515, 192.47, "没做完的，第二天早上先做。", "Méi Zuò Wán De, Dì Èr Tiān Zǎo Shàng Xiān Zuò.", "Việc chưa làm xong thì sáng hôm sau làm trước."], [192.47, 197.874, "朋友叫我去公园玩，我会先做完计划再去。", "Péng Yǒu Jiào Wǒ Qù Gōng Yuán Wán, Wǒ Huì Xiān Zuò Wán Jì Huà Zài Qù.", "Bạn rủ tôi đi công viên chơi, tôi làm xong kế hoạch rồi mới đi."], [197.874, 203.542, "朋友高兴地说：“你的计划真有用，我也想学！”", "Péng Yǒu Gāo Xìng De Shuō: Nǐ De Jì Huà Zhēn Yǒu Yòng, Wǒ Yě Xiǎng Xué!", "Bạn tôi vui vẻ nói: “Kế hoạch của cậu thật hữu ích, tớ cũng muốn học theo!”"], [203.542, 210.326, "我笑着说：“不是计划有用，是每天做一点儿有用，你也可以。”", "Wǒ Xiào Zhe Shuō: Bú Shì Jì Huà Yǒu Yòng, Shì Měi Tiān Zuò Yì Diǎn Ér Yǒu Yòng, Nǐ Yě Kě Yǐ.", "Tôi cười nói: “Không phải kế hoạch hay đâu, mà là mỗi ngày làm một chút mới có ích, cậu cũng làm được mà.”"], [210.326, 214.194, "我还教朋友用我的方法写计划。", "Wǒ Hái Jiāo Péng Yǒu Yòng Wǒ De Fāng Fǎ Xiě Jì Huà.", "Tôi còn dạy bạn cách viết kế hoạch theo phương pháp của tôi."], [214.194, 219.526, "他写得比我还简单，可是他也坚持下来了。", "Tā Xiě De Bǐ Wǒ Hái Jiǎn Dān, Kě Shì Tā Yě Jiān Chí Xià Lái Le.", "Cậu ấy viết còn đơn giản hơn tôi, nhưng cậu ấy cũng kiên trì được."], [219.526, 224.166, "我们约好，每个星期天一起检查一次。", "Wǒ Men Yuē Hǎo, Měi Ge Xīng Qī Tiān Yì Qǐ Jiǎn Chá Yí Cì.", "Chúng tôi hẹn nhau, mỗi Chủ nhật cùng kiểm tra một lần."], [224.166, 230.242, "周末做练习的时候，我发现错的地方比以前少了。", "Zhōu Mò Zuò Liàn Xí De Shí Hou, Wǒ Fā Xiàn Cuò De Dì Fang Bǐ Yǐ Qián Shǎo Le.", "Cuối tuần làm bài tập, tôi thấy chỗ sai ít hơn trước."], [230.242, 236.222, "以前我最怕复习生词，现在觉得复习也不难了。", "Yǐ Qián Wǒ Zuì Pà Fù Xí Shēng Cí, Xiàn Zài Jué De Fù Xí Yě Bù Nán Le.", "Trước đây tôi sợ nhất là ôn từ mới, giờ thấy ôn tập cũng không khó nữa."], [236.222, 243.693, "妈妈高兴地说：“你这个月学习比以前顺利多了，妈妈真为你高兴。”", "Mā Mā Gāo Xìng De Shuō: Nǐ Zhè Ge Yuè Xué Xí Bǐ Yǐ Qián Shùn Lì Duō Le, Mā Mā Zhēn Wèi Nǐ Gāo Xìng.", "Mẹ vui vẻ nói: “Tháng này con học thuận hơn trước nhiều, mẹ thật sự mừng cho con.”"], [243.693, 248.449, "我把用过的计划纸留下来，放在书里。", "Wǒ Bǎ Yòng Guò De Jì Huà Zhǐ Liú Xia Lái, Fàng Zài Shū Lǐ.", "Tôi giữ lại những tờ kế hoạch đã dùng, kẹp trong sách."], [248.449, 253.397, "每次看见它们，我就想起这一个月的事。", "Měi Cì Kàn Jiàn Tā Men, Wǒ Jiù Xiǎng Qǐ Zhè Yí Gè Yuè De Shì.", "Mỗi lần nhìn thấy chúng, tôi lại nhớ chuyện của tháng này."], [253.397, 257.529, "学期中间，老师表扬了我的进步。", "Xué Qī Zhōng Jiān, Lǎo Shī Biǎo Yáng Le Wǒ De Jìn Bù.", "Giữa học kỳ, thầy khen sự tiến bộ của tôi."], [257.529, 262.989, "我知道，这个进步是从每天二十分钟开始的。", "Wǒ Zhī Dào, Zhè Ge Jìn Bù Shì Cóng Měi Tiān Èr Shí Fēn Zhōng Kāi Shǐ De.", "Tôi biết, sự tiến bộ này bắt đầu từ hai mươi phút mỗi ngày."], [262.989, 267.097, "这样我不再因为一次没完成就放弃。", "Zhè Yàng Wǒ Bú Zài Yīn Wèi Yí Cì Méi Wán Chéng Jiù Fàng Qì.", "Như vậy tôi không còn vì một lần chưa hoàn thành mà bỏ cuộc."], [267.097, 273.365, "新的学期，我还想加一件小事：每天写一句话。", "Xīn De Xué Qī, Wǒ Hái Xiǎng Jiā Yí Jiàn Xiǎo Shì: Měi Tiān Xiě Yí Jù Huà.", "Học kỳ mới, tôi muốn thêm một việc nhỏ: mỗi ngày viết một câu."], [273.365, 278.481, "我不写很多，只写一句今天学到的东西。", "Wǒ Bù Xiě Hěn Duō, Zhǐ Xiě Yí Jù Jīn Tiān Xué Dào De Dōng Xi.", "Tôi không viết nhiều, chỉ viết một câu về điều hôm nay học được."], [278.481, 283.492, "我想，小事做久了，也会有大改变。", "Wǒ Xiǎng, Xiǎo Shì Zuò Jiǔ Le, Yě Huì Yǒu Dà Gǎi Biàn.", "Tôi nghĩ, việc nhỏ làm lâu ngày cũng sẽ tạo ra thay đổi lớn."], [283.492, 287.672, "学期结束的时候，这个习惯还在。", "Xué Qī Jié Shù De Shí Hòu, Zhè Ge Xí Guàn Hái Zài.", "Khi học kỳ kết thúc, thói quen này vẫn còn."], [287.672, 294.084, "现在，写计划已经是我每个新学期要做的第一件事了。", "Xiàn Zài, Xiě Jì Huà Yǐ Jīng Shì Wǒ Měi Ge Xīn Xué Qī Yào Zuò De Dì Yī Jiàn Shì Le.", "Bây giờ, viết kế hoạch đã là việc đầu tiên tôi làm mỗi học kỳ mới."], [294.084, 301.792, "妈妈看见我的本子，笑着说：“这么多钩，都是你一天一天做出来的。”", "Mā Mā Kàn Jiàn Wǒ De Běn Zi, Xiào Zhe Shuō: Zhè Me Duō Gōu, Dōu Shì Nǐ Yì Tiān Yì Tiān Zuò Chū Lái De.", "Mẹ nhìn cuốn vở của tôi, cười nói: “Nhiều dấu tích thế này, đều là con làm ra từng ngày từng ngày đấy.”"]]}, "hsk3-19": {"dur": 320.66, "cues": [[7.338, 11.061, "我们楼里的人以前很少打招呼。", "Wǒ Men Lóu Lǐ De Rén Yǐ Qián Hěn Shǎo Dǎ Zhāo Hū.", "Người trong tòa nhà của chúng tôi trước đây rất ít chào hỏi nhau."], [11.061, 16.874, "我住在这栋楼三年了，可是很多邻居我都不认识。", "Wǒ Zhù Zài Zhè Dòng Lóu Sān Nián Le, Kě Shì Hěn Duō Lín Jū Wǒ Dōu Bú Rèn Shi.", "Tôi sống ở tòa nhà này ba năm rồi, nhưng nhiều hàng xóm tôi vẫn không quen."], [16.874, 22.998, "在电梯里见面，大家都看着自己的手机，很少说话。", "Zài Diàn Tī Lǐ Jiàn Miàn, Dà Jiā Dōu Kàn Zhe Zì Jǐ De Shǒu Jī, Hěn Shǎo Shuō Huà.", "Gặp nhau trong thang máy, mọi người đều nhìn vào điện thoại của mình, ít khi nói chuyện."], [22.998, 29.002, "有时候我也想先说一句“你好”，可是心里有点儿紧张。", "Yǒu Shí Hou Wǒ Yě Xiǎng Xiān Shuō Yí Jù Nǐ Hǎo, Kě Shì Xīn Lǐ Yǒu Diǎn Ér Jǐn Zhāng.", "Đôi khi tôi cũng muốn chào “xin chào” trước, nhưng trong lòng hơi hồi hộp."], [29.002, 33.758, "今年春天，居委会组织了一次打扫活动。", "Jīn Nián Chūn Tiān, Jū Wěi Huì Zǔ Zhī Le Yí Cì Dǎ Sǎo Huó Dòng.", "Mùa xuân năm nay, ban quản lý tổ chức một buổi dọn dẹp."], [33.758, 42.258, "妈妈笑着说：“星期六上午，大家一起打扫楼道，你也去吧，妈妈等你一起去。”", "Mā Mā Xiào Zhe Shuō: Xīng Qī Liù Shàng Wǔ, Dà Jiā Yì Qǐ Dǎ Sǎo Lóu Dào, Nǐ Yě Qù Ba, Mā Mā Děng Nǐ Yì Qǐ Qù.", "Mẹ cười nói: “Sáng thứ Bảy mọi người cùng dọn hành lang, con cũng đi nhé, mẹ đợi con đi cùng.”"], [42.258, 47.758, "我一开始不想去，因为星期六我想多睡一会儿。", "Wǒ Yì Kāi Shǐ Bù Xiǎng Qù, Yīn Wèi Xīng Qī Liù Wǒ Xiǎng Duō Shuì Yí Huì Er.", "Ban đầu tôi không muốn đi, vì thứ Bảy tôi muốn ngủ thêm một lúc."], [47.758, 54.474, "妈妈笑着说：“去吧，妈妈相信你，你也可以认识新朋友。”", "Mā Mā Xiào Zhe Shuō: Qù Ba, Mā Mā Xiāng Xìn Nǐ, Nǐ Yě Kě Yǐ Rèn Shi Xīn Péng Yǒu.", "Mẹ cười nói: “Đi đi, mẹ tin con, con cũng có thể quen thêm bạn mới mà.”"], [54.474, 59.768, "大家一起清扫楼道，还在楼下种了几盆花。", "Dà Jiā Yì Qǐ Qīng Sǎo Lóu Dào, Hái Zài Lóu Xià Zhǒng Le Jǐ Pén Huā.", "Mọi người cùng quét dọn hành lang, còn trồng vài chậu hoa ở dưới nhà."], [59.768, 64.068, "干活的时候，我认识了对门的张先生。", "Gàn Huó De Shí Hòu, Wǒ Rèn Shi Le Duì Mén De Zhāng Xiān Shēng.", "Trong lúc làm việc, tôi quen bác Trương ở nhà đối diện."], [64.068, 69.112, "张先生头发花白，说话很慢，人很热情。", "Zhāng Xiān Shēng Tóu Fa Huā Bái, Shuō Huà Hěn Màn, Rén Hěn Rè Qíng.", "Bác Trương tóc hoa râm, nói chậm rãi, người rất nhiệt tình."], [69.112, 74.012, "他和我一起扫楼道，我帮他拿重的箱子。", "Tā Hé Wǒ Yì Qǐ Sǎo Lóu Dào, Wǒ Bāng Tā Ná Zhòng De Xiāng Zi.", "Bác cùng tôi quét hành lang, tôi giúp bác cầm chiếc thùng nặng."], [74.012, 79.319, "我们一边干活一边聊天，很快就不紧张了。", "Wǒ Men Yì Biān Gàn Huó Yì Biān Liáo Tiān, Hěn Kuài Jiù Bù Jǐn Zhāng Le.", "Chúng tôi vừa làm vừa trò chuyện, rất nhanh đã hết hồi hộp."], [79.319, 85.731, "王奶奶也来了，她笑着带了水和几个刚做好的包子给大家。", "Wáng Nǎi Nai Yě Lái Le, Tā Xiào Zhe Dài Le Shuǐ Hé Jǐ Ge Gāng Zuò Hǎo De Bāo Zi Gěi Dà Jiā.", "Bà Vương cũng đến, bà cười mang nước và mấy chiếc bánh bao vừa làm xong cho mọi người."], [85.731, 92.648, "她笑着说：“大家先休息一下，吃一点儿东西再干，别太累了。”", "Tā Xiào Zhe Shuō: Dà Jiā Xiān Xiū Xi Yí Xià, Chī Yì Diǎn Ér Dōng Xi Zài Gàn, Bié Tài Lèi Le.", "Bà cười nói: “Mọi người nghỉ một lát, ăn chút gì rồi làm tiếp, đừng mệt quá nhé.”"], [92.648, 97.044, "那天上午，楼道比以前干净了很多。", "Nà Tiān Shàng Wǔ, Lóu Dào Bǐ Yǐ Qián Gān Jìng Le Hěn Duō.", "Sáng hôm đó, hành lang sạch hơn trước rất nhiều."], [97.044, 102.256, "现在见面都会笑一笑，有时也互相帮忙。", "Xiàn Zài Jiàn Miàn Dōu Huì Xiào Yi Xiào, Yǒu Shí Yě Hù Xiāng Bāng Máng.", "Bây giờ gặp nhau đều mỉm cười, thỉnh thoảng còn giúp đỡ lẫn nhau."], [102.256, 107.392, "我觉得，关系常常是从一件小事开始的。", "Wǒ Jué De, Guān Xì Cháng Cháng Shì Cóng Yí Jiàn Xiǎo Shì Kāi Shǐ De.", "Tôi thấy, quan hệ thường bắt đầu từ một việc nhỏ."], [107.392, 112.484, "有一天晚上，我看电视的时候声音太大了。", "Yǒu Yì Tiān Wǎn Shàng, Wǒ Kàn Diàn Shì De Shí Hou Shēng Yīn Tài Dà Le.", "Một tối nọ, lúc xem ti vi tôi mở tiếng quá to."], [112.484, 121.069, "张先生站在我家门口，小声说：“孩子，电视的声音有点儿大，我睡不着了。”", "Zhāng Xiān Shēng Zhàn Zài Wǒ Jiā Mén Kǒu, Xiǎo Shēng Shuō: Hái Zi, Diàn Shì De Shēng Yīn Yǒu Diǎn Ér Dà, Wǒ Shuì Bù Zháo Le.", "Bác Trương đứng ở cửa nhà tôi, khẽ nói: “Cháu ơi, tiếng ti vi hơi to, bác không ngủ được.”"], [121.069, 128.201, "我马上把声音关小，不好意思地说：“对不起，我以后一定注意。”", "Wǒ Mǎ Shàng Bǎ Shēng Yīn Guān Xiǎo, Bù Hǎo Yì Si De Shuō: Duì Bu Qǐ, Wǒ Yǐ Hòu Yí Dìng Zhù Yì.", "Tôi lập tức vặn nhỏ tiếng, áy náy nói: “Cháu xin lỗi, sau này cháu nhất định sẽ chú ý.”"], [128.201, 132.909, "他笑着说：“没关系，谢谢你理解。”", "Tā Xiào Zhe Shuō: Méi Guān Xì, Xiè Xie Nǐ Lǐ Jiě.", "Bác cười nói: “Không sao, cảm ơn cháu đã hiểu.”"], [132.909, 138.169, "从那天起，我晚上看电视都先关好门。", "Cóng Nà Tiān Qǐ, Wǒ Wǎn Shàng Kàn Diàn Shì Dōu Xiān Guān Hǎo Mén.", "Từ hôm đó, tối xem ti vi tôi đều đóng cửa cẩn thận trước."], [138.169, 144.103, "我发现，多为别人想一想，大家就少了很多麻烦。", "Wǒ Fā Xiàn, Duō Wèi Bié Ren Xiǎng Yì Xiǎng, Dà Jiā Jiù Shǎo Le Hěn Duō Má Fan.", "Tôi nhận ra, nghĩ cho người khác nhiều hơn một chút thì mọi người sẽ bớt nhiều phiền phức."], [144.103, 148.499, "张先生后来还教我修了一个坏掉的灯。", "Zhāng Xiān Shēng Hòu Lái Hái Jiào Wǒ Xiū Le Yí Gè Huài Diào De Dēng.", "Sau đó bác Trương còn dạy tôi sửa một chiếc đèn bị hỏng."], [148.499, 154.935, "那天晚上，我家的灯坏了，我不会修，心里很着急。", "Nà Tiān Wǎn Shàng, Wǒ Jiā De Dēng Huài Le, Wǒ Bú Huì Xiū, Xīn Lǐ Hěn Zháo Jí.", "Tối hôm đó, đèn nhà tôi hỏng, tôi không biết sửa, trong lòng rất sốt ruột."], [154.935, 160.291, "张先生拿着工具来我家，十分钟就修完了。", "Zhāng Xiān Shēng Ná Zhe Gōng Jù Lái Wǒ Jiā, Shí Fēn Zhōng Jiù Xiū Wán Le.", "Bác Trương mang dụng cụ đến nhà tôi, mười phút là sửa xong."], [160.291, 166.696, "我高兴地说：“谢谢您！您教得真好，下次我自己就会了。”", "Wǒ Gāo Xìng De Shuō: Xiè Xie Nín! Nín Jiāo De Zhēn Hǎo, Xià Cì Wǒ Zì Jǐ Jiù Huì Le.", "Tôi vui vẻ nói: “Cảm ơn bác! Bác dạy hay thật, lần sau cháu tự làm được rồi.”"], [166.696, 170.204, "我也帮他把重箱子抬上了楼。", "Wǒ Yě Bāng Tā Bǎ Zhòng Xiāng Zǐ Tái Shàng Le Lóu.", "Tôi cũng giúp bác khiêng chiếc thùng nặng lên tầng."], [170.204, 175.032, "我们休息了两次，才把箱子抬到他家。", "Wǒ Men Xiū Xi Le Liǎng Cì, Cái Bǎ Xiāng Zi Tái Dào Tā Jiā.", "Chúng tôi nghỉ hai lần mới khiêng được chiếc thùng đến nhà bác."], [175.032, 180.916, "他请我喝了一杯茶，还给我看了他年轻时候的照片。", "Tā Qǐng Wǒ Hē Le Yì Bēi Chá, Huán Gěi Wǒ Kàn Le Tā Nián Qīng Shí Hou De Zhào Piàn.", "Bác mời tôi uống một tách trà, còn cho tôi xem ảnh thời trẻ của bác."], [180.916, 186.503, "照片里的张先生站在学校门口，笑得很高兴。", "Zhào Piàn Lǐ De Zhāng Xiān Shēng Zhàn Zài Xué Xiào Mén Kǒu, Xiào De Hěn Gāo Xìng.", "Trong ảnh, bác Trương đứng ở cổng trường, cười rất vui."], [186.503, 189.435, "楼道里的花现在开了。", "Lóu Dào Lǐ De Huā Xiàn Zài Kāi Le.", "Hoa trong hành lang bây giờ đã nở."], [189.435, 192.295, "每天出门都能看见。", "Měi Tiān Chū Mén Dōu Néng Kàn Jiàn.", "Mỗi ngày ra khỏi nhà đều nhìn thấy."], [192.295, 197.363, "王奶奶每天早上都来看花，给花一点儿水。", "Wáng Nǎi Nai Měi Tiān Zǎo Shàng Dōu Lái Kàn Huā, Gěi Huā Yì Diǎn Ér Shuǐ.", "Bà Vương mỗi sáng đều đến ngắm hoa, cho hoa một chút nước."], [197.363, 202.983, "有时候我起得早，也和她一起照顾花，说说话。", "Yǒu Shí Hou Wǒ Qǐ De Zǎo, Yě Hé Tā Yì Qǐ Zhào Gù Huā, Shuō Shuō Huà.", "Đôi khi tôi dậy sớm, cũng cùng bà chăm hoa, trò chuyện đôi câu."], [202.983, 210.326, "她说：“花和人一样，我们关心它，它慢慢就长大了，也开花了。”", "Tā Shuō: Huā Hé Rén Yí Yàng, Wǒ Men Guān Xīn Tā, Tā Màn Màn Jiù Zhǎng Dà Le, Yě Kāi Huā Le.", "Bà nói: “Hoa cũng như người, chúng ta quan tâm nó thì nó sẽ từ từ lớn lên, và cũng nở hoa.”"], [210.326, 214.626, "大家见面会说一句今天天气不错。", "Dà Jiā Jiàn Miàn Huì Shuō Yí Jù Jīn Tiān Tiān Qì Bú Cuò.", "Mọi người gặp nhau sẽ nói một câu: hôm nay thời tiết đẹp."], [214.626, 219.382, "有时候还会多说几句孩子和工作的事。", "Yǒu Shí Hou Hái Huì Duō Shuō Jǐ Jù Hái Zi Hé Gōng Zuò De Shì.", "Đôi khi còn nói thêm vài câu chuyện con cái và công việc."], [219.382, 223.97, "上个星期，我出门的时候忘了带伞。", "Shàng Gè Xīng Qī, Wǒ Chū Mén De Shí Hou Wàng Le Dài Sǎn.", "Tuần trước, lúc ra ngoài tôi quên mang ô."], [223.97, 229.638, "天突然下起了大雨，我站在楼下等雨小一点儿。", "Tiān Tū Rán Xià Qǐ Le Dà Yǔ, Wǒ Zhàn Zài Lóu Xià Děng Yǔ Xiǎo Yì Diǎn Ér.", "Trời bỗng đổ mưa to, tôi đứng dưới nhà đợi mưa nhỏ bớt."], [229.638, 237.447, "王奶奶看见了，笑着说：“我的伞你先用吧，明天再还我，别着急。”", "Wáng Nǎi Nai Kàn Jiàn Le, Xiào Zhe Shuō: Wǒ De Sǎn Nǐ Xiān Yòng Ba, Míng Tiān Zài Huán Wǒ, Bié Zháo Jí.", "Bà Vương nhìn thấy, cười nói: “Ô của bà cháu cứ dùng trước đi, mai trả bà cũng được, đừng sốt ruột.”"], [237.447, 242.443, "第二天我把伞还给她，还送给她一些花。", "Dì Èr Tiān Wǒ Bǎ Sǎn Huán Gěi Tā, Hái Sòng Gěi Tā Yì Xiē Huā.", "Hôm sau tôi trả ô cho bà, còn tặng bà ít hoa."], [242.443, 248.895, "她高兴地说：“花真好看，谢谢你，我会好好照顾的。”", "Tā Gāo Xìng De Shuō: Huā Zhēn Hǎo Kàn, Xiè Xie Nǐ, Wǒ Huì Hǎo Hǎo Zhào Gù De.", "Bà vui vẻ nói: “Hoa đẹp thật, cảm ơn cháu, bà sẽ chăm sóc nó cẩn thận.”"], [248.895, 254.683, "现在，谁家做了好吃的菜，都会给邻居送一点儿。", "Xiàn Zài, Shéi Jiā Zuò Le Hǎo Chī De Cài, Dōu Huì Gěi Lín Jū Sòng Yì Diǎn Ér.", "Bây giờ, nhà ai nấu món ngon cũng mang cho hàng xóm một ít."], [254.683, 259.535, "张先生做了饺子，会先给我们送一碗。", "Zhāng Xiān Shēng Zuò Le Jiǎo Zi, Huì Xiān Gěi Wǒ Men Sòng Yì Wǎn.", "Bác Trương làm sủi cảo, sẽ mang cho nhà tôi một bát trước."], [259.535, 264.891, "妈妈做了西红柿鸡蛋，也会分一点儿给王奶奶。", "Mā Mā Zuò Le Xī Hóng Shì Jī Dàn, Yě Huì Fēn Yì Diǎn Ér Gěi Wáng Nǎi Nai.", "Mẹ làm món cà chua trứng, cũng chia cho bà Vương một ít."], [264.891, 270.768, "楼里的孩子们也认识了，下课以后一起在楼下玩。", "Lóu Lǐ De Hái Zi Men Yě Rèn Shi Le, Xià Kè Yǐ Hòu Yì Qǐ Zài Lóu Xià Wán.", "Trẻ con trong tòa nhà cũng quen nhau, tan học cùng chơi dưới nhà."], [270.768, 277.276, "以前安静的楼道，现在常常能听见大家说话和笑的声音。", "Yǐ Qián Ān Jìng De Lóu Dào, Xiàn Zài Cháng Cháng Néng Tīng Jiàn Dà Jiā Shuō Huà Hé Xiào De Shēng Yīn.", "Hành lang vốn yên tĩnh, giờ thường nghe thấy tiếng mọi người nói chuyện và tiếng cười."], [277.276, 280.592, "我觉得这栋楼比以前温暖。", "Wǒ Jué De Zhè Dòng Lóu Bǐ Yǐ Qián Wēn Nuǎn.", "Tôi thấy tòa nhà này ấm áp hơn trước."], [280.592, 287.324, "我也明白了，邻居不是住在旁边的人，是可以互相帮忙的朋友。", "Wǒ Yě Míng Bai Le, Lín Jū Bú Shì Zhù Zài Páng Biān De Rén, Shì Kě Yǐ Hù Xiāng Bāng Máng De Péng Yǒu.", "Tôi cũng hiểu ra, hàng xóm không chỉ là người ở bên cạnh, mà là bạn bè có thể giúp đỡ lẫn nhau."], [287.324, 292.44, "下个春天，我们还想在楼下再种一些花。", "Xià Ge Chūn Tiān, Wǒ Men Hái Xiǎng Zài Lóu Xià Zài Zhǒng Yì Xiē Huā.", "Mùa xuân tới, chúng tôi muốn trồng thêm ít hoa dưới nhà."], [292.44, 298.036, "我想报名参加居委会的活动，下次我还要去。", "Wǒ Xiǎng Bào Míng Cān Jiā Jū Wěi Huì De Huó Dòng, Xià Cì Wǒ Hái Yào Qù.", "Tôi muốn đăng ký tham gia hoạt động của ban quản lý, lần sau tôi vẫn sẽ đi."], [298.036, 304.592, "因为我知道，温暖的楼，是从大家的一件件小事开始的。", "Yīn Wèi Wǒ Zhī Dào, Wēn Nuǎn De Lóu, Shì Cóng Dà Jiā De Yí Jiàn Jiàn Xiǎo Shì Kāi Shǐ De.", "Vì tôi biết, một tòa nhà ấm áp bắt đầu từ từng việc nhỏ của mọi người."], [304.592, 312.104, "王奶奶看着楼下的花，笑着说：“花开了，我们这栋楼，也像家了。”", "Wáng Nǎi Nai Kàn Zhe Lóu Xià De Huā, Xiào Zhe Shuō: Huā Kāi Le, Wǒ Men Zhè Dòng Lóu, Yě Xiàng Jiā Le.", "Bà Vương nhìn hoa dưới nhà, cười nói: “Hoa nở rồi, tòa nhà của chúng ta cũng giống như nhà rồi.”"]]}, "hsk3-20": {"dur": 333.96, "cues": [[6.804, 11.583, "快毕业的时候，我不知道该学什么专业。", "Kuài Bì Yè De Shí Hòu, Wǒ Bù Zhī Dào Gāi Xué Shén Me Zhuān Yè.", "Lúc sắp tốt nghiệp, tôi không biết nên học ngành gì."], [11.583, 16.484, "我上高中的时候，每天都在想这件事。", "Wǒ Shàng Gāo Zhōng De Shí Hòu, Měi Tiān Dōu Zài Xiǎng Zhè Jiàn Shì.", "Lúc tôi học cấp ba, ngày nào cũng nghĩ về việc này."], [16.484, 21.36, "同学们有的想当医生，有的想当老师。", "Tóng Xué Men Yǒu De Xiǎng Dāng Yī Shēng, Yǒu De Xiǎng Dāng Lǎo Shī.", "Các bạn, có người muốn làm bác sĩ, có người muốn làm giáo viên."], [21.36, 25.078, "我问自己：“我最喜欢做什么？”", "Wǒ Wèn Zì Jǐ: Wǒ Zuì Xǐ Huan Zuò Shén Me?", "Tôi tự hỏi mình: “Mình thích làm gì nhất?”"], [25.078, 30.914, "父母希望我学经济，我自己对新闻更有兴趣。", "Fù Mǔ Xī Wàng Wǒ Xué Jīng Jì, Wǒ Zì Jǐ Duì Xīn Wén Gèng Yǒu Xìng Qù.", "Bố mẹ mong tôi học kinh tế, còn tôi lại hứng thú với báo chí hơn."], [30.914, 37.854, "爸爸说：“学经济，以后工作好找，爸爸是怕你以后太累。”", "Bà Ba Shuō: Xué Jīng Jì, Yǐ Hòu Gōng Zuò Hǎo Zhǎo, Bà Ba Shì Pà Nǐ Yǐ Hòu Tài Lèi.", "Bố nói: “Học kinh tế, sau này dễ tìm việc, bố là sợ con sau này vất vả quá.”"], [37.854, 44.866, "妈妈拉着我的手说：“我们都是为你好，你慢慢想，妈妈不急。”", "Mā Mā Lā Zhe Wǒ De Shǒu Shuō: Wǒ Men Dōu Shì Wèi Nǐ Hǎo, Nǐ Màn Màn Xiǎng, Mā Mā Bù Jí.", "Mẹ nắm tay tôi nói: “Bố mẹ đều vì tốt cho con, con cứ từ từ nghĩ, mẹ không vội đâu.”"], [44.866, 49.334, "我没有马上回答，因为我心里也不清楚。", "Wǒ Méi Yǒu Mǎ Shàng Huí Dá, Yīn Wèi Wǒ Xīn Lǐ Yě Bù Qīng Chu.", "Tôi không trả lời ngay, vì trong lòng tôi cũng chưa rõ."], [49.334, 56.773, "有几个晚上，房间里很安静，我想这件事，想了很久也睡不着。", "Yǒu Jǐ Ge Wǎn Shàng, Fáng Jiān Lǐ Hěn Ān Jìng, Wǒ Xiǎng Zhè Jiàn Shì, Xiǎng Le Hěn Jiǔ Yě Shuì Bù Zháo.", "Mấy buổi tối, trong phòng rất yên tĩnh, tôi nghĩ về việc này, nghĩ rất lâu mà vẫn không ngủ được."], [56.773, 62.489, "我去问了两位老师，也跟已经工作的学长聊天。", "Wǒ Qù Wèn Le Liǎng Wèi Lǎo Shī, Yě Gēn Yǐ Jīng Gōng Zuò De Xué Zhǎng Liáo Tiān.", "Tôi đi hỏi hai thầy giáo, cũng trò chuyện với anh khóa trên đã đi làm."], [62.489, 69.477, "老师笑着说：“先别急，慢慢来，你可以多了解几个专业。”", "Lǎo Shī Xiào Zhe Shuō: Xiān Bié Jí, Màn Màn Lái, Nǐ Kě Yǐ Duō Liǎo Jiě Jǐ Ge Zhuān Yè.", "Thầy cười nói: “Đừng vội, cứ từ từ, em có thể tìm hiểu thêm vài ngành.”"], [69.477, 77.641, "学长笑着说：“每天工作的时间很长，所以要选自己喜欢的，想清楚啊。”", "Xué Zhǎng Xiào Zhe Shuō: Měi Tiān Gōng Zuò De Shí Jiān Hěn Cháng, Suǒ Yǐ Yào Xuǎn Zì Jǐ Xǐ Huan De, Xiǎng Qīng Chu A.", "Anh khóa trên cười nói: “Thời gian làm việc mỗi ngày rất dài, nên phải chọn việc mình thích, nghĩ cho rõ nhé.”"], [77.641, 83.615, "他们都说，兴趣重要，可是也要了解真实的工作。", "Tā Men Dōu Shuō, Xìng Qù Zhòng Yào, Kě Shì Yě Yào Liǎo Jiě Zhēn Shí De Gōng Zuò.", "Họ đều nói, sở thích quan trọng, nhưng cũng phải hiểu công việc thực tế."], [83.615, 88.779, "回家以后，我把两个专业都写在本子上。", "Huí Jiā Yǐ Hòu, Wǒ Bǎ Liǎng Gè Zhuān Yè Dōu Xiě Zài Běn Zi Shàng.", "Về nhà, tôi viết cả hai ngành vào vở."], [88.779, 94.879, "我在经济下面写了“工作多”，在新闻下面写了“喜欢”。", "Wǒ Zài Jīng Jì Xià Miàn Xiě Le Gōng Zuò Duō, Zài Xīn Wén Xià Miàn Xiě Le Xǐ Huan.", "Dưới ngành kinh tế tôi viết “nhiều việc làm”, dưới ngành báo chí tôi viết “thích”."], [94.879, 99.149, "看着这个本子，我还是不知道怎么选。", "Kàn Zhe Zhè Ge Běn Zi, Wǒ Hái Shì Bù Zhī Dào Zěn Me Xuǎn.", "Nhìn cuốn vở đó, tôi vẫn không biết nên chọn thế nào."], [99.149, 105.561, "我到报社实习了两个星期，发现自己确实喜欢写报道。", "Wǒ Dào Bào Shè Shí Xí Le Liǎng Gè Xīng Qī, Fā Xiàn Zì Jǐ Què Shí Xǐ Huan Xiě Bào Dào.", "Tôi đến tòa soạn thực tập hai tuần, nhận ra mình thật sự thích viết tin bài."], [105.561, 109.549, "第一天，编辑带我认识了办公室。", "Dì Yī Tiān, Biān Jí Dài Wǒ Rèn Shi Le Bàn Gōng Shì.", "Ngày đầu tiên, biên tập viên dẫn tôi làm quen với văn phòng."], [109.549, 116.518, "他笑着说：“别急，写报道以前，要先去看看真实的事。”", "Tā Xiào Zhe Shuō: Bié Jí, Xiě Bào Dào Yǐ Qián, Yào Xiān Qù Kàn Kan Zhēn Shí De Shì.", "Anh ấy cười nói: “Đừng vội, trước khi viết bài phải đi xem việc thật trước đã.”"], [116.518, 121.754, "实习的两个星期里，我每天写一篇短报道。", "Shí Xí De Liǎng Gè Xīng Qī Lǐ, Wǒ Měi Tiān Xiě Yì Piān Duǎn Bào Dào.", "Trong hai tuần thực tập, mỗi ngày tôi viết một bài tin ngắn."], [121.754, 126.414, "第一次写得太长，编辑让我删掉一半。", "Dì Yī Cì Xiě Dé Tài Cháng, Biān Jí Ràng Wǒ Shān Diào Yí Bàn.", "Lần đầu tôi viết quá dài, biên tập viên bảo tôi cắt bỏ một nửa."], [126.414, 130.891, "他说读者要先看见最重要的事实。", "Tā Shuō Dú Zhě Yào Xiān Kàn Jiàn Zuì Zhòng Yào De Shì Shí.", "Anh ấy nói người đọc phải nhìn thấy sự thật quan trọng nhất trước."], [130.891, 134.039, "我改了三遍，才通过。", "Wǒ Gǎi Le Sān Biàn, Cái Tōng Guò.", "Tôi sửa ba lần mới được duyệt."], [134.039, 141.131, "那三遍，我一句话一句话地改，改得很慢，可是学到了很多。", "Nà Sān Biàn, Wǒ Yí Jù Huà Yí Jù Huà De Gǎi, Gǎi De Hěn Màn, Kě Shì Xué Dào Le Hěn Duō.", "Ba lần sửa đó, tôi sửa từng câu từng câu một, sửa rất chậm, nhưng học được rất nhiều."], [141.131, 145.551, "第二个星期，我跟编辑去了一个学校。", "Dì Èr Gè Xīng Qī, Wǒ Gēn Biān Jí Qù Le Yí Gè Xué Xiào.", "Tuần thứ hai, tôi đi cùng biên tập viên đến một trường học."], [145.551, 151.219, "我们听一位老师说学校的事，我一边听一边记。", "Wǒ Men Tīng Yí Wèi Lǎo Shī Shuō Xué Xiào De Shì, Wǒ Yì Biān Tīng Yì Biān Jì.", "Chúng tôi nghe một thầy giáo kể chuyện của trường, tôi vừa nghe vừa ghi."], [151.219, 156.804, "回来以后，我写得比第一次快，也比第一次短。", "Huí Lái Yǐ Hòu, Wǒ Xiě De Bǐ Dì Yī Cì Kuài, Yě Bǐ Dì Yī Cì Duǎn.", "Trở về, tôi viết nhanh hơn lần đầu, cũng ngắn hơn lần đầu."], [156.804, 163.936, "编辑笑着说：“这次不错！写得比第一次好多了，明天可以更好。”", "Biān Jí Xiào Zhe Shuō: Zhè Cì Bù Cuò! Xiě De Bǐ Dì Yī Cì Hǎo Duō Le, Míng Tiān Kě Yǐ Gèng Hǎo.", "Biên tập viên cười nói: “Lần này khá lắm! Viết tốt hơn lần đầu nhiều rồi, ngày mai còn có thể tốt hơn.”"], [163.936, 168.308, "实习快结束的时候，我有点儿不想走。", "Shí Xí Kuài Jié Shù De Shí Hou, Wǒ Yǒu Diǎn Ér Bù Xiǎng Zǒu.", "Khi kỳ thực tập sắp kết thúc, tôi hơi không muốn ra về."], [168.308, 173.453, "因为我发现，写报道的时候我一点儿也不累。", "Yīn Wèi Wǒ Fā Xiàn, Xiě Bào Dào De Shí Hou Wǒ Yì Diǎn Ér Yě Bú Lèi.", "Vì tôi nhận ra, lúc viết bài tôi chẳng mệt chút nào."], [173.453, 178.833, "父母看到那篇报道，终于理解了我的兴趣。", "Fù Mǔ Kàn Dào Nà Piān Bào Dào, Zhōng Yú Lǐ Jiě Le Wǒ De Xìng Qù.", "Bố mẹ xem bài báo đó, cuối cùng đã hiểu sở thích của tôi."], [178.833, 185.797, "妈妈高兴地说：“这篇写得真清楚，妈妈都看懂了，为你高兴！”", "Mā Mā Gāo Xìng De Shuō: Zhè Piān Xiě De Zhēn Qīng Chu, Mā Mā Dōu Kàn Dǒng Le, Wèi Nǐ Gāo Xìng!", "Mẹ vui vẻ nói: “Bài này viết rõ ràng thật, mẹ đọc hiểu hết, mẹ mừng cho con!”"], [185.797, 192.377, "爸爸没有说话，他坐在灯下，把那篇报道慢慢看了两遍。", "Bà Ba Méi Yǒu Shuō Huà, Tā Zuò Zài Dēng Xià, Bǎ Nà Piān Bào Dào Màn Màn Kàn Le Liǎng Biàn.", "Bố không nói gì, ông ngồi dưới ánh đèn, chậm rãi đọc bài báo đó hai lần."], [192.377, 200.249, "爸爸慢慢地说：“好，爸爸看了两遍，你写得很认真，爸爸为你高兴。”", "Bà Ba Màn Màn De Shuō: Hǎo, Bà Ba Kàn Le Liǎng Biàn, Nǐ Xiě De Hěn Rèn Zhēn, Bà Ba Wèi Nǐ Gāo Xìng.", "Bố chậm rãi nói: “Được, bố đã đọc hai lần, con viết rất nghiêm túc, bố mừng cho con.”"], [200.249, 206.349, "最后我和父母好好谈了一次，他们支持我的选择。", "Zuì Hòu Wǒ Hé Fù Mǔ Hǎo Hǎo Tán Le Yí Cì, Tā Men Zhī Chí Wǒ De Xuǎn Zé.", "Cuối cùng tôi nói chuyện kỹ với bố mẹ một lần, họ ủng hộ lựa chọn của tôi."], [206.349, 211.417, "我们谈了一个晚上，把心里的担心都说了。", "Wǒ Men Tán Le Yí Gè Wǎn Shàng, Bǎ Xīn Lǐ De Dān Xīn Dōu Shuō Le.", "Chúng tôi nói chuyện cả một buổi tối, nói hết những lo lắng trong lòng."], [211.417, 218.709, "妈妈笑着说：“学新闻也可以，妈妈支持你，可是你要认真学。”", "Mā Mā Xiào Zhe Shuō: Xué Xīn Wén Yě Kě Yǐ, Mā Mā Zhī Chí Nǐ, Kě Shì Nǐ Yào Rèn Zhēn Xué.", "Mẹ cười nói: “Học báo chí cũng được, mẹ ủng hộ con, nhưng con phải học nghiêm túc nhé.”"], [218.709, 225.841, "我高兴地说：“我会认真学，也会多看一点儿经济的书，谢谢你们。”", "Wǒ Gāo Xìng De Shuō: Wǒ Huì Rèn Zhēn Xué, Yě Huì Duō Kàn Yì Diǎn Ér Jīng Jì De Shū, Xiè Xie Nǐ Men.", "Tôi vui vẻ nói: “Con sẽ học nghiêm túc, cũng sẽ đọc thêm sách về kinh tế, cảm ơn bố mẹ.”"], [225.841, 232.408, "爸爸笑着说：“路是你自己的，我们支持你，也相信你。”", "Bà Ba Xiào Zhe Shuō: Lù Shì Nǐ Zì Jǐ De, Wǒ Men Zhī Chí Nǐ, Yě Xiāng Xìn Nǐ.", "Bố cười nói: “Con đường là của con, bố mẹ ủng hộ con, cũng tin con.”"], [232.408, 236.324, "听了这句话，我晚上睡得很好。", "Tīng Le Zhè Jù Huà, Wǒ Wǎn Shàng Shuì De Hěn Hǎo.", "Nghe câu đó, tối hôm ấy tôi ngủ rất ngon."], [236.324, 241.162, "第二天，我决定了：大学学新闻专业。", "Dì Èr Tiān, Wǒ Jué Dìng Le: Dà Xué Xué Xīn Wén Zhuān Yè.", "Hôm sau, tôi quyết định: lên đại học sẽ học ngành báo chí."], [241.162, 245.174, "我把这个决定告诉了老师和学长。", "Wǒ Bǎ Zhè Ge Jué Dìng Gào Su Le Lǎo Shī Hé Xué Zhǎng.", "Tôi báo quyết định này cho thầy và anh khóa trên."], [245.174, 252.81, "老师笑着说：“太好了！有兴趣很好，还要写一个计划，慢慢来。”", "Lǎo Shī Xiào Zhe Shuō: Tài Hǎo Le! Yǒu Xìng Qù Hěn Hǎo, Hái Yào Xiě Yí Gè Jì Huà, Màn Màn Lái.", "Thầy cười nói: “Tốt quá! Có sở thích thì tốt, còn phải viết một kế hoạch nữa, cứ từ từ.”"], [252.81, 259.462, "我给自己写了一个计划：多读书，多写，多出去看看。", "Wǒ Gěi Zì Jǐ Xiě Le Yí Gè Jì Huà: Duō Dú Shū, Duō Xiě, Duō Chū Qù Kàn Kan.", "Tôi viết cho mình một kế hoạch: đọc sách nhiều, viết nhiều, ra ngoài xem nhiều."], [259.462, 266.913, "学长笑着说：“真为你高兴！以后工作了，也不要忘了今天的想法。”", "Xué Zhǎng Xiào Zhe Shuō: Zhēn Wèi Nǐ Gāo Xìng! Yǐ Hòu Gōng Zuò Le, Yě Bú Yào Wàng Le Jīn Tiān De Xiǎng Fǎ.", "Anh khóa trên cười nói: “Thật mừng cho em! Sau này đi làm, đừng quên suy nghĩ của ngày hôm nay nhé.”"], [266.913, 271.741, "我把那篇改了三遍的报道留在本子里。", "Wǒ Bǎ Nà Piān Gǎi Le Sān Biàn De Bào Dào Liú Zài Běn Zi Lǐ.", "Tôi giữ bài báo sửa ba lần đó trong cuốn vở."], [271.741, 277.107, "每次看见它，我就想起实习的那两个星期。", "Měi Cì Kàn Jiàn Tā, Wǒ Jiù Xiǎng Qǐ Shí Xí De Nà Liǎng Gè Xīng Qī.", "Mỗi lần nhìn thấy nó, tôi lại nhớ hai tuần thực tập ấy."], [277.107, 282.175, "现在我更确定，自己想继续走这条路。", "Xiàn Zài Wǒ Gèng Què Dìng, Zì Jǐ Xiǎng Jì Xù Zǒu Zhè Tiáo Lù.", "Bây giờ tôi càng chắc chắn, mình muốn tiếp tục đi con đường này."], [282.175, 286.379, "我知道，这条路不会每天都容易。", "Wǒ Zhī Dào, Zhè Tiáo Lù Bú Huì Měi Tiān Dōu Róng Yì.", "Tôi biết, con đường này sẽ không ngày nào cũng dễ dàng."], [286.379, 290.691, "可是我喜欢，我就愿意一直走下去。", "Kě Shì Wǒ Xǐ Huan, Wǒ Jiù Yuàn Yì Yì Zhí Zǒu Xià Qù.", "Nhưng tôi thích, nên tôi sẵn lòng đi tiếp mãi."], [290.691, 295.831, "上大学的第一天，爸爸送我到学校门口。", "Shàng Dà Xué De Dì Yī Tiān, Bà Ba Sòng Wǒ Dào Xué Xiào Mén Kǒu.", "Ngày đầu tiên vào đại học, bố đưa tôi đến cổng trường."], [295.831, 303.059, "他笑着说：“好好学，我们在家等你的新报道，爸爸为你高兴。”", "Tā Xiào Zhe Shuō: Hǎo Hǎo Xué, Wǒ Men Zài Jiā Děng Nǐ De Xīn Bào Dào, Bà Ba Wèi Nǐ Gāo Xìng.", "Bố cười nói: “Học cho tốt nhé, bố mẹ ở nhà chờ bài báo mới của con, bố mừng cho con.”"], [303.059, 311.287, "我笑着说：“好！我的第一篇报道，先写我们学校，写好了先给你们看。”", "Wǒ Xiào Zhe Shuō: Hǎo! Wǒ De Dì Yī Piān Bào Dào, Xiān Xiě Wǒ Men Xué Xiào, Xiě Hǎo Le Xiān Gěi Nǐ Men Kàn.", "Tôi cười nói: “Vâng! Bài báo đầu tiên của con sẽ viết về trường mình trước, viết xong con cho bố mẹ xem đầu tiên.”"], [311.287, 318.491, "我想，这样的生活就是我想要的：做喜欢的事，认真地做下去。", "Wǒ Xiǎng, Zhè Yàng De Shēng Huó Jiù Shì Wǒ Xiǎng Yào De: Zuò Xǐ Huan De Shì, Rèn Zhēn De Zuò Xià Qù.", "Tôi nghĩ, cuộc sống như vậy chính là điều tôi muốn: làm việc mình thích, và nghiêm túc làm mãi."], [318.491, 325.311, "那天晚上，我在本子上写了一句话：我选了自己喜欢的路。", "Nà Tiān Wǎn Shàng, Wǒ Zài Běn Zi Shàng Xiě Le Yí Jù Huà: Wǒ Xuǎn Le Zì Jǐ Xǐ Huan De Lù.", "Tối hôm đó, tôi viết vào vở một câu: Tôi đã chọn con đường mình yêu thích."]]}, "hsk3-21": {"dur": 312.22, "cues": [[7.338, 12.742, "同学告诉我，他上个星期坐高铁去看了爷爷。", "Tóng Xué Gào Su Wǒ, Tā Shàng Ge Xīng Qī Zuò Gāo Tiě Qù Kàn Le Yé Ye.", "Bạn học kể với tôi rằng tuần trước bạn ấy đi tàu cao tốc thăm ông."], [12.742, 18.434, "他说高铁很快，三个小时就到了，还很舒服。", "Tā Shuō Gāo Tiě Hěn Kuài, Sān Gè Xiǎo Shí Jiù Dào Le, Hái Hěn Shū Fu.", "Bạn ấy nói tàu cao tốc rất nhanh, ba tiếng là đến nơi, lại rất thoải mái."], [18.434, 23.313, "我听了以后，心里很想自己也试一试。", "Wǒ Tīng Le Yǐ Hòu, Xīn Lǐ Hěn Xiǎng Zì Jǐ Yě Shì Yi Shì.", "Nghe xong, trong lòng tôi rất muốn tự mình thử một lần."], [23.313, 29.101, "我回家问妈妈，这个周末我们能不能也坐一次高铁。", "Wǒ Huí Jiā Wèn Mā Ma, Zhè Ge Zhōu Mò Wǒ Men Néng Bù Néng Yě Zuò Yí Cì Gāo Tiě.", "Về nhà tôi hỏi mẹ, cuối tuần này nhà mình có thể đi tàu cao tốc một lần không."], [29.101, 35.828, "妈妈笑着说：好，妈妈也想去，我们坐高铁去看叔叔。", "Mā Ma Xiào Zhe Shuō: Hǎo, Mā Ma Yě Xiǎng Qù, Wǒ Men Zuò Gāo Tiě Qù Kàn Shū Shu.", "Mẹ cười nói: Được, mẹ cũng muốn đi, nhà mình đi tàu cao tốc thăm chú nhé."], [35.828, 41.04, "上个周末，我第一次坐高铁去另一个城市。", "Shàng Ge Zhōu Mò, Wǒ Dì Yī Cì Zuò Gāo Tiě Qù Lìng Yí Gè Chéng Shì.", "Cuối tuần trước, lần đầu tôi đi tàu cao tốc sang thành phố khác."], [41.04, 46.3, "那天早上，我六点就醒了，很快洗了脸。", "Nà Tiān Zǎo Shàng, Wǒ Liù Diǎn Jiù Xǐng Le, Hěn Kuài Xǐ Le Liǎn.", "Sáng hôm đó tôi sáu giờ đã tỉnh, rửa mặt thật nhanh."], [46.3, 51.848, "我吃完早饭，又看了一次书包，怕忘记车票。", "Wǒ Chī Wán Zǎo Fàn, Yòu Kàn Le Yí Cì Shū Bāo, Pà Wàng Jì Chē Piào.", "Ăn sáng xong, tôi lại kiểm tra cặp một lần, sợ quên vé tàu."], [51.848, 57.794, "妈妈笑着说：不着急，慢慢来，我们的时间很多。", "Mā Ma Xiào Zhe Shuō: Bù Zhāo Jí, Màn Man Lái, Wǒ Men De Shí Jiān Hěn Duō.", "Mẹ cười nói: Đừng vội, cứ từ từ, nhà mình còn nhiều thời gian."], [57.794, 62.911, "妈妈陪我去车站，教我怎么买票和找座位。", "Mā Ma Péi Wǒ Qù Chē Zhàn, Jiāo Wǒ Zěn Me Mǎi Piào Hé Zhǎo Zuò Wèi.", "Mẹ đi cùng tôi đến ga, dạy tôi cách mua vé và tìm chỗ ngồi."], [62.911, 66.562, "车站很大，里面的人也很多。", "Chē Zhàn Hěn Dà, Lǐ Miàn De Rén Yě Hěn Duō.", "Nhà ga rất lớn, người bên trong cũng rất đông."], [66.562, 70.767, "我跟在妈妈后面，心里有一点儿紧张。", "Wǒ Gēn Zài Mā Ma Hòu Miàn, Xīn Lǐ Yǒu Yì Diǎn Ér Jǐn Zhāng.", "Tôi đi theo sau mẹ, trong lòng hơi căng thẳng."], [70.767, 74.861, "买票的时候，前面有很多人在等。", "Mǎi Piào De Shí Hou, Qián Miàn Yǒu Hěn Duō Rén Zài Děng.", "Lúc mua vé, phía trước có rất nhiều người đang đợi."], [74.861, 78.465, "我问妈妈：我们的车几点开？", "Wǒ Wèn Mā Ma: Wǒ Men De Chē Jǐ Diǎn Kāi?", "Tôi hỏi mẹ: Tàu của nhà mình mấy giờ chạy?"], [78.465, 84.109, "妈妈看了看车票，说：九点，还有二十分钟。", "Mā Ma Kàn Le Kàn Chē Piào, Shuō: Jiǔ Diǎn, Hái Yǒu Èr Shí Fēn Zhōng.", "Mẹ nhìn vé rồi nói: Chín giờ, còn hai mươi phút nữa."], [84.109, 92.345, "等车的时候，我站在窗户旁边，听着车站里的声音，看外面的车来来去去。", "Děng Chē De Shí Hou, Wǒ Zhàn Zài Chuāng Hu Páng Biān, Tīng Zhe Chē Zhàn Lǐ De Shēng Yīn, Kàn Wài Miàn De Chē Lái Lái Qù Qù.", "Lúc đợi tàu, tôi đứng cạnh cửa sổ, lắng nghe âm thanh trong ga, nhìn xe cộ qua lại bên ngoài."], [92.345, 96.573, "一辆高铁慢慢开进来，声音很小。", "Yí Liàng Gāo Tiě Màn Man Kāi Jìn Lái, Shēng Yīn Hěn Xiǎo.", "Một đoàn tàu cao tốc từ từ chạy vào, tiếng rất nhỏ."], [96.573, 102.4, "妈妈笑着说：看，这就是我们的车，快上车吧。", "Mā Ma Xiào Zhe Shuō: Kàn, Zhè Jiù Shì Wǒ Men De Chē, Kuài Shàng Chē Ba.", "Mẹ cười nói: Nhìn kìa, đây chính là tàu của nhà mình, lên tàu nhanh nào."], [102.4, 107.636, "上车以后，我拿着车票，慢慢找我的座位。", "Shàng Chē Yǐ Hòu, Wǒ Ná Zhe Chē Piào, Màn Man Zhǎo Wǒ De Zuò Wèi.", "Lên tàu rồi, tôi cầm vé, từ từ tìm chỗ ngồi của mình."], [107.636, 112.44, "我的座位是七号，妈妈的座位是八号。", "Wǒ De Zuò Wèi Shì Qī Hào, Mā Ma De Zuò Wèi Shì Bā Hào.", "Ghế của tôi là số bảy, ghế của mẹ là số tám."], [112.44, 118.084, "可是我太高兴了，走过了七号，坐到了九号。", "Kě Shì Wǒ Tài Gāo Xìng Le, Zǒu Guò Le Qī Hào, Zuò Dào Le Jiǔ Hào.", "Nhưng tôi vui quá, đi qua số bảy, ngồi xuống số chín."], [118.084, 123.416, "旁边的人笑着说：你坐错了，这是九号。", "Páng Biān De Rén Xiào Zhe Shuō: Nǐ Zuò Cuò Le, Zhè Shì Jiǔ Hào.", "Người bên cạnh cười nói: Cháu ngồi nhầm rồi, đây là số chín."], [123.416, 129.405, "我马上站起来，说：对不起，我这就去找七号。", "Wǒ Mǎ Shàng Zhàn Qǐ Lái, Shuō: Duì Bù Qǐ, Wǒ Zhè Jiù Qù Zhǎo Qī Hào.", "Tôi lập tức đứng dậy, nói: Xin lỗi ạ, cháu đi tìm số bảy ngay đây."], [129.405, 134.641, "妈妈帮我找到了七号，我坐在了窗户旁边。", "Mā Ma Bāng Wǒ Zhǎo Dào Le Qī Hào, Wǒ Zuò Zài Le Chuāng Hu Páng Biān.", "Mẹ giúp tôi tìm được số bảy, tôi ngồi xuống cạnh cửa sổ."], [134.641, 140.573, "车开得很快，可是车里很安静，我觉得很舒服。", "Chē Kāi Dé Hěn Kuài, Kě Shì Chē Lǐ Hěn Ān Jìng, Wǒ Jué De Hěn Shū Fu.", "Tàu chạy rất nhanh nhưng trong toa rất yên tĩnh, tôi thấy rất thoải mái."], [140.573, 145.929, "我坐在靠窗的位置，看见外面的山和田野。", "Wǒ Zuò Zài Kào Chuāng De Wèi Zhi, Kàn Jiàn Wài Miàn De Shān Hé Tián Yě.", "Tôi ngồi cạnh cửa sổ, nhìn thấy núi và ruộng bên ngoài."], [145.929, 152.005, "外面还有很多小房子，房子旁边开着很多好看的花。", "Wài Miàn Hái Yǒu Hěn Duō Xiǎo Fáng Zi, Fáng Zi Páng Biān Kāi Zhe Hěn Duō Hǎo Kàn De Huā.", "Bên ngoài còn nhiều ngôi nhà nhỏ, bên nhà nở nhiều hoa đẹp."], [152.005, 156.977, "我问妈妈：车为什么这么快，还这么安静？", "Wǒ Wèn Mā Ma: Chē Wèi Shén Me Zhè Me Kuài, Hái Zhè Me Ān Jìng?", "Tôi hỏi mẹ: Sao tàu nhanh thế mà vẫn yên tĩnh thế ạ?"], [156.977, 164.095, "妈妈笑着说：对，高铁就是这样，又快又安全，坐着很舒服。", "Mā Ma Xiào Zhe Shuō: Duì, Gāo Tiě Jiù Shì Zhè Yàng, Yòu Kuài Yòu Ān Quán, Zuò Zhe Hěn Shū Fu.", "Mẹ cười nói: Đúng vậy, tàu cao tốc là như thế đấy, vừa nhanh vừa an toàn, ngồi rất thoải mái."], [164.095, 168.563, "我喝了一口水，又看了看外面的山。", "Wǒ Hē Le Yì Kǒu Shuǐ, Yòu Kàn Le Kàn Wài Miàn De Shān.", "Tôi uống một ngụm nước, rồi lại nhìn núi bên ngoài."], [168.563, 175.623, "旁边的人在安静地看书，看得很认真，我也想像他一样安静。", "Páng Biān De Rén Zài Ān Jìng De Kàn Shū, Kàn Dé Hěn Rèn Zhēn, Wǒ Yě Xiǎng Xiàng Tā Yí Yàng Ān Jìng.", "Người bên cạnh đang yên lặng đọc sách, đọc rất chăm chú, tôi cũng muốn yên tĩnh như anh ấy."], [175.623, 179.107, "我也拿出我的书，看了一会儿。", "Wǒ Yě Ná Chū Wǒ De Shū, Kàn Le Yí Huì Er.", "Tôi cũng lấy sách của mình ra, đọc một lúc."], [179.107, 184.343, "看了一会儿，我觉得有点儿累，就睡了一会儿。", "Kàn Le Yí Huì Er, Wǒ Jué De Yǒu Diǎn Ér Lèi, Jiù Shuì Le Yí Huì Er.", "Đọc một lúc, tôi thấy hơi mệt, nên ngủ một lát."], [184.343, 190.587, "我醒来的时候，妈妈说：快到了，收拾好你的书包。", "Wǒ Xǐng Lái De Shí Hou, Mā Ma Shuō: Kuài Dào Le, Shōu Shi Hǎo Nǐ De Shū Bāo.", "Khi tôi tỉnh dậy, mẹ nói: Sắp đến rồi, thu dọn cặp của con đi."], [190.587, 194.143, "不到三个小时，我们就到了。", "Bú Dào Sān Gè Xiǎo Shí, Wǒ Men Jiù Dào Le.", "Chưa đầy ba tiếng, chúng tôi đã đến nơi."], [194.143, 200.226, "下车的时候人很多，我拉着妈妈的手，慢慢往前走。", "Xià Chē De Shí Hou Rén Hěn Duō, Wǒ Lā Zhe Mā Ma De Shǒu, Màn Man Wǎng Qián Zǒu.", "Lúc xuống tàu người rất đông, tôi nắm tay mẹ, từ từ đi về phía trước."], [200.226, 205.03, "叔叔在出口等我们，还给我们带了水。", "Shū Shu Zài Chū Kǒu Děng Wǒ Men, Hái Gěi Wǒ Men Dài Le Shuǐ.", "Chú đợi chúng tôi ở lối ra và mang nước cho chúng tôi."], [205.03, 209.906, "叔叔问我：第一次坐高铁，你怕不怕？", "Shū Shu Wèn Wǒ: Dì Yī Cì Zuò Gāo Tiě, Nǐ Pà Bú Pà?", "Chú hỏi tôi: Lần đầu đi tàu cao tốc, cháu có sợ không?"], [209.906, 215.76, "我笑着说：不怕，我很喜欢，下次我还要坐。", "Wǒ Xiào Zhe Shuō: Bú Pà, Wǒ Hěn Xǐ Huan, Xià Cì Wǒ Hái Yào Zuò.", "Tôi cười nói: Không sợ ạ, cháu rất thích, lần sau cháu vẫn muốn đi nữa."], [215.76, 221.236, "叔叔带我们去他家，他们一路上一直在说话。", "Shū Shu Dài Wǒ Men Qù Tā Jiā, Tā Men Yí Lù Shàng Yì Zhí Zài Shuō Huà.", "Chú đưa chúng tôi về nhà chú, họ nói chuyện suốt dọc đường."], [221.236, 226.836, "在叔叔家，我吃了很多菜，还喝了他做的汤。", "Zài Shū Shu Jiā, Wǒ Chī Le Hěn Duō Cài, Hái Hē Le Tā Zuò De Tāng.", "Ở nhà chú, tôi ăn nhiều món, còn uống canh chú nấu."], [226.836, 233.512, "下午，叔叔带我去他家附近走走，给我讲这个城市的故事。", "Xià Wǔ, Shū Shu Dài Wǒ Qù Tā Jiā Fù Jìn Zǒu Zou, Gěi Wǒ Jiǎng Zhè Ge Chéng Shì De Gù Shi.", "Buổi chiều, chú đưa tôi đi dạo gần nhà, kể cho tôi nghe chuyện về thành phố này."], [233.512, 239.119, "我觉得这个城市不大，可是很安静，也很舒服。", "Wǒ Jué De Zhè Ge Chéng Shì Bú Dà, Kě Shì Hěn Ān Jìng, Yě Hěn Shū Fu.", "Tôi thấy thành phố này không lớn, nhưng rất yên tĩnh và thoải mái."], [239.119, 245.203, "晚上回来的时候，天已经晚了，车站的人还是很多。", "Wǎn Shàng Huí Lái De Shí Hou, Tiān Yǐ Jīng Wǎn Le, Chē Zhàn De Rén Hái Shì Hěn Duō.", "Buổi tối lúc quay về, trời đã muộn, người ở ga vẫn rất đông."], [245.203, 250.079, "回来的路上，我自己去取票，没有走错。", "Huí Lái De Lù Shàng, Wǒ Zì Jǐ Qù Qǔ Piào, Méi Yǒu Zǒu Cuò.", "Trên đường về, tôi tự đi lấy vé và không đi nhầm."], [250.079, 255.651, "这次妈妈没有帮我，她站在后面，看我自己做。", "Zhè Cì Mā Ma Méi Yǒu Bāng Wǒ, Tā Zhàn Zài Hòu Miàn, Kàn Wǒ Zì Jǐ Zuò.", "Lần này mẹ không giúp tôi, mẹ đứng phía sau, nhìn tôi tự làm."], [255.651, 260.551, "我先看车票上的时间，再去找我的座位。", "Wǒ Xiān Kàn Chē Piào Shàng De Shí Jiān, Zài Qù Zhǎo Wǒ De Zuò Wèi.", "Tôi xem giờ trên vé trước, rồi đi tìm chỗ ngồi của mình."], [260.551, 266.078, "我高兴地说：妈妈，我会了，我自己找到了！", "Wǒ Gāo Xìng De Shuō: Mā Ma, Wǒ Huì Le, Wǒ Zì Jǐ Zhǎo Dào Le!", "Tìm được chỗ rồi, tôi vui vẻ nói: Mẹ ơi, con biết làm rồi, con tự tìm được rồi!"], [266.078, 270.304, "妈妈说我长大了，可以自己坐车了。", "Mā Ma Shuō Wǒ Zhǎng Dà Le, Kě Yǐ Zì Jǐ Zuò Chē Le.", "Mẹ nói tôi đã lớn, có thể tự đi tàu."], [270.304, 274.676, "我想以后假期也可以坐高铁去看奶奶。", "Wǒ Xiǎng Yǐ Hòu Jià Qī Yě Kě Yǐ Zuò Gāo Tiě Qù Kàn Nǎi Nai.", "Tôi muốn sau này kỳ nghỉ cũng đi tàu cao tốc thăm bà."], [274.676, 279.359, "这次旅行让我知道了高铁又方便又安全。", "Zhè Cì Lǚ Xíng Ràng Wǒ Zhī Dào Le Gāo Tiě Yòu Fāng Biàn Yòu Ān Quán.", "Chuyến đi này giúp tôi biết tàu cao tốc vừa tiện vừa an toàn."], [279.359, 283.371, "我回到家，把这件事告诉了爸爸。", "Wǒ Huí Dào Jiā, Bǎ Zhè Jiàn Shì Gào Su Le Bà Ba.", "Về đến nhà, tôi kể chuyện này cho bố nghe."], [283.371, 289.646, "爸爸听了很高兴，说：好，下次我们全家一起去。", "Bà Ba Tīng Le Hěn Gāo Xìng, Shuō: Hǎo, Xià Cì Wǒ Men Quán Jiā Yì Qǐ Qù.", "Bố nghe xong rất vui, nói: Tốt, lần sau cả nhà mình cùng đi nhé."], [289.646, 294.282, "我还把车票留作纪念，放在书包里。", "Wǒ Hái Bǎ Chē Piào Liú Zuò Jì Niàn, Fàng Zài Shū Bāo Lǐ.", "Tôi còn giữ vé làm kỷ niệm, để trong cặp."], [294.282, 298.03, "我希望明年还能再坐一次高铁。", "Wǒ Xī Wàng Míng Nián Hái Néng Zài Zuò Yí Cì Gāo Tiě.", "Tôi hy vọng năm sau lại được đi tàu cao tốc một lần nữa."], [298.03, 303.578, "妈妈笑着说：以后你想去哪儿，妈妈都陪你去。", "Mā Ma Xiào Zhe Shuō: Yǐ Hòu Nǐ Xiǎng Qù Nǎ Ér, Mā Ma Dōu Péi Nǐ Qù.", "Mẹ cười nói: Sau này con muốn đi đâu, mẹ đều đi cùng con."]]}, "hsk3-22": {"dur": 288.42, "cues": [[8.011, 14.135, "有一天，老师问我们：你们每天早上几点起床？", "Yǒu Yì Tiān, Lǎo Shī Wèn Wǒ Men: Nǐ Men Měi Tiān Zǎo Shàng Jǐ Diǎn Qǐ Chuáng?", "Một hôm, cô giáo hỏi chúng tôi: Mỗi sáng các em dậy lúc mấy giờ?"], [14.135, 20.427, "同学们有的说七点，有的说六点，还有的说五点半。", "Tóng Xué Men Yǒu De Shuō Qī Diǎn, Yǒu De Shuō Liù Diǎn, Hái Yǒu De Shuō Wǔ Diǎn Bàn.", "Các bạn có bạn nói bảy giờ, có bạn nói sáu giờ, có bạn còn nói năm rưỡi."], [20.427, 26.122, "我听了以后，心里想：只有我一个人起得最晚。", "Wǒ Tīng Le Yǐ Hòu, Xīn Lǐ Xiǎng: Zhǐ Yǒu Wǒ Yí Gè Rén Qǐ Dé Zuì Wǎn.", "Nghe xong, tôi nghĩ trong lòng: Chỉ có mình là dậy muộn nhất."], [26.122, 31.55, "以前我每天睡到八点，常常来不及吃早饭。", "Yǐ Qián Wǒ Měi Tiān Shuì Dào Bā Diǎn, Cháng Cháng Lái Bù Jí Chī Zǎo Fàn.", "Trước đây tôi ngủ đến tám giờ, thường không kịp ăn sáng."], [31.55, 36.835, "因为起得晚，我去学校的时候总是很着急。", "Yīn Wèi Qǐ Dé Wǎn, Wǒ Qù Xué Xiào De Shí Hou Zǒng Shì Hěn Zhāo Jí.", "Vì dậy muộn, lúc đi học tôi lúc nào cũng vội vàng."], [36.835, 41.633, "有时候我跑到学校，上课已经开始了。", "Yǒu Shí Hou Wǒ Pǎo Dào Xué Xiào, Shàng Kè Yǐ Jīng Kāi Shǐ Le.", "Có lúc tôi chạy đến trường thì giờ học đã bắt đầu rồi."], [41.633, 47.733, "老师笑着说：你要是早一点儿起，就不会这么着急了。", "Lǎo Shī Xiào Zhe Shuō: Nǐ Yào Shì Zǎo Yì Diǎn Ér Qǐ, Jiù Bú Huì Zhè Me Zhāo Jí Le.", "Cô giáo cười nói: Nếu em dậy sớm hơn một chút thì sẽ không vội như thế nữa."], [47.733, 52.081, "那天回家，我把这件事告诉了爸爸。", "Nà Tiān Huí Jiā, Wǒ Bǎ Zhè Jiàn Shì Gào Su Le Bà Ba.", "Hôm đó về nhà, tôi kể chuyện này cho bố nghe."], [52.081, 57.629, "爸爸说早起对身体好，问我愿不愿试一试。", "Bà Ba Shuō Zǎo Qǐ Duì Shēn Tǐ Hǎo, Wèn Wǒ Yuàn Bù Yuàn Shì Yi Shì.", "Bố nói dậy sớm tốt cho sức khỏe và hỏi tôi có muốn thử không."], [57.629, 65.132, "我想了想，高兴地说：好，我从明天开始，跟爸爸一起试一试。", "Wǒ Xiǎng Le Xiǎng, Gāo Xìng De Shuō: Hǎo, Wǒ Cóng Míng Tiān Kāi Shǐ, Gēn Bà Ba Yì Qǐ Shì Yi Shì.", "Tôi nghĩ một lúc, vui vẻ nói: Vâng, con sẽ bắt đầu từ ngày mai, cùng bố thử ạ."], [65.132, 69.312, "那天晚上，我把闹钟定在六点半。", "Nà Tiān Wǎn Shàng, Wǒ Bǎ Nào Zhōng Dìng Zài Liù Diǎn Bàn.", "Tối hôm đó tôi đặt báo thức lúc sáu rưỡi."], [69.312, 74.476, "我还把书包放在门口，明天起来就能走。", "Wǒ Hái Bǎ Shū Bāo Fàng Zài Mén Kǒu, Míng Tiān Qǐ Lái Jiù Néng Zǒu.", "Tôi còn để cặp ở cửa, sáng mai dậy là đi được ngay."], [74.476, 81.944, "第二天，闹钟六点半就响了，响得很急，好像在叫我快起来。", "Dì Èr Tiān, Nào Zhōng Liù Diǎn Bàn Jiù Xiǎng Le, Xiǎng Dé Hěn Jí, Hǎo Xiàng Zài Jiào Wǒ Kuài Qǐ Lái.", "Ngày thứ hai, đồng hồ báo thức sáu rưỡi đã reo, reo rất gấp, như đang gọi tôi dậy nhanh lên."], [81.944, 85.812, "第一天很难，我很想再睡一会儿。", "Dì Yī Tiān Hěn Nán, Wǒ Hěn Xiǎng Zài Shuì Yí Huì Er.", "Ngày đầu rất khó, tôi muốn ngủ thêm một lát."], [85.812, 90.836, "我对自己说：再睡五分钟，就五分钟。", "Wǒ Duì Zì Jǐ Shuō: Zài Shuì Wǔ Fēn Zhōng, Jiù Wǔ Fēn Zhōng.", "Tôi tự nhủ: Ngủ thêm năm phút thôi, chỉ năm phút thôi."], [90.836, 95.304, "可是我想起老师的话，还是慢慢起来了。", "Kě Shì Wǒ Xiǎng Qǐ Lǎo Shī De Huà, Hái Shì Màn Man Qǐ Lái Le.", "Nhưng tôi nhớ lời cô giáo, vẫn từ từ dậy."], [95.304, 99.892, "爸爸已经起来做早饭，屋里有了香味。", "Bà Ba Yǐ Jīng Qǐ Lái Zuò Zǎo Fàn, Wū Lǐ Yǒu Le Xiāng Wèi.", "Bố đã dậy nấu sáng, trong nhà có mùi thơm."], [99.892, 106.712, "爸爸看见我，笑着说：你今天起得真早，爸爸太高兴了。", "Bà Ba Kàn Jiàn Wǒ, Xiào Zhe Shuō: Nǐ Jīn Tiān Qǐ Dé Zhēn Zǎo, Bà Ba Tài Gāo Xìng Le.", "Bố thấy tôi, cười nói: Hôm nay con dậy sớm thật đấy, bố vui lắm."], [106.712, 111.293, "我洗完脸，觉得头脑比以前清楚多了。", "Wǒ Xǐ Wán Liǎn, Jué De Tóu Nǎo Bǐ Yǐ Qián Qīng Chu Duō Le.", "Tôi rửa mặt xong thấy đầu óc tỉnh hơn trước nhiều."], [111.293, 115.857, "那天我慢慢吃完早饭，一点儿也不着急。", "Nà Tiān Wǒ Màn Man Chī Wán Zǎo Fàn, Yì Diǎn Ér Yě Bù Zhāo Jí.", "Hôm đó tôi ăn sáng thong thả, chẳng vội chút nào."], [115.857, 122.253, "第二天和第三天，还是很难，我有时候真想放弃。", "Dì Èr Tiān Hé Dì Sān Tiān, Hái Shì Hěn Nán, Wǒ Yǒu Shí Hou Zhēn Xiǎng Fàng Qì.", "Ngày thứ hai và thứ ba vẫn rất khó, có lúc tôi thật sự muốn bỏ cuộc."], [122.253, 129.121, "第四天早上，外面下起了大雨，雨声很大，屋里也很冷。", "Dì Sì Tiān Zǎo Shàng, Wài Miàn Xià Qǐ Le Dà Yǔ, Yǔ Shēng Hěn Dà, Wū Lǐ Yě Hěn Lěng.", "Sáng ngày thứ tư, bên ngoài mưa to, tiếng mưa rất lớn, trong nhà cũng rất lạnh."], [129.121, 133.91, "我想：今天下雨，就多睡一会儿吧。", "Wǒ Xiǎng: Jīn Tiān Xià Yǔ, Jiù Duō Shuì Yí Huì Er Ba.", "Tôi nghĩ: Hôm nay mưa, ngủ thêm một lát vậy."], [133.91, 140.13, "爸爸走过来说：爸爸相信你，难的时候更要坚持。", "Bà Ba Zǒu Guò Lái Shuō: Bà Ba Xiāng Xìn Nǐ, Nán De Shí Hou Gèng Yào Jiān Chí.", "Bố đi tới nói: Bố tin con, lúc khó càng phải kiên trì."], [140.13, 146.1, "听了爸爸的话，我还是起来了，还帮爸爸做了早饭。", "Tīng Le Bà Ba De Huà, Wǒ Hái Shì Qǐ Lái Le, Hái Bāng Bà Ba Zuò Le Zǎo Fàn.", "Nghe lời bố, tôi vẫn dậy, còn giúp bố làm bữa sáng."], [146.1, 152.486, "那天我到学校的时候，雨已经小了，我的心里很高兴。", "Nà Tiān Wǒ Dào Xué Xiào De Shí Hou, Yǔ Yǐ Jīng Xiǎo Le, Wǒ De Xīn Lǐ Hěn Gāo Xìng.", "Hôm đó khi tôi đến trường, mưa đã nhỏ lại, trong lòng tôi rất vui."], [152.486, 156.81, "一个星期以后，我慢慢习惯了早起。", "Yí Gè Xīng Qī Yǐ Hòu, Wǒ Màn Màn Xí Guàn Le Zǎo Qǐ.", "Sau một tuần tôi dần quen dậy sớm."], [156.81, 161.75, "每天早上我会先喝水，然后收拾书包。", "Měi Tiān Zǎo Shàng Wǒ Huì Xiān Hē Shuǐ, Rán Hòu Shōu Shi Shū Bāo.", "Mỗi sáng tôi uống nước trước, rồi xếp cặp sách."], [161.75, 167.01, "起来以后，我还跟爸爸一起在楼下走一走。", "Qǐ Lái Yǐ Hòu, Wǒ Hái Gēn Bà Ba Yì Qǐ Zài Lóu Xià Zǒu Yi Zǒu.", "Dậy rồi, tôi còn cùng bố đi dạo dưới nhà một vòng."], [167.01, 175.612, "早上的空气很好，人也很少，很安静，爸爸和我慢慢走着，心里很舒服。", "Zǎo Shàng De Kōng Qì Hěn Hǎo, Rén Yě Hěn Shǎo, Hěn Ān Jìng, Bà Ba Hé Wǒ Màn Man Zǒu Zhe, Xīn Lǐ Hěn Shū Fu.", "Không khí buổi sáng rất tốt, người qua lại cũng ít, rất yên tĩnh, bố con tôi thong thả đi, trong lòng rất thoải mái."], [175.612, 179.961, "到学校以前，我还有时间读课文。", "Dào Xué Xiào Yǐ Qián, Wǒ Hái Yǒu Shí Jiān Dú Kè Wén.", "Trước khi đến trường tôi còn thời gian đọc bài."], [179.961, 186.037, "我读课文的时候，同学问我：你最近怎么来得这么早？", "Wǒ Dú Kè Wén De Shí Hou, Tóng Xué Wèn Wǒ: Nǐ Zuì Jìn Zěn Me Lái Dé Zhè Me Zǎo?", "Lúc tôi đọc bài, bạn học hỏi tôi: Dạo này sao cậu đến sớm thế?"], [186.037, 194.537, "我笑着说：因为我开始早起了，早上还能多读一会儿书，我觉得早起真好。", "Wǒ Xiào Zhe Shuō: Yīn Wèi Wǒ Kāi Shǐ Zǎo Qǐ Le, Zǎo Shàng Hái Néng Duō Dú Yí Huì Er Shū, Wǒ Jué De Zǎo Qǐ Zhēn Hǎo.", "Tôi cười nói: Vì tớ bắt đầu dậy sớm rồi, buổi sáng còn đọc thêm được một lúc sách, tớ thấy dậy sớm thật tốt."], [194.537, 198.261, "老师表扬我早晨精神很好。", "Lǎo Shī Biǎo Yáng Wǒ Zǎo Chén Jīng Shén Hěn Hǎo.", "Cô giáo khen buổi sáng tôi rất tỉnh táo."], [198.261, 203.233, "上课的时候，我也能听清楚老师的话了。", "Shàng Kè De Shí Hou, Wǒ Yě Néng Tīng Qīng Chu Lǎo Shī De Huà Le.", "Lúc học, tôi cũng nghe rõ lời cô giáo hơn."], [203.233, 208.747, "以前我上课想睡觉，现在我一点儿也不想睡。", "Yǐ Qián Wǒ Shàng Kè Xiǎng Shuì Jiào, Xiàn Zài Wǒ Yì Diǎn Ér Yě Bù Xiǎng Shuì.", "Trước đây học tôi buồn ngủ, giờ tôi chẳng buồn ngủ chút nào."], [208.747, 212.639, "周末的时候，我也没有睡到八点。", "Zhōu Mò De Shí Hou, Wǒ Yě Méi Yǒu Shuì Dào Bā Diǎn.", "Cuối tuần, tôi cũng không ngủ đến tám giờ nữa."], [212.639, 219.099, "周末早上，我帮妈妈买了早饭，妈妈没有想到我会起来。", "Zhōu Mò Zǎo Shàng, Wǒ Bāng Mā Ma Mǎi Le Zǎo Fàn, Mā Ma Méi Yǒu Xiǎng Dào Wǒ Huì Qǐ Lái.", "Sáng cuối tuần, tôi giúp mẹ mua bữa sáng, mẹ không ngờ tôi đã dậy."], [219.099, 226.255, "妈妈笑着问我：你怎么起来了？今天不用上学，你不多睡一会儿吗？", "Mā Ma Xiào Zhe Wèn Wǒ: Nǐ Zěn Me Qǐ Lái Le? Jīn Tiān Bú Yòng Shàng Xué, Nǐ Bù Duō Shuì Yí Huì Er Ma?", "Mẹ cười hỏi tôi: Sao con dậy rồi? Hôm nay không phải đi học, con không ngủ thêm một lát à?"], [226.255, 233.407, "我笑着说：我已经习惯了，醒了就睡不着了，早饭我去买吧。", "Wǒ Xiào Zhe Shuō: Wǒ Yǐ Jīng Xí Guàn Le, Xǐng Le Jiù Shuì Bù Zháo Le, Zǎo Fàn Wǒ Qù Mǎi Ba.", "Tôi cười nói: Con quen rồi, tỉnh là không ngủ lại được nữa, bữa sáng để con đi mua nhé."], [233.407, 237.635, "现在我不需要爸爸叫我，自己会醒。", "Xiàn Zài Wǒ Bù Xū Yào Bà Ba Jiào Wǒ, Zì Jǐ Huì Xǐng.", "Giờ tôi không cần bố gọi, tự tỉnh."], [237.635, 241.673, "有时候我比闹钟还早醒五分钟。", "Yǒu Shí Hou Wǒ Bǐ Nào Zhōng Hái Zǎo Xǐng Wǔ Fēn Zhōng.", "Có lúc tôi còn tỉnh trước đồng hồ báo thức năm phút."], [241.673, 249.381, "爸爸笑着说：看到你这样，爸爸真高兴，这个习惯，你要一直留着。", "Bà Ba Xiào Zhe Shuō: Kàn Dào Nǐ Zhè Yàng, Bà Ba Zhēn Gāo Xìng, Zhè Ge Xí Guàn, Nǐ Yào Yì Zhí Liú Zhe.", "Bố cười nói: Nhìn con như vậy bố thật vui, thói quen này con phải giữ mãi đấy."], [249.381, 253.817, "早起让我的学习和运动都更顺利了。", "Zǎo Qǐ Ràng Wǒ De Xué Xí Hé Yùn Dòng Dōu Gèng Shùn Lì Le.", "Dậy sớm giúp học tập và vận động của tôi thuận hơn."], [253.817, 260.18, "我把闹钟放在书包旁边，每天晚上都先看一次时间。", "Wǒ Bǎ Nào Zhōng Fàng Zài Shū Bāo Páng Biān, Měi Tiān Wǎn Shàng Dōu Xiān Kàn Yí Cì Shí Jiān.", "Tôi để đồng hồ báo thức cạnh cặp, tối nào cũng xem giờ trước một lần."], [260.18, 266.147, "我知道，早起不是一天的事，是每天都要做的事。", "Wǒ Zhī Dào, Zǎo Qǐ Bú Shì Yì Tiān De Shì, Shì Měi Tiān Dōu Yào Zuò De Shì.", "Tôi biết, dậy sớm không phải chuyện một ngày, mà là việc phải làm mỗi ngày."], [266.147, 272.222, "明天早上六点半，我还会像今天一样，早早地起来。", "Míng Tiān Zǎo Shàng Liù Diǎn Bàn, Wǒ Hái Huì Xiàng Jīn Tiān Yí Yàng, Zǎo Zǎo De Qǐ Lái.", "Sáng mai sáu rưỡi, tôi vẫn sẽ dậy sớm như hôm nay."], [272.222, 279.162, "一想到早上热热的早饭和爸爸的笑，我就觉得早起一点儿也不难。", "Yì Xiǎng Dào Zǎo Shàng Rè Rè De Zǎo Fàn Hé Bà Ba De Xiào, Wǒ Jiù Jué De Zǎo Qǐ Yì Diǎn Ér Yě Bù Nán.", "Nghĩ đến bữa sáng nóng hổi buổi sáng và nụ cười của bố, tôi thấy dậy sớm chẳng khó chút nào."]]}, "hsk3-23": {"dur": 293.93, "cues": [[7.756, 13.232, "我们搬到新楼以后，隔壁住着一位姓王的奶奶。", "Wǒ Men Bān Dào Xīn Lóu Yǐ Hòu, Gé Bì Zhù Zhe Yí Wèi Xìng Wáng De Nǎi Nai.", "Sau khi chuyển sang nhà mới, bên cạnh có một bà họ Vương."], [13.232, 19.211, "搬家那天，楼里的人很多，可是没有人跟我们说话。", "Bān Jiā Nà Tiān, Lóu Lǐ De Rén Hěn Duō, Kě Shì Méi Yǒu Rén Gēn Wǒ Men Shuō Huà.", "Ngày chuyển nhà, trong tòa nhà có nhiều người, nhưng không ai nói chuyện với nhà tôi."], [19.211, 26.819, "妈妈笑着说：新地方就是这样，慢慢就好了，我们会认识新朋友的。", "Mā Ma Xiào Zhe Shuō: Xīn Dì Fāng Jiù Shì Zhè Yàng, Màn Man Jiù Hǎo Le, Wǒ Men Huì Rèn Shi Xīn Péng You De.", "Mẹ cười nói: Chỗ mới là vậy đấy, dần dần sẽ quen thôi, nhà mình sẽ quen bạn mới mà."], [26.819, 32.079, "第二天早上，我在门口第一次看见王奶奶。", "Dì Èr Tiān Zǎo Shàng, Wǒ Zài Mén Kǒu Dì Yī Cì Kàn Jiàn Wáng Nǎi Nai.", "Sáng hôm sau, tôi lần đầu thấy bà Vương ở cửa."], [32.079, 37.082, "我小声说了一句奶奶好，她对我笑了笑。", "Wǒ Xiǎo Shēng Shuō Le Yí Jù Nǎi Nai Hǎo, Tā Duì Wǒ Xiào Le Xiào.", "Tôi khẽ chào một câu cháu chào bà, bà cười với tôi."], [37.082, 42.798, "她常常一个人在阳台晒太阳，看起来有些寂寞。", "Tā Cháng Cháng Yí Gè Rén Zài Yáng Tái Shài Tài Yáng, Kàn Qǐ Lái Yǒu Xiē Jì Mò.", "Bà thường một mình phơi nắng trên ban công, trông hơi cô đơn."], [42.798, 46.906, "我问妈妈：奶奶为什么总是一个人？", "Wǒ Wèn Mā Ma: Nǎi Nai Wèi Shén Me Zǒng Shì Yí Gè Rén?", "Tôi hỏi mẹ: Sao bà lúc nào cũng một mình ạ?"], [46.906, 54.242, "妈妈小声说：她的家人不在这边，她一个人住，我们要多陪陪她。", "Mā Ma Xiǎo Shēng Shuō: Tā De Jiā Rén Bú Zài Zhè Biān, Tā Yí Gè Rén Zhù, Wǒ Men Yào Duō Péi Péi Tā.", "Mẹ khẽ nói: Người nhà của bà không ở đây, bà sống một mình, nhà mình phải ở bên bà nhiều hơn."], [54.242, 58.758, "有一天我帮她把重的东西提上电梯。", "Yǒu Yì Tiān Wǒ Bāng Tā Bǎ Zhòng De Dōng Xi Tí Shàng Diàn Tī.", "Có hôm tôi giúp bà xách đồ nặng lên thang máy."], [58.758, 62.938, "那天她买了很多菜，一个人拿不动。", "Nà Tiān Tā Mǎi Le Hěn Duō Cài, Yí Gè Rén Ná Bù Dòng.", "Hôm đó bà mua nhiều rau, một mình xách không nổi."], [62.938, 67.802, "我说：奶奶，我帮您拿，您慢慢走。", "Wǒ Shuō: Nǎi Nai, Wǒ Bāng Nín Ná, Nín Màn Man Zǒu.", "Tôi nói: Bà ơi, cháu xách giúp bà, bà cứ đi từ từ."], [67.802, 72.702, "奶奶很高兴，送给我几个自己做的包子。", "Nǎi Nai Hěn Gāo Xìng, Sòng Gěi Wǒ Jǐ Gè Zì Jǐ Zuò De Bāo Zi.", "Bà rất vui và tặng tôi vài cái bánh bao tự làm."], [72.702, 79.57, "包子还热着，我拿在手里，味道也很好，我吃了两个还想吃。", "Bāo Zi Hái Rè Zhe, Wǒ Ná Zài Shǒu Lǐ, Wèi Dào Yě Hěn Hǎo, Wǒ Chī Le Liǎng Gè Hái Xiǎng Chī.", "Bánh bao vẫn còn nóng, tôi cầm trên tay, vị cũng rất ngon, tôi ăn hai cái vẫn muốn ăn nữa."], [79.57, 85.055, "我对奶奶说：您做的包子比外面买的还好吃。", "Wǒ Duì Nǎi Nai Shuō: Nín Zuò De Bāo Zi Bǐ Wài Miàn Mǎi De Hái Hǎo Chī.", "Tôi nói với bà: Bánh bao bà làm còn ngon hơn bánh mua ở ngoài."], [85.055, 89.955, "从那以后，我经过她家门口会打招呼。", "Cóng Nà Yǐ Hòu, Wǒ Jīng Guò Tā Jiā Mén Kǒu Huì Dǎ Zhāo Hu.", "Từ đó mỗi lần qua cửa nhà bà tôi đều chào hỏi."], [89.955, 93.967, "有时候她教我辨认几种常见的花。", "Yǒu Shí Hou Tā Jiāo Wǒ Biàn Rèn Jǐ Zhǒng Cháng Jiàn De Huā.", "Đôi khi bà dạy tôi nhận vài loài hoa quen thuộc."], [93.967, 100.955, "她看着窗户旁边的花说：你看，这种花早上开，晚上合上。", "Tā Kàn Zhe Chuāng Hu Páng Biān De Huā Shuō: Nǐ Kàn, Zhè Zhǒng Huā Zǎo Shàng Kāi, Wǎn Shàng Hé Shàng.", "Bà nhìn bông hoa bên cửa sổ nói: Cháu xem này, loài hoa này sáng nở, tối khép lại."], [100.955, 106.115, "我听了觉得很有意思，回家还告诉了妈妈。", "Wǒ Tīng Le Jué De Hěn Yǒu Yì Si, Huí Jiā Hái Gào Su Le Mā Ma.", "Nghe xong tôi thấy rất thú vị, về nhà còn kể cho mẹ nghe."], [106.115, 110.415, "妈妈做了菜，也会分一点给她尝。", "Mā Ma Zuò Le Cài, Yě Huì Fēn Yì Diǎn Gěi Tā Cháng.", "Mẹ nấu món gì cũng chia bà một ít nếm thử."], [110.415, 116.03, "有一次妈妈做了饺子，让我先给奶奶送一些去。", "Yǒu Yí Cì Mā Ma Zuò Le Jiǎo Zi, Ràng Wǒ Xiān Gěi Nǎi Nai Sòng Yì Xiē Qù.", "Có lần mẹ làm bánh chẻo, bảo tôi mang sang cho bà một ít trước."], [116.03, 121.146, "奶奶的儿子在外地工作，节日不能经常回来。", "Nǎi Nai De Ér Zi Zài Wài Dì Gōng Zuò, Jié Rì Bù Néng Jīng Cháng Huí Lái.", "Con trai bà làm việc xa, ngày lễ không về thường xuyên."], [121.146, 130.414, "有一天晚上，我经过奶奶家门口，听见她在打电话，声音很小，好像有点儿不高兴。", "Yǒu Yì Tiān Wǎn Shàng, Wǒ Jīng Guò Nǎi Nai Jiā Mén Kǒu, Tīng Jiàn Tā Zài Dǎ Diàn Huà, Shēng Yīn Hěn Xiǎo, Hǎo Xiàng Yǒu Diǎn Ér Bù Gāo Xìng.", "Một tối, tôi đi qua cửa nhà bà, nghe thấy bà đang gọi điện, giọng rất nhỏ, hình như hơi buồn."], [130.414, 135.674, "第二天她告诉我，儿子下个月才能回来一次。", "Dì Èr Tiān Tā Gào Su Wǒ, Ér Zi Xià Ge Yuè Cái Néng Huí Lái Yí Cì.", "Hôm sau bà kể với tôi, tháng sau con trai bà mới về được một lần."], [135.674, 139.614, "那几天天气很冷，还下了大雨。", "Nà Jǐ Tiān Tiān Qì Hěn Lěng, Hái Xià Le Dà Yǔ.", "Mấy hôm đó trời rất lạnh, còn mưa to."], [139.614, 144.73, "奶奶感冒了，一个人在家，累得做不了饭。", "Nǎi Nai Gǎn Mào Le, Yí Gè Rén Zài Jiā, Lèi Dé Zuò Bù Liǎo Fàn.", "Bà bị cảm, một mình ở nhà, mệt đến không nấu nổi cơm."], [144.73, 149.894, "妈妈知道了，马上煮了热汤，让我送过去。", "Mā Ma Zhī Dào Le, Mǎ Shàng Zhǔ Le Rè Tāng, Ràng Wǒ Sòng Guò Qù.", "Mẹ biết chuyện, lập tức nấu canh nóng, bảo tôi mang sang."], [149.894, 155.37, "我还去药店给奶奶买了药，回来告诉她怎么吃。", "Wǒ Hái Qù Yào Diàn Gěi Nǎi Nai Mǎi Le Yào, Huí Lái Gào Su Tā Zěn Me Chī.", "Tôi còn ra hiệu thuốc mua thuốc cho bà, về dặn bà cách uống."], [155.37, 163.376, "奶奶拉着我的手，笑着说：有你们在，奶奶一点儿也不怕，心里热热的。", "Nǎi Nai Lā Zhe Wǒ De Shǒu, Xiào Zhe Shuō: Yǒu Nǐ Men Zài, Nǎi Nai Yì Diǎn Ér Yě Bú Pà, Xīn Lǐ Rè Rè De.", "Bà nắm tay tôi, cười nói: Có các cháu ở đây, bà chẳng sợ chút nào, trong lòng ấm áp lắm."], [163.376, 169.476, "三天以后，奶奶的身体好了，能自己下楼走走了。", "Sān Tiān Yǐ Hòu, Nǎi Nai De Shēn Tǐ Hǎo Le, Néng Zì Jǐ Xià Lóu Zǒu Zou Le.", "Ba ngày sau, bà khỏe lại, tự xuống nhà đi dạo được rồi."], [169.476, 175.12, "她做的第一件事，就是给我们送来一些自己做的菜。", "Tā Zuò De Dì Yī Jiàn Shì, Jiù Shì Gěi Wǒ Men Sòng Lái Yì Xiē Zì Jǐ Zuò De Cài.", "Việc đầu tiên bà làm là mang sang cho nhà tôi một ít món bà tự nấu."], [175.12, 182.648, "奶奶还给儿子打电话，说了我们帮她的事，儿子在电话里连声说谢谢。", "Nǎi Nai Hái Gěi Ér Zi Dǎ Diàn Huà, Shuō Le Wǒ Men Bāng Tā De Shì, Ér Zi Zài Diàn Huà Lǐ Lián Shēng Shuō Xiè Xie.", "Bà còn gọi điện cho con trai, kể chuyện nhà tôi giúp bà, anh ấy ở đầu dây liên tục nói cảm ơn."], [182.648, 186.78, "天气冷了，爸爸帮她检查了窗户。", "Tiān Qì Lěng Le, Bà Ba Bāng Tā Jiǎn Chá Le Chuāng Hu.", "Trời lạnh, bố giúp bà kiểm tra cửa sổ."], [186.78, 194.08, "爸爸对奶奶说：窗户关不好，晚上屋里会很冷，我帮您看看吧。", "Bà Ba Duì Nǎi Nai Shuō: Chuāng Hu Guān Bù Hǎo, Wǎn Shàng Wū Lǐ Huì Hěn Lěng, Wǒ Bāng Nín Kàn Kan Ba.", "Bố nói với bà: Cửa sổ đóng không kín, tối trong nhà sẽ rất lạnh, để con xem giúp bà."], [194.08, 199.227, "检查完以后，奶奶请爸爸喝了一杯热茶。", "Jiǎn Chá Wán Yǐ Hòu, Nǎi Nai Qǐng Bà Ba Hē Le Yì Bēi Rè Chá.", "Kiểm tra xong, bà mời bố uống một cốc trà nóng."], [199.227, 203.743, "过年的时候，我们邀请她一起来吃饺子。", "Guò Nián De Shí Hou, Wǒ Men Yāo Qǐng Tā Yì Qǐ Lái Chī Jiǎo Zi.", "Tết chúng tôi mời bà đến ăn bánh chẻo."], [203.743, 212.891, "妈妈笑着说：过年的时候，人多才好，奶奶来了，我们一起吃饺子，大家都很高兴。", "Mā Ma Xiào Zhe Shuō: Guò Nián De Shí Hou, Rén Duō Cái Hǎo, Nǎi Nai Lái Le, Wǒ Men Yì Qǐ Chī Jiǎo Zi, Dà Jiā Dōu Hěn Gāo Xìng.", "Mẹ cười nói: Tết là phải đông người mới vui, bà đến rồi, nhà mình cùng ăn bánh chẻo, ai cũng vui."], [212.891, 220.719, "那天晚上，奶奶穿了一件红衣服，坐在热热的饺子旁边，笑得很开心。", "Nà Tiān Wǎn Shàng, Nǎi Nai Chuān Le Yí Jiàn Hóng Yī Fu, Zuò Zài Rè Rè De Jiǎo Zi Páng Biān, Xiào Dé Hěn Kāi Xīn.", "Tối hôm đó, bà mặc một chiếc áo đỏ, ngồi bên đĩa bánh chẻo nóng hổi, cười rất vui."], [220.719, 225.489, "她笑着说，有邻居就像有家人一样。", "Tā Xiào Zhe Shuō, Yǒu Lín Jū Jiù Xiàng Yǒu Jiā Rén Yí Yàng.", "Bà cười nói có hàng xóm như có thêm người nhà."], [225.489, 231.997, "吃完饺子，奶奶的儿子打来电话，问她过年过得好不好。", "Chī Wán Jiǎo Zi, Nǎi Nai De Ér Zi Dǎ Lái Diàn Huà, Wèn Tā Guò Nián Guò Dé Hǎo Bù Hǎo.", "Ăn bánh chẻo xong, con trai bà gọi điện đến, hỏi bà đón Tết có vui không."], [231.997, 241.093, "奶奶高兴地说：很好很好，邻居请我吃了饺子，大家对我都很好，我一点儿也不寂寞。", "Nǎi Nai Gāo Xìng De Shuō: Hěn Hǎo Hěn Hǎo, Lín Jū Qǐng Wǒ Chī Le Jiǎo Zi, Dà Jiā Duì Wǒ Dōu Hěn Hǎo, Wǒ Yì Diǎn Ér Yě Bú Jì Mò.", "Bà vui vẻ nói: Vui lắm vui lắm, hàng xóm mời mẹ ăn bánh chẻo, ai cũng tốt với mẹ, mẹ chẳng cô đơn chút nào."], [241.093, 246.785, "现在，我每天放学回家，都会先去看看奶奶。", "Xiàn Zài, Wǒ Měi Tiān Fàng Xué Huí Jiā, Dōu Huì Xiān Qù Kàn Kan Nǎi Nai.", "Giờ mỗi ngày tan học về, tôi đều ghé thăm bà trước."], [246.785, 252.117, "同学来我家的时候，我也带他们去看奶奶的花。", "Tóng Xué Lái Wǒ Jiā De Shí Hou, Wǒ Yě Dài Tā Men Qù Kàn Nǎi Nai De Huā.", "Khi bạn học đến nhà tôi, tôi cũng dẫn các bạn sang xem hoa của bà."], [252.117, 256.325, "奶奶很高兴，还拿出包子请我们吃。", "Nǎi Nai Hěn Gāo Xìng, Hái Ná Chū Bāo Zi Qǐng Wǒ Men Chī.", "Bà rất vui, còn lấy bánh bao mời chúng tôi ăn."], [256.325, 260.385, "她要是需要帮忙，就会给我打电话。", "Tā Yào Shì Xū Yào Bāng Máng, Jiù Huì Gěi Wǒ Dǎ Diàn Huà.", "Nếu bà cần giúp gì, bà sẽ gọi điện cho tôi."], [260.385, 265.497, "我觉得，邻居互相帮忙，是应该做的事。", "Wǒ Jué De, Lín Jū Hù Xiāng Bāng Máng, Shì Yīng Gāi Zuò De Shì.", "Tôi thấy, hàng xóm giúp đỡ lẫn nhau là việc nên làm."], [265.497, 271.957, "现在奶奶的阳台上有很多花，她每天早上都给花浇水。", "Xiàn Zài Nǎi Nai De Yáng Tái Shàng Yǒu Hěn Duō Huā, Tā Měi Tiān Zǎo Shàng Dōu Gěi Huā Jiāo Shuǐ.", "Giờ trên ban công nhà bà có nhiều hoa, sáng nào bà cũng tưới nước cho hoa."], [271.957, 277.145, "和邻居好好相处，让我的生活更温暖了。", "Hé Lín Jū Hǎo Hao Xiāng Chǔ, Ràng Wǒ De Shēng Huó Gèng Wēn Nuǎn Le.", "Sống hòa thuận với hàng xóm làm cuộc sống tôi ấm hơn."], [277.145, 285.307, "每天回家，先听见奶奶说一声回来了，我就知道，今天又是温暖的一天。", "Měi Tiān Huí Jiā, Xiān Tīng Jiàn Nǎi Nai Shuō Yì Shēng Huí Lái Le, Wǒ Jiù Zhī Dào, Jīn Tiān Yòu Shì Wēn Nuǎn De Yì Tiān.", "Mỗi ngày về nhà, nghe tiếng bà nói 'về rồi à' đầu tiên, tôi biết hôm nay lại là một ngày ấm áp."]]}, "hsk3-24": {"dur": 305.29, "cues": [[7.198, 12.986, "那天妈妈下班很晚，回到家的时候看起来很累。", "Nà Tiān Mā Ma Xià Bān Hěn Wǎn, Huí Dào Jiā De Shí Hou Kàn Qǐ Lái Hěn Lèi.", "Hôm đó mẹ tan làm rất muộn, về đến nhà trông rất mệt."], [12.986, 20.766, "她放下包，坐下来，笑着说：今天真累，妈妈先休息一会儿，好吗？", "Tā Fàng Xià Bāo, Zuò Xià Lái, Xiào Zhe Shuō: Jīn Tiān Zhēn Lèi, Mā Ma Xiān Xiū Xi Yí Huì Er, Hǎo Ma?", "Mẹ đặt túi xuống, ngồi xuống, cười nói: Hôm nay mệt thật, mẹ nghỉ một lát trước nhé, được không con?"], [20.766, 26.331, "我看着妈妈，心里想：今天我来做一次饭吧。", "Wǒ Kàn Zhe Mā Ma, Xīn Lǐ Xiǎng: Jīn Tiān Wǒ Lái Zuò Yí Cì Fàn Ba.", "Tôi nhìn mẹ, nghĩ trong lòng: Hôm nay để mình nấu cơm một lần vậy."], [26.331, 32.575, "放假的那天，我想学着给妈妈做一道西红柿鸡蛋。", "Fàng Jià De Nà Tiān, Wǒ Xiǎng Xué Zhe Gěi Mā Ma Zuò Yí Dào Xī Hóng Shì Jī Dàn.", "Ngày nghỉ tôi muốn học nấu món trứng cà chua cho mẹ."], [32.575, 38.579, "我问妈妈：妈妈，你教我做西红柿鸡蛋，好不好？", "Wǒ Wèn Mā Ma: Mā Ma, Nǐ Jiāo Wǒ Zuò Xī Hóng Shì Jī Dàn, Hǎo Bù Hǎo?", "Tôi hỏi mẹ: Mẹ ơi, mẹ dạy con làm món trứng cà chua nhé, được không ạ?"], [38.579, 44.606, "妈妈笑着说：好，今天你做，我在旁边教你。", "Mā Ma Xiào Zhe Shuō: Hǎo, Jīn Tiān Nǐ Zuò, Wǒ Zài Páng Biān Jiāo Nǐ.", "Mẹ cười nói: Được, hôm nay con làm, mẹ ở bên cạnh dạy con."], [44.606, 50.034, "我们先去买了西红柿和鸡蛋，还买了一点儿糖。", "Wǒ Men Xiān Qù Mǎi Le Xī Hóng Shì Hé Jī Dàn, Hái Mǎi Le Yì Diǎn Ér Táng.", "Chúng tôi đi mua cà chua và trứng trước, còn mua thêm một ít đường."], [50.034, 56.239, "妈妈说：做菜以前，要先洗手，也要先洗菜。", "Mā Ma Shuō: Zuò Cài Yǐ Qián, Yào Xiān Xǐ Shǒu, Yě Yào Xiān Xǐ Cài.", "Mẹ nói: Trước khi nấu phải rửa tay trước, cũng phải rửa rau trước."], [56.239, 61.331, "妈妈先让我在热水里把西红柿的皮去掉。", "Mā Ma Xiān Ràng Wǒ Zài Rè Shuǐ Lǐ Bǎ Xī Hóng Shì De Pí Qù Diào.", "Mẹ bảo tôi trần cà chua trong nước nóng để bỏ vỏ."], [61.331, 67.695, "西红柿在热水里放了一会儿，红红的，皮就好去了。", "Xī Hóng Shì Zài Rè Shuǐ Lǐ Fàng Le Yí Huì Er, Hóng Hóng De, Pí Jiù Hǎo Qù Le.", "Cà chua để trong nước nóng một lúc, đỏ đỏ, là vỏ dễ bỏ hẳn."], [67.695, 73.147, "然后她教我切菜，要慢慢切，小心手。", "Rán Hòu Tā Jiāo Wǒ Qiē Cài, Yào Màn Man Qiē, Xiǎo Xīn Shǒu.", "Sau đó mẹ dạy tôi thái rau, thái chậm và cẩn thận tay."], [73.147, 79.007, "我切得很慢，西红柿有大有小，一点儿也不一样。", "Wǒ Qiē Dé Hěn Màn, Xī Hóng Shì Yǒu Dà Yǒu Xiǎo, Yì Diǎn Ér Yě Bú Yí Yàng.", "Tôi thái rất chậm, miếng cà chua to nhỏ khác nhau, chẳng miếng nào giống miếng nào."], [79.007, 86.471, "妈妈笑着说：没关系，第一次都是这样，慢慢来，你做得很好。", "Mā Ma Xiào Zhe Shuō: Méi Guān Xi, Dì Yī Cì Dōu Shì Zhè Yàng, Màn Man Lái, Nǐ Zuò Dé Hěn Hǎo.", "Mẹ cười nói: Không sao, lần đầu ai cũng vậy, cứ từ từ, con làm tốt lắm."], [86.471, 90.915, "鸡蛋打进碗里，用筷子搅拌均匀。", "Jī Dàn Dǎ Jìn Wǎn Lǐ, Yòng Kuài Zi Jiǎo Bàn Jūn Yún.", "Đập trứng vào bát, dùng đũa khuấy đều."], [90.915, 96.055, "我打鸡蛋的时候，有一点儿鸡蛋到了碗外面。", "Wǒ Dǎ Jī Dàn De Shí Hou, Yǒu Yì Diǎn Ér Jī Dàn Dào Le Wǎn Wài Miàn.", "Lúc đập trứng, có một ít trứng ra ngoài bát."], [96.055, 99.985, "我笑了笑，妈妈帮我收拾好了。", "Wǒ Xiào Le Xiào, Mā Ma Bāng Wǒ Shōu Shi Hǎo Le.", "Tôi cười cười, mẹ giúp tôi dọn sạch."], [99.985, 105.845, "锅热了以后放油，我先炒鸡蛋，再炒西红柿。", "Guō Rè Le Yǐ Hòu Fàng Yóu, Wǒ Xiān Chǎo Jī Dàn, Zài Chǎo Xī Hóng Shì.", "Chảo nóng thì cho dầu, tôi xào trứng trước, rồi xào cà chua."], [105.845, 112.353, "油一热，就有了小小的声音，我有点儿怕，手离锅很远。", "Yóu Yí Rè, Jiù Yǒu Le Xiǎo Xiǎo De Shēng Yīn, Wǒ Yǒu Diǎn Ér Pà, Shǒu Lí Guō Hěn Yuǎn.", "Dầu vừa nóng đã có tiếng nhỏ, tôi hơi sợ, tay để cách chảo rất xa."], [112.353, 120.277, "妈妈站在我旁边，笑着说：别怕，妈妈在呢，慢慢把鸡蛋放进去。", "Mā Ma Zhàn Zài Wǒ Páng Biān, Xiào Zhe Shuō: Bié Pà, Mā Ma Zài Ne, Màn Man Bǎ Jī Dàn Fàng Jìn Qù.", "Mẹ đứng bên cạnh tôi, cười nói: Đừng sợ, có mẹ ở đây, từ từ cho trứng vào."], [120.277, 125.759, "我听了妈妈的话，慢慢地做，一点儿也不着急。", "Wǒ Tīng Le Mā Ma De Huà, Màn Man De Zuò, Yì Diǎn Ér Yě Bù Zhāo Jí.", "Tôi nghe lời mẹ, làm từ từ, chẳng vội chút nào."], [125.759, 131.019, "第一次炒鸡蛋的时候，有一点儿鸡蛋炒坏了。", "Dì Yī Cì Chǎo Jī Dàn De Shí Hou, Yǒu Yì Diǎn Ér Jī Dàn Chǎo Huài Le.", "Lần đầu xào trứng, có một ít trứng bị xào hỏng."], [131.019, 135.631, "我小声说：是不是做坏了？还能吃吗？", "Wǒ Xiǎo Shēng Shuō: Shì Bú Shì Zuò Huài Le? Hái Néng Chī Ma?", "Tôi khẽ nói: Có phải hỏng rồi không ạ? Còn ăn được không ạ?"], [135.631, 144.753, "妈妈尝了一口，笑着说：没坏，就是做的时间长了一点儿，下次注意一点儿就好了。", "Mā Ma Cháng Le Yì Kǒu, Xiào Zhe Shuō: Méi Huài, Jiù Shì Zuò De Shí Jiān Cháng Le Yì Diǎn Ér, Xià Cì Zhù Yì Yì Diǎn Ér Jiù Hǎo Le.", "Mẹ nếm một miếng, cười nói: Không hỏng đâu, chỉ là làm hơi lâu một chút thôi, lần sau để ý một chút là được."], [144.753, 151.021, "然后我炒西红柿，这次我看着时间，没有再炒坏。", "Rán Hòu Wǒ Chǎo Xī Hóng Shì, Zhè Cì Wǒ Kàn Zhe Shí Jiān, Méi Yǒu Zài Chǎo Huài.", "Sau đó tôi xào cà chua, lần này tôi để ý thời gian, không xào hỏng nữa."], [151.021, 156.185, "菜出锅以前，妈妈帮我加一点盐和糖。", "Cài Chū Guō Yǐ Qián, Mā Ma Bāng Wǒ Jiā Yì Diǎn Yán Hé Táng.", "Trước khi ra mâm mẹ giúp tôi cho thêm chút muối và đường."], [156.185, 162.656, "妈妈笑着说：盐不能多，糖也不能多，一点儿就可以了。", "Mā Ma Xiào Zhe Shuō: Yán Bù Néng Duō, Táng Yě Bù Néng Duō, Yì Diǎn Ér Jiù Kě Yǐ Le.", "Mẹ cười nói: Muối không được nhiều, đường cũng không được nhiều, một chút là được rồi."], [162.656, 167.364, "虽然形状不太好看，可是味道还不错。", "Suī Rán Xíng Zhuàng Bú Tài Hǎo Kàn, Kě Shì Wèi Dào Hái Bú Cuò.", "Tuy bề ngoài không đẹp lắm nhưng vị còn khá ngon."], [167.364, 174.208, "我把热热的菜放在桌子上，看着爸爸妈妈，心里有一点儿紧张。", "Wǒ Bǎ Rè Rè De Cài Fàng Zài Zhuō Zi Shàng, Kàn Zhe Bà Ba Mā Ma, Xīn Lǐ Yǒu Yì Diǎn Ér Jǐn Zhāng.", "Tôi đặt món ăn nóng hổi lên bàn, nhìn bố mẹ, trong lòng hơi căng thẳng."], [174.208, 179.252, "爸爸下班回来，尝了一口，说很好吃。", "Bà Ba Xià Bān Huí Lái, Cháng Le Yì Kǒu, Shuō Hěn Hǎo Chī.", "Bố tan làm về nếm một miếng và khen rất ngon."], [179.252, 185.568, "爸爸又吃了一口，笑着问我：这么好吃，是你做的吗？", "Bà Ba Yòu Chī Le Yì Kǒu, Xiào Zhe Wèn Wǒ: Zhè Me Hǎo Chī, Shì Nǐ Zuò De Ma?", "Bố ăn thêm một miếng nữa, cười hỏi tôi: Ngon thế này, là con làm à?"], [185.568, 192.076, "我高兴地说：是我做的，妈妈只教我，都是我自己做的。", "Wǒ Gāo Xìng De Shuō: Shì Wǒ Zuò De, Mā Ma Zhǐ Jiāo Wǒ, Dōu Shì Wǒ Zì Jǐ Zuò De.", "Tôi vui vẻ nói: Là con làm ạ, mẹ chỉ dạy con thôi, đều là con tự làm ạ."], [192.076, 197.288, "妈妈说我第一次做菜就能做好，真了不起。", "Mā Ma Shuō Wǒ Dì Yī Cì Zuò Cài Jiù Néng Zuò Hǎo, Zhēn Liǎo Bù Qǐ.", "Mẹ nói lần đầu nấu mà làm được như vậy thật giỏi."], [197.288, 204.18, "爸爸笑着说：下次你做的时候，一定要叫爸爸先尝第一口。", "Bà Ba Xiào Zhe Shuō: Xià Cì Nǐ Zuò De Shí Hou, Yí Dìng Yào Jiào Bà Ba Xiān Cháng Dì Yī Kǒu.", "Bố cười nói: Lần sau con nấu, nhất định phải gọi bố nếm miếng đầu tiên nhé."], [204.18, 208.724, "那天晚上，我们三个人把菜都吃完了。", "Nà Tiān Wǎn Shàng, Wǒ Men Sān Gè Rén Bǎ Cài Dōu Chī Wán Le.", "Tối hôm đó, ba người chúng tôi ăn hết sạch món ăn."], [208.724, 214.296, "吃完饭，我主动去洗碗，妈妈笑着看着我。", "Chī Wán Fàn, Wǒ Zhǔ Dòng Qù Xǐ Wǎn, Mā Ma Xiào Zhe Kàn Zhe Wǒ.", "Ăn cơm xong, tôi chủ động đi rửa bát, mẹ cười nhìn tôi."], [214.296, 219.316, "我把做菜的过程记在小本上，免得忘记。", "Wǒ Bǎ Zuò Cài De Guò Chéng Jì Zài Xiǎo Běn Shàng, Miǎn Dé Wàng Jì.", "Tôi ghi các bước vào sổ nhỏ để khỏi quên."], [219.316, 226.418, "我还把要注意的地方写下来：做的时间不能太长，盐不能太多。", "Wǒ Hái Bǎ Yào Zhù Yì De Dì Fāng Xiě Xià Lái: Zuò De Shí Jiān Bù Néng Tài Cháng, Yán Bù Néng Tài Duō.", "Tôi còn ghi lại những chỗ cần chú ý: thời gian nấu không được quá lâu, muối không được quá nhiều."], [226.418, 232.446, "第二个星期，我又做了一次，这次没有人帮我放盐。", "Dì Èr Gè Xīng Qī, Wǒ Yòu Zuò Le Yí Cì, Zhè Cì Méi Yǒu Rén Bāng Wǒ Fàng Yán.", "Tuần thứ hai, tôi lại làm một lần nữa, lần này không ai giúp tôi cho muối."], [232.446, 237.865, "这次鸡蛋没有坏，西红柿也切得比上次好。", "Zhè Cì Jī Dàn Méi Yǒu Huài, Xī Hóng Shì Yě Qiē Dé Bǐ Shàng Cì Hǎo.", "Lần này trứng không hỏng, cà chua cũng thái đẹp hơn lần trước."], [237.865, 242.789, "奶奶来我家的时候，我也给她做了这道菜。", "Nǎi Nai Lái Wǒ Jiā De Shí Hou, Wǒ Yě Gěi Tā Zuò Le Zhè Dào Cài.", "Khi bà đến nhà tôi, tôi cũng làm món này cho bà ăn."], [242.789, 250.961, "奶奶吃完，笑着说：真好吃，你做的菜，有妈妈的味道，奶奶很喜欢。", "Nǎi Nai Chī Wán, Xiào Zhe Shuō: Zhēn Hǎo Chī, Nǐ Zuò De Cài, Yǒu Mā Ma De Wèi Dào, Nǎi Nai Hěn Xǐ Huan.", "Bà ăn xong, cười nói: Ngon lắm, món cháu nấu có hương vị của mẹ cháu, bà rất thích."], [250.961, 255.789, "下次我想试一试做米饭和简单的汤。", "Xià Cì Wǒ Xiǎng Shì Yi Shì Zuò Mǐ Fàn Hé Jiǎn Dān De Tāng.", "Lần sau tôi muốn thử nấu cơm và canh đơn giản."], [255.789, 264.313, "妈妈笑着说：好，下次我教你做汤，你先把这次的菜做好，妈妈相信你。", "Mā Ma Xiào Zhe Shuō: Hǎo, Xià Cì Wǒ Jiāo Nǐ Zuò Tāng, Nǐ Xiān Bǎ Zhè Cì De Cài Zuò Hǎo, Mā Ma Xiāng Xìn Nǐ.", "Mẹ cười nói: Được, lần sau mẹ dạy con nấu canh, con cứ làm tốt món lần này trước đã, mẹ tin con."], [264.313, 273.044, "妈妈还笑着说：做菜和学习一样，认真做，就能做好，妈妈等着吃你做的菜。", "Mā Ma Hái Xiào Zhe Shuō: Zuò Cài Hé Xué Xí Yí Yàng, Rèn Zhēn Zuò, Jiù Néng Zuò Hǎo, Mā Ma Děng Zhe Chī Nǐ Zuò De Cài.", "Mẹ còn cười nói: Nấu ăn cũng như học tập, làm nghiêm túc là sẽ làm tốt, mẹ chờ ăn món con nấu."], [273.044, 277.607, "学会做菜以后，我觉得自己更有用了。", "Xué Huì Zuò Cài Yǐ Hòu, Wǒ Jué De Zì Jǐ Gèng Yǒu Yòng Le.", "Biết nấu ăn rồi tôi cảm thấy mình hữu ích hơn."], [277.607, 285.436, "现在妈妈累了的时候，我会笑着说：妈妈，您休息，今天我来做饭。", "Xiàn Zài Mā Ma Lèi Le De Shí Hou, Wǒ Huì Xiào Zhe Shuō: Mā Ma, Nín Xiū Xi, Jīn Tiān Wǒ Lái Zuò Fàn.", "Giờ khi mẹ mệt, tôi sẽ cười nói: Mẹ ơi, mẹ nghỉ đi, hôm nay để con nấu cơm."], [285.436, 290.432, "我还想学做更多的菜，一个一个慢慢学。", "Wǒ Hái Xiǎng Xué Zuò Gèng Duō De Cài, Yí Gè Yí Gè Màn Man Xué.", "Tôi còn muốn học nấu thêm nhiều món nữa, học từng món một từ từ."], [290.432, 296.556, "我想让妈妈常常吃到我做的菜，那是我最开心的事。", "Wǒ Xiǎng Ràng Mā Ma Cháng Cháng Chī Dào Wǒ Zuò De Cài, Nà Shì Wǒ Zuì Kāi Xīn De Shì.", "Tôi muốn để mẹ thường được ăn món tôi nấu, đó là việc khiến tôi vui nhất."]]}, "hsk3-25": {"dur": 306.89, "cues": [[7.384, 13.508, "我一直想买一本大词典，可是那本词典要两百块钱。", "Wǒ Yì Zhí Xiǎng Mǎi Yì Běn Dà Cí Diǎn, Kě Shì Nà Běn Cí Diǎn Yào Liǎng Bǎi Kuài Qián.", "Tôi vẫn luôn muốn mua một cuốn từ điển lớn, nhưng cuốn từ điển đó giá hai trăm tệ."], [13.508, 19.56, "我看了看自己有的钱，还差一点儿，不能买那本词典。", "Wǒ Kàn Le Kàn Zì Jǐ Yǒu De Qián, Hái Chà Yì Diǎn Ér, Bù Néng Mǎi Nà Běn Cí Diǎn.", "Tôi xem số tiền mình có, vẫn thiếu một chút, chưa mua được cuốn từ điển đó."], [19.56, 25.565, "妈妈笑着说：不着急，你可以等一等，慢慢攒钱。", "Mā Ma Xiào Zhe Shuō: Bù Zhāo Jí, Nǐ Kě Yǐ Děng Yi Děng, Màn Man Zǎn Qián.", "Mẹ cười nói: Đừng vội, con có thể đợi một thời gian, từ từ dành tiền."], [25.565, 31.281, "我想了想，说：我想自己工作，自己赚钱买。", "Wǒ Xiǎng Le Xiǎng, Shuō: Wǒ Xiǎng Zì Jǐ Gōng Zuò, Zì Jǐ Zhuàn Qián Mǎi.", "Tôi nghĩ một lúc rồi nói: Con muốn tự đi làm, tự kiếm tiền để mua."], [31.281, 36.709, "暑假快到了，我想找一份兼职工作攒点钱。", "Shǔ Jià Kuài Dào Le, Wǒ Xiǎng Zhǎo Yí Fèn Jiān Zhí Gōng Zuò Zǎn Diǎn Qián.", "Sắp hè, tôi muốn tìm việc làm thêm để dành chút tiền."], [36.709, 42.065, "我先在网上看了看，可是离家近的工作很少。", "Wǒ Xiān Zài Wǎng Shàng Kàn Le Kàn, Kě Shì Lí Jiā Jìn De Gōng Zuò Hěn Shǎo.", "Tôi xem trên mạng trước, nhưng việc gần nhà rất ít."], [42.065, 46.317, "同学介绍我去离家不远的书店帮忙。", "Tóng Xué Jiè Shào Wǒ Qù Lí Jiā Bù Yuǎn De Shū Diàn Bāng Máng.", "Bạn giới thiệu tôi đến tiệm sách gần nhà giúp việc."], [46.317, 54.52, "同学笑着说：别担心，那家书店的老板很好，你去问问吧，他会帮你的。", "Tóng Xué Xiào Zhe Shuō: Bié Dān Xīn, Nà Jiā Shū Diàn De Lǎo Bǎn Hěn Hǎo, Nǐ Qù Wèn Wen Ba, Tā Huì Bāng Nǐ De.", "Bạn cười nói: Đừng lo, chủ tiệm sách đó rất tốt, cậu đến hỏi thử đi, chú ấy sẽ giúp cậu."], [54.52, 59.204, "第二天下午，我一个人去了那家书店。", "Dì Èr Tiān Xià Wǔ, Wǒ Yí Gè Rén Qù Le Nà Jiā Shū Diàn.", "Chiều hôm sau, tôi một mình đến tiệm sách đó."], [59.204, 66.936, "我站在书店门口，听着里面安静的声音，先看了看里面，心里很紧张。", "Wǒ Zhàn Zài Shū Diàn Mén Kǒu, Tīng Zhe Lǐ Miàn Ān Jìng De Shēng Yīn, Xiān Kàn Le Kàn Lǐ Miàn, Xīn Lǐ Hěn Jǐn Zhāng.", "Tôi đứng ở cửa tiệm sách, lắng nghe âm thanh yên tĩnh bên trong, nhìn vào trong trước, trong lòng rất căng thẳng."], [66.936, 72.916, "我对老板说：您好，我想在这里做兼职，可以吗？", "Wǒ Duì Lǎo Bǎn Shuō: Nín Hǎo, Wǒ Xiǎng Zài Zhè Lǐ Zuò Jiān Zhí, Kě Yǐ Ma?", "Tôi nói với chủ tiệm: Chào chú ạ, cháu muốn làm thêm ở đây, có được không ạ?"], [72.916, 78.728, "老板看了看我，问我：你以前做过这样的工作吗？", "Lǎo Bǎn Kàn Le Kàn Wǒ, Wèn Wǒ: Nǐ Yǐ Qián Zuò Guò Zhè Yàng De Gōng Zuò Ma?", "Chủ tiệm nhìn tôi, hỏi: Trước đây cháu từng làm việc như thế này chưa?"], [78.728, 86.587, "我认真地说：没有，可是我很喜欢看书，也愿意学习，我会认真做的。", "Wǒ Rèn Zhēn De Shuō: Méi Yǒu, Kě Shì Wǒ Hěn Xǐ Huan Kàn Shū, Yě Yuàn Yì Xué Xí, Wǒ Huì Rèn Zhēn Zuò De.", "Tôi nghiêm túc nói: Chưa ạ, nhưng cháu rất thích đọc sách, cũng sẵn lòng học hỏi, cháu sẽ làm việc nghiêm túc ạ."], [86.587, 92.495, "老板让我先试一个星期，主要整理书和回答问题。", "Lǎo Bǎn Ràng Wǒ Xiān Shì Yí Gè Xīng Qī, Zhǔ Yào Zhěng Lǐ Shū Hé Huí Dá Wèn Tí.", "Chủ tiệm cho tôi thử một tuần, chủ yếu xếp sách và trả lời câu hỏi."], [92.495, 97.779, "第一天我很紧张，常常不知道书架在哪里。", "Dì Yī Tiān Wǒ Hěn Jǐn Zhāng, Cháng Cháng Bù Zhī Dào Shū Jià Zài Nǎ Lǐ.", "Ngày đầu tôi rất căng thẳng, thường không biết kệ sách ở đâu."], [97.779, 103.183, "同事耐心地教我，还告诉我怎么跟客人说话。", "Tóng Shì Nài Xīn De Jiāo Wǒ, Hái Gào Su Wǒ Zěn Me Gēn Kè Rén Shuō Huà.", "Đồng nghiệp kiên nhẫn dạy tôi và bảo cách nói chuyện với khách."], [103.183, 111.758, "同事笑着说：别紧张，客人问的时候，你先听清楚，再慢慢回答就可以了。", "Tóng Shì Xiào Zhe Shuō: Bié Jǐn Zhāng, Kè Rén Wèn De Shí Hou, Nǐ Xiān Tīng Qīng Chu, Zài Màn Man Huí Dá Jiù Kě Yǐ Le.", "Đồng nghiệp cười nói: Đừng căng thẳng, khi khách hỏi, cậu nghe rõ trước, rồi trả lời từ từ là được."], [111.758, 116.754, "第二天，有一位客人问我一本书在哪里。", "Dì Èr Tiān, Yǒu Yí Wèi Kè Rén Wèn Wǒ Yì Běn Shū Zài Nǎ Lǐ.", "Ngày thứ hai, có một vị khách hỏi tôi một cuốn sách ở đâu."], [116.754, 121.678, "我找了很久，也没有找到，心里很着急。", "Wǒ Zhǎo Le Hěn Jiǔ, Yě Méi Yǒu Zhǎo Dào, Xīn Lǐ Hěn Zhāo Jí.", "Tôi tìm rất lâu mà không tìm thấy, trong lòng rất sốt ruột."], [121.678, 129.938, "客人等了一会儿，笑着说：没关系，不着急，我下次再来，你慢慢学。", "Kè Rén Děng Le Yí Huì Er, Xiào Zhe Shuō: Méi Guān Xi, Bù Zhāo Jí, Wǒ Xià Cì Zài Lái, Nǐ Màn Man Xué.", "Khách đợi một lúc, cười nói: Không sao, đừng vội, lần sau tôi quay lại, cháu cứ từ từ học."], [129.938, 134.281, "我看着客人走出去，心里很不舒服。", "Wǒ Kàn Zhe Kè Rén Zǒu Chū Qù, Xīn Lǐ Hěn Bù Shū Fu.", "Tôi nhìn khách đi ra, trong lòng rất khó chịu."], [134.281, 143.237, "同事走过来，笑着说：没事没事，我带你把每个书架都看一遍，看完就记住了。", "Tóng Shì Zǒu Guò Lái, Xiào Zhe Shuō: Méi Shì Méi Shì, Wǒ Dài Nǐ Bǎ Měi Gè Shū Jià Dōu Kàn Yí Biàn, Kàn Wán Jiù Jì Zhù Le.", "Đồng nghiệp đi tới, cười nói: Không sao không sao, tớ đưa cậu xem từng kệ sách một lượt, xem xong là nhớ thôi."], [143.237, 149.121, "那天下班以前，我把书架的位置都记在了小本上。", "Nà Tiān Xià Bān Yǐ Qián, Wǒ Bǎ Shū Jià De Wèi Zhi Dōu Jì Zài Le Xiǎo Běn Shàng.", "Hôm đó trước khi tan ca, tôi ghi vị trí các kệ sách hết vào sổ nhỏ."], [149.121, 154.436, "慢慢的，我能记住小说类和学习类的位置了。", "Màn Màn De, Wǒ Néng Jì Zhù Xiǎo Shuō Lèi Hé Xué Xí Lèi De Wèi Zhi Le.", "Dần dần tôi nhớ vị trí tiểu thuyết và sách học tập."], [154.436, 159.984, "第三天，那位客人又来了，还问上次那本书。", "Dì Sān Tiān, Nà Wèi Kè Rén Yòu Lái Le, Hái Wèn Shàng Cì Nà Běn Shū.", "Ngày thứ ba, vị khách đó lại đến, vẫn hỏi cuốn sách lần trước."], [159.984, 163.612, "这次我马上带他找到了那本书。", "Zhè Cì Wǒ Mǎ Shàng Dài Tā Zhǎo Dào Le Nà Běn Shū.", "Lần này tôi lập tức dẫn bác ấy tìm được cuốn sách đó."], [163.612, 171.728, "客人笑着说：谢谢你，这么快就找到了，你比上次快多了，我很高兴。", "Kè Rén Xiào Zhe Shuō: Xiè Xie Nǐ, Zhè Me Kuài Jiù Zhǎo Dào Le, Nǐ Bǐ Shàng Cì Kuài Duō Le, Wǒ Hěn Gāo Xìng.", "Khách cười nói: Cảm ơn cháu, tìm được nhanh thế, cháu nhanh hơn lần trước nhiều rồi, bác rất vui."], [171.728, 175.752, "听了这句话，我的心里特别高兴。", "Tīng Le Zhè Jù Huà, Wǒ De Xīn Lǐ Tè Bié Gāo Xìng.", "Nghe câu đó, trong lòng tôi đặc biệt vui."], [175.752, 180.364, "有一天下午很忙，我搬了很多箱子。", "Yǒu Yì Tiān Xià Wǔ Hěn Máng, Wǒ Bān Le Hěn Duō Xiāng Zi.", "Có một buổi chiều rất đông, tôi khiêng nhiều thùng."], [180.364, 186.56, "那天下午来了很多客人，书店里的人比平时多很多。", "Nà Tiān Xià Wǔ Lái Le Hěn Duō Kè Rén, Shū Diàn Lǐ De Rén Bǐ Píng Shí Duō Hěn Duō.", "Chiều hôm đó có nhiều khách đến, người trong tiệm đông hơn ngày thường rất nhiều."], [186.56, 192.684, "我一会儿整理书，一会儿回答问题，忙得没有时间喝水。", "Wǒ Yí Huì Er Zhěng Lǐ Shū, Yí Huì Er Huí Dá Wèn Tí, Máng Dé Méi Yǒu Shí Jiān Hē Shuǐ.", "Tôi lúc xếp sách, lúc trả lời câu hỏi, bận đến không có thời gian uống nước."], [192.684, 198.04, "下班的时候，腿有点儿累，心里却很高兴。", "Xià Bān De Shí Hou, Tuǐ Yǒu Diǎn Ér Lèi, Xīn Lǐ Què Hěn Gāo Xìng.", "Tan ca chân hơi mỏi nhưng trong lòng rất vui."], [198.04, 207.377, "老板走过来，笑着说：今天你做了很多事，做得很好，累了吧，回去好好休息吧。", "Lǎo Bǎn Zǒu Guò Lái, Xiào Zhe Shuō: Jīn Tiān Nǐ Zuò Le Hěn Duō Shì, Zuò Dé Hěn Hǎo, Lèi Le Ba, Huí Qù Hǎo Hao Xiū Xi Ba.", "Chủ tiệm đi tới, cười nói: Hôm nay cháu làm nhiều việc, làm rất tốt, mệt rồi phải không, về nghỉ ngơi cho khỏe nhé."], [207.377, 211.677, "一个星期结束，老板说我可以留下来。", "Yí Gè Xīng Qī Jié Shù, Lǎo Bǎn Shuō Wǒ Kě Yǐ Liú Xià Lái.", "Hết tuần chủ tiệm nói tôi có thể ở lại."], [211.677, 219.916, "老板笑着说：你认真，也愿意学，客人也喜欢你，我这里需要你这样的人。", "Lǎo Bǎn Xiào Zhe Shuō: Nǐ Rèn Zhēn, Yě Yuàn Yì Xué, Kè Rén Yě Xǐ Huan Nǐ, Wǒ Zhè Lǐ Xū Yào Nǐ Zhè Yàng De Rén.", "Chủ tiệm cười nói: Cháu nghiêm túc, cũng chịu học, khách cũng thích cháu, chỗ chú cần người như cháu."], [219.916, 224.048, "我回家把这个消息告诉了爸爸妈妈。", "Wǒ Huí Jiā Bǎ Zhè Ge Xiāo Xi Gào Su Le Bà Ba Mā Ma.", "Tôi về nhà báo tin này cho bố mẹ."], [224.048, 231.921, "妈妈笑着说：真好，工作的时候要认真，也要注意休息，别太累了。", "Mā Ma Xiào Zhe Shuō: Zhēn Hǎo, Gōng Zuò De Shí Hou Yào Rèn Zhēn, Yě Yào Zhù Yì Xiū Xi, Bié Tài Lèi Le.", "Mẹ cười nói: Tốt quá, làm việc phải nghiêm túc, cũng phải chú ý nghỉ ngơi, đừng mệt quá nhé."], [231.921, 238.477, "后面的几个星期，我每天都很早到书店，从来没有晚过。", "Hòu Miàn De Jǐ Gè Xīng Qī, Wǒ Měi Tiān Dōu Hěn Zǎo Dào Shū Diàn, Cóng Lái Méi Yǒu Wǎn Guò.", "Mấy tuần sau đó, ngày nào tôi cũng đến tiệm rất sớm, chưa bao giờ muộn."], [238.477, 245.853, "下雨的那天，客人很少，书店里很安静，我把书架都整理好了。", "Xià Yǔ De Nà Tiān, Kè Rén Hěn Shǎo, Shū Diàn Lǐ Hěn Ān Jìng, Wǒ Bǎ Shū Jià Dōu Zhěng Lǐ Hǎo Le.", "Ngày mưa, khách rất ít, trong tiệm sách rất yên tĩnh, tôi sắp xếp các kệ sách đâu vào đấy."], [245.853, 251.113, "拿到第一个月的工资，我买了一本想要的词典。", "Ná Dào Dì Yī Gè Yuè De Gōng Zī, Wǒ Mǎi Le Yì Běn Xiǎng Yào De Cí Diǎn.", "Nhận tháng lương đầu tiên, tôi mua cuốn từ điển mong muốn bấy lâu."], [251.113, 256.781, "买词典那天，我还有一点儿钱，给妈妈买了一本书。", "Mǎi Cí Diǎn Nà Tiān, Wǒ Hái Yǒu Yì Diǎn Ér Qián, Gěi Mā Ma Mǎi Le Yì Běn Shū.", "Ngày mua từ điển, tôi còn một ít tiền, mua cho mẹ một cuốn sách."], [256.781, 266.24, "妈妈拿到书，高兴得看了又看，说：这是你用工资买的，妈妈太高兴了，要好好留着。", "Mā Ma Ná Dào Shū, Gāo Xìng Dé Kàn Le Yòu Kàn, Shuō: Zhè Shì Nǐ Yòng Gōng Zī Mǎi De, Mā Ma Tài Gāo Xìng Le, Yào Hǎo Hao Liú Zhe.", "Mẹ cầm cuốn sách, vui đến xem đi xem lại, nói: Đây là sách con dùng tiền lương mua, mẹ vui lắm, sẽ giữ cẩn thận."], [266.24, 271.668, "工作让我知道了赚钱不容易，也更珍惜时间。", "Gōng Zuò Ràng Wǒ Zhī Dào Le Zhuàn Qián Bù Róng Yì, Yě Gèng Zhēn Xī Shí Jiān.", "Công việc này giúp tôi biết kiếm tiền khó và trân thời gian hơn."], [271.668, 279.661, "现在我用那本词典学习，每次打开它，我就想起在书店工作的那个暑假。", "Xiàn Zài Wǒ Yòng Nà Běn Cí Diǎn Xué Xí, Měi Cì Dǎ Kāi Tā, Wǒ Jiù Xiǎng Qǐ Zài Shū Diàn Gōng Zuò De Nà Ge Shǔ Jià.", "Giờ tôi dùng cuốn từ điển đó để học, mỗi lần mở nó ra, tôi lại nhớ đến mùa hè làm việc ở tiệm sách."], [279.661, 284.513, "明年如果还有假期，我还想去做兼职。", "Míng Nián Rú Guǒ Hái Yǒu Jià Qī, Wǒ Hái Xiǎng Qù Zuò Jiān Zhí.", "Năm sau nếu còn nghỉ, tôi vẫn muốn làm thêm."], [284.513, 291.021, "后来，我又去了那家书店，跟老板和同事说了一声谢谢。", "Hòu Lái, Wǒ Yòu Qù Le Nà Jiā Shū Diàn, Gēn Lǎo Bǎn Hé Tóng Shì Shuō Le Yì Shēng Xiè Xie.", "Sau đó, tôi lại đến tiệm sách đó, nói một lời cảm ơn với chủ tiệm và đồng nghiệp."], [291.021, 297.553, "老板笑着说：你能来，我们就很高兴，以后常来看看。", "Lǎo Bǎn Xiào Zhe Shuō: Nǐ Néng Lái, Wǒ Men Jiù Hěn Gāo Xìng, Yǐ Hòu Cháng Lái Kàn Kan.", "Chủ tiệm cười nói: Cháu đến được là chúng tôi vui rồi, sau này thường ghé qua nhé."]]}, "hsk3-26": {"dur": 268.97, "cues": [[8.057, 12.492, "那天晚上，我又玩手机玩到十二点。", "Nà Tiān Wǎn Shàng, Wǒ Yòu Wán Shǒu Jī Wán Dào Shí Èr Diǎn.", "Tối hôm đó, tôi lại chơi điện thoại đến mười hai giờ."], [12.492, 20.896, "妈妈走进我的房间，小声说，都十二点了，明天还要上课，你怎么还没睡？", "Mā Ma Zǒu Jìn Wǒ De Fáng Jiān, Xiǎo Shēng Shuō, Dōu Shí Èr Diǎn Le, Míng Tiān Hái Yào Shàng Kè, Nǐ Zěn Me Hái Méi Shuì?", "Mẹ bước vào phòng tôi, khẽ nói: Đã mười hai giờ rồi, mai còn phải đi học, sao con chưa ngủ?"], [20.896, 24.068, "我说，我再玩五分钟。", "Wǒ Shuō, Wǒ Zài Wán Wǔ Fēn Zhōng.", "Tôi nói: Con chơi thêm năm phút nữa."], [24.068, 28.212, "可是五分钟以后，我还在看手机。", "Kě Shì Wǔ Fēn Zhōng Yǐ Hòu, Wǒ Hái Zài Kàn Shǒu Jī.", "Nhưng năm phút sau, tôi vẫn đang xem điện thoại."], [28.212, 33.553, "有一段时间，我每天晚上玩手机玩到很晚。", "Yǒu Yí Duàn Shí Jiān, Wǒ Měi Tiān Wǎn Shàng Wán Shǒu Jī Wán Dào Hěn Wǎn.", "Có một thời gian tôi mỗi tối chơi điện thoại đến rất khuya."], [33.553, 38.909, "第二天上课总是没精神，作业也写得慢。", "Dì Èr Tiān Shàng Kè Zǒng Shì Méi Jīng Shén, Zuò Yè Yě Xiě Dé Màn.", "Hôm sau lên lớp lúc nào cũng uể oải, bài làm chậm."], [38.909, 45.009, "有一天早上，我起晚了，早饭也没吃就去了学校。", "Yǒu Yì Tiān Zǎo Shàng, Wǒ Qǐ Wǎn Le, Zǎo Fàn Yě Méi Chī Jiù Qù Le Xué Xiào.", "Một buổi sáng, tôi dậy muộn, chưa ăn sáng đã đi học."], [45.009, 51.502, "上课的时候，我的眼睛很累，老师的话我也听不清楚。", "Shàng Kè De Shí Hou, Wǒ De Yǎn Jing Hěn Lèi, Lǎo Shī De Huà Wǒ Yě Tīng Bù Qīng Chu.", "Trong giờ học, mắt tôi rất mỏi, lời cô tôi cũng nghe không rõ."], [51.502, 56.162, "老师找我谈话，建议我每天少玩一会儿。", "Lǎo Shī Zhǎo Wǒ Tán Huà, Jiàn Yì Wǒ Měi Tiān Shǎo Wán Yí Huì Er.", "Cô gọi tôi nói chuyện và khuyên mỗi ngày chơi ít hơn."], [56.162, 61.398, "老师问我，你每天晚上玩多长时间手机？", "Lǎo Shī Wèn Wǒ, Nǐ Měi Tiān Wǎn Shàng Wán Duō Cháng Shí Jiān Shǒu Jī?", "Cô hỏi tôi: Mỗi tối em chơi điện thoại bao lâu?"], [61.398, 64.546, "我小声说，我也不知道。", "Wǒ Xiǎo Shēng Shuō, Wǒ Yě Bù Zhī Dào.", "Tôi nói khẽ: Em cũng không biết."], [64.546, 71.959, "老师笑着说，没关系，你回家看一看手机上的时间，就知道了。", "Lǎo Shī Xiào Zhe Shuō, Méi Guān Xi, Nǐ Huí Jiā Kàn Yí Kàn Shǒu Jī Shàng De Shí Jiān, Jiù Zhī Dào Le.", "Cô cười nói: Không sao, em về nhà xem thời gian trên điện thoại là biết ngay."], [71.959, 77.699, "我算了一下，发现自己一天竟看了三个小时。", "Wǒ Suàn Le Yí Xià, Fā Xiàn Zì Jǐ Yì Tiān Jìng Kàn Le Sān Gè Xiǎo Shí.", "Tôi tính ra một ngày mình xem tới ba tiếng."], [77.699, 83.476, "我看着手机，心里想，三个小时真的太多了。", "Wǒ Kàn Zhe Shǒu Jī, Xīn Lǐ Xiǎng, Sān Gè Xiǎo Shí Zhēn De Tài Duō Le.", "Tôi nhìn điện thoại, nghĩ thầm: Ba tiếng thật sự quá nhiều."], [83.476, 87.776, "那天晚上，我和妈妈一起说这件事。", "Nà Tiān Wǎn Shàng, Wǒ Hé Mā Ma Yì Qǐ Shuō Zhè Jiàn Shì.", "Tối hôm đó, tôi cùng mẹ nói về chuyện này."], [87.776, 91.716, "妈妈说，我们一起想个好办法吧。", "Mā Ma Shuō, Wǒ Men Yì Qǐ Xiǎng Ge Hǎo Bàn Fǎ Ba.", "Mẹ nói: Chúng ta cùng nghĩ một cách hay nhé."], [91.716, 96.502, "我把这几句话写在纸上，贴在门上。", "Wǒ Bǎ Zhè Jǐ Jù Huà Xiě Zài Zhǐ Shàng, Tiē Zài Mén Shàng.", "Tôi viết mấy câu này lên giấy, dán lên cửa."], [96.502, 101.618, "从下周起，我把手机放在客厅充电。", "Cóng Xià Zhōu Qǐ, Wǒ Bǎ Shǒu Jī Fàng Zài Kè Tīng Chōng Diàn.", "Từ tuần sau tôi để điện thoại sạc ở phòng khách."], [101.618, 105.606, "只有作业做完，才能玩二十分钟。", "Zhǐ Yǒu Zuò Yè Zuò Wán, Cái Néng Wán Èr Shí Fēn Zhōng.", "Chỉ khi làm xong bài tập mới được chơi hai mươi phút."], [105.606, 111.874, "第一天，作业做完以后，我玩了二十分钟就停下了。", "Dì Yī Tiān, Zuò Yè Zuò Wán Yǐ Hòu, Wǒ Wán Le Èr Shí Fēn Zhōng Jiù Tíng Xià Le.", "Ngày đầu tiên, làm xong bài tập, tôi chơi hai mươi phút rồi dừng lại."], [111.874, 116.959, "可是手机就在客厅，我总想去看一看。", "Kě Shì Shǒu Jī Jiù Zài Kè Tīng, Wǒ Zǒng Xiǎng Qù Kàn Yí Kàn.", "Nhưng điện thoại ở ngay phòng khách, tôi cứ muốn ra xem."], [116.959, 122.387, "开始几天很想拿手机，我就去帮妈妈洗碗。", "Kāi Shǐ Jǐ Tiān Hěn Xiǎng Ná Shǒu Jī, Wǒ Jiù Qù Bāng Mā Ma Xǐ Wǎn.", "Mấy ngày đầu rất muốn cầm điện thoại, tôi đi giúp mẹ rửa bát."], [122.387, 127.06, "妈妈笑着说，今天的碗洗得很干净。", "Mā Ma Xiào Zhe Shuō, Jīn Tiān De Wǎn Xǐ Dé Hěn Gān Jìng.", "Mẹ cười nói: Hôm nay bát rửa sạch lắm."], [127.06, 132.075, "洗完碗，我又和妹妹在客厅玩了一会儿。", "Xǐ Wán Wǎn, Wǒ Yòu Hé Mèi Mei Zài Kè Tīng Wán Le Yí Huì Er.", "Rửa bát xong, tôi lại chơi với em gái ở phòng khách một lúc."], [132.075, 136.783, "晚上九点以后，我只看书或者听音乐。", "Wǎn Shàng Jiǔ Diǎn Yǐ Hòu, Wǒ Zhǐ Kàn Shū Huò Zhě Tīng Yīn Yuè.", "Sau chín giờ tối tôi chỉ đọc sách hoặc nghe nhạc."], [136.783, 141.323, "开始的时候，我看书看一会儿就想睡觉。", "Kāi Shǐ De Shí Hou, Wǒ Kàn Shū Kàn Yí Huì Er Jiù Xiǎng Shuì Jiào.", "Lúc đầu, đọc sách một lúc là tôi buồn ngủ."], [141.323, 147.331, "妈妈说，慢慢来，先早睡一天，再早睡一天。", "Mā Ma Shuō, Màn Màn Lái, Xiān Zǎo Shuì Yì Tiān, Zài Zǎo Shuì Yì Tiān.", "Mẹ nói: Cứ từ từ, ngủ sớm một ngày trước, rồi thêm một ngày nữa."], [147.331, 153.095, "有一天晚上，朋友给我打电话，叫我一起玩游戏。", "Yǒu Yì Tiān Wǎn Shàng, Péng You Gěi Wǒ Dǎ Diàn Huà, Jiào Wǒ Yì Qǐ Wán Yóu Xì.", "Một tối nọ, bạn gọi điện cho tôi, rủ chơi game cùng."], [153.095, 156.963, "我看了看时间，已经九点多了。", "Wǒ Kàn Le Kàn Shí Jiān, Yǐ Jīng Jiǔ Diǎn Duō Le.", "Tôi nhìn giờ, đã hơn chín giờ rồi."], [156.963, 162.559, "我对朋友说，今天太晚了，我们周末再玩吧。", "Wǒ Duì Péng You Shuō, Jīn Tiān Tài Wǎn Le, Wǒ Men Zhōu Mò Zài Wán Ba.", "Tôi nói với bạn: Hôm nay muộn quá rồi, cuối tuần mình chơi nhé."], [162.559, 168.299, "朋友说，好，没关系，那我们周末一起玩。", "Péng You Shuō, Hǎo, Méi Guān Xi, Nà Wǒ Men Zhōu Mò Yì Qǐ Wán.", "Bạn nói: Được, không sao đâu, vậy cuối tuần mình cùng chơi nhé."], [168.299, 175.125, "我回到房间以后，心里有一点儿不舒服，可是也有一点儿高兴。", "Wǒ Huí Dào Fáng Jiān Yǐ Hòu, Xīn Lǐ Yǒu Yì Diǎn Ér Bù Shū Fu, Kě Shì Yě Yǒu Yì Diǎn Ér Gāo Xìng.", "Về phòng, trong lòng tôi hơi khó chịu, nhưng cũng hơi vui."], [175.125, 180.409, "两个星期以后，我的眼睛没有以前那么累了。", "Liǎng Gè Xīng Qī Yǐ Hòu, Wǒ De Yǎn Jing Méi Yǒu Yǐ Qián Nà Me Lèi Le.", "Hai tuần sau mắt tôi không mỏi như trước."], [180.409, 184.733, "我早上也不用妈妈叫，自己就能起来。", "Wǒ Zǎo Shàng Yě Bú Yòng Mā Ma Jiào, Zì Jǐ Jiù Néng Qǐ Lái.", "Buổi sáng tôi cũng không cần mẹ gọi, tự dậy được."], [184.733, 189.87, "早饭我也能慢慢吃了，不用跑着去学校。", "Zǎo Fàn Wǒ Yě Néng Màn Màn Chī Le, Bú Yòng Pǎo Zhe Qù Xué Xiào.", "Bữa sáng tôi cũng ăn thong thả được, không phải chạy đến trường."], [189.87, 195.562, "上课能专心听讲，老师的问题我也能回答。", "Shàng Kè Néng Zhuān Xīn Tīng Jiǎng, Lǎo Shī De Wèn Tí Wǒ Yě Néng Huí Dá.", "Trong lớp tập trung nghe giảng và trả lời được câu hỏi của cô."], [195.562, 201.446, "有一次老师问了一个难问题，班里只有我回答对了。", "Yǒu Yí Cì Lǎo Shī Wèn Le Yí Gè Nán Wèn Tí, Bān Lǐ Zhǐ Yǒu Wǒ Huí Dá Duì Le.", "Có lần cô hỏi một câu khó, trong lớp chỉ mình tôi trả lời đúng."], [201.446, 207.234, "老师笑着说，你这几天上课比以前认真多了。", "Lǎo Shī Xiào Zhe Shuō, Nǐ Zhè Jǐ Tiān Shàng Kè Bǐ Yǐ Qián Rèn Zhēn Duō Le.", "Cô cười nói: Mấy hôm nay em học nghiêm túc hơn trước nhiều."], [207.234, 211.325, "听了老师的话，我心里特别高兴。", "Tīng Le Lǎo Shī De Huà, Wǒ Xīn Lǐ Tè Bié Gāo Xìng.", "Nghe lời cô, trong lòng tôi đặc biệt vui."], [211.325, 216.969, "周末我仍然可以玩一会儿游戏，但会按时停下。", "Zhōu Mò Wǒ Réng Rán Kě Yǐ Wán Yí Huì Er Yóu Xì, Dàn Huì Àn Shí Tíng Xià.", "Cuối tuần tôi vẫn chơi game một lát nhưng dừng đúng giờ."], [216.969, 222.757, "周末和朋友玩游戏的时候，我还告诉他们我的办法。", "Zhōu Mò Hé Péng You Wán Yóu Xì De Shí Hou, Wǒ Hái Gào Su Tā Men Wǒ De Bàn Fǎ.", "Cuối tuần chơi game với bạn, tôi còn kể cho các bạn cách của mình."], [222.757, 227.44, "有一个朋友说，他回家也想这样做。", "Yǒu Yí Gè Péng You Shuō, Tā Huí Jiā Yě Xiǎng Zhè Yàng Zuò.", "Một bạn nói, về nhà bạn ấy cũng muốn làm như vậy."], [227.44, 234.173, "现在，我每天晚上十点就睡觉，早上七点自己醒来。", "Xiàn Zài, Wǒ Měi Tiān Wǎn Shàng Shí Diǎn Jiù Shuì Jiào, Zǎo Shàng Qī Diǎn Zì Jǐ Xǐng Lái.", "Bây giờ mỗi tối mười giờ tôi đi ngủ, bảy giờ sáng tự tỉnh dậy."], [234.173, 240.321, "手机还是很有意思，可是我知道，时间是自己的。", "Shǒu Jī Hái Shì Hěn Yǒu Yì Si, Kě Shì Wǒ Zhī Dào, Shí Jiān Shì Zì Jǐ De.", "Điện thoại vẫn rất thú vị, nhưng tôi biết thời gian là của chính mình."], [240.321, 243.877, "我想，我会一直这样做下去。", "Wǒ Xiǎng, Wǒ Huì Yì Zhí Zhè Yàng Zuò Xià Qù.", "Tôi nghĩ mình sẽ cứ làm như vậy mãi."], [243.877, 248.513, "这样，我的眼睛不累，学习也更好了。", "Zhè Yàng, Wǒ De Yǎn Jing Bú Lèi, Xué Xí Yě Gèng Hǎo Le.", "Như vậy, mắt tôi không mỏi, học cũng tốt hơn."], [248.513, 253.864, "减少玩手机的时间，让我的生活更健康了。", "Jiǎn Shǎo Wán Shǒu Jī De Shí Jiān, Ràng Wǒ De Shēng Huó Gèng Jiàn Kāng Le.", "Giảm thời gian chơi điện thoại giúp cuộc sống tôi khỏe hơn."], [253.864, 259.744, "妈妈笑着对我说，看到你这样，妈妈真的很高兴。", "Mā Ma Xiào Zhe Duì Wǒ Shuō, Kàn Dào Nǐ Zhè Yàng, Mā Ma Zhēn De Hěn Gāo Xìng.", "Mẹ cười nói với tôi: Thấy con như vậy, mẹ thật sự rất vui."]]}, "hsk3-27": {"dur": 258.16, "cues": [[8.057, 12.501, "那天早上，我高高兴兴地走进教室。", "Nà Tiān Zǎo Shàng, Wǒ Gāo Gāo Xìng Xìng De Zǒu Jìn Jiào Shì.", "Sáng hôm đó, tôi vui vẻ bước vào lớp học."], [12.501, 17.972, "我对小刚说，早上好，今天的作业你做了吗？", "Wǒ Duì Xiǎo Gāng Shuō, Zǎo Shàng Hǎo, Jīn Tiān De Zuò Yè Nǐ Zuò Le Ma?", "Tôi nói với Tiểu Cương: Chào buổi sáng, bài tập hôm nay cậu làm chưa?"], [17.972, 23.208, "上周三，同桌小刚一整天都不跟我说话。", "Shàng Zhōu Sān, Tóng Zhuō Xiǎo Gāng Yì Zhěng Tiān Dōu Bù Gēn Wǒ Shuō Huà.", "Thứ Tư tuần trước bạn cùng bàn Tiểu Cương cả ngày không nói với tôi."], [23.208, 28.204, "小刚看了看我，什么也没说，就坐下了。", "Xiǎo Gāng Kàn Le Kàn Wǒ, Shén Me Yě Méi Shuō, Jiù Zuò Xià Le.", "Tiểu Cương nhìn tôi một cái, không nói gì, rồi ngồi xuống."], [28.204, 33.112, "我以为他生气了，可是我也不知道为什么。", "Wǒ Yǐ Wéi Tā Shēng Qì Le, Kě Shì Wǒ Yě Bù Zhī Dào Wèi Shén Me.", "Tôi tưởng cậu giận nhưng không biết vì sao."], [33.112, 38.324, "上课的时候，我把书给他看，他也不看我。", "Shàng Kè De Shí Hou, Wǒ Bǎ Shū Gěi Tā Kàn, Tā Yě Bú Kàn Wǒ.", "Trong giờ học, tôi đưa sách cho cậu xem, cậu cũng không nhìn tôi."], [38.324, 42.469, "我心里想，我做错了什么事吗？", "Wǒ Xīn Lǐ Xiǎng, Wǒ Zuò Cuò Le Shén Me Shì Ma?", "Tôi nghĩ thầm: Mình đã làm sai chuyện gì sao?"], [42.469, 48.065, "中午吃饭的时候，小刚一个人坐在很远的地方。", "Zhōng Wǔ Chī Fàn De Shí Hou, Xiǎo Gāng Yí Gè Rén Zuò Zài Hěn Yuǎn De Dì Fāng.", "Trưa ăn cơm, Tiểu Cương ngồi một mình ở chỗ rất xa."], [48.065, 53.104, "我想过去跟他说话，可是又有一点儿害怕。", "Wǒ Xiǎng Guò Qù Gēn Tā Shuō Huà, Kě Shì Yòu Yǒu Yì Diǎn Ér Hài Pà.", "Tôi muốn lại nói chuyện với cậu, nhưng lại hơi sợ."], [53.104, 58.028, "下午上课，老师的话我一句也听不懂。", "Xià Wǔ Shàng Kè, Lǎo Shī De Huà Wǒ Yí Jù Yě Tīng Bù Dǒng.", "Buổi chiều học, lời cô tôi một câu cũng không nghe vào được."], [58.028, 61.536, "我看着小刚，心里很难受。", "Wǒ Kàn Zhe Xiǎo Gāng, Xīn Lǐ Hěn Nán Shòu.", "Tôi nhìn Tiểu Cương, trong lòng rất khó chịu."], [61.536, 64.575, "我决定下课以后问他。", "Wǒ Jué Dìng Xià Kè Yǐ Hòu Wèn Tā.", "Tôi quyết định hết giờ sẽ hỏi cậu."], [64.575, 69.691, "下课的时候，我终于忍不住问他怎么回事。", "Xià Kè De Shí Hou, Wǒ Zhōng Yú Rěn Bù Zhù Wèn Tā Zěn Me Huí Shì.", "Hết giờ học tôi không chịu nổi và hỏi chuyện gì đã xảy ra."], [69.691, 74.759, "我小声问，小刚，你为什么不跟我说话？", "Wǒ Xiǎo Shēng Wèn, Xiǎo Gāng, Nǐ Wèi Shén Me Bù Gēn Wǒ Shuō Huà?", "Tôi khẽ hỏi: Tiểu Cương, sao cậu không nói chuyện với tớ?"], [74.759, 78.003, "小刚说，你自己看吧。", "Xiǎo Gāng Shuō, Nǐ Zì Jǐ Kàn Ba.", "Tiểu Cương nói: Cậu tự xem đi."], [78.003, 83.267, "他给我看手机，说我在群里说了他的坏话。", "Tā Gěi Wǒ Kàn Shǒu Jī, Shuō Wǒ Zài Qún Lǐ Shuō Le Tā De Huài Huà.", "Cậu cho xem tin nhắn và nói tôi nói xấu cậu trong nhóm."], [83.267, 89.127, "我一看，那根本不是我发的，是别人用了我的旧号。", "Wǒ Yì Kàn, Nà Gēn Běn Bú Shì Wǒ Fā De, Shì Bié Ren Yòng Le Wǒ De Jiù Hào.", "Tôi thấy đó không phải tôi gửi, ai đó dùng số cũ của tôi."], [89.127, 94.891, "我着急地说，这个号我早就不用了，真的不是我。", "Wǒ Zháo Jí De Shuō, Zhè Ge Hào Wǒ Zǎo Jiù Bú Yòng Le, Zhēn De Bú Shì Wǒ.", "Tôi sốt ruột nói: Số này tớ lâu rồi không dùng nữa, thật sự không phải tớ."], [94.891, 100.171, "小刚看着我，问，真的吗，那是谁发的？", "Xiǎo Gāng Kàn Zhe Wǒ, Wèn, Zhēn De Ma, Nà Shì Shéi Fā De?", "Tiểu Cương nhìn tôi, hỏi: Thật không, vậy ai gửi?"], [100.171, 104.927, "我说，我也不知道，我们去问班长吧。", "Wǒ Shuō, Wǒ Yě Bù Zhī Dào, Wǒ Men Qù Wèn Bān Zhǎng Ba.", "Tôi nói: Tớ cũng không biết, mình đi hỏi lớp trưởng đi."], [104.927, 109.491, "我们马上向班长说明，班长也帮我作证。", "Wǒ Men Mǎ Shàng Xiàng Bān Zhǎng Shuō Míng, Bān Zhǎng Yě Bāng Wǒ Zuò Zhèng.", "Chúng tôi ngay giải thích với lớp trưởng và cậu ấy làm chứng cho tôi."], [109.491, 116.695, "班长看了看手机，笑着说，你们别着急，这个号上周就换人了。", "Bān Zhǎng Kàn Le Kàn Shǒu Jī, Xiào Zhe Shuō, Nǐ Men Bié Zháo Jí, Zhè Ge Hào Shàng Zhōu Jiù Huàn Rén Le.", "Lớp trưởng xem điện thoại, cười nói: Các cậu đừng sốt ruột, số này tuần trước đã đổi người rồi."], [116.695, 122.276, "班长还说，他见过用这个号的人，不是我们班的。", "Bān Zhǎng Hái Shuō, Tā Jiàn Guò Yòng Zhè Ge Hào De Rén, Bú Shì Wǒ Men Bān De.", "Lớp trưởng còn nói, cậu ấy từng gặp người dùng số này, không phải lớp mình."], [122.276, 128.16, "听了班长的话，小刚不说话了，他的脸慢慢红了。", "Tīng Le Bān Zhǎng De Huà, Xiǎo Gāng Bù Shuō Huà Le, Tā De Liǎn Màn Màn Hóng Le.", "Nghe lời lớp trưởng, Tiểu Cương im lặng, mặt cậu từ từ đỏ lên."], [128.16, 133.204, "小刚红着脸向我道歉，我也松了一口气。", "Xiǎo Gāng Hóng Zhe Liǎn Xiàng Wǒ Dào Qiàn, Wǒ Yě Sōng Le Yì Kǒu Qì.", "Tiểu Cương đỏ mặt xin lỗi, tôi cũng thở phào."], [133.204, 138.484, "小刚说，对不起，我没问清楚就生气了。", "Xiǎo Gāng Shuō, Duì Bu Qǐ, Wǒ Méi Wèn Qīng Chu Jiù Shēng Qì Le.", "Tiểu Cương nói: Xin lỗi, tớ chưa hỏi rõ đã giận rồi."], [138.484, 143.888, "我说，没关系，我知道你心里也不舒服。", "Wǒ Shuō, Méi Guān Xi, Wǒ Zhī Dào Nǐ Xīn Lǐ Yě Bù Shū Fu.", "Tôi nói: Không sao, tớ biết trong lòng cậu cũng khó chịu."], [143.888, 147.865, "误会不说清楚，会让人真难受。", "Wù Huì Bù Shuō Qīng Chu, Huì Ràng Rén Zhēn Nán Shòu.", "Hiểu lầm mà không nói kịp thật khiến người ta khó chịu."], [147.865, 151.637, "那天下课以后，我们一起回家。", "Nà Tiān Xià Kè Yǐ Hòu, Wǒ Men Yì Qǐ Huí Jiā.", "Hôm đó sau giờ học, chúng tôi cùng về nhà."], [151.637, 157.473, "路上，小刚请我喝了一杯水，还跟我说对不起。", "Lù Shàng, Xiǎo Gāng Qǐng Wǒ Hē Le Yì Bēi Shuǐ, Hái Gēn Wǒ Shuō Duì Bu Qǐ.", "Trên đường, Tiểu Cương mời tôi uống một cốc nước, còn nói xin lỗi tôi."], [157.473, 162.54, "我笑着说，好了好了，这件事过去了。", "Wǒ Xiào Zhe Shuō, Hǎo Le Hǎo Le, Zhè Jiàn Shì Guò Qù Le.", "Tôi cười nói: Thôi nào, chuyện này qua rồi."], [162.54, 167.296, "从那以后，我们约好有事先当面问清楚。", "Cóng Nà Yǐ Hòu, Wǒ Men Yuē Hǎo Yǒu Shì Xiān Dāng Miàn Wèn Qīng Chu.", "Sau đó chúng tôi hẹn có chuyện gì hỏi trực tiếp trước."], [167.296, 172.826, "我们还说好，谁生气了，就先坐下来慢慢说。", "Wǒ Men Hái Shuō Hǎo, Shéi Shēng Qì Le, Jiù Xiān Zuò Xià Lái Màn Màn Shuō.", "Chúng tôi còn hẹn, ai giận thì ngồi xuống nói từ từ trước."], [172.826, 178.014, "我还改了群密码，提醒朋友不要乱开玩笑。", "Wǒ Hái Gǎi Le Qún Mì Mǎ, Tí Xǐng Péng You Bú Yào Luàn Kāi Wán Xiào.", "Tôi đổi mật khẩu nhóm, nhắc bạn đừng đùa bừa bãi."], [178.014, 183.252, "我也在群里告诉大家，那个旧号不是我的了。", "Wǒ Yě Zài Qún Lǐ Gào Su Dà Jiā, Nà Ge Jiù Hào Bú Shì Wǒ De Le.", "Tôi cũng nói với mọi người trong nhóm, số cũ đó không còn là của tôi nữa."], [183.252, 188.392, "发坏话的人看到了，也在群里说对不起。", "Fā Huài Huà De Rén Kàn Dào Le, Yě Zài Qún Lǐ Shuō Duì Bu Qǐ.", "Người gửi lời nói xấu thấy được, cũng nói xin lỗi trong nhóm."], [188.392, 194.398, "他说，他只是开玩笑，他也不知道我们会这么难受。", "Tā Shuō, Tā Zhǐ Shì Kāi Wán Xiào, Tā Yě Bù Zhī Dào Wǒ Men Huì Zhè Me Nán Shòu.", "Cậu ấy nói, mình chỉ đùa thôi, cũng không biết chúng ta lại khó chịu như vậy."], [194.398, 200.978, "小刚笑着说，好了，玩笑也要小心，不能让朋友难受。", "Xiǎo Gāng Xiào Zhe Shuō, Hǎo Le, Wán Xiào Yě Yào Xiǎo Xīn, Bù Néng Ràng Péng You Nán Shòu.", "Tiểu Cương cười nói: Thôi nào, đùa cũng phải cẩn thận, không thể làm bạn khó chịu."], [200.978, 206.142, "大家听了都笑了，说以后开玩笑要小心。", "Dà Jiā Tīng Le Dōu Xiào Le, Shuō Yǐ Hòu Kāi Wán Xiào Yào Xiǎo Xīn.", "Mọi người nghe xong đều cười, nói sau này đùa phải cẩn thận."], [206.142, 211.557, "这次经历让我知道，诚实和沟通都很重要。", "Zhè Cì Jīng Lì Ràng Wǒ Zhī Dào, Chéng Shí Hé Gōu Tōng Dōu Hěn Zhòng Yào.", "Lần này giúp tôi biết trung thực và giao tiếp đều quan trọng."], [211.557, 216.697, "第二天上课，小刚把他的笔记本借给我看。", "Dì Èr Tiān Shàng Kè, Xiǎo Gāng Bǎ Tā De Bǐ Jì Běn Jiè Gěi Wǒ Kàn.", "Hôm sau lên lớp, Tiểu Cương cho tôi mượn vở của cậu xem."], [216.697, 221.453, "我有一道题不会做，他慢慢讲给我听。", "Wǒ Yǒu Yí Dào Tí Bú Huì Zuò, Tā Màn Màn Jiǎng Gěi Wǒ Tīng.", "Tôi có một bài không biết làm, cậu giảng chậm rãi cho tôi nghe."], [221.453, 228.273, "小刚讲完以后，我会做了，我对他说，谢谢你，小刚。", "Xiǎo Gāng Jiǎng Wán Yǐ Hòu, Wǒ Huì Zuò Le, Wǒ Duì Tā Shuō, Xiè Xie Nǐ, Xiǎo Gāng.", "Tiểu Cương giảng xong, tôi đã biết làm, tôi nói với cậu: Cảm ơn cậu, Tiểu Cương."], [228.273, 236.31, "他笑着说，我们是同桌，也是好朋友，有你这样的朋友，我真的很高兴。", "Tā Xiào Zhe Shuō, Wǒ Men Shì Tóng Zhuō, Yě Shì Hǎo Péng You, Yǒu Nǐ Zhè Yàng De Péng You, Wǒ Zhēn De Hěn Gāo Xìng.", "Cậu cười nói: Chúng ta là bạn cùng bàn, cũng là bạn tốt, có người bạn như cậu, tớ thật sự rất vui."], [236.31, 241.906, "现在我和小刚又像以前一样，常常一起学习。", "Xiàn Zài Wǒ Hé Xiǎo Gāng Yòu Xiàng Yǐ Qián Yí Yàng, Cháng Cháng Yì Qǐ Xué Xí.", "Giờ tôi và Tiểu Cương lại học cùng nhau như xưa."], [241.906, 248.89, "我想，好朋友有话就要说出来，说出来以后，心里就舒服多了。", "Wǒ Xiǎng, Hǎo Péng You Yǒu Huà Jiù Yào Shuō Chū Lái, Shuō Chū Lái Yǐ Hòu, Xīn Lǐ Jiù Shū Fu Duō Le.", "Tôi nghĩ, bạn tốt có chuyện gì phải nói ra, nói ra rồi trong lòng sẽ dễ chịu hơn nhiều."]]}, "hsk3-28": {"dur": 258.52, "cues": [[7.941, 13.945, "那天早上，妈妈没有像每天一样早早起来做早饭。", "Nà Tiān Zǎo Shàng, Mā Ma Méi Yǒu Xiàng Měi Tiān Yí Yàng Zǎo Zǎo Qǐ Lái Zuò Zǎo Fàn.", "Sáng hôm đó, mẹ không dậy sớm làm bữa sáng như mọi ngày."], [13.945, 18.994, "我走进妈妈的房间，看见她还在床上。", "Wǒ Zǒu Jìn Mā Ma De Fáng Jiān, Kàn Jiàn Tā Hái Zài Chuáng Shàng.", "Tôi bước vào phòng mẹ, thấy mẹ vẫn còn trên giường."], [18.994, 24.014, "我问，妈妈，你怎么了，是不是不舒服？", "Wǒ Wèn, Mā Ma, Nǐ Zěn Me Le, Shì Bú Shì Bù Shū Fu?", "Tôi hỏi: Mẹ, mẹ sao vậy, có phải không khỏe không?"], [24.014, 29.443, "妈妈小声说，我头很疼，想再睡一会儿。", "Mā Ma Xiǎo Shēng Shuō, Wǒ Tóu Hěn Téng, Xiǎng Zài Shuì Yí Huì Er.", "Mẹ nói khẽ: Đầu mẹ đau lắm, muốn ngủ thêm một lúc."], [29.443, 34.583, "上个月妈妈感冒发烧，整个人都弱弱的。", "Shàng Gè Yuè Mā Ma Gǎn Mào Fā Shāo, Zhěng Gè Rén Dōu Ruò Ruò De.", "Tháng trước mẹ tôi cảm cúm sốt, người rất yếu."], [34.583, 40.923, "爸爸要上班，妹妹又还小，照顾她的任务落在我身上。", "Bà Ba Yào Shàng Bān, Mèi Mei Yòu Hái Xiǎo, Zhào Gù Tā De Rèn Wu Luò Zài Wǒ Shēn Shàng.", "Bố đi làm, em gái còn nhỏ, việc chăm mẹ giao cho tôi."], [40.923, 46.831, "爸爸出门以前对我说，今天你要好好照顾妈妈。", "Bà Ba Chū Mén Yǐ Qián Duì Wǒ Shuō, Jīn Tiān Nǐ Yào Hǎo Hāo Zhào Gù Mā Ma.", "Trước khi ra khỏi nhà, bố nói với tôi: Hôm nay con phải chăm sóc mẹ cho tốt."], [46.831, 51.323, "我说，爸爸，你放心，我能做好。", "Wǒ Shuō, Bà Ba, Nǐ Fàng Xīn, Wǒ Néng Zuò Hǎo.", "Tôi nói: Bố, bố yên tâm, con làm được."], [51.323, 57.4, "爸爸还说，妈妈更不舒服的时候，你马上给我打电话。", "Bà Ba Hái Shuō, Mā Ma Gèng Bù Shū Fu De Shí Hou, Nǐ Mǎ Shàng Gěi Wǒ Dǎ Diàn Huà.", "Bố còn nói: Lúc mẹ khó chịu hơn, con gọi điện cho bố ngay."], [57.4, 62.206, "我先给妈妈一杯热水，让她慢慢喝。", "Wǒ Xiān Gěi Mā Ma Yì Bēi Rè Shuǐ, Ràng Tā Màn Màn Hē.", "Tôi đưa mẹ một cốc nước nóng trước, để mẹ uống từ từ."], [62.206, 66.29, "我去药店买了药，很快就回来了。", "Wǒ Qù Yào Diàn Mǎi Le Yào, Hěn Kuài Jiù Huí Lái Le.", "Tôi ra hiệu thuốc mua thuốc rồi nhanh chóng quay về."], [66.29, 70.038, "药店的人问我，是谁生病了？", "Yào Diàn De Rén Wèn Wǒ, Shì Shéi Shēng Bìng Le?", "Người ở hiệu thuốc hỏi tôi: Ai bị ốm vậy?"], [70.038, 74.386, "我说，是我妈妈，她感冒发烧了。", "Wǒ Shuō, Shì Wǒ Mā Ma, Tā Gǎn Mào Fā Shāo Le.", "Tôi nói: Là mẹ tôi, mẹ bị cảm và sốt."], [74.386, 80.852, "他给了我药，还笑着说，先让妈妈喝热水，再吃药。", "Tā Gěi Le Wǒ Yào, Hái Xiào Zhe Shuō, Xiān Ràng Mā Ma Hē Rè Shuǐ, Zài Chī Yào.", "Anh ấy đưa thuốc cho tôi, còn cười dặn: Cho mẹ uống nước nóng trước, rồi mới uống thuốc."], [80.852, 87.48, "回家以后，我把手放在妈妈的头上，妈妈的头还是很热。", "Huí Jiā Yǐ Hòu, Wǒ Bǎ Shǒu Fàng Zài Mā Ma De Tóu Shàng, Mā Ma De Tóu Hái Shì Hěn Rè.", "Về đến nhà, tôi đặt tay lên trán mẹ, trán mẹ vẫn rất nóng."], [87.48, 91.278, "我让妈妈吃完药，好好休息。", "Wǒ Ràng Mā Ma Chī Wán Yào, Hǎo Hāo Xiū Xi.", "Tôi để mẹ uống thuốc xong, nghỉ ngơi cho khỏe."], [91.278, 96.202, "中午我煮了稀饭，一口一口地喂她吃。", "Zhōng Wǔ Wǒ Zhǔ Le Xī Fàn, Yì Kǒu Yì Kǒu De Wèi Tā Chī.", "Trưa tôi nấu cháo và bón từng thìa."], [96.202, 103.236, "煮稀饭的时候，我站在旁边，一直看着，心里只想着妈妈。", "Zhǔ Xī Fàn De Shí Hou, Wǒ Zhàn Zài Páng Biān, Yì Zhí Kàn Zhe, Xīn Lǐ Zhǐ Xiǎng Zhe Mā Ma.", "Khi nấu cháo, tôi đứng bên cạnh trông mãi, trong lòng chỉ nghĩ đến mẹ."], [103.236, 109.456, "妈妈吃了几口，慢慢笑着说，今天的稀饭真好吃。", "Mā Ma Chī Le Jǐ Kǒu, Màn Màn Xiào Zhe Shuō, Jīn Tiān De Xī Fàn Zhēn Hǎo Chī.", "Mẹ ăn mấy miếng, từ từ mỉm cười nói: Cháo hôm nay ngon thật đấy."], [109.456, 114.08, "我听了很高兴，又给她喝了一点儿水。", "Wǒ Tīng Le Hěn Gāo Xìng, Yòu Gěi Tā Hē Le Yì Diǎn Ér Shuǐ.", "Nghe vậy tôi rất vui, lại cho mẹ uống thêm chút nước."], [114.08, 119.46, "妈妈不能起床，我就把毛巾放在她额头上。", "Mā Ma Bù Néng Qǐ Chuáng, Wǒ Jiù Bǎ Máo Jīn Fàng Zài Tā É Tóu Shàng.", "Mẹ không dậy được, tôi đặt khăn lên trán bà."], [119.46, 124.459, "毛巾热了，我就去洗一洗，再放回去。", "Máo Jīn Rè Le, Wǒ Jiù Qù Xǐ Yì Xǐ, Zài Fàng Huí Qù.", "Khăn nóng lên, tôi lại đi giặt rồi đặt lại."], [124.459, 129.719, "妹妹站在门口，小声问，妈妈好点儿了吗？", "Mèi Mei Zhàn Zài Mén Kǒu, Xiǎo Shēng Wèn, Mā Ma Hǎo Diǎn Ér Le Ma?", "Em gái đứng ở cửa, khẽ hỏi: Mẹ đỡ hơn chưa?"], [129.719, 134.234, "我说，妈妈在睡觉，我们小声一点儿。", "Wǒ Shuō, Mā Ma Zài Shuì Jiào, Wǒ Men Xiǎo Shēng Yì Diǎn Ér.", "Tôi nói: Mẹ đang ngủ, chúng ta nói khẽ một chút."], [134.234, 139.645, "晚上她没有胃口，我就坐在旁边跟她说话。", "Wǎn Shàng Tā Méi Yǒu Wèi Kǒu, Wǒ Jiù Zuò Zài Páng Biān Gēn Tā Shuō Huà.", "Tối mẹ chán ăn, tôi ngồi bên cạnh nói chuyện."], [139.645, 144.353, "妹妹想进房间，我先让她安静一点儿。", "Mèi Mei Xiǎng Jìn Fáng Jiān, Wǒ Xiān Ràng Tā ān Jìng Yì Diǎn Ér.", "Em muốn vào phòng, tôi bảo em yên lặng một chút."], [144.353, 149.908, "妹妹听了，就坐在客厅看书，没有大声说话。", "Mèi Mei Tīng Le, Jiù Zuò Zài Kè Tīng Kàn Shū, Méi Yǒu Dà Shēng Shuō Huà.", "Em nghe xong, ngồi ở phòng khách đọc sách, không nói to."], [149.908, 156.296, "晚上爸爸回来了，他看了看妈妈，问我，妈妈今天怎么样？", "Wǎn Shàng Bà Ba Huí Lái Le, Tā Kàn Le Kàn Mā Ma, Wèn Wǒ, Mā Ma Jīn Tiān Zěn Me Yàng?", "Tối bố về, bố nhìn mẹ, hỏi tôi: Hôm nay mẹ thế nào?"], [156.296, 161.316, "我说，妈妈吃了药，也吃了一点儿稀饭。", "Wǒ Shuō, Mā Ma Chī Le Yào, Yě Chī Le Yì Diǎn Ér Xī Fàn.", "Tôi nói: Mẹ đã uống thuốc, cũng ăn được một ít cháo."], [161.316, 166.441, "爸爸说，你做得很好，今天你很累吧。", "Bà Ba Shuō, Nǐ Zuò Dé Hěn Hǎo, Jīn Tiān Nǐ Hěn Lèi Ba.", "Bố nói: Con làm rất tốt, hôm nay con mệt lắm nhỉ."], [166.441, 171.965, "第二天早上，妈妈还是发烧，我有点儿担心。", "Dì Èr Tiān Zǎo Shàng, Mā Ma Hái Shì Fā Shāo, Wǒ Yǒu Diǎn Ér Dān Xīn.", "Sáng hôm sau, mẹ vẫn sốt, tôi hơi lo."], [171.965, 176.001, "我给爸爸打电话，问要不要去医院。", "Wǒ Gěi Bà Ba Dǎ Diàn Huà, Wèn Yào Bú Yào Qù Yī Yuàn.", "Tôi gọi điện cho bố, hỏi có cần đi bệnh viện không."], [176.001, 181.719, "爸爸说，先吃药，多喝水，下午再看看。", "Bà Ba Shuō, Xiān Chī Yào, Duō Hē Shuǐ, Xià Wǔ Zài Kàn Kan.", "Bố nói: Uống thuốc trước, uống nhiều nước, chiều xem lại."], [181.719, 187.003, "妈妈握着我的手说，不要担心，妈妈没事。", "Mā Ma Wò Zhe Wǒ De Shǒu Shuō, Bú Yào Dān Xīn, Mā Ma Méi Shì.", "Mẹ nắm tay tôi nói: Đừng lo, mẹ không sao."], [187.003, 192.772, "那一天，我一直坐在妈妈旁边，她睡我就看书。", "Nà Yì Tiān, Wǒ Yì Zhí Zuò Zài Mā Ma Páng Biān, Tā Shuì Wǒ Jiù Kàn Shū.", "Hôm đó, tôi luôn ngồi bên mẹ, mẹ ngủ thì tôi đọc sách."], [192.772, 198.32, "三天以后，妈妈的烧退了，脸色也好多了。", "Sān Tiān Yǐ Hòu, Mā Ma De Shāo Tuì Le, Liǎn Sè Yě Hǎo Duō Le.", "Ba ngày sau sốt của mẹ đã hạ, mặt mẹ cũng đỡ hơn."], [198.32, 203.268, "妈妈能自己坐起来了，还喝了一碗稀饭。", "Mā Ma Néng Zì Jǐ Zuò Qǐ Lái Le, Hái Hē Le Yì Wǎn Xī Fàn.", "Mẹ tự ngồi dậy được rồi, còn ăn hết một bát cháo."], [203.268, 207.16, "她笑着说，这几天你最累了。", "Tā Xiào Zhe Shuō, Zhè Jǐ Tiān Nǐ Zuì Lèi Le.", "Mẹ cười nói: Mấy hôm nay con vất vả nhất."], [207.16, 212.23, "她握着我的手说，谢谢你这几天的照顾。", "Tā Wò Zhe Wǒ De Shǒu Shuō, Xiè Xie Nǐ Zhè Jǐ Tiān De Zhào Gù.", "Bà nắm tay tôi và cảm ơn những ngày chăm sóc."], [212.23, 218.234, "我虽然很累，可是看到妈妈好起来，心里很高兴。", "Wǒ Suī Rán Hěn Lèi, Kě Shì Kàn Dào Mā Ma Hǎo Qǐ Lái, Xīn Lǐ Hěn Gāo Xìng.", "Tôi mệt nhưng thấy mẹ khỏe lại thì rất vui."], [218.234, 223.254, "晚上，妈妈做了一碗汤，让我们一起喝。", "Wǎn Shàng, Mā Ma Zuò Le Yì Wǎn Tāng, Ràng Wǒ Men Yì Qǐ Hē.", "Buổi tối, mẹ nấu một bát canh, bảo chúng tôi cùng ăn."], [223.254, 230.388, "爸爸笑着说，以后我们都要多照顾妈妈，妈妈好了，我们都高兴。", "Bà Ba Xiào Zhe Shuō, Yǐ Hòu Wǒ Men Dōu Yào Duō Zhào Gù Mā Ma, Mā Ma Hǎo Le, Wǒ Men Dōu Gāo Xìng.", "Bố cười nói: Sau này chúng ta đều phải chăm sóc mẹ nhiều hơn, mẹ khỏe rồi, cả nhà mình đều vui."], [230.388, 234.208, "妹妹说，她也要学着照顾妈妈。", "Mèi Mei Shuō, Tā Yě Yào Xué Zhe Zhào Gù Mā Ma.", "Em gái nói, em cũng muốn học chăm sóc mẹ."], [234.208, 240.02, "这次让我知道了，家人生病时每个人都要出力。", "Zhè Cì Ràng Wǒ Zhī Dào Le, Jiā Rén Shēng Bìng Shí Měi Gè Rén Dōu Yào Chū Lì.", "Lần này giúp tôi biết khi người nhà ốm, mỗi người đều phải góp sức."], [240.02, 244.104, "以后家人不舒服，我也会这样做。", "Yǐ Hòu Jiā Rén Bù Shū Fu, Wǒ Yě Huì Zhè Yàng Zuò.", "Sau này nếu bố hoặc em không khỏe, tôi cũng sẽ làm như vậy."], [244.104, 249.244, "因为我知道，家人好了，家里就温暖了。", "Yīn Wèi Wǒ Zhī Dào, Jiā Rén Hǎo Le, Jiā Lǐ Jiù Wēn Nuǎn Le.", "Vì tôi biết, người nhà khỏe rồi, nhà sẽ ấm áp."]]}, "hsk3-29": {"dur": 275.33, "cues": [[7.546, 12.494, "新学期开始，学校门口贴着兴趣班广告。", "Xīn Xué Qī Kāi Shǐ, Xué Xiào Mén Kǒu Tiē Zhe Xìng Qù Bān Guǎng Gào.", "Học kỳ mới bắt đầu, cổng trường dán quảng cáo tuyển lớp ngoại khóa."], [12.494, 18.642, "我看了看广告，有唱歌班、画画班，还有运动班。", "Wǒ Kàn Le Kàn Guǎng Gào, Yǒu Chàng Gē Bān, Huà Huà Bān, Hái Yǒu Yùn Dòng Bān.", "Tôi xem quảng cáo, có lớp hát, lớp vẽ, còn có lớp thể thao."], [18.642, 23.592, "我站在门口想了很久，还是想学唱歌。", "Wǒ Zhàn Zài Mén Kǒu Xiǎng Le Hěn Jiǔ, Hái Shì Xiǎng Xué Chàng Gē.", "Tôi đứng ở cổng nghĩ rất lâu, vẫn muốn học hát."], [23.592, 27.94, "回家以后，我跟妈妈说了这件事。", "Huí Jiā Yǐ Hòu, Wǒ Gēn Mā Ma Shuō Le Zhè Jiàn Shì.", "Về nhà, tôi kể chuyện này với mẹ."], [27.94, 34.328, "妈妈问我，你真的想学唱歌吗，学唱歌要花很多时间。", "Mā Ma Wèn Wǒ, Nǐ Zhēn De Xiǎng Xué Chàng Gē Ma, Xué Chàng Gē Yào Huā Hěn Duō Shí Jiān.", "Mẹ hỏi tôi: Con thật sự muốn học hát à, học hát tốn nhiều thời gian đấy."], [34.328, 39.218, "我说，我想学唱歌，我会好好练的。", "Wǒ Shuō, Wǒ Xiǎng Xué Chàng Gē, Wǒ Huì Hǎo Hǎo Liàn De.", "Tôi nói: Con muốn học hát, con sẽ luyện tập chăm chỉ."], [39.218, 44.287, "我一直想学唱歌，就报名参加了唱歌班。", "Wǒ Yì Zhí Xiǎng Xué Chàng Gē, Jiù Bào Míng Cān Jiā Le Chàng Gē Bān.", "Tôi luôn muốn học hát nên đăng ký tham gia lớp hát."], [44.287, 49.738, "报名那天，老师问我，你以前学过唱歌吗？", "Bào Míng Nà Tiān, Lǎo Shī Wèn Wǒ, Nǐ Yǐ Qián Xué Guò Chàng Gē Ma?", "Ngày đăng ký, thầy hỏi tôi: Trước đây em từng học hát chưa?"], [49.738, 53.294, "我说，没有，这是第一次。", "Wǒ Shuō, Méi Yǒu, Zhè Shì Dì Yī Cì.", "Tôi nói: Chưa ạ, đây là lần đầu tiên."], [53.294, 59.025, "老师笑着说，没关系，我们从最简单的开始。", "Lǎo Shī Xiào Zhe Shuō, Méi Guān Xi, Wǒ Men Cóng Zuì Jiǎn Dān De Kāi Shǐ.", "Thầy cười nói: Không sao, chúng ta bắt đầu từ cái đơn giản nhất."], [59.025, 64.237, "第一次上课，老师让我们先听简单的节拍。", "Dì Yī Cì Shàng Kè, Lǎo Shī Ràng Wǒ Men Xiān Tīng Jiǎn Dān De Jié Pāi.", "Buổi học đầu cô bảo nghe nhịp đơn giản trước."], [64.237, 68.681, "老师用手打节拍，让我们和他一起打。", "Lǎo Shī Yòng Shǒu Dǎ Jié Pāi, Ràng Wǒ Men Hé Tā Yì Qǐ Dǎ.", "Thầy dùng tay gõ nhịp, bảo chúng tôi gõ cùng thầy."], [68.681, 72.121, "我打得不好，总是慢一点儿。", "Wǒ Dǎ Dé Bù Hǎo, Zǒng Shì Màn Yì Diǎn Ér.", "Tôi gõ không tốt, lúc nào cũng chậm một chút."], [72.121, 77.381, "旁边的一个同学小声告诉我，先听，再打。", "Páng Biān De Yí Gè Tóng Xué Xiǎo Shēng Gào Su Wǒ, Xiān Tīng, Zài Dǎ.", "Một bạn bên cạnh khẽ bảo tôi: Nghe trước, rồi gõ."], [77.381, 81.873, "我唱了一遍又一遍，声音还是不清楚。", "Wǒ Chàng Le Yí Biàn Yòu Yí Biàn, Shēng Yīn Hái Shì Bù Qīng Chu.", "Tôi hát đi hát lại nhiều lần, giọng vẫn chưa rõ."], [81.873, 85.837, "下课以后，我的声音还是很小。", "Xià Kè Yǐ Hòu, Wǒ De Shēng Yīn Hái Shì Hěn Xiǎo.", "Sau giờ học, giọng tôi vẫn còn rất nhỏ."], [85.837, 89.861, "我心里想，学唱歌真的这么难吗？", "Wǒ Xīn Lǐ Xiǎng, Xué Chàng Gē Zhēn De Zhè Me Nán Ma?", "Tôi nghĩ thầm: Học hát thật sự khó thế này sao?"], [89.861, 95.991, "回家以后，我每天练二十分钟，声音慢慢清楚了。", "Huí Jiā Yǐ Hòu, Wǒ Měi Tiān Liàn Èr Shí Fēn Zhōng, Shēng Yīn Màn Màn Qīng Chu Le.", "Về nhà mỗi ngày tôi luyện hai mươi phút, giọng dần rõ hơn."], [95.991, 100.603, "有一天，我练了十分钟就不想练了。", "Yǒu Yì Tiān, Wǒ Liàn Le Shí Fēn Zhōng Jiù Bù Xiǎng Liàn Le.", "Có một hôm, tôi luyện mười phút đã không muốn luyện nữa."], [100.603, 106.439, "妈妈看见了，坐在我旁边说，休息一会儿再练吧。", "Mā Ma Kàn Jiàn Le, Zuò Zài Wǒ Páng Biān Shuō, Xiū Xi Yí Huì Er Zài Liàn Ba.", "Mẹ thấy vậy, ngồi bên tôi nói: Nghỉ một lúc rồi luyện tiếp nhé."], [106.439, 111.747, "休息的时候，妈妈给我听了一首好听的曲子。", "Xiū Xi De Shí Hou, Mā Ma Gěi Wǒ Tīng Le Yì Shǒu Hǎo Tīng De Qǔ Zi.", "Lúc nghỉ, mẹ cho tôi nghe một bản nhạc hay."], [111.747, 116.657, "我听了以后，又站起来，慢慢唱了起来。", "Wǒ Tīng Le Yǐ Hòu, Yòu Zhàn Qǐ Lái, Màn Màn Chàng Le Qǐ Lái.", "Nghe xong, tôi lại đứng dậy, từ từ hát tiếp."], [116.657, 121.101, "两周后，我能唱第一首短曲子了。", "Liǎng Zhōu Hòu, Wǒ Néng Chàng Dì Yī Shǒu Duǎn Qǔ Zi Le.", "Hai tuần sau tôi hát được bài ngắn đầu tiên."], [121.101, 125.761, "我把这首曲子唱给妈妈听，妈妈一直笑。", "Wǒ Bǎ Zhè Shǒu Qǔ Zi Chàng Gěi Mā Ma Tīng, Mā Ma Yì Zhí Xiào.", "Tôi hát bài này cho mẹ nghe, mẹ cười mãi."], [125.761, 130.519, "妈妈笑着说，你唱得比上周好多了。", "Mā Ma Xiào Zhe Shuō, Nǐ Chàng Dé Bǐ Shàng Zhōu Hǎo Duō Le.", "Mẹ cười nói: Con hát hay hơn tuần trước nhiều."], [130.519, 135.299, "同学们来自不同年级，大家常常一起练。", "Tóng Xué Men Lái Zì Bù Tóng Nián Jí, Dà Jiā Cháng Cháng Yì Qǐ Liàn.", "Bạn trong lớp nhạc đến từ nhiều khối, thường tập cùng nhau."], [135.299, 139.983, "班里有一个同学比我大，他唱得很好。", "Bān Lǐ Yǒu Yí Gè Tóng Xué Bǐ Wǒ Dà, Tā Chàng Dé Hěn Hǎo.", "Trong lớp có một bạn lớn hơn tôi, bạn ấy hát rất hay."], [139.983, 143.683, "我不会的地方，他就慢慢教我。", "Wǒ Bú Huì De Dì Fāng, Tā Jiù Màn Màn Jiāo Wǒ.", "Chỗ nào tôi không biết, bạn ấy từ từ dạy tôi."], [143.683, 147.335, "我也帮班里的小同学听节拍。", "Wǒ Yě Bāng Bān Lǐ De Xiǎo Tóng Xué Tīng Jié Pāi.", "Tôi cũng giúp các bạn nhỏ trong lớp nghe nhịp."], [147.335, 151.882, "大家一起练的时候，我觉得特别有意思。", "Dà Jiā Yì Qǐ Liàn De Shí Hou, Wǒ Jué De Tè Bié Yǒu Yì Si.", "Khi mọi người luyện cùng nhau, tôi thấy đặc biệt thú vị."], [151.882, 157.526, "有一天，老师告诉我们，下个月有一次演出。", "Yǒu Yì Tiān, Lǎo Shī Gào Su Wǒ Men, Xià Ge Yuè Yǒu Yí Cì Yǎn Chū.", "Một hôm, thầy bảo chúng tôi: Tháng sau có một buổi biểu diễn."], [157.526, 161.25, "我听了，心里又高兴又紧张。", "Wǒ Tīng Le, Xīn Lǐ Yòu Gāo Xìng Yòu Jǐn Zhāng.", "Nghe xong, trong lòng tôi vừa vui vừa hồi hộp."], [161.25, 166.51, "老师说，我们要一起练一首长一点儿的曲子。", "Lǎo Shī Shuō, Wǒ Men Yào Yì Qǐ Liàn Yì Shǒu Cháng Yì Diǎn Ér De Qǔ Zi.", "Thầy nói: Chúng ta sẽ cùng luyện một bản nhạc dài hơn một chút."], [166.51, 172.202, "从那天起，我们每天下课以后多练二十分钟。", "Cóng Nà Tiān Qǐ, Wǒ Men Měi Tiān Xià Kè Yǐ Hòu Duō Liàn Èr Shí Fēn Zhōng.", "Từ hôm đó, mỗi ngày sau giờ học chúng tôi luyện thêm hai mươi phút."], [172.202, 176.19, "有一次我唱错了，心里很着急。", "Yǒu Yí Cì Wǒ Chàng Cuò Le, Xīn Lǐ Hěn Zháo Jí.", "Có lần tôi hát sai, trong lòng rất sốt ruột."], [176.19, 182.184, "同学小声说，没关系，慢慢来，我们再练一次。", "Tóng Xué Xiǎo Shēng Shuō, Méi Guān Xi, Màn Màn Lái, Wǒ Men Zài Liàn Yí Cì.", "Bạn khẽ nói: Không sao, cứ từ từ, chúng ta luyện lại một lần."], [182.184, 189.707, "演出那天，我们站在大家前面，心里有点儿紧张，可是掌声很大。", "Yǎn Chū Nà Tiān, Wǒ Men Zhàn Zài Dà Jiā Qián Miàn, Xīn Lǐ Yǒu Diǎn Ér Jǐn Zhāng, Kě Shì Zhǎng Shēng Hěn Dà.", "Ngày biểu diễn, chúng tôi đứng trước mọi người, trong lòng hơi hồi hộp, nhưng tiếng vỗ tay rất lớn."], [189.707, 197.127, "演出以前，老师对我们说，不要紧张，就像每天练习的时候一样。", "Yǎn Chū Yǐ Qián, Lǎo Shī Duì Wǒ Men Shuō, Bú Yào Jǐn Zhāng, Jiù Xiàng Měi Tiān Liàn Xí De Shí Hou Yí Yàng.", "Trước buổi biểu diễn, thầy nói với chúng tôi: Đừng hồi hộp, cứ như lúc luyện tập mỗi ngày."], [197.127, 201.154, "演出开始以后，我慢慢不紧张了。", "Yǎn Chū Kāi Shǐ Yǐ Hòu, Wǒ Màn Màn Bù Jǐn Zhāng Le.", "Buổi biểu diễn bắt đầu, tôi dần không hồi hộp nữa."], [201.154, 206.798, "我们唱完了最后一首曲子，下面的人都站起来了。", "Wǒ Men Chàng Wán Le Zuì Hòu Yì Shǒu Qǔ Zi, Xià Miàn De Rén Dōu Zhàn Qǐ Lái Le.", "Chúng tôi hát xong bài cuối cùng, mọi người ở dưới đều đứng dậy."], [206.798, 211.914, "妈妈坐在下面对我笑，我感到特别自豪。", "Mā Ma Zuò Zài Xià Miàn Duì Wǒ Xiào, Wǒ Gǎn Dào Tè Bié Zì Háo.", "Mẹ ngồi ở dưới cười với tôi, tôi thấy rất tự hào."], [211.914, 219.359, "演出完了以后，妈妈笑着说，你今天唱得真好，妈妈真的很高兴。", "Yǎn Chū Wán Le Yǐ Hòu, Mā Ma Xiào Zhe Shuō, Nǐ Jīn Tiān Chàng Dé Zhēn Hǎo, Mā Ma Zhēn De Hěn Gāo Xìng.", "Biểu diễn xong, mẹ cười nói: Hôm nay con hát hay thật, mẹ thật sự rất vui."], [219.359, 223.059, "我说，是老师和同学帮了我。", "Wǒ Shuō, Shì Lǎo Shī Hé Tóng Xué Bāng Le Wǒ.", "Tôi nói: Là nhờ thầy và các bạn giúp con."], [223.059, 227.741, "老师鼓励我坚持，说进步需要花时间。", "Lǎo Shī Gǔ Lì Wǒ Jiān Chí, Shuō Jìn Bù Xū Yào Huā Shí Jiān.", "Cô khích lệ tôi kiên trì và nói tiến bộ cần thời gian."], [227.741, 233.593, "回家的路上，我唱着歌，心里想着下一次演出。", "Huí Jiā De Lù Shàng, Wǒ Chàng Zhe Gē, Xīn Lǐ Xiǎng Zhe Xià Yí Cì Yǎn Chū.", "Trên đường về nhà, tôi vừa đi vừa hát, trong lòng nghĩ đến buổi biểu diễn lần sau."], [233.593, 238.794, "现在除了写作业，我也会留一点时间唱歌。", "Xiàn Zài Chú Le Xiě Zuò Yè, Wǒ Yě Huì Liú Yì Diǎn Shí Jiān Chàng Gē.", "Giờ ngoài làm bài tập tôi cũng dành chút thời gian để hát."], [238.794, 244.654, "有时候妹妹坐在旁边听我唱歌，她说她也想学。", "Yǒu Shí Hou Mèi Mei Zuò Zài Páng Biān Tīng Wǒ Chàng Gē, Tā Shuō Tā Yě Xiǎng Xué.", "Đôi khi em gái ngồi bên nghe tôi hát, em nói em cũng muốn học."], [244.654, 249.578, "我就教她最简单的节拍，她打得很高兴。", "Wǒ Jiù Jiāo Tā Zuì Jiǎn Dān De Jié Pāi, Tā Dǎ Dé Hěn Gāo Xìng.", "Tôi dạy em nhịp đơn giản nhất, em gõ rất vui."], [249.578, 255.006, "参加兴趣班让我的周末更快乐，也更自信了。", "Cān Jiā Xìng Qù Bān Ràng Wǒ De Zhōu Mò Gèng Kuài Lè, Yě Gèng Zì Xìn Le.", "Tham gia lớp ngoại khóa làm cuối tuần vui hơn và tự tin hơn."], [255.006, 260.914, "下个学期，我还要参加唱歌班，学更长的曲子。", "Xià Ge Xué Qī, Wǒ Hái Yào Cān Jiā Chàng Gē Bān, Xué Gèng Cháng De Qǔ Zi.", "Học kỳ sau, tôi vẫn tham gia lớp hát, học những bài dài hơn."], [260.914, 266.15, "妈妈笑着说，好，妈妈等着听你唱新歌。", "Mā Ma Xiào Zhe Shuō, Hǎo, Mā Ma Děng Zhe Tīng Nǐ Chàng Xīn Gē.", "Mẹ cười nói: Được, mẹ chờ nghe con hát bài mới nhé."]]}, "hsk3-30": {"dur": 266.46, "cues": [[8.29, 12.83, "出门以前，妈妈让我再看看带的东西。", "Chū Mén Yǐ Qián, Mā Ma Ràng Wǒ Zài Kàn Kan Dài De Dōng Xi.", "Trước khi đi, mẹ bảo tôi xem lại đồ mang theo."], [12.83, 16.986, "我带了水、水果，还有一本书。", "Wǒ Dài Le Shuǐ, Shuǐ Guǒ, Hái Yǒu Yì Běn Shū.", "Tôi mang nước, hoa quả, còn có một quyển sách."], [16.986, 22.895, "妹妹把她的小铲子放在包里，一路上都很小心。", "Mèi Mei Bǎ Tā De Xiǎo Chǎn Zi Fàng Zài Bāo Lǐ, Yí Lù Shàng Dōu Hěn Xiǎo Xīn.", "Em gái để cái xẻng nhỏ của em vào túi, dọc đường rất cẩn thận."], [22.895, 27.795, "去年秋天，我们全家开车去海边旅行。", "Qù Nián Qiū Tiān, Wǒ Men Quán Jiā Kāi Chē Qù Hǎi Biān Lǚ Xíng.", "Mùa thu năm ngoái cả nhà lái xe đi biển."], [27.795, 33.799, "爸爸开车，妈妈坐在前面，我和妹妹坐在后面。", "Bà Ba Kāi Chē, Mā Ma Zuò Zài Qián Miàn, Wǒ Hé Mèi Mei Zuò Zài Hòu Miàn.", "Bố lái xe, mẹ ngồi phía trước, tôi và em gái ngồi phía sau."], [33.799, 39.827, "车开了两个小时，妹妹问了三次，我们什么时候到？", "Chē Kāi Le Liǎng Gè Xiǎo Shí, Mèi Mei Wèn Le Sān Cì, Wǒ Men Shén Me Shí Hou Dào?", "Xe chạy hai tiếng, em gái hỏi ba lần: Khi nào mình đến?"], [39.827, 45.766, "爸爸笑着说，快了快了，再过半个小时就到了。", "Bà Ba Xiào Zhe Shuō, Kuài Le Kuài Le, Zài Guò Bàn Gè Xiǎo Shí Jiù Dào Le.", "Bố cười nói: Sắp rồi, sắp rồi, nửa tiếng nữa là đến."], [45.766, 51.314, "路上下了一阵小雨，天空出现了一道彩虹。", "Lù Shàng Xià Le Yí Zhèn Xiǎo Yǔ, Tiān Kōng Chū Xiàn Le Yí Dào Cǎi Hóng.", "Trên đường mưa nhỏ một lúc, trời xuất hiện cầu vồng."], [51.314, 56.022, "爸爸把车开到路边，我们下车看彩虹。", "Bà Ba Bǎ Chē Kāi Dào Lù Biān, Wǒ Men Xià Chē Kàn Cǎi Hóng.", "Bố lái xe vào lề đường, chúng tôi xuống xe ngắm cầu vồng."], [56.022, 61.161, "我给彩虹拍了照片，妹妹高兴得一直笑。", "Wǒ Gěi Cǎi Hóng Pāi Le Zhào Piàn, Mèi Mei Gāo Xìng Dé Yì Zhí Xiào.", "Tôi chụp ảnh cầu vồng, em gái vui đến cười mãi."], [61.161, 66.925, "我们先去旅馆，把东西放在房间里，再去海边。", "Wǒ Men Xiān Qù Lǚ Guǎn, Bǎ Dōng Xi Fàng Zài Fáng Jiān Lǐ, Zài Qù Hǎi Biān.", "Chúng tôi đến nhà nghỉ trước, để đồ trong phòng, rồi mới ra biển."], [66.925, 72.957, "妹妹第一次看见海，高兴得在沙滩上跑来跑去。", "Mèi Mei Dì Yī Cì Kàn Jiàn Hǎi, Gāo Xìng De Zài Shā Tān Shàng Pǎo Lái Pǎo Qù.", "Em gái lần đầu thấy biển, vui chạy qua chạy lại trên cát."], [72.957, 79.537, "她跑到海边，又跑回来，对妈妈说，妈妈，海真大。", "Tā Pǎo Dào Hǎi Biān, Yòu Pǎo Huí Lái, Duì Mā Ma Shuō, Mā Ma, Hǎi Zhēn Dà.", "Em chạy ra biển rồi chạy về, nói với mẹ: Mẹ ơi, biển lớn thật."], [79.537, 85.078, "爸爸教她用铲子做城堡，我站在旁边拍照。", "Bà Ba Jiāo Tā Yòng Chǎn Zi Zuò Chéng Bǎo, Wǒ Zhàn Zài Páng Biān Pāi Zhào.", "Bố dạy em dùng xẻng nhỏ làm lâu đài, tôi đứng cạnh chụp ảnh."], [85.078, 90.89, "我也做了一个小城堡，可是水一来，城堡就坏了。", "Wǒ Yě Zuò Le Yí Gè Xiǎo Chéng Bǎo, Kě Shì Shuǐ Yì Lái, Chéng Bǎo Jiù Huài Le.", "Tôi cũng làm một lâu đài nhỏ, nhưng nước vừa đến, lâu đài hỏng mất."], [90.89, 95.574, "妹妹说，没关系，我们再做一个更大的。", "Mèi Mei Shuō, Méi Guān Xi, Wǒ Men Zài Zuò Yí Gè Gèng Dà De.", "Em nói: Không sao, mình làm cái khác to hơn."], [95.574, 101.1, "这一次，爸爸帮我们，城堡做得又大又好看。", "Zhè Yí Cì, Bà Ba Bāng Wǒ Men, Chéng Bǎo Zuò Dé Yòu Dà Yòu Hǎo Kàn.", "Lần này bố giúp chúng tôi, lâu đài làm vừa to vừa đẹp."], [101.1, 106.432, "中午在小馆子吃饭，老板娘送了一碗汤。", "Zhōng Wǔ Zài Xiǎo Guǎn Zi Chī Fàn, Lǎo Bǎn Niáng Sòng Le Yì Wǎn Tāng.", "Trưa chúng tôi ăn ở quán nhỏ, bà chủ tặn thêm một bát canh."], [106.432, 110.3, "老板娘问我们，你们是从哪儿来的？", "Lǎo Bǎn Niáng Wèn Wǒ Men, Nǐ Men Shì Cóng Nǎ Er Lái De?", "Bà chủ hỏi chúng tôi: Các cháu từ đâu đến?"], [110.3, 115.8, "爸爸说，我们开车来的，就住在海边的旅馆。", "Bà Ba Shuō, Wǒ Men Kāi Chē Lái De, Jiù Zhù Zài Hǎi Biān De Lǚ Guǎn.", "Bố nói: Chúng tôi lái xe đến, ở ngay nhà nghỉ bên biển."], [115.8, 119.62, "那碗汤很热，我们喝了都说好。", "Nà Wǎn Tāng Hěn Rè, Wǒ Men Hē Le Dōu Shuō Hǎo.", "Bát canh đó rất nóng, chúng tôi uống xong đều khen ngon."], [119.62, 126.456, "吃完饭，老板娘还告诉我们，下午退潮的时候有小螃蟹。", "Chī Wán Fàn, Lǎo Bǎn Niáng Hái Gào Su Wǒ Men, Xià Wǔ Tuì Cháo De Shí Hou Yǒu Xiǎo Páng Xiè.", "Ăn xong, bà chủ còn bảo chúng tôi, chiều lúc nước rút có cua con."], [126.456, 132.244, "下午退潮的时候，我们在石头上找到了小螃蟹。", "Xià Wǔ Tuì Cháo De Shí Hou, Wǒ Men Zài Shí Tou Shàng Zhǎo Dào Le Xiǎo Páng Xiè.", "Chiều nước rút, trên đá chúng tôi thấy cua con."], [132.244, 137.024, "妹妹小声说，你们看，它走得真慢。", "Mèi Mei Xiǎo Shēng Shuō, Nǐ Men Kàn, Tā Zǒu Dé Zhēn Màn.", "Em gái khẽ nói: Mọi người xem, nó đi chậm thật."], [137.024, 142.733, "我把螃蟹放进水桶，看完以后又放回海里。", "Wǒ Bǎ Páng Xiè Fàng Jìn Shuǐ Tǒng, Kàn Wán Yǐ Hòu Yòu Fàng Huí Hǎi Lǐ.", "Tôi bỏ cua vào xô, xem xong thả lại biển."], [142.733, 148.257, "爸爸说，螃蟹的家在海里，我们不能带它走。", "Bà Ba Shuō, Páng Xiè De Jiā Zài Hǎi Lǐ, Wǒ Men Bù Néng Dài Tā Zǒu.", "Bố nói: Nhà của cua ở trong biển, chúng ta không thể mang nó đi."], [148.257, 153.757, "妹妹对螃蟹说，再见，明年我再来看你。", "Mèi Mei Duì Páng Xiè Shuō, Zài Jiàn, Míng Nián Wǒ Zài Lái Kàn Nǐ.", "Em gái nói với con cua: Tạm biệt, năm sau mình lại đến thăm bạn."], [153.757, 159.266, "螃蟹慢慢走回海里，我们站在旁边看着它。", "Páng Xiè Màn Màn Zǒu Huí Hǎi Lǐ, Wǒ Men Zhàn Zài Páng Biān Kàn Zhe Tā.", "Con cua từ từ đi về biển, chúng tôi đứng bên nhìn nó."], [159.266, 164.382, "傍晚的风很凉，妈妈把外套披在我肩上。", "Bàng Wǎn De Fēng Hěn Liáng, Mā Ma Bǎ Wài Tào Pī Zài Wǒ Jiān Shàng.", "Gió chiều lạnh, mẹ khoác áo lên vai tôi."], [164.382, 168.538, "我说，妈妈，我不冷，你穿吧。", "Wǒ Shuō, Mā Ma, Wǒ Bù Lěng, Nǐ Chuān Ba.", "Tôi nói: Mẹ, con không lạnh, mẹ mặc đi."], [168.538, 173.987, "妈妈笑着说，妈妈也不冷，我们一起走走吧。", "Mā Ma Xiào Zhe Shuō, Mā Ma Yě Bù Lěng, Wǒ Men Yì Qǐ Zǒu Zou Ba.", "Mẹ cười nói: Mẹ cũng không lạnh, chúng ta cùng đi dạo nhé."], [173.987, 178.311, "我问爸爸，你小时候也来过海边吗？", "Wǒ Wèn Bà Ba, Nǐ Xiǎo Shí Hou Yě Lái Guò Hǎi Biān Ma?", "Tôi hỏi bố: Hồi nhỏ bố cũng từng đến biển à?"], [178.311, 185.227, "爸爸说，他小时候也来过海边，还给我们讲了那时候的故事。", "Bà Ba Shuō, Tā Xiǎo Shí Hou Yě Lái Guò Hǎi Biān, Hái Gěi Wǒ Men Jiǎng Le Nà Shí Hou De Gù Shi.", "Bố nói, hồi nhỏ bố cũng từng đến biển, còn kể cho chúng tôi nghe chuyện hồi đó."], [185.227, 189.939, "那个故事很好听，我们听了都笑了。", "Nà Ge Gù Shi Hěn Hǎo Tīng, Wǒ Men Tīng Le Dōu Xiào Le.", "Câu chuyện đó rất hay, chúng tôi nghe xong đều cười."], [189.939, 194.407, "回旅馆的路上，妹妹在车上睡着了。", "Huí Lǚ Guǎn De Lù Shàng, Mèi Mei Zài Chē Shàng Shuì Zháo Le.", "Trên đường về nhà nghỉ em ngủ gật trên xe."], [194.407, 198.779, "爸爸把车开得很慢，让妹妹好好睡。", "Bà Ba Bǎ Chē Kāi Dé Hěn Màn, Ràng Mèi Mei Hǎo Hāo Shuì.", "Bố lái xe rất chậm, để em gái ngủ ngon."], [198.779, 204.495, "到了旅馆，爸爸叫醒妹妹，我们一起走进房间。", "Dào Le Lǚ Guǎn, Bà Ba Jiào Xǐng Mèi Mei, Wǒ Men Yì Qǐ Zǒu Jìn Fáng Jiān.", "Đến nhà nghỉ, bố gọi em dậy, chúng tôi cùng vào phòng."], [204.495, 211.023, "到了旅馆，爸爸小声叫醒妹妹，我们一起慢慢走进房间。", "Dào Le Lǚ Guǎn, Bà Ba Xiǎo Shēng Jiào Xǐng Mèi Mei, Wǒ Men Yì Qǐ Màn Màn Zǒu Jìn Fáng Jiān.", "Đến nhà nghỉ, bố khẽ gọi em dậy, chúng tôi cùng từ từ bước vào phòng."], [211.023, 216.782, "妹妹看着彩虹的照片说，这是我最喜欢的一张。", "Mèi Mei Kàn Zhe Cǎi Hóng De Zhào Piàn Shuō, Zhè Shì Wǒ Zuì Xǐ Huan De Yí Zhāng.", "Em gái nhìn ảnh cầu vồng nói: Đây là tấm em thích nhất."], [216.782, 221.333, "第二天早上，我们又去海边走了一会儿。", "Dì Èr Tiān Zǎo Shàng, Wǒ Men Yòu Qù Hǎi Biān Zǒu Le Yí Huì Er.", "Sáng hôm sau, chúng tôi lại ra biển đi dạo một lúc."], [221.333, 227.169, "回家的时候，妹妹在车上说，下次我还要来。", "Huí Jiā De Shí Hou, Mèi Mei Zài Chē Shàng Shuō, Xià Cì Wǒ Hái Yào Lái.", "Lúc về nhà, em gái nói trên xe: Lần sau em vẫn muốn đến."], [227.169, 236.1, "妈妈笑着说，好，我们一家人以后多一起旅行，妈妈也最喜欢和你们一起出门了。", "Mā Ma Xiào Zhe Shuō, Hǎo, Wǒ Men Yì Jiā Rén Yǐ Hòu Duō Yì Qǐ Lǚ Xíng, Mā Ma Yě Zuì Xǐ Huan Hé Nǐ Men Yì Qǐ Chū Mén Le.", "Mẹ cười nói: Được, sau này cả nhà mình cùng đi du lịch nhiều hơn nhé, mẹ cũng thích nhất là được đi cùng các con."], [236.1, 241.696, "虽然只住了两天，可是全家都觉得很放松。", "Suī Rán Zhǐ Zhù Le Liǎng Tiān, Kě Shì Quán Jiā Dōu Jué De Hěn Fàng Sōng.", "Dù chỉ ở hai ngày nhưng cả nhà đều thấy thư giãn."], [241.696, 246.356, "旅行中的小事，现在想起来仍然温暖。", "Lǚ Xíng Zhōng De Xiǎo Shì, Xiàn Zài Xiǎng Qǐ Lái Réng Rán Wēn Nuǎn.", "Những việc nhỏ trong chuyến đi giờ nhớ lại vẫn ấm lòng."], [246.356, 251.712, "回到家，我把彩虹的照片放在我的桌子上。", "Huí Dào Jiā, Wǒ Bǎ Cǎi Hóng De Zhào Piàn Fàng Zài Wǒ De Zhuō Zi Shàng.", "Về đến nhà, tôi để ảnh cầu vồng lên bàn của mình."], [251.712, 257.164, "我想明年春天，我们还可以一起去别处看看。", "Wǒ Xiǎng Míng Nián Chūn Tiān, Wǒ Men Hái Kě Yǐ Yì Qǐ Qù Bié Chù Kàn Kan.", "Tôi muốn mùa xuân năm sau cả nhà lại đi nơi khác xem."]]}};
